def _extract_json_block(txt):
    """Strip markdown fences and parse the first JSON object in the text."""
    if not txt:
        return None
    clean = txt.strip().lstrip("```json").lstrip("```").rstrip("```").strip()
    j0 = clean.find("{")
    j1 = clean.rfind("}") + 1
    if j0 < 0 or j1 <= j0:
        return None
    try:
        return json.loads(clean[j0:j1])
    except Exception:
        return None


def _is_quota_error(err_str):
    """Detect a Gemini quota / rate-limit error from the exception string."""
    if not err_str:
        return False
    s = str(err_str)
    return ("RESOURCE_EXHAUSTED" in s) or ("429" in s) or ("quota" in s.lower())


def _vertex_gemini_json(model_key, prompt, system=None, max_tokens=1024, temperature=0.3,
                       _fallback_chain=None):
    """Call a Gemini model (google-genai SDK, API key auth) and return parsed JSON.

    Gemini 2.5 models have "thinking" enabled by default — thinking tokens
    count against max_output_tokens and can cause truncated/empty JSON
    responses for structured outputs. We disable thinking explicitly here
    since none of our JSON surfaces benefit from chain-of-thought, and the
    saved tokens go entirely to the actual response (cheaper + more reliable).

    Free-tier fallback: when a paid model (reasoning/narrative/premium ->
    gemini-2.5-pro) returns RESOURCE_EXHAUSTED, the call is retried against
    the "fast" tier (gemini-2.5-flash-lite, free-tier quota). Quality drops
    a notch but the panel still gets a real AI verdict instead of an
    "Unavailable" placeholder.
    """
    if not _gemini_available or _gemini_client is None:
        return None, "gemini_unavailable"
    if _fallback_chain is None:
        # Build the per-tier fallback chain ONCE. Paid tiers fall back to
        # "fast"; the "fast" tier has no further fallback.
        _fallback_chain = ["fast"] if model_key in ("reasoning", "narrative", "premium") else []
    try:
        model_id = VERTEX_MODELS.get(model_key)
        if not model_id:
            return None, f"unknown_model_key:{model_key}"
        resp = _gemini_client.models.generate_content(
            model=model_id,
            contents=prompt,
            config={
                "system_instruction": system or "Respond with raw JSON only — no markdown, no backticks.",
                "max_output_tokens": max_tokens,
                "temperature": temperature,
                "response_mime_type": "application/json",
                "thinking_config": {"thinking_budget": 0},
            },
        )
        txt = getattr(resp, "text", None) or ""
        parsed = _extract_json_block(txt)
        if parsed is None:
            # Surface enough context to diagnose without leaking the full prompt.
            snippet = (txt[:200] + "…") if len(txt) > 200 else txt
            finish = None
            try:
                finish = resp.candidates[0].finish_reason if resp.candidates else None
            except Exception:
                pass
            return None, f"json_parse_failed (finish={finish}, len={len(txt)}, head={snippet!r})"
        return parsed, None
    except Exception as ex:
        err = str(ex)
        if _is_quota_error(err) and _fallback_chain:
            next_key, *rest = _fallback_chain
            app.logger.warning(
                "[gemini] %s hit quota, falling back to %s (%s)",
                model_key, next_key, VERTEX_MODELS.get(next_key, "?"),
            )
            return _vertex_gemini_json(
                next_key, prompt, system=system,
                max_tokens=max_tokens, temperature=temperature,
                _fallback_chain=rest,
            )
        return None, err


# Backwards-compatible alias: every caller that used to hit Claude now
# transparently routes through Gemini. Kept under the old name so route
# definitions and the deepdive insights helper don't need touch-ups.
def _vertex_claude_json(model_key, prompt, system, max_tokens=2000, temperature=0.4):
    """Legacy name; now a thin wrapper that calls Gemini under the hood."""
    return _vertex_gemini_json(model_key, prompt, system=system,
                               max_tokens=max_tokens, temperature=temperature)


def _vertex_gemini_json_image(model_key, prompt, image_bytes, mime_type,
                              system=None, max_tokens=2048, temperature=0.2,
                              _fallback_chain=None):
    """Multimodal variant of _vertex_gemini_json: prompt + inline image bytes.

    Gemini 2.5 accepts inline image parts up to ~20MB. We pass the raw bytes
    via google.genai.types.Part.from_bytes so callers don't need to base64
    the payload themselves. Same quota-fallback chain as the text-only path.
    """
    if not _gemini_available or _gemini_client is None:
        return None, "gemini_unavailable"
    if _fallback_chain is None:
        _fallback_chain = ["fast"] if model_key in ("reasoning", "narrative", "premium") else []
    try:
        from google.genai import types as _genai_types
    except Exception as ex:
        return None, f"genai_types_unavailable:{ex}"
    try:
        model_id = VERTEX_MODELS.get(model_key)
        if not model_id:
            return None, f"unknown_model_key:{model_key}"
        image_part = _genai_types.Part.from_bytes(data=image_bytes, mime_type=mime_type)
        resp = _gemini_client.models.generate_content(
            model=model_id,
            contents=[image_part, prompt],
            config={
                "system_instruction": system or "Respond with raw JSON only — no markdown, no backticks.",
                "max_output_tokens": max_tokens,
                "temperature": temperature,
                "response_mime_type": "application/json",
                "thinking_config": {"thinking_budget": 0},
            },
        )
        txt = getattr(resp, "text", None) or ""
        parsed = _extract_json_block(txt)
        if parsed is None:
            snippet = (txt[:200] + "…") if len(txt) > 200 else txt
            finish = None
            try:
                finish = resp.candidates[0].finish_reason if resp.candidates else None
            except Exception:
                pass
            return None, f"json_parse_failed (finish={finish}, len={len(txt)}, head={snippet!r})"
        return parsed, None
    except Exception as ex:
        err = str(ex)
        if _is_quota_error(err) and _fallback_chain:
            next_key, *rest = _fallback_chain
            app.logger.warning(
                "[gemini-image] %s hit quota, falling back to %s (%s)",
                model_key, next_key, VERTEX_MODELS.get(next_key, "?"),
            )
            return _vertex_gemini_json_image(
                next_key, prompt, image_bytes, mime_type,
                system=system, max_tokens=max_tokens, temperature=temperature,
                _fallback_chain=rest,
            )
        return None, err


def _vertex_gemini_text(model_key, prompt, system=None, max_tokens=600, temperature=0.5,
                       _fallback_chain=None):
    """Call Gemini and return the plain text response (not JSON).

    Used by paragraph-form surfaces — HR scouting writeups, single-bullet
    summaries — where forcing application/json would just wrap the text in
    a wrapper key. Returns (text_str_or_None, error_str_or_None).

    Same free-tier fallback as _vertex_gemini_json: paid tiers retry on
    gemini-2.5-flash-lite when the primary model returns RESOURCE_EXHAUSTED.
    """
    if not _gemini_available or _gemini_client is None:
        return None, "gemini_unavailable"
    if _fallback_chain is None:
        _fallback_chain = ["fast"] if model_key in ("reasoning", "narrative", "premium") else []
    try:
        model_id = VERTEX_MODELS.get(model_key)
        if not model_id:
            return None, f"unknown_model_key:{model_key}"
        resp = _gemini_client.models.generate_content(
            model=model_id,
            contents=prompt,
            config={
                "system_instruction":  system or "You are an expert MLB betting analyst.",
                "max_output_tokens":   max_tokens,
                "temperature":         temperature,
                "thinking_config":     {"thinking_budget": 0},
            },
        )
        txt = (getattr(resp, "text", None) or "").strip()
        if not txt:
            finish = None
            try:
                finish = resp.candidates[0].finish_reason if resp.candidates else None
            except Exception:
                pass
            return None, f"empty_response (finish={finish})"
        return txt, None
    except Exception as ex:
        err = str(ex)
        if _is_quota_error(err) and _fallback_chain:
            next_key, *rest = _fallback_chain
            app.logger.warning(
                "[gemini] %s hit quota (text), falling back to %s (%s)",
                model_key, next_key, VERTEX_MODELS.get(next_key, "?"),
            )
            return _vertex_gemini_text(
                next_key, prompt, system=system,
                max_tokens=max_tokens, temperature=temperature,
                _fallback_chain=rest,
            )
        return None, err


def _bq_query_rows(sql, params=None, timeout=15):
    """Execute a parameterized BigQuery SELECT and return list of dict rows."""
    if not _bigquery_available or _bq_client is None:
        return None
    try:
        from google.cloud import bigquery as _bq_mod
        job_config = _bq_mod.QueryJobConfig(query_parameters=params or [])
        job = _bq_client.query(sql, job_config=job_config)
        rows = job.result(timeout=timeout)
        return [dict(r.items()) for r in rows]
    except Exception as ex:
        app.logger.warning(f"[bq] query failed: {ex}")
        return None


