# Domed / retractable-roof stadiums (weather is always INDOOR/controlled)
# ── Team Defensive Metrics (Statcast Outs Above Average) ────────────────────
# Real team defense from Baseball Savant's OAA leaderboard. Positive OAA =
# better-than-average defense (suppresses hits on balls in play); negative =
# porous defense (inflates them). Populated at startup by _load_team_defense();
# an empty cache => every defense factor falls back to neutral (1.0).
#
# (Replaces a dead UZR stub: _TEAM_UZR was declared but never populated and
#  _team_uzr_hit_mult was never called, so team defense had zero effect on any
#  projection. This wires a live signal into the BABIP-dependent props.)
_team_def_lock = threading.RLock()   # reentrant: rankings route holds it while calling _team_def_hit_mult
_TEAM_DEFENSE: dict[int, dict] = {}   # team_id -> {team, oaa, oaa_rhh, oaa_lhh, rank, success}
_TEAM_DEF_STATS = {"mean": 0.0, "std": 1.0, "n": 0, "season": None}
_team_def_loaded = False


def _load_team_defense():
    """Load Statcast team Outs Above Average from Baseball Savant.

    Builds _TEAM_DEFENSE per team_id plus the league mean/std used to z-score
    each team's OAA. Z-scoring keeps the factor scale-invariant: raw OAA grows
    in magnitude over the season, but its standardized value stays comparable.
    Graceful no-op on fetch failure — the defense factor then stays neutral.
    """
    global _team_def_loaded
    url_t = ("https://baseballsavant.mlb.com/leaderboard/outs_above_average?"
             "type=Fielding_Team&startYear={year}&endYear={year}&split=no&team="
             "&range=year&min=q&pos=&roles=&viz=show&csv=true")
    try:
        rows, season = _fetch_sv_csv_by_season(url_t, _season_candidates(depth=3))
    except Exception as ex:
        logging.warning(f"[TeamDefense] OAA fetch error: {ex}")
        return
    if not rows:
        logging.warning("[TeamDefense] OAA leaderboard unavailable — defense factor neutral")
        return
    parsed, oaas = {}, []
    for r in rows:
        try:
            tid = int(r.get("team_id") or 0)
        except (TypeError, ValueError):
            continue
        if not tid:
            continue
        oaa = _safe_num(r.get("outs_above_average"), 0.0)
        parsed[tid] = {
            "team":    (r.get("team_name") or "").strip(),
            "oaa":     oaa,
            "oaa_rhh": _safe_num(r.get("outs_above_average_rhh"), 0.0),
            "oaa_lhh": _safe_num(r.get("outs_above_average_lhh"), 0.0),
            "success": (r.get("actual_success_rate_formatted") or "").strip(),
        }
        oaas.append(oaa)
    if not parsed:
        return
    n = len(oaas)
    mean = sum(oaas) / n
    std = max(1e-6, (sum((x - mean) ** 2 for x in oaas) / n) ** 0.5) if n > 1 else 1.0
    for rank, (tid, _v) in enumerate(sorted(parsed.items(), key=lambda kv: -kv[1]["oaa"]), start=1):
        parsed[tid]["rank"] = rank
    with _team_def_lock:
        _TEAM_DEFENSE.clear(); _TEAM_DEFENSE.update(parsed)
        _TEAM_DEF_STATS.update({"mean": mean, "std": std, "n": n, "season": season})
        _team_def_loaded = True
    logging.info(f"[TeamDefense] {n} teams OAA loaded (season={season}, mean={mean:.1f}, std={std:.1f})")


def _team_def_hit_mult(fielding_team_id) -> float:
    """Hit-suppression multiplier from team OAA for BABIP-dependent props
    (hits/TB/RBI/runs). Uses a z-score so it's scale-invariant across the
    season: ~+1 SD of defense => -2% on contact props, clamped to ±6%. HR props
    are intentionally NOT adjusted — home runs don't depend on fielding.
    Returns 1.0 (neutral) when the team is unknown or data hasn't loaded.
    """
    if not fielding_team_id:
        return 1.0
    with _team_def_lock:
        rec = _TEAM_DEFENSE.get(int(fielding_team_id))
        mean, std = _TEAM_DEF_STATS["mean"], _TEAM_DEF_STATS["std"]
    if not rec:
        return 1.0
    z = (rec.get("oaa", mean) - mean) / (std or 1.0)
    return min(1.06, max(0.94, 1.0 - z * 0.02))


# pitcher_id -> (date_iso, fielding_team_id); the fielding team for a batter is
# whoever the opposing pitcher plays for. Resolved via the MLB people API and
# cached for the day so it costs one call per starter.
_pitcher_team_lock = threading.Lock()
_pitcher_team_cache: dict = {}


def _fielding_team_for_pitcher(pitcher_id):
    if not pitcher_id:
        return None
    try:
        pid = int(pitcher_id)
    except (TypeError, ValueError):
        return None
    today = datetime.now(ET).date().isoformat()
    with _pitcher_team_lock:
        hit = _pitcher_team_cache.get(pid)
        if hit and hit[0] == today:
            return hit[1]
    team_id = None
    try:
        r = requests.get(f"{MLB_API}/people/{pid}?hydrate=currentTeam", timeout=8)
        r.raise_for_status()
        ppl = r.json().get("people", [])
        if ppl:
            team_id = (ppl[0].get("currentTeam") or {}).get("id")
    except Exception:
        team_id = None
    with _pitcher_team_lock:
        _evict_if_large(_pitcher_team_cache, 400)
        _pitcher_team_cache[pid] = (today, team_id)
    return team_id


def _def_factor_for_pitcher(pitcher_id) -> float:
    """Convenience: resolve the opposing pitcher's team and return its
    hit-suppression multiplier. Neutral (1.0) on any miss."""
    return _team_def_hit_mult(_fielding_team_for_pitcher(pitcher_id))

DOME_VENUES = {
    12,    # Tropicana Field (fixed dome)
    14,    # Rogers Centre (retractable)
    15,    # Chase Field (retractable)
    32,    # American Family Field (retractable)
    680,   # T-Mobile Park (retractable)
    2392,  # Daikin Park / Minute Maid (retractable)
    4169,  # loanDepot park (retractable)
    5325,  # Globe Life Field (retractable)
    4321,  # Globe Life Field alt
}

# Ballpark orientation: compass azimuth (degrees clockwise from true north) of
# the line from home plate through the pitcher's mound to straightaway center
# field. Wind blowing TOWARD this bearing carries fly balls out of the park;
# wind blowing the opposite way knocks them down. Used by _wind_field_geometry()
# to turn a raw "12 mph NE" string into an actionable OUT/IN/CROSS read.
#
# Only outdoor parks are listed — the eight dome/retractable venues in
# DOME_VENUES play in controlled air, so a directional read is meaningless
# there. Bearings are bucketed to the nearest well-established quadrant; the
# downstream classifier only resolves OUT / IN / CROSS (45-degree bins), so
# small per-park errors never flip the sign of the call.
PARK_CF_BEARING = {
    1:    45,   # Angel Stadium — CF to NE
    2:    30,   # Camden Yards — CF to NNE
    3:    45,   # Fenway Park — CF to NE
    4:    43,   # Rate Field (Chicago AL) — CF to NE
    5:    0,    # Progressive Field — CF to N
    7:    45,   # Kauffman Stadium — CF to NE
    17:   30,   # Wrigley Field — CF to NNE (the classic wind park)
    19:   0,    # Coors Field — CF to N
    22:   25,   # Dodger Stadium — CF to NNE
    31:   120,  # PNC Park — CF to ESE (toward the river)
    2394: 150,  # Comerica Park — CF to SSE
    2395: 90,   # Oracle Park — CF to E (McCovey Cove)
    2602: 120,  # Great American Ball Park — CF to ESE
    2680: 0,    # Petco Park — CF to N
    2681: 15,   # Citizens Bank Park — CF to NNE
    2889: 60,   # Busch Stadium — CF to ENE
    3289: 28,   # Citi Field — CF to NNE
    3309: 30,   # Nationals Park — CF to NNE
    3312: 68,   # Target Field — CF to ENE
    3313: 75,   # Yankee Stadium — CF to ENE
    4705: 138,  # Truist Park — CF to SE
}


def _wind_field_geometry(venue_id, wind_deg, wind_speed):
    """Resolve a meteorological wind (direction it blows FROM, in degrees) into
    the component blowing out toward center field for a given park.

    Open-Meteo's ``winddirection_10m`` follows the meteorological convention:
    it is the heading the wind is coming *from*. The ball is carried toward the
    opposite heading, so we rotate by 180 degrees before comparing to the
    park's home-plate -> CF bearing.

    Returns a dict with:
      ``out``   signed mph blowing out to CF (+) or in from CF (-)
      ``cross`` signed mph of crosswind (+ = toward right field / L->R)
      ``field`` short label: "OUT to CF" / "IN from CF" / "Crosswind L->R" / ...
      ``emoji`` a directional glyph for the UI
    or ``None`` when the park bearing or wind data is unavailable.
    """
    try:
        bearing = PARK_CF_BEARING.get(int(venue_id or 0))
    except (TypeError, ValueError):
        bearing = None
    if bearing is None:
        return None
    try:
        spd = float(wind_speed)
        deg = float(wind_deg)
    except (TypeError, ValueError):
        return None
    if spd <= 0:
        return {"out": 0.0, "cross": 0.0, "field": "Calm", "emoji": "\U0001F4A4"}
    to_dir = (deg + 180.0) % 360.0
    delta = ((to_dir - bearing + 180.0) % 360.0) - 180.0   # signed, [-180, 180]
    rad = math.radians(delta)
    out = round(spd * math.cos(rad), 1)
    cross = round(spd * math.sin(rad), 1)
    ad = abs(delta)
    if ad <= 45:
        field, emoji = "OUT to CF", "↗"
    elif ad >= 135:
        field, emoji = "IN from CF", "↙"
    else:
        if delta > 0:
            field, emoji = "Crosswind L→R", "➡"
        else:
            field, emoji = "Crosswind R→L", "⬅"
    return {"out": out, "cross": cross, "field": field, "emoji": emoji}


def _scoring_environment(temp, wind_out, park_factor, rain_chance, dome=False):
    """Blend temperature, the out-to-CF wind component, and the park run factor
    into a single per-team run delta plus a plain-language verdict. This is the
    composite "scoring environment" the deep-dive surfaces above the raw cards.

    All deltas are runs-per-team relative to a neutral 70F / calm / 1.00-park
    baseline and are clamped so no single driver can dominate the read.
    """
    drivers = []
    if dome:
        return {
            "runDelta": 0.0, "tier": "CONTROLLED", "color": "neutral",
            "label": "Indoor / roof closed — weather neutralized",
            "drivers": ["Climate-controlled air: no wind or temperature effect"],
        }

    temp_d = 0.0
    try:
        t = float(temp)
        temp_d = max(-0.45, min(0.45, (t - 70.0) / 10.0 * 0.12))
        if t >= 85:
            drivers.append(f"Hot {int(t)}°F air thins out — ball carries (+)")
        elif t <= 50:
            drivers.append(f"Cold {int(t)}°F air is dense — ball dies (−)")
    except (TypeError, ValueError):
        pass

    wind_d = 0.0
    if isinstance(wind_out, (int, float)):
        wind_d = max(-0.6, min(0.6, float(wind_out) * 0.035))
        if wind_out >= 6:
            drivers.append(f"{abs(round(wind_out))} mph blowing OUT — fly balls carry (+)")
        elif wind_out <= -6:
            drivers.append(f"{abs(round(wind_out))} mph blowing IN — fly balls held up (−)")

    park_d = 0.0
    try:
        pf = float(park_factor)
        park_d = max(-0.9, min(0.9, (pf - 1.0) * 4.5))
        if pf >= 1.05:
            drivers.append(f"{pf:.2f}x hitter's park dimensions (+)")
        elif pf <= 0.95:
            drivers.append(f"{pf:.2f}x pitcher's park dimensions (−)")
    except (TypeError, ValueError):
        pass

    rain_note = None
    try:
        rc = float(rain_chance)
        if rc >= 60:
            rain_note = f"{int(rc)}% rain risk — heavy air, possible delay"
            drivers.append(rain_note + " (−)")
    except (TypeError, ValueError):
        pass

    total = round(temp_d + wind_d + park_d - (0.1 if rain_note else 0.0), 2)
    if total >= 0.5:
        tier, color, label = "HITTER-FRIENDLY", "good", "Run-scoring environment favors overs / hitter props"
    elif total >= 0.2:
        tier, color, label = "SLIGHT HITTER LEAN", "good", "Modest tailwind for offense"
    elif total <= -0.5:
        tier, color, label = "PITCHER-FRIENDLY", "bad", "Suppressed environment favors unders / NRFI / K props"
    elif total <= -0.2:
        tier, color, label = "SLIGHT PITCHER LEAN", "bad", "Modest drag on offense"
    else:
        tier, color, label = "NEUTRAL", "neutral", "Balanced scoring environment"
    if not drivers:
        drivers.append("No standout weather or park driver — plays neutral")
    return {
        "runDelta": total, "tier": tier, "color": color,
        "label": label, "drivers": drivers,
    }


def _wind_run_adj(wx, scale=1.0):
    """Per-team run adjustment from the out-to-CF wind component (signed mph).

    ~10 mph blowing out ≈ +0.25 R/team at scale=1.0, blowing in the reverse;
    clamped to ±0.45 so wind never overwhelms the rest of the run model. Pass
    scale<1 for half-game (F5/NRFI) projections. Returns 0.0 whenever the wind
    geometry is unavailable — dome, a park without a known CF bearing, or calm.
    """
    try:
        if not wx or wx.get("dome"):
            return 0.0
        wo = wx.get("wind_out")
        if wo is None:
            return 0.0
        return round(max(-0.45, min(0.45, float(wo) * 0.025)) * scale, 2)
    except Exception:
        return 0.0


