# Approximate 3-year rolling HR park index from Statcast data.
# Camden Yards (110) reflects the 2025 wall restoration; override if Savant
# rolling window hasn't fully refreshed yet.
HR_PARK_FACTORS = {
    109: 114, 144: 94,  110: 108, 111: 101, 112: 109, 137: 92,
    115: 112, 116: 100, 117: 103, 118: 108, 119: 104, 108: 95,
    146: 95,  158: 99,  142: 99,  121: 100, 147: 118, 133: 107,
    143: 111, 134: 95,  136: 95,  138: 98,  139: 96,  140: 112,
    141: 102, 120: 99,  135: 97,  145: 95,  113: 100, 114: 98,
}

# ── Handedness-split HR park factors (index 100 = neutral) ──────────────────
# Only parks with well-documented LHB/RHB HR asymmetry are listed; every other
# park inherits the symmetric HR_PARK_FACTORS value for both hands via
# _hr_park_factor_hand(). Keeping the list curated avoids asserting a split
# direction we aren't confident about (a wrong direction is worse than none).
HR_PARK_FACTORS_HAND = {
    147: {"L": 134, "R": 100},  # Yankee Stadium — short RF porch inflates LHB power
    137: {"L": 80,  "R": 96},   # Oracle Park — deep RF / Triples Alley buries LHB
    111: {"L": 90,  "R": 104},  # Fenway — deep RF suppresses LHB; Monster aids RHB
    110: {"L": 112, "R": 95},   # Camden Yards — 2022 LF wall move suppressed RHB HR
    117: {"L": 99,  "R": 110},  # Daikin/Minute Maid — short LF Crawford boxes aid RHB
    134: {"L": 104, "R": 92},   # PNC Park — short RF favors LHB, deep LF buries RHB
    143: {"L": 114, "R": 108},  # Citizens Bank — bandbox, LHB edge
    116: {"L": 96,  "R": 92},   # Comerica — deep gaps suppress HR, RHB most
}


def _hr_park_factor_hand(home_team_id, hand):
    """HR park multiplier (1.0 = neutral) for a batter of the given hand. Uses
    the curated handedness table when available, else the symmetric HR index."""
    h = "L" if str(hand or "R").upper().startswith("L") else "R"
    rec = HR_PARK_FACTORS_HAND.get(home_team_id)
    if rec and h in rec:
        return round(rec[h] / 100.0, 2)
    return round(HR_PARK_FACTORS.get(home_team_id, 100) / 100.0, 2)

_fg_lock = threading.Lock()
_fg_cond = threading.Condition(_fg_lock)   # notified when FG load completes
_fg_bat = {}
_fg_pit = {}
_fg_loaded = False
_fg_load_date = None
_fg_loading = False

# ── Historical FG + daily matchup caches ─────────────────────────────────────
# Keyed by MLBAM int ID → {year → {stat_key → value}}
_fg_hist_lock = threading.Lock()
_fg_bat_hist: dict = {}
_fg_pit_hist: dict = {}
_fg_hist_loaded = False

# Daily pre-computed matchup rows keyed by (batter_id_str, pitcher_id_str)
_matchup_lock_local = threading.Lock()
_matchup_cache: dict = {}
_matchup_date_loaded = None

_HTML_TAG_RE = re.compile(r'<[^>]+>')


def _load_fg_data():
    global _fg_loaded, _fg_load_date, _fg_loading
    # Do NOT check _fg_loading here — _maybe_refresh_fg pre-sets it before
    # spawning this function in a thread.  Checking it would cause the load
    # to exit immediately, leaving FG data permanently stale.
    # De-duplication is the caller's responsibility (_maybe_refresh_fg uses
    # _fg_lock to ensure only one thread is spawned at a time).
    with _fg_cond:
        if _fg_loaded and _fg_load_date == datetime.now().date():
            return  # already loaded today — skip
        _fg_loading = True
    try:
        logging.info("[FG] _load_fg_data: starting MLB-API-derived load…")
        _load_fg_data_from_mlb_api()
        with _fg_cond:
            has_data = bool(_fg_pit) or bool(_fg_bat)
            _fg_loaded = has_data
            _fg_load_date = datetime.now().date() if has_data else None
        logging.info(f"[FG] _load_fg_data done: loaded={_fg_loaded} pit={len(_fg_pit)} bat={len(_fg_bat)}")
    finally:
        with _fg_cond:
            _fg_loading = False
            _fg_cond.notify_all()


def _safe_num(v, default=0.0):
    try:
        if v in (None, "", "-.--", ".---", "N/A"): return default
        return float(v)
    except Exception:
        return default


def _normalize_date_str(value, fallback=None):
    """Return a YYYY-MM-DD string from loose date/datetime inputs."""
    fb = (fallback or datetime.now(ET).strftime("%Y-%m-%d")).strip()
    raw = str(value or "").strip()
    if not raw:
        return fb

    token = raw.split("T", 1)[0].strip().replace("/", "-")
    try:
        return datetime.strptime(token, "%Y-%m-%d").strftime("%Y-%m-%d")
    except Exception:
        return fb


def _season_candidates(depth=4):
    """Return candidate MLB seasons from current year backwards."""
    y = datetime.now().year
    out = []
    for i in range(max(1, int(depth)) + 1):
        out.append(max(2000, y - i))
    # Preserve order while removing duplicates.
    return list(dict.fromkeys(out))


def _load_fg_data_from_mlb_api():
    """Derive FG-compatible batting/pitching caches from the MLB Stats API
    *bulk* stats endpoint (`/stats?playerPool=all`).

    Using the bulk endpoint instead of 900+ per-player calls:
      * one API call for all pitchers, one for all hitters
      * ~2 seconds instead of 90 seconds
      * zero silent drops from rate limiting / timeouts
      * no `list index out of range` on empty splits

    Populates the same keys as pybaseball, so fg_pitcher()/fg_batter() lookups
    work without any downstream changes.
    """
    global _fg_bat, _fg_pit
    year = datetime.now().year
    logging.info("[FG] Starting MLB-API-derived load…")

    # Fetch every active player's batSide so the matchup projection can use
    # handedness.  One small call for the whole league.
    bat_side_by_name = {}
    try:
        r = requests.get(
            f"{MLB_API}/sports/1/players?season={year}&activeStatus=Y",
            timeout=20,
        )
        r.raise_for_status()
        for p in (r.json().get("people", []) or []):
            name = (p.get("fullName") or "").strip()
            if name:
                bat_side_by_name[name.lower()] = ((p.get("batSide") or {}).get("code") or "R")
        logging.info(f"[FG] {len(bat_side_by_name)} active players found")
    except Exception as ex:
        logging.warning(f"[FG-derived] player list failed: {ex}")

    def _fetch_bulk_splits(group_name):
        """Fetch MLB bulk stat splits with fallbacks for endpoint quirks."""
        seasons = _season_candidates(depth=4)
        variants = [
            {"gameType": "R", "sportId": 1},
            {"sportId": 1},
            {"gameType": "R"},
            {},
        ]
        for season in seasons:
            for variant in variants:
                params = {
                    "stats": "season",
                    "group": group_name,
                    "season": season,
                    "playerPool": "all",
                    "limit": 5000,
                    "min": 1,
                }
                params.update(variant)
                try:
                    r = requests.get(f"{MLB_API}/stats", params=params, timeout=45)
                    r.raise_for_status()
                    stats_groups = r.json().get("stats", []) or []
                    splits = stats_groups[0].get("splits", []) if stats_groups else []
                    if splits:
                        logging.info(f"[FG-derived] {group_name} splits={len(splits)} season={season}")
                        return splits, season
                    logging.info(f"[FG-derived] {group_name} empty season={season} — trying next variant")
                except requests.exceptions.Timeout:
                    logging.warning(f"[FG-derived] {group_name} TIMEOUT season={season} — trying next")
                except Exception as ex:
                    logging.warning(f"[FG-derived] {group_name} fetch failed season={season}: {ex}")
        return [], None

    # ── Pitchers (one bulk call) ──────────────────────────────────────────
    pit_out = {}
    splits, pit_season = _fetch_bulk_splits("pitching")
    if pit_season and pit_season != year:
        logging.info(f"[FG-derived] Using fallback pitching season {pit_season}")

    for row in splits:
        try:
            person = row.get("player") or {}
            pid    = person.get("id")
            name   = (person.get("fullName") or "").strip()
            if not name: continue
            s = row.get("stat") or {}
            if not s: continue

            era  = _safe_num(s.get("era"), 4.50)
            whip = _safe_num(s.get("whip"), 1.30)
            ip   = _safe_num(s.get("inningsPitched"), 0)
            k9   = _safe_num(s.get("strikeoutsPer9Inn"), 8.5)
            bb9  = _safe_num(s.get("walksPer9Inn"), 3.2)
            hr9  = _safe_num(s.get("homeRunsPer9"), 1.1)
            so   = _safe_num(s.get("strikeOuts"), 0)
            bb   = _safe_num(s.get("baseOnBalls"), 0)
            hr   = _safe_num(s.get("homeRuns"), 0)
            hits = _safe_num(s.get("hits"), 0)
            hbp  = _safe_num(s.get("hitByPitch"), 0)
            bf   = _safe_num(s.get("battersFaced"), 0)
            ab   = _safe_num(s.get("atBats"), 0)
            ao   = _safe_num(s.get("airOuts"), 0)
            go   = _safe_num(s.get("groundOuts"), 0)
            runs = _safe_num(s.get("runs"), 0)

            fip = (round((13*hr + 3*(bb + hbp) - 2*so) / ip + 3.10, 2)
                   if ip > 0 else round(era, 2))
            league_hrfb = 0.108
            fly_balls   = ao
            exp_hr = fly_balls * league_hrfb if fly_balls > 0 else hr
            xfip = (round((13*exp_hr + 3*(bb + hbp) - 2*so) / ip + 3.10, 2)
                    if ip > 0 else fip)

            pa_est  = bf if bf > 0 else max(ip * 4.3, 1)
            kpct_v  = round(so / pa_est, 3) if pa_est > 0 else 0.0
            bbpct_v = round(bb / pa_est, 3) if pa_est > 0 else 0.0

            bip_den = ab - so - hr
            babip_v = round(max(0.0, (hits - hr)) / bip_den, 3) if bip_den > 0 else 0.290

            lob_num = hits + bb + hbp - runs
            lob_den = hits + bb + hbp - 1.4*hr
            lob_v   = round(max(0.0, min(1.0, lob_num / lob_den)), 3) if lob_den > 0 else 0.72

            war_v = round(max(0.0, (4.00 - fip) * (ip / 9.0) * 0.11), 1)

            pit_out[name.lower()] = {
                "fg_era":   round(era, 2),
                "fg_fip":   fip,
                "fg_xfip":  xfip,
                "fg_whip":  round(whip, 2),
                "fg_k9":    round(k9, 2),
                "fg_bb9":   round(bb9, 2),
                "fg_hr9":   round(hr9, 2),
                "fg_kpct":  kpct_v,
                "fg_bbpct": bbpct_v,
                "fg_babip": babip_v,
                "fg_lob":   lob_v,
                "fg_war":   war_v,
                "fg_ip":    round(ip, 1),
                "fg_g":     int(_safe_num(s.get("gamesPlayed"),  0)),
                "fg_gs":    int(_safe_num(s.get("gamesStarted"), 0)),
                "fg_w":     int(_safe_num(s.get("wins"),   0)),
                "fg_l":     int(_safe_num(s.get("losses"), 0)),
                "fg_gb_pct": round(go / (go + ao), 3) if (go + ao) > 0 else 0.45,
            }
        except Exception as ex:
            logging.warning(f"[FG-pit-derived] pid={person.get('id') if 'person' in dir() else '?'}: {ex}")

    # ── Batters (one bulk call) ───────────────────────────────────────────
    bat_out = {}
    splits, bat_season = _fetch_bulk_splits("hitting")
    if bat_season and bat_season != year:
        logging.info(f"[FG-derived] Using fallback hitting season {bat_season}")

    for row in splits:
        try:
            person = row.get("player") or {}
            pid    = person.get("id")
            name   = (person.get("fullName") or "").strip()
            if not name: continue
            s = row.get("stat") or {}
            if not s: continue

            avg  = _safe_num(s.get("avg"), 0.0)
            obp  = _safe_num(s.get("obp"), 0.0)
            slg  = _safe_num(s.get("slg"), 0.0)
            ops  = _safe_num(s.get("ops"), round(obp + slg, 3))
            pa   = int(_safe_num(s.get("plateAppearances"), 0))
            ab   = _safe_num(s.get("atBats"), 0)
            so   = _safe_num(s.get("strikeOuts"), 0)
            bb   = _safe_num(s.get("baseOnBalls"), 0)
            hbp  = _safe_num(s.get("hitByPitch"), 0)
            hits = _safe_num(s.get("hits"), 0)
            hr   = _safe_num(s.get("homeRuns"), 0)
            dbl  = _safe_num(s.get("doubles"), 0)
            tpl  = _safe_num(s.get("triples"), 0)
            sf   = _safe_num(s.get("sacFlies"), 0)
            singles = max(0.0, hits - dbl - tpl - hr)

            woba_num = 0.696*bb + 0.726*hbp + 0.888*singles + 1.258*dbl + 1.599*tpl + 2.054*hr
            woba_den = ab + bb + sf + hbp
            woba = round(woba_num / woba_den, 3) if woba_den > 0 else 0.320
            wrc  = round(((woba - 0.320) / 1.15 + 0.325) / 0.325 * 100) if woba > 0 else 100
            bip_den = ab - so - hr + sf
            babip_v = round(max(0.0, (hits - hr)) / bip_den, 3) if bip_den > 0 else 0.295

            bat_out[name.lower()] = {
                "fg_avg":   round(avg, 3),
                "fg_obp":   round(obp, 3),
                "fg_slg":   round(slg, 3),
                "fg_ops":   round(ops, 3),
                "fg_woba":  woba,
                "fg_wrc":   wrc,
                "fg_pa":    pa,
                "fg_r":     int(_safe_num(s.get("runs"), 0)),
                "fg_hr":    int(hr),
                "fg_rbi":   int(_safe_num(s.get("rbi"), 0)),
                "fg_sb":    int(_safe_num(s.get("stolenBases"), 0)),
                "fg_war":   round(max(0.0, (woba - 0.320) * (pa / 600.0) * 6.0), 1) if pa > 0 else 0.0,
                "fg_babip": babip_v,
                "fg_bbpct": round(bb / pa, 3) if pa > 0 else 0.0,
                "fg_kpct":  round(so / pa, 3) if pa > 0 else 0.0,
                "fg_iso":   round(max(0.0, slg - avg), 3) if avg > 0 else 0.0,
                "fg_bats":  bat_side_by_name.get(name.lower(), "R"),
            }
        except Exception as ex:
            logging.warning(f"[FG-bat-derived] pid={person.get('id') if 'person' in dir() else '?'}: {ex}")

    with _fg_lock:
        _fg_pit = pit_out
        _fg_bat = bat_out
    logging.info(f"[FG] Done — {len(pit_out)} pitchers / {len(bat_out)} batters")
    logging.info(f"[FG] Cache ready — {len(pit_out)} P / {len(bat_out)} B")

def _maybe_refresh_fg():
    global _fg_loading
    with _fg_lock:
        # Atomically check and set _fg_loading so only one thread spawns a loader.
        if _fg_loading:
            return
        if _fg_loaded and _fg_load_date == datetime.now().date():
            return
        _fg_loading = True
    def _runner():
        global _fg_loading
        try:
            _load_fg_data()
        except Exception as _ex:
            logging.error(f"[FG] background load error: {_ex}")
        finally:
            with _fg_cond:
                _fg_loading = False
                _fg_cond.notify_all()
    threading.Thread(target=_runner, daemon=True).start()


# ── Pitch-type key mapping: FG pitching arsenal → FG batting run values ───────
# Each tuple is (pitcher_pct_col, batter_rv100_col)
_PITCH_FG_PAIRS = [
    ('pct_fa',  'rv_fa'),   # 4-seam fastball
    ('pct_ft',  'rv_ft'),   # 2-seam fastball
    ('pct_si',  'rv_si'),   # sinker
    ('pct_fc',  'rv_fc'),   # cutter
    ('pct_sl',  'rv_sl'),   # slider
    ('pct_st',  'rv_st'),   # sweeper
    ('pct_slo', 'rv_slo'),  # slurve
    ('pct_cu',  'rv_cu'),   # curveball
    ('pct_kc',  'rv_kc'),   # knuckle-curve
    ('pct_ch',  'rv_ch'),   # changeup
    ('pct_fs',  'rv_fs'),   # splitter
]


def _load_fg_historical():
    """
    Load all fg_batting_YYYY.csv and fg_pitching_YYYY.csv files from data/.
    Builds per-player-per-year stat records keyed by MLBAM int ID.
    Called once at startup in a background thread.
    """
    global _fg_bat_hist, _fg_pit_hist, _fg_hist_loaded

    data_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'data')

    def _sf(v):
        try:
            f = float(v)
            return None if (f != f) else f   # NaN → None
        except (TypeError, ValueError):
            return None

    def _strip(s):
        return _HTML_TAG_RE.sub('', s or '').strip()

    bat_hist = {}
    for path in sorted(_glob.glob(os.path.join(data_dir, 'fg_batting_*.csv'))):
        try:
            with open(path, newline='', encoding='utf-8-sig') as f:
                for row in csvmod.DictReader(f):
                    try:
                        mid = int(float(row['xMLBAMID']))
                        yr  = int(float(row['Season']))
                    except (KeyError, TypeError, ValueError):
                        continue
                    if mid not in bat_hist:
                        bat_hist[mid] = {}
                    bat_hist[mid][yr] = {
                        'name':    _strip(row.get('Name', '')),
                        'pa':      _sf(row.get('PA')),
                        'woba':    _sf(row.get('wOBA')),
                        'xwoba':   _sf(row.get('xwOBA')),
                        'avg':     _sf(row.get('AVG')),
                        'obp':     _sf(row.get('OBP')),
                        'slg':     _sf(row.get('SLG')),
                        'iso':     _sf(row.get('ISO')),
                        'kpct':    _sf(row.get('K%')),
                        'bbpct':   _sf(row.get('BB%')),
                        'hard_pct':_sf(row.get('Hard%')),
                        'wrc_plus':_sf(row.get('wRC+')),
                        # Per-pitch RV/100 (positive = batter above avg on that pitch)
                        'rv_fa':   _sf(row.get('pfxwFA/C')),
                        'rv_ft':   _sf(row.get('pfxwFT/C')),
                        'rv_si':   _sf(row.get('pfxwSI/C')),
                        'rv_fc':   _sf(row.get('pfxwFC/C')),
                        'rv_sl':   _sf(row.get('pfxwSL/C')),
                        'rv_st':   _sf(row.get('pfxwST/C')),
                        'rv_slo':  _sf(row.get('pfxwSLO/C')),
                        'rv_cu':   _sf(row.get('pfxwCU/C')),
                        'rv_kc':   _sf(row.get('pfxwKC/C')),
                        'rv_ch':   _sf(row.get('pfxwCH/C')),
                        'rv_fs':   _sf(row.get('pfxwFS/C')),
                    }
        except Exception as exc:
            logging.warning(f"[FG hist] batting load error {path}: {exc}")

    pit_hist = {}
    for path in sorted(_glob.glob(os.path.join(data_dir, 'fg_pitching_*.csv'))):
        try:
            with open(path, newline='', encoding='utf-8-sig') as f:
                for row in csvmod.DictReader(f):
                    try:
                        mid = int(float(row['xMLBAMID']))
                        yr  = int(float(row['Season']))
                    except (KeyError, TypeError, ValueError):
                        continue
                    if mid not in pit_hist:
                        pit_hist[mid] = {}
                    pit_hist[mid][yr] = {
                        'name':    _strip(row.get('Name', '')),
                        'ip':      _sf(row.get('IP')),
                        'era':     _sf(row.get('ERA')),
                        'fip':     _sf(row.get('FIP')),
                        'xfip':    _sf(row.get('xFIP')),
                        'xera':    _sf(row.get('xERA')),
                        'kpct':    _sf(row.get('K%')),
                        'bbpct':   _sf(row.get('BB%')),
                        # Arsenal mix (fractions 0–1)
                        'pct_fa':  _sf(row.get('pfxFA%')),
                        'pct_ft':  _sf(row.get('pfxFT%')),
                        'pct_si':  _sf(row.get('pfxSI%')),
                        'pct_fc':  _sf(row.get('pfxFC%')),
                        'pct_sl':  _sf(row.get('pfxSL%')),
                        'pct_st':  _sf(row.get('pfxST%')),
                        'pct_slo': _sf(row.get('pfxSLO%')),
                        'pct_cu':  _sf(row.get('pfxCU%')),
                        'pct_kc':  _sf(row.get('pfxKC%')),
                        'pct_ch':  _sf(row.get('pfxCH%')),
                        'pct_fs':  _sf(row.get('pfxFS%')),
                        # Velocities
                        'velo_fa': _sf(row.get('pfxvFA')),
                        'velo_sl': _sf(row.get('pfxvSL')),
                        'velo_st': _sf(row.get('pfxvST')),
                        'velo_si': _sf(row.get('pfxvSI')),
                    }
        except Exception as exc:
            logging.warning(f"[FG hist] pitching load error {path}: {exc}")

    with _fg_hist_lock:
        _fg_bat_hist.update(bat_hist)
        _fg_pit_hist.update(pit_hist)
        _fg_hist_loaded = True
    logging.info(f"[FG hist] {len(bat_hist)} batters / {len(pit_hist)} pitchers loaded from CSVs")


def _load_matchup_files():
    """
    Load the most recent mlb_matchups_YYYYMMDD.csv from data/.
    Indexes rows by (batter_id_str, pitcher_id_str) for O(1) lookup.
    Provides platoon splits + BvP H2H + batter quality metrics without API calls.
    """
    global _matchup_cache, _matchup_date_loaded

    data_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'data')
    files = sorted(_glob.glob(os.path.join(data_dir, 'mlb_matchups_*.csv')), reverse=True)
    if not files:
        return

    cache = {}
    for path in files[:2]:   # load the two most recent days
        try:
            with open(path, newline='', encoding='utf-8-sig') as f:
                for row in csvmod.DictReader(f):
                    bid = (row.get('batter_id') or '').strip()
                    pid = (row.get('pitcher_id') or '').strip()
                    if bid and pid:
                        cache.setdefault((bid, pid), row)   # earlier file wins on conflict
        except Exception as exc:
            logging.warning(f"[Matchup] load error {path}: {exc}")

    with _matchup_lock_local:
        _matchup_cache.clear()
        _matchup_cache.update(cache)
        _matchup_date_loaded = datetime.now().date()
    logging.info(f"[Matchup] {len(cache)} matchup rows loaded")


def _matchup_row(batter_id, pitcher_id):
    """Return the pre-computed matchup row for (batter_id, pitcher_id), or None."""
    key = (str(batter_id), str(pitcher_id))
    with _matchup_lock_local:
        return _matchup_cache.get(key)


def _fg_pitch_matchup_score(batter_mlbam, pitcher_mlbam):
    """
    Arsenal-based matchup score using FG per-pitch run-value data.

    Uses the pitcher's most recent-season pitch mix and a recency-weighted
    (2-year half-life) average of the batter's RV/100 against each pitch type.

    Returns (score_mult, breakdown):
        score_mult: 1.0 = league avg, >1.0 = batter-favorable
        breakdown: sorted list of {pitch, usage_pct, batter_rv100}
    """
    if not _fg_hist_loaded:
        return 1.0, []
    try:
        bid = int(batter_mlbam)
        pid = int(pitcher_mlbam)
    except (TypeError, ValueError):
        return 1.0, []

    with _fg_hist_lock:
        bat_years = dict(_fg_bat_hist.get(bid, {}))
        pit_years = dict(_fg_pit_hist.get(pid, {}))

    if not bat_years or not pit_years:
        return 1.0, []

    cur_year = datetime.now().year

    # Pitcher: use most recent season with ≥20 IP
    pit_entry = None
    for yr in sorted(pit_years.keys(), reverse=True):
        e = pit_years[yr]
        if (e.get('ip') or 0) >= 20:
            pit_entry = e
            break
    if not pit_entry:
        return 1.0, []

    # Batter: recency-weighted RV/100 per pitch type (2-year half-life, ≥50 PA)
    rv_num = {}
    rv_den = {}
    for yr, entry in bat_years.items():
        if (entry.get('pa') or 0) < 50:
            continue
        years_ago = max(0, cur_year - yr)
        if years_ago > 4:
            continue
        decay = 0.5 ** (years_ago / 2.0)
        for _, rv_key in _PITCH_FG_PAIRS:
            val = entry.get(rv_key)
            if val is not None:
                rv_num[rv_key] = rv_num.get(rv_key, 0.0) + val * decay
                rv_den[rv_key] = rv_den.get(rv_key, 0.0) + decay

    bat_rv = {k: rv_num[k] / rv_den[k] for k in rv_num if rv_den.get(k)}
    if not bat_rv:
        return 1.0, []

    # Weighted score: sum(pitcher_pct × batter_rv100) across arsenal
    total_rv  = 0.0
    total_pct = 0.0
    breakdown = []
    for pct_key, rv_key in _PITCH_FG_PAIRS:
        pct = pit_entry.get(pct_key) or 0.0
        if pct < 0.02:
            continue
        rv = bat_rv.get(rv_key, 0.0)   # missing → assume league avg (0)
        total_rv  += pct * rv
        total_pct += pct
        breakdown.append({
            'pitch':        pct_key.replace('pct_', '').upper(),
            'usage_pct':    round(pct * 100, 1),
            'batter_rv100': round(rv, 2),
        })

    if total_pct < 0.10:
        return 1.0, []

    # Convert weighted RV/100 to a multiplier.
    # Dividing by 25 maps a ±3.0 RV score to a ±12 % swing — conservative but meaningful.
    score_mult = max(0.70, min(1.30, 1.0 + total_rv / 25.0))
    return round(score_mult, 3), sorted(breakdown, key=lambda x: x['usage_pct'], reverse=True)


# Pitcher name -> MLBAM ID lookup, used by the arsenal-similarity BvP prior
# (_aggregate_vs_similar_pitchers) to convert "similar pitcher" names from
# _sv_arsenal_pct into the MLBAM IDs that pybaseball Statcast logs key on.
_pitcher_name_to_mlbam: dict = {}
_pitcher_name_to_mlbam_lock = threading.Lock()
_pitcher_name_to_mlbam_loaded = False

_FG_NAME_HTML_RE = re.compile(r"<[^>]+>")


def _ascii_fold(s):
    """Strip accents (Sánchez -> Sanchez) so name keys match across sources."""
    if not s:
        return s
    return "".join(
        c for c in unicodedata.normalize("NFKD", s)
        if not unicodedata.combining(c)
    )


def _load_pitcher_name_to_mlbam():
    """Build name -> MLBAM ID map from every fg_pitching_*.csv on disk.

    Scans all seasons because the current-year file is mid-season and may
    miss low-IP pitchers; older seasons fill those gaps. Newer seasons win
    on conflict (handles ID reuse / name changes).

    Registers BOTH the bare HTML-stripped Name (matches Savant ASCII keys)
    and the PlayerName (may carry accents) under _sv_key()-normalized
    lowercase keys, plus an ASCII-folded variant of each, so lookups work
    regardless of which spelling the caller passes.
    """
    global _pitcher_name_to_mlbam_loaded
    data_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'data')
    files = sorted(_glob.glob(os.path.join(data_dir, 'fg_pitching_*.csv')))  # oldest first
    if not files:
        logging.warning("[NameMap] no fg_pitching_*.csv files; arsenal prior disabled")
        return
    out = {}
    for path in files:
        try:
            with open(path, newline='', encoding='utf-8-sig') as f:
                for row in csvmod.DictReader(f):
                    mlbam = (row.get("xMLBAMID") or "").strip()
                    if not mlbam:
                        continue
                    try:
                        mid = int(mlbam)
                    except ValueError:
                        continue
                    # Name column is HTML-wrapped ("<a ...>Cameron Schlittler</a>");
                    # PlayerName is bare but may carry accents.
                    html_name = _FG_NAME_HTML_RE.sub("", row.get("Name") or "").strip()
                    player_name = (row.get("PlayerName") or "").strip()
                    for nm in {html_name, player_name}:
                        if not nm:
                            continue
                        # Newer files overwrite older ones (oldest scanned first).
                        out[_sv_key(nm)] = mid
                        out[_sv_key(_ascii_fold(nm))] = mid
        except Exception as ex:
            logging.warning(f"[NameMap] load error {os.path.basename(path)}: {ex}")
    if not out:
        return
    with _pitcher_name_to_mlbam_lock:
        _pitcher_name_to_mlbam.clear()
        _pitcher_name_to_mlbam.update(out)
        _pitcher_name_to_mlbam_loaded = True
    logging.info(f"[NameMap] {len(out)} pitcher name->MLBAM entries from {len(files)} season files")


# Batter profile lookup (mlbam_id -> {bats, name}) for the similar-batters
# pitcher-side prior. Loaded from fg_batting_*.csv (same multi-season scan
# pattern as the pitcher map above).
_batter_profiles: dict = {}
_batter_profiles_lock = threading.Lock()
_batter_profiles_loaded = False


def _load_batter_profiles():
    """Build mlbam_id -> {bats, name} map from fg_batting_*.csv files."""
    global _batter_profiles_loaded
    data_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'data')
    files = sorted(_glob.glob(os.path.join(data_dir, 'fg_batting_*.csv')))  # oldest first
    if not files:
        logging.warning("[BatterProfiles] no fg_batting_*.csv; pitcher-side prior disabled")
        return
    out = {}
    for path in files:
        try:
            with open(path, newline='', encoding='utf-8-sig') as f:
                for row in csvmod.DictReader(f):
                    mlbam = (row.get("xMLBAMID") or "").strip()
                    if not mlbam:
                        continue
                    try:
                        mid = int(mlbam)
                    except ValueError:
                        continue
                    bats = (row.get("Bats") or "").strip().upper() or None
                    name = (row.get("PlayerName") or "").strip()
                    if not name:
                        name = _FG_NAME_HTML_RE.sub("", row.get("Name") or "").strip()
                    if not name:
                        continue
                    # Newest file wins on conflict (handles handedness changes,
                    # e.g. switch hitters reclassified).
                    out[mid] = {"bats": bats, "name": name}
        except Exception as ex:
            logging.warning(f"[BatterProfiles] load error {os.path.basename(path)}: {ex}")
    if not out:
        return
    with _batter_profiles_lock:
        _batter_profiles.clear()
        _batter_profiles.update(out)
        _batter_profiles_loaded = True
    logging.info(f"[BatterProfiles] {len(out)} batter profiles from {len(files)} season files")


def _prewarm_pitcher_statcast():
    """Warm pybaseball Statcast cache for every probable starter today.

    The matchup CSV only contains pitchers with prior BvP history (~10 per
    slate); the full slate has ~30 probable starters. Pulling all of them
    up front means /api/matchup is hot for any (batter, pitcher) combo a
    user clicks into, not just the BvP-history pairs.

    Uses fetch_schedule() which already hydrates probablePitcher, so this
    is one MLB Stats API call to enumerate plus N pybaseball pulls (cached
    on disk via PYBASEBALL_CACHE=1).
    """
    try:
        today_str = datetime.now().strftime("%Y-%m-%d")
        games = fetch_schedule(today_str)
    except Exception as ex:
        logging.warning(f"[PitcherPriorWarm] schedule fetch failed: {ex}")
        return
    pitcher_ids = set()
    for g in games or []:
        teams = (g.get("teams") or {})
        for side in ("away", "home"):
            pp = ((teams.get(side) or {}).get("probablePitcher") or {})
            pid = pp.get("id")
            if pid:
                try:
                    pitcher_ids.add(int(pid))
                except (TypeError, ValueError):
                    pass
    if not pitcher_ids:
        logging.info("[PitcherPriorWarm] no probable starters; skipping")
        return
    logging.info(f"[PitcherPriorWarm] warming Statcast cache for {len(pitcher_ids)} starters")
    done = 0
    failed = 0
    with ThreadPoolExecutor(max_workers=4) as ex:
        futures = {ex.submit(_load_pitcher_statcast, pid): pid for pid in pitcher_ids}
        for fut in as_completed(futures):
            try:
                df = fut.result()
                if df is None or (hasattr(df, "empty") and df.empty):
                    failed += 1
                else:
                    done += 1
            except Exception:
                failed += 1
    logging.info(f"[PitcherPriorWarm] complete: {done} hit, {failed} miss out of {len(pitcher_ids)}")


def _prewarm_arsenal_priors():
    """After boot, warm pybaseball Statcast cache for today's slate batters.

    Idea: the first /api/matchup request per batter has to wait 4-8s for the
    cold pybaseball pull. By front-running these pulls in a background thread
    after boot, the user-facing latency drops to ~50ms (in-memory filter).

    Waits up to 60s for _matchup_cache to populate (the matchup CSV loader
    runs in its own boot thread), then dispatches the pulls 6-wide.
    """
    deadline = time.time() + 60
    while time.time() < deadline:
        with _matchup_lock_local:
            ready = bool(_matchup_cache)
        if ready:
            break
        time.sleep(2)
    with _matchup_lock_local:
        rows = list(_matchup_cache.values())
    batter_ids = set()
    for r in rows:
        bid_raw = (r.get('batter_id') or '').strip() if isinstance(r, dict) else ''
        if bid_raw and bid_raw.isdigit():
            batter_ids.add(int(bid_raw))
    if not batter_ids:
        logging.info("[ArsenalPriorWarm] no batter IDs in matchup cache; skipping")
        return
    logging.info(f"[ArsenalPriorWarm] warming Statcast cache for {len(batter_ids)} batters")
    done = 0
    failed = 0
    # We deliberately call the lazy loader here rather than touching the cache
    # dict directly — it handles disk-cache reuse via PYBASEBALL_CACHE=1 and
    # populates _batter_statcast_cache atomically.
    with ThreadPoolExecutor(max_workers=6) as ex:
        futures = {ex.submit(_load_batter_statcast, bid): bid for bid in batter_ids}
        for fut in as_completed(futures):
            try:
                df = fut.result()
                if df is None or (hasattr(df, "empty") and df.empty):
                    failed += 1
                else:
                    done += 1
            except Exception:
                failed += 1
            total = done + failed
            if total % 50 == 0:
                logging.info(f"[ArsenalPriorWarm] {total}/{len(batter_ids)} ({done} hit, {failed} miss)")
    logging.info(f"[ArsenalPriorWarm] complete: {done} hit, {failed} miss out of {len(batter_ids)}")


# Launch historical data loaders at startup. Deferred into a function and
# invoked at the very end of module load (see _launch_startup_loaders() call
# near the bottom) because several of these loaders reference functions defined
# later in this file (e.g. _sv_key, fetch_schedule). Starting the threads here
# raced module execution and intermittently raised NameError before those names
# were bound.
def _launch_startup_loaders():
    threading.Thread(target=_load_fg_historical, daemon=True).start()
    threading.Thread(target=_load_matchup_files, daemon=True).start()
    threading.Thread(target=_load_pitcher_name_to_mlbam, daemon=True).start()
    threading.Thread(target=_load_batter_profiles, daemon=True).start()
    threading.Thread(target=_prewarm_arsenal_priors,   daemon=True).start()
    threading.Thread(target=_prewarm_pitcher_statcast, daemon=True).start()
    threading.Thread(target=_load_team_defense,        daemon=True).start()


def _wait_for_fg_data(timeout_sec=30):
    """Wait for FG data to be loaded, blocking efficiently via Condition instead of busy-wait.

    Timeout raised to 30 s to survive Render cold-starts.
    Condition relaxed: passes if pitchers OR batters are loaded.
    """
    _maybe_refresh_fg()
    deadline = time.time() + timeout_sec
    while True:
        with _fg_cond:
            if _fg_loaded and (len(_fg_pit) > 0 or len(_fg_bat) > 0):
                return True
            remaining = deadline - time.time()
            if remaining <= 0:
                return False
            _fg_cond.wait(timeout=min(remaining, 5.0))
        # Re-trigger outside the lock if load failed and nothing is running.
        _maybe_refresh_fg()


def _wait_for_savant_data(timeout_sec=30):
    """Wait for Savant data to be loaded, blocking efficiently via Condition instead of busy-wait.

    Timeout raised to 30 s to survive Render cold-starts.
    Condition relaxed: passes if pitcherXStats OR batterXStats loaded.
    Arsenal failing alone no longer blocks every API call.
    """
    _maybe_refresh_savant()
    deadline = time.time() + timeout_sec
    while True:
        with _sv_cond:
            if _sv_loaded and (len(_sv_pit_xstats) > 0 or len(_sv_bat_xstats) > 0):
                return True
            remaining = deadline - time.time()
            if remaining <= 0:
                return False
            _sv_cond.wait(timeout=min(remaining, 5.0))
        # Re-trigger outside the lock if load failed and nothing is running.
        _maybe_refresh_savant()


_fuzzy_name_cache: dict = {}          # {(name_lower, dict_id): matched_key | ""}
_fuzzy_name_lock = threading.Lock()

def _fuzzy_lookup(name, cache, _dict_id=None):
    """Fuzzy name lookup with result caching.

    Pass _dict_id=id(underlying_dict) from the caller so the cache survives
    the dict copy but is invalidated automatically when the data is refreshed
    (the underlying dict object is replaced, changing its id).
    """
    if not name or not cache: return {}
    k = name.strip().lower()
    if k in cache: return cache[k]
    if _dict_id is not None:
        with _fuzzy_name_lock:
            matched = _fuzzy_name_cache.get((k, _dict_id))
        if matched is not None:
            return cache.get(matched, {})
    m = difflib.get_close_matches(k, cache.keys(), n=1, cutoff=0.78)
    matched = m[0] if m else ""
    if _dict_id is not None:
        with _fuzzy_name_lock:
            _evict_if_large(_fuzzy_name_cache, 5000)
            _fuzzy_name_cache[(k, _dict_id)] = matched
    return cache[matched] if matched else {}

def fg_batter(name):
    """FanGraphs batter stats with Brain overlay fallback.
    Live FG data wins any key conflict; brain fills gaps for missing/thin players.
    """
    with _fg_lock:
        c = dict(_fg_bat)
        _bat_id = id(_fg_bat)
    live = _fuzzy_lookup(name, c, _bat_id)
    try:
        from brain_merge_patch import _brain_fuzzy, _brain_bat_overlay as _bbo
        with _brain_overlay_lock:
            brain = _brain_fuzzy(name, _bbo)
    except Exception:
        brain = {}
    if not live and not brain:
        return {}
    if not live:
        return brain
    if brain:
        merged = dict(brain)
        merged.update(live)
        return merged
    return live

def fg_pitcher(name):
    """FanGraphs pitcher stats with Brain overlay fallback.
    Live FG data wins any key conflict; brain fills gaps for missing/thin players.
    """
    with _fg_lock:
        c = dict(_fg_pit)
        _pit_id = id(_fg_pit)
    live = _fuzzy_lookup(name, c, _pit_id)
    try:
        from brain_merge_patch import _brain_fuzzy, _brain_pit_overlay as _bpo
        with _brain_overlay_lock:
            brain = _brain_fuzzy(name, _bpo)
    except Exception:
        brain = {}
    if not live and not brain:
        return {}
    if not live:
        return brain
    if brain:
        merged = dict(brain)
        merged.update(live)
        return merged
    return live

# ── Baseball Savant Cache ─────────────────────────────────────────────────────
_sv_lock         = threading.Lock()
_sv_cond         = threading.Condition(_sv_lock)   # notified when Savant load completes
_sv_pit_xstats   = {}
_sv_bat_xstats   = {}
_sv_bat_statcast = {}
_sv_arsenal_pct       = {}
_sv_arsenal_velo      = {}
_sv_pit_arsenal_stats = {}  # {player_id_str: {pitch_name: {usage,ba,slg,woba,whiff_pct,hh_pct,k_pct,run_val}}}
_sv_bat_arsenal_stats = {}  # {player_id_str: {pitch_name: {slg,woba,whiff_pct,hh_pct}}}
_sv_loaded    = False
_sv_load_date = None
_sv_loading   = False

# Local pitcher arsenal cache loaded from data/ CSVs (populated once on first pitcher lookup)
# These are declared at module level so _pitcher_model does not need globals() tricks.
_local_arsenal_cache: object = None   # None → not yet loaded; tuple(dict, dict) → loaded
_local_arsenal_lock  = threading.Lock()

# Per-player direct Savant lookup cache {(player_id, year): (date, dict)}
_sv_player_batter_cache: dict = {}
_sv_player_batter_lock  = threading.Lock()

# ── Injury Cache (MLB transactions) ─────────────────────────────────────────
_injury_lock = threading.Lock()
_injury_cache = {}
_injury_last_refresh = None
_injury_loading = False
_injury_worker_started = False

# ── NRFI Cache (same-day, lineup-sensitive) ─────────────────────────────────
_nrfi_cache = {}

# ── Per-game correlation cache (same-day, lineup-sensitive) ────────────────
_correlation_cache = {}

