def _blank_batter_line(b):
    return {'id': b.get('id'), 'name': b.get('name', ''), 'slot': b.get('slot', 0), 'pos': b.get('pos', ''), 'bats': b.get('bats', 'S'), 'pa': 0, 'ab': 0, 'h': 0, '1b': 0, '2b': 0, '3b': 0, 'hr': 0, 'rbi': 0, 'r': 0, 'bb': 0, 'k': 0, 'tb': 0, 'sb': 0, 'cs': 0}


def _blank_pitcher_line(name):
    return {'name': name, 'outs': 0, 'h': 0, 'er': 0, 'bb': 0, 'k': 0, 'hr': 0}


def _advance_walk(bases, batter_idx, stats, pstats):
    runs = 0
    if bases[0] is not None and bases[1] is not None and bases[2] is not None:
        ridx = bases[2]; stats[ridx]['r'] += 1; stats[batter_idx]['rbi'] += 1; runs += 1; pstats['er'] += 1
    third = bases[1] if (bases[0] is not None and bases[1] is not None) else bases[2]
    second = bases[0] if bases[0] is not None else bases[1]
    first = batter_idx
    if bases[0] is not None and bases[1] is not None and bases[2] is not None:
        bases[:] = [first, second, third]
    elif bases[0] is not None and bases[1] is not None:
        bases[:] = [first, bases[0], bases[1]]
    elif bases[0] is not None:
        bases[:] = [first, bases[0], bases[2]]
    else:
        bases[0] = first
    return runs


def _advance_hit(event, bases, batter_idx, stats, pstats, rng, outs_before):
    runs = 0
    def score_runner(idx):
        nonlocal runs
        if idx is not None:
            stats[idx]['r'] += 1; stats[batter_idx]['rbi'] += 1; runs += 1; pstats['er'] += 1
    if event == '1b':
        if bases[2] is not None: score_runner(bases[2]); bases[2] = None
        if bases[1] is not None:
            if outs_before == 2 or rng.random() < 0.60:
                score_runner(bases[1]); bases[1] = None
        new_third = None
        if bases[0] is not None:
            if rng.random() < 0.38:
                new_third = bases[0]; bases[0] = None
            else:
                bases[1] = bases[0]; bases[0] = None
        if bases[1] is not None and new_third is None:
            bases[2] = bases[1]; bases[1] = None
        elif new_third is not None:
            bases[2] = new_third
        bases[0] = batter_idx
    elif event == '2b':
        if bases[2] is not None: score_runner(bases[2])
        if bases[1] is not None: score_runner(bases[1])
        new_third = None
        if bases[0] is not None:
            if rng.random() < 0.58: score_runner(bases[0])
            else: new_third = bases[0]
        bases[:] = [None, batter_idx, new_third]
    elif event == '3b':
        for idx in list(bases):
            if idx is not None: score_runner(idx)
        bases[:] = [None, None, batter_idx]
    elif event == 'hr':
        for idx in list(bases):
            if idx is not None: score_runner(idx)
        score_runner(batter_idx)
        bases[:] = [None, None, None]
    return runs


# ── Catcher Pop Time (Baseball Savant) ───────────────────────────────────────
# Pop time = seconds from pitch contact → catcher release → 2B glove.
# League average ~2.00s. Sub-1.90s = elite (e.g. Contreras). 2.10s+ = weak.
# Loaded from Baseball Savant catcher pop time leaderboard at startup.
# key: lowercase catcher name  →  value: float avg pop time
_CATCHER_POP_CACHE: dict[str, float] = {}
_LEAGUE_POP_AVG = 2.00

def _catcher_sb_mult(catcher_name: str) -> float:
    """
    Scale SB success probability based on catcher pop time.
    Fast arm (1.88s): suppresses SB ~30%. Slow arm (2.12s): boosts ~30%.
    Neutral (2.00s): returns 1.0.
    """
    pop = _CATCHER_POP_CACHE.get((catcher_name or '').lower().strip(), _LEAGUE_POP_AVG)
    delta = _LEAGUE_POP_AVG - pop   # positive = fast arm = suppresses steals
    return min(1.35, max(0.65, 1.0 - delta * 2.5))

def _maybe_steal(bases, lineup, stats, rng, probs_map, outs):
    if outs >= 2:
        return 0
    if bases[0] is not None and bases[1] is None:
        ridx = bases[0]
        pr = probs_map.get(ridx, {})
        if rng.random() < pr.get('steal_rate', 0.0):
            _catcher = pr.get('opp_catcher', '')
            _pop_mult = _catcher_sb_mult(_catcher)
            _adj_success = min(0.95, max(0.35, pr.get('steal_success', 0.72) * _pop_mult))
            if rng.random() < _adj_success:
                bases[1] = ridx; bases[0] = None; stats[ridx]['sb'] += 1
                return 1
            else:
                bases[0] = None; stats[ridx]['cs'] += 1
                return -1
    if bases[1] is not None and bases[2] is None and outs == 0:
        ridx = bases[1]
        pr = probs_map.get(ridx, {})
        if rng.random() < pr.get('steal_rate', 0.0) * 0.30:
            _catcher2 = pr.get('opp_catcher', '')
            _pop_mult2 = _catcher_sb_mult(_catcher2)
            if rng.random() < min(0.90, max(0.30, (pr.get('steal_success', 0.72) - 0.08) * _pop_mult2)):
                bases[2] = ridx; bases[1] = None; stats[ridx]['sb'] += 1
                return 1
            else:
                bases[1] = None; stats[ridx]['cs'] += 1
                return -1
    return 0


def _select_relief_tier(inning, runs_allowed, starter_outs, tiers):
    if inning >= 8 and runs_allowed <= 4:
        return tiers['closer']
    if inning >= 7 and runs_allowed <= 5:
        return tiers['setup']
    if starter_outs >= 18 and inning >= 6:
        return tiers['setup']
    return tiers['middle']


def _team_relief_fatigue_woba(team_id: int) -> float:
    """
    Best-effort computation of team bullpen fatigue wOBA penalty.
    Uses the last 3 days of relief appearances; returns 0.0 on any error.
    """
    try:
        recent = _team_recent_games(team_id, 3)
        if not recent:
            return 0.0
        report = _build_bullpen_fatigue(team_id, '', recent)
        penalties = []
        for rel in report.get('relievers', []):
            dp = rel.get('days_pitched') or []
            pl = rel.get('pitches_total') or 0
            p = relief_fatigue_penalty(dp, min(pl, 35))
            if p > 0:
                penalties.append(p)
        if not penalties:
            return 0.0
        return round(sum(penalties) / len(penalties), 4)
    except Exception:
        return 0.0


# Day-level cache for the relief-fatigue penalty. The full computation fetches
# each team's recent boxscores, so we never run it inline on a latency-sensitive
# projection path — _relief_fatigue_penalty_cached warms it in the background and
# returns 0.0 until ready (the projection refines on the next render), mirroring
# the FG/Savant "responsive now, refresh later" pattern used elsewhere.
_relief_fatigue_cache: dict = {}
_relief_fatigue_lock = threading.Lock()
_relief_fatigue_warming: set = set()


def _relief_fatigue_penalty_cached(team_id):
    if not team_id:
        return 0.0
    today = datetime.now(ET).date().isoformat()
    key = (int(team_id), today)
    with _relief_fatigue_lock:
        if key in _relief_fatigue_cache:
            return _relief_fatigue_cache[key]
        if key in _relief_fatigue_warming:
            return 0.0
        _relief_fatigue_warming.add(key)

    def _warm():
        try:
            val = _team_relief_fatigue_woba(team_id)
        except Exception:
            val = 0.0
        with _relief_fatigue_lock:
            _relief_fatigue_cache[key] = val
            _relief_fatigue_warming.discard(key)

    threading.Thread(target=_warm, daemon=True).start()
    return 0.0


def _bullpen_run_boost(opp_pen):
    """Runs added to a team's projection from facing a fatigued opposing bullpen.
    The opponent's relief-fatigue wOBA penalty applied over ~14 relief PA, scaled
    to runs and clamped to +0.5 so a gassed pen nudges rather than dominates. Only
    ever positive — fatigue inflates late scoring; a fresh pen contributes 0."""
    try:
        return round(min(0.5, max(0.0, float(opp_pen) * 11.7)), 2)
    except Exception:
        return 0.0


def _simulate_offense(lineup, opp_starter, opp_team_id, park, rng, batx_map=None,
                      wx_mults=None, ump_adj=None, relief_fatigue_woba: float = 0.0):
    """
    batx_map: dict {batter_index: batx_dict} pre-computed by _batx_for_sim().
    When provided, BAT X multipliers are applied to _derive_probs() output for
    every PA, making each simulated at-bat matchup-aware (platoon, form, BvP, etc).
    """
    stats = [_blank_batter_line(b) for b in lineup]
    starter_line = _blank_pitcher_line(opp_starter['name'])
    tiers = _bullpen_tiers(opp_starter, opp_team_id)
    relief_lines = {'Closer': _blank_pitcher_line('Closer'), 'Setup': _blank_pitcher_line('Setup'), 'Middle': _blank_pitcher_line('Middle')}
    starter_target = _starter_outs_target(opp_starter, rng)
    runs = 0; batter_ptr = 0
    pitcher_batters_faced = {}
    pitcher_pitch_counts = {}
    arsenal_cache = {}

    def _arsenal_size(pitcher_model):
        pitcher_name = pitcher_model.get('name', '')
        if pitcher_name in arsenal_cache:
            return arsenal_cache[pitcher_name]
        arsenal = (sv_pitcher(pitcher_name).get('sv_arsenal_pct') or {}) if pitcher_name else {}
        arsenal_size = len(arsenal.keys()) if isinstance(arsenal, dict) and arsenal else 3
        arsenal_cache[pitcher_name] = arsenal_size or 3
        return arsenal_cache[pitcher_name]

    _is_relief = {False}  # mutable flag: True once starter exits

    def _pa_probs(batter, pitcher_model, batx_adjustments, is_relief=False):
        pitcher_name = pitcher_model.get('name', 'Unknown')
        batters_faced = pitcher_batters_faced.get(pitcher_name, 0)
        pitches_thrown = pitcher_pitch_counts.get(pitcher_name, 0)
        ttop_val = ttop_woba_penalty(batters_faced, pitches_thrown, _arsenal_size(pitcher_model))
        # Apply bullpen fatigue wOBA penalty for relief appearances
        extra_penalty = relief_fatigue_woba if is_relief else 0.0
        probs = derive_probs_v2(
            batter,
            pitcher_model,
            park,
            batx=batx_adjustments,
            wx_mults=wx_mults,
            ump_adj=ump_adj,
            ttop_penalty_val=ttop_val + extra_penalty,
        )
        pitcher_batters_faced[pitcher_name] = batters_faced + 1
        pitcher_pitch_counts[pitcher_name] = pitches_thrown + 5
        return _normalize_pa_probs(probs)

    # Pre-compute probs against starter with BAT X; relief uses same BAT X but fresh probs
    probs_cache = {}
    for i, b in enumerate(lineup):
        bx = batx_map.get(i) if batx_map else None
        probs_cache[i] = _pa_probs(b, opp_starter, bx, is_relief=False)
    for inning in range(1, 10):
        outs = 0
        bases = [None, None, None]
        while outs < 3:
            steal_outcome = _maybe_steal(bases, lineup, stats, rng, probs_cache, outs)
            if steal_outcome == -1:
                outs += 1
                if starter_line['outs'] < starter_target:
                    starter_line['outs'] += 1
                else:
                    tier0 = _select_relief_tier(inning, runs, starter_line['outs'], tiers)
                    relief_lines[tier0['name']]['outs'] += 1
                if outs >= 3:
                    break
            b = lineup[batter_ptr]
            s = stats[batter_ptr]
            _starter_pitches = pitcher_pitch_counts.get(opp_starter.get('name', ''), 0)
            _pitch_limit = 100 + (5 if _safe_f(opp_starter.get('fg_ip'), 0) > 120 else 0)  # 100 avg, 105 workhorse
            use_starter = (starter_line['outs'] < starter_target) and (_starter_pitches < _pitch_limit)
            if use_starter:
                pm = opp_starter
                pl = starter_line
            else:
                pm = _select_relief_tier(inning, runs, starter_line['outs'], tiers)
                pl = relief_lines[pm['name']]
            bx = batx_map.get(batter_ptr) if batx_map else None
            probs = _pa_probs(b, pm, bx, is_relief=not use_starter)
            probs = apply_base_state_mult(probs, base_state_pa_mult(bases, outs))
            probs_cache[batter_ptr] = probs
            ev = _pick_event(probs, rng)
            s['pa'] += 1
            if ev == 'bb':
                s['bb'] += 1; pl['bb'] += 1
                runs += _advance_walk(bases, batter_ptr, stats, pl)
            elif ev in ('1b', '2b', '3b', 'hr'):
                s['ab'] += 1; s['h'] += 1; pl['h'] += 1
                if ev == '1b': s['1b'] += 1; s['tb'] += 1
                elif ev == '2b': s['2b'] += 1; s['tb'] += 2
                elif ev == '3b': s['3b'] += 1; s['tb'] += 3
                elif ev == 'hr': s['hr'] += 1; s['tb'] += 4; pl['hr'] += 1
                runs += advance_runners_markov(ev, bases, batter_ptr, stats, pl, rng, outs)
            else:
                s['ab'] += 1; outs += 1; pl['outs'] += 1
                if ev == 'k': s['k'] += 1; pl['k'] += 1
            batter_ptr = (batter_ptr + 1) % len(lineup)
    bullpen_tot = _blank_pitcher_line('Bullpen')
    for rl in relief_lines.values():
        bullpen_tot['outs'] += rl['outs']; bullpen_tot['h'] += rl['h']; bullpen_tot['er'] += rl['er']; bullpen_tot['bb'] += rl['bb']; bullpen_tot['k'] += rl['k']; bullpen_tot['hr'] += rl['hr']
    return {
        'batters': stats,
        'starter': starter_line,
        'bullpen': bullpen_tot,
        'relief_lines': relief_lines,
        'bullpen_models': tiers,
        'runs': runs,
        'hits': sum(x['h'] for x in stats),
        'bb': sum(x['bb'] for x in stats),
        'k': sum(x['k'] for x in stats),
        'tb': sum(x['tb'] for x in stats),
        'sb': sum(x['sb'] for x in stats),
    }


def _summarize_player(lines):
    def arr(k): return [x[k] for x in lines]
    hits = arr('h'); hr = arr('hr'); rbi = arr('rbi'); runs = arr('r'); bb = arr('bb'); k = arr('k'); tb = arr('tb'); sb = arr('sb')
    hrr = [(x.get('h', 0) + x.get('r', 0) + x.get('rbi', 0)) for x in lines]
    return {
        'mean_hits': round(statistics.mean(hits), 3), 'median_hits': statistics.median(hits),
        'mean_hr': round(statistics.mean(hr), 3), 'mean_rbi': round(statistics.mean(rbi), 3),
        'mean_runs': round(statistics.mean(runs), 3), 'mean_bb': round(statistics.mean(bb), 3),
        'mean_k': round(statistics.mean(k), 3), 'mean_tb': round(statistics.mean(tb), 3), 'mean_sb': round(statistics.mean(sb), 3),
        'mean_hrr': round(statistics.mean(hrr), 3),
        'p10_hits': round(_pct(hits, 0.10), 2), 'p50_hits': round(_pct(hits, 0.50), 2), 'p90_hits': round(_pct(hits, 0.90), 2),
        'p10_tb': round(_pct(tb, 0.10), 2), 'p50_tb': round(_pct(tb, 0.50), 2), 'p90_tb': round(_pct(tb, 0.90), 2),
        'p10_k': round(_pct(k, 0.10), 2), 'p50_k': round(_pct(k, 0.50), 2), 'p90_k': round(_pct(k, 0.90), 2),
        'p_1plus_hit': round(sum(1 for x in hits if x >= 1) / len(hits), 3),
        'p_2plus_hit': round(sum(1 for x in hits if x >= 2) / len(hits), 3),
        'p_1plus_hr': round(sum(1 for x in hr if x >= 1) / len(hr), 3),
        'p_1plus_rbi': round(sum(1 for x in rbi if x >= 1) / len(rbi), 3),
        'p_1plus_run': round(sum(1 for x in runs if x >= 1) / len(runs), 3),
        'p_2plus_tb': round(sum(1 for x in tb if x >= 2) / len(tb), 3),
        'p_1plus_bb': round(sum(1 for x in bb if x >= 1) / len(bb), 3),
        'p_1plus_k': round(sum(1 for x in k if x >= 1) / len(k), 3),
        'p_1plus_sb': round(sum(1 for x in sb if x >= 1) / len(sb), 3),
        'p_2plus_hrr': round(sum(1 for x in hrr if x >= 2) / len(hrr), 3),
        'p_3plus_hrr': round(sum(1 for x in hrr if x >= 3) / len(hrr), 3),
        'p_4plus_hrr': round(sum(1 for x in hrr if x >= 4) / len(hrr), 3),
    }


def _summarize_pitcher(lines):
    def arr(k): return [x[k] for x in lines]
    outs = arr('outs'); er = arr('er'); ks = arr('k'); hs = arr('h'); bbs = arr('bb')
    return {
        'mean_outs': round(statistics.mean(outs), 2), 'median_outs': statistics.median(outs),
        'mean_er': round(statistics.mean(er), 2), 'mean_k': round(statistics.mean(ks), 2),
        'mean_h': round(statistics.mean(hs), 2), 'mean_bb': round(statistics.mean(bbs), 2),
        'p10_outs': round(_pct(outs, 0.10), 2), 'p50_outs': round(_pct(outs, 0.50), 2), 'p90_outs': round(_pct(outs, 0.90), 2),
        'p10_k': round(_pct(ks, 0.10), 2), 'p50_k': round(_pct(ks, 0.50), 2), 'p90_k': round(_pct(ks, 0.90), 2),
        'p10_er': round(_pct(er, 0.10), 2), 'p50_er': round(_pct(er, 0.50), 2), 'p90_er': round(_pct(er, 0.90), 2),
        'p_12plus_outs': round(sum(1 for x in outs if x >= 12)/len(outs), 3),
        'p_15plus_outs': round(sum(1 for x in outs if x >= 15)/len(outs), 3),
        'p_18plus_outs': round(sum(1 for x in outs if x >= 18)/len(outs), 3),
        'p_4plus_k': round(sum(1 for x in ks if x >= 4)/len(ks), 3),
        'p_5plus_k': round(sum(1 for x in ks if x >= 5)/len(ks), 3),
        'p_6plus_k': round(sum(1 for x in ks if x >= 6)/len(ks), 3),
        'p_2plus_er': round(sum(1 for x in er if x >= 2)/len(er), 3),
        'p_3plus_er': round(sum(1 for x in er if x >= 3)/len(er), 3),
    }


def _pearson_corr(xs, ys):
    if not xs or not ys or len(xs) != len(ys):
        return 0.0
    n = len(xs)
    if n < 2:
        return 0.0
    mx = sum(xs) / n
    my = sum(ys) / n
    num = 0.0
    dx2 = 0.0
    dy2 = 0.0
    for x, y in zip(xs, ys):
        dx = x - mx
        dy = y - my
        num += dx * dy
        dx2 += dx * dx
        dy2 += dy * dy
    den = (dx2 * dy2) ** 0.5
    if den <= 1e-12:
        return 0.0
    return max(-1.0, min(1.0, num / den))


def _corr_strength_label(r):
    if r >= 0.55:
        return 'STRONG+'
    if r >= 0.25:
        return 'CORRELATED'
    if r <= -0.45:
        return 'STRONG-'
    if r <= -0.20:
        return 'NEGATIVE'
    return 'NEUTRAL'


def _corr_warning(row_a, row_b, r):
    if r > -0.25:
        return None
    mk_a = row_a.get('market')
    mk_b = row_b.get('market')
    if (
        mk_a == 'pitcher_strikeouts' and mk_b in {'batter_hits', 'batter_total_bases', 'batter_runs', 'batter_rbis'}
    ) or (
        mk_b == 'pitcher_strikeouts' and mk_a in {'batter_hits', 'batter_total_bases', 'batter_runs', 'batter_rbis'}
    ):
        if row_a.get('team') and row_b.get('team') and row_a.get('team') != row_b.get('team'):
            return 'High K game suppresses opposing contact outcomes'
    if r <= -0.45:
        return 'Strong negative relationship can reduce same-game parlay hit rate'
    return 'Negative correlation warning for combined legs'


def _game_lineup_signature(game_obj, away_lineup, home_lineup):
    away_pitcher = ((game_obj or {}).get('teams', {}).get('away', {}).get('probablePitcher', {}) or {}).get('fullName', '')
    home_pitcher = ((game_obj or {}).get('teams', {}).get('home', {}).get('probablePitcher', {}) or {}).get('fullName', '')
    away_names = ','.join((p.get('name') or p.get('fullName') or '').strip() for p in (away_lineup or [])[:9])
    home_names = ','.join((p.get('name') or p.get('fullName') or '').strip() for p in (home_lineup or [])[:9])
    return f"{away_pitcher}|{home_pitcher}|{away_names}|{home_names}"


def _simulation_fallback_payload(game_obj, game_pk, sims=0, warning=''):
    """Build a minimal-but-valid simulation response when full Monte Carlo fails."""
    g = game_obj or {}
    away_t = (g.get('teams', {}).get('away', {}) or {}).get('team', {}) or {}
    home_t = (g.get('teams', {}).get('home', {}) or {}).get('team', {}) or {}
    away_abbr = away_t.get('abbreviation', 'AWAY')
    home_abbr = home_t.get('abbreviation', 'HOME')
    away_name = ((g.get('teams', {}).get('away', {}) or {}).get('probablePitcher', {}) or {}).get('fullName', 'Away SP')
    home_name = ((g.get('teams', {}).get('home', {}) or {}).get('probablePitcher', {}) or {}).get('fullName', 'Home SP')

    lineups = g.get('lineups') or {}

    # Try to source actual batters: prefer schedule-hydrated lineups, then active roster.
    def _from_schedule(hitters):
        out = []
        for p in hitters or []:
            pid = p.get('id') or p.get('playerId')
            nm = (p.get('fullName') or p.get('name') or '').strip()
            if not pid or not nm:
                continue
            out.append({'id': pid, 'name': nm,
                        'pos': ((p.get('primaryPosition') or {}).get('abbreviation') or '?')})
            if len(out) >= 9:
                break
        return out

    def _from_roster(team_id):
        out = []
        if not team_id:
            return out
        try:
            for entry in _get_active_roster(team_id):
                pos = ((entry.get('position') or {}).get('abbreviation') or '?')
                if pos in ('P', 'SP', 'RP', 'CP'):
                    continue
                person = entry.get('person') or {}
                pid = person.get('id')
                nm = (person.get('fullName') or '').strip()
                if not pid or not nm:
                    continue
                out.append({'id': pid, 'name': nm, 'pos': pos})
                if len(out) >= 9:
                    break
        except Exception:
            pass
        return out

    away_roster = _from_schedule(lineups.get('awayBatters')) or _from_roster(away_t.get('id'))
    home_roster = _from_schedule(lineups.get('homeBatters')) or _from_roster(home_t.get('id'))

    # Pre-warm bio cache in parallel so handedness counts reflect real lineup makeup.
    _missing_pids = [b.get('id') for b in (away_roster + home_roster)
                     if b.get('id') and b.get('id') not in _bio_cache]
    if _missing_pids:
        try:
            with ThreadPoolExecutor(max_workers=min(len(_missing_pids), 9)) as _pool:
                list(_pool.map(player_profile, _missing_pids))
        except Exception:
            pass

    def _hand_counts(roster):
        counts = {'L': 0, 'R': 0, 'S': 0}
        for b in roster:
            pid = b.get('id')
            bats = (_bio_cache.get(pid) or {}).get('bats') or 'S'
            bats = bats if bats in counts else 'S'
            counts[bats] += 1
        return counts

    away_hand_counts = _hand_counts(away_roster)
    home_hand_counts = _hand_counts(home_roster)

    away_batters = [{
        'slot': i + 1, 'id': b.get('id'), 'name': b.get('name'), 'pos': b.get('pos'),
        'bats': (_bio_cache.get(b.get('id')) or {}).get('bats', 'S'),
        'ab': 4, 'h': 1, 'hr': 0, 'rbi': 0, 'r': 0, 'bb': 0, 'k': 1, 'tb': 1,
    } for i, b in enumerate(away_roster[:9])]
    home_batters = [{
        'slot': i + 1, 'id': b.get('id'), 'name': b.get('name'), 'pos': b.get('pos'),
        'bats': (_bio_cache.get(b.get('id')) or {}).get('bats', 'S'),
        'ab': 4, 'h': 1, 'hr': 0, 'rbi': 0, 'r': 0, 'bb': 0, 'k': 1, 'tb': 1,
    } for i, b in enumerate(home_roster[:9])]

    return {
        'success': True,
        'fallback': True,
        'warning': warning or 'Simulation fallback returned due to upstream data issue.',
        'meta': {
            'sims': int(sims or 0),
            'awayAbbr': away_abbr,
            'homeAbbr': home_abbr,
            'parkFactor': PARK_FACTORS.get(home_t.get('id'), 1.0),
            'gamePk': game_pk,
        },
        'team': {
            'away_mean_runs': 4.2,
            'home_mean_runs': 4.3,
            'mean_total': 8.5,
            'median_total': 8.0,
            'p_8plus_total': 0.53,
            'p_9plus_total': 0.46,
            'p_10plus_total': 0.35,
            'away_win_pct': 0.48,
            'home_win_pct': 0.49,
            'tie_pct': 0.03,
        },
        'handedness': {
            'awayLineup': away_hand_counts,
            'homeLineup': home_hand_counts,
            'awayStarterHand': 'R',
            'homeStarterHand': 'R',
        },
        'playerProps': {'away': [], 'home': []},
        'pitcherProps': {
            'awayStarter': {'name': away_name, 'mean_k': 0, 'mean_outs': 0, 'mean_er': 0, 'mean_h': 0, 'mean_bb': 0},
            'homeStarter': {'name': home_name, 'mean_k': 0, 'mean_outs': 0, 'mean_er': 0, 'mean_h': 0, 'mean_bb': 0},
            'awayBullpen': {'name': away_abbr + ' Bullpen', 'mean_k': 0, 'mean_outs': 0, 'mean_er': 0, 'mean_h': 0, 'mean_bb': 0},
            'homeBullpen': {'name': home_abbr + ' Bullpen', 'mean_k': 0, 'mean_outs': 0, 'mean_er': 0, 'mean_h': 0, 'mean_bb': 0},
            'awayBullpenTiers': {'closer': {}, 'setup': {}, 'middle': {}},
            'homeBullpenTiers': {'closer': {}, 'setup': {}, 'middle': {}},
        },
        'correlations': [],
        'top_sgp_combos': [],
        'sampleBoxscore': {
            'away': {'batters': away_batters, 'runs': 4, 'hits': 8, 'bb': 3, 'k': 8},
            'home': {'batters': home_batters, 'runs': 4, 'hits': 8, 'bb': 3, 'k': 8},
            'away_abbr': away_abbr,
            'home_abbr': home_abbr,
            'away_pitcher': away_name,
            'home_pitcher': home_name,
        },
        'projectedBoxscore': {
            'away': {'batters': [], 'mean_runs': 4.2, 'mean_hits': 8.0, 'mean_bb': 3.0, 'mean_k': 8.0, 'mean_tb': 13.0},
            'home': {'batters': [], 'mean_runs': 4.3, 'mean_hits': 8.0, 'mean_bb': 3.0, 'mean_k': 8.0, 'mean_tb': 13.0},
            'away_abbr': away_abbr,
            'home_abbr': home_abbr,
            'away_pitcher': away_name,
            'home_pitcher': home_name,
            'sims': int(sims or 0),
        },
    }


def _pctl(arr, p):
    """Linear-interpolated percentile of a numeric list (p in 0–100)."""
    if not arr:
        return 0.0
    s = sorted(arr)
    if len(s) == 1:
        return float(s[0])
    k = (len(s) - 1) * (p / 100.0)
    lo = int(k)
    hi = min(lo + 1, len(s) - 1)
    return float(s[lo] + (s[hi] - s[lo]) * (k - lo))


def _do_simulate(game_pk, sims):
    """Core simulation logic, extracted so it can run in a background thread.
    Returns a plain dict (not a Flask Response)."""
    try:
        sims = max(1500, min(5000, int(sims) if sims else 5000))

        # Prefer direct game lookup so deep-dive works for non-today game IDs too.
        g = fetch_schedule_game(game_pk)
        if not g:
            raw = fetch_schedule(datetime.now(ET).strftime('%Y-%m-%d'))
            g = next((x for x in raw if x.get('gamePk') == game_pk), None)
        if not g:
            fallback = _simulation_fallback_payload(
                {},
                game_pk,
                sims=sims,
                warning='Game not found for simulation; returned fallback payload.'
            )
            return fallback
        away_team = g.get('teams', {}).get('away', {}).get('team', {})
        home_team = g.get('teams', {}).get('home', {}).get('team', {})
        away_team_id = away_team.get('id')
        home_team_id = home_team.get('id')

        box = {}
        try:
            r_box = requests.get(f"{MLB_API}/game/{game_pk}/boxscore", timeout=10)
            if r_box.ok:
                box = (r_box.json() or {}).get('teams', {}) or {}
        except Exception:
            box = {}
        away_lineup = get_batters_from_boxscore(box.get('away', {}), 'away')
        home_lineup = get_batters_from_boxscore(box.get('home', {}), 'home')

        def _parse_sched_lineup(hitters):
            out = []
            for i, p in enumerate(hitters or [], start=1):
                name = (p.get('fullName') or p.get('name') or '').strip()
                pid = p.get('id') or p.get('playerId')
                pos = (p.get('primaryPosition') or {}).get('abbreviation', '?')
                if not name:
                    continue
                fgb = fg_batter(name)
                svb = sv_batter(name)
                bio = _bio_cache.get(pid) or {}
                out.append({
                    'slot': i,
                    'id': pid,
                    'name': name,
                    'pos': pos,
                    'bats': bio.get('bats', 'R'),
                    'avg': fgb.get('fg_avg', '.---'),
                    'obp': fgb.get('fg_obp', '.---'),
                    'slg': fgb.get('fg_slg', '.---'),
                    'ops': fgb.get('fg_ops', '.---'),
                    'fg_sb': fgb.get('fg_sb', 0),
                    'fg_woba': fgb.get('fg_woba', 'N/A'),
                    'fg_wrc': fgb.get('fg_wrc', 'N/A'),
                    'sv_xba': svb.get('sv_xba', 'N/A'),
                    'sv_xslg': svb.get('sv_xslg', 'N/A'),
                    'sv_xwoba': svb.get('sv_xwoba', 'N/A'),
                    'sv_ev': svb.get('sv_ev', 'N/A'),
                    'sv_hh_pct': svb.get('sv_hh_pct', 'N/A'),
                    'sv_brl_pct': svb.get('sv_brl_pct', 'N/A'),
                })
            return out

        def _roster_lineup(team_id):
            if not team_id:
                return []
            try:
                out = []
                for entry in _get_active_roster(team_id):
                    pos = ((entry.get('position') or {}).get('abbreviation') or '?')
                    if pos in ('P', 'SP', 'RP', 'CP'):
                        continue
                    name = ((entry.get('person') or {}).get('fullName') or '').strip()
                    pid = (entry.get('person') or {}).get('id')
                    if not name:
                        continue
                    fgb = fg_batter(name)
                    svb = sv_batter(name)
                    bio = _bio_cache.get(pid) or {}
                    out.append({
                        'slot': len(out) + 1,
                        'id': pid,
                        'name': name,
                        'pos': pos,
                        'bats': bio.get('bats', 'R'),
                        'avg': fgb.get('fg_avg', '.---'),
                        'obp': fgb.get('fg_obp', '.---'),
                        'slg': fgb.get('fg_slg', '.---'),
                        'ops': fgb.get('fg_ops', '.---'),
                        'fg_sb': fgb.get('fg_sb', 0),
                        'fg_woba': fgb.get('fg_woba', 'N/A'),
                        'fg_wrc': fgb.get('fg_wrc', 'N/A'),
                        'sv_xba': svb.get('sv_xba', 'N/A'),
                        'sv_xslg': svb.get('sv_xslg', 'N/A'),
                        'sv_xwoba': svb.get('sv_xwoba', 'N/A'),
                        'sv_ev': svb.get('sv_ev', 'N/A'),
                        'sv_hh_pct': svb.get('sv_hh_pct', 'N/A'),
                        'sv_brl_pct': svb.get('sv_brl_pct', 'N/A'),
                    })
                    if len(out) >= 9:
                        break
                return out
            except Exception:
                return []

        if not away_lineup or not home_lineup:
            lineups = (g.get('lineups') or {})
            if not away_lineup:
                away_lineup = _parse_sched_lineup(lineups.get('awayBatters'))
            if not home_lineup:
                home_lineup = _parse_sched_lineup(lineups.get('homeBatters'))
            if len(away_lineup) < 5:
                away_lineup = _roster_lineup(away_team_id)
            if len(home_lineup) < 5:
                home_lineup = _roster_lineup(home_team_id)
        if not away_lineup or not home_lineup:
            return {'success': False, 'error': 'Lineups unavailable for simulation'}
        # Pre-warm _bio_cache for all lineup players so bats handedness is correct
        # even on a cold server restart (avoids L0/R0/S0 in the handedness block).
        # Parallel fetch to stay within the JS 90s abort timeout.
        _missing_pids = [_b.get('id') for _b in away_lineup + home_lineup
                         if _b.get('id') and _b.get('id') not in _bio_cache]
        if _missing_pids:
            with ThreadPoolExecutor(max_workers=min(len(_missing_pids), 9)) as _pool:
                list(_pool.map(player_profile, _missing_pids))
        for _b in away_lineup + home_lineup:
            _pid = _b.get('id')
            if _pid and _pid in _bio_cache:
                _b['bats'] = _bio_cache[_pid].get('bats', _b.get('bats', 'S'))
        today = datetime.now(ET).strftime('%Y-%m-%d')
        lineup_signature = _game_lineup_signature(g, away_lineup, home_lineup)
        cache_signature = f"{lineup_signature}|sims:{sims}|hand:v2"
        cached = _correlation_cache.get(game_pk)
        if cached and cached.get('date') == today and cached.get('signature') == cache_signature:
            return cached.get('payload') or {'success': False, 'error': 'Cached simulation payload missing'}

        away_abbr = away_team.get('abbreviation', 'AWAY')
        home_abbr = home_team.get('abbreviation', 'HOME')

        away_p = g.get('teams', {}).get('away', {}).get('probablePitcher', {})
        home_p = g.get('teams', {}).get('home', {}).get('probablePitcher', {})
        # _pitcher_model hits pitcher_stats_mlb (MLB API) + local CSV — run in parallel.
        with ThreadPoolExecutor(max_workers=2) as _pm_ex:
            _away_pm_fut = _pm_ex.submit(_pitcher_model,
                                         away_p.get('fullName', 'Away SP'),
                                         away_p.get('id'), away_team_id)
            _home_pm_fut = _pm_ex.submit(_pitcher_model,
                                         home_p.get('fullName', 'Home SP'),
                                         home_p.get('id'), home_team_id)
        away_pitcher = _away_pm_fut.result()
        home_pitcher = _home_pm_fut.result()
        park = PARK_FACTORS.get(home_team_id, 1.0)

        # ── Compute venue/time locals needed for weather before parallel block ─
        ven      = g.get('venue', {})
        venue_id = ven.get('id')
        vloc     = ven.get('location', {}) or {}
        coords   = vloc.get('defaultCoordinates', {}) or {}
        lat      = coords.get('latitude')
        lon      = coords.get('longitude')
        try:
            dt_utc  = datetime.fromisoformat(g.get('gameDate', '').replace('Z', '+00:00'))
            utc_off = VENUE_UTC_OFFSET.get(venue_id, -5)
            ghour   = (dt_utc + timedelta(hours=utc_off)).hour
        except Exception:
            ghour = 13
        game_date_str = (g.get('gameDate') or today).split('T')[0]

        # ── Run all pre-simulation IO in parallel (bullpen × 2, weather, ump) ─
        with ThreadPoolExecutor(max_workers=4) as _pre_ex:
            _fat_away_fut = _pre_ex.submit(_team_relief_fatigue_woba, home_team_id)
            _fat_home_fut = _pre_ex.submit(_team_relief_fatigue_woba, away_team_id)
            _wx_fut       = _pre_ex.submit(get_weather, lat, lon, ghour, venue_id)
            _off_fut      = _pre_ex.submit(_fetch_schedule_with_officials,
                                           game_date_str, game_date_str)

        try:
            away_relief_fatigue_woba = _fat_away_fut.result()
        except Exception:
            away_relief_fatigue_woba = 0.0
        try:
            home_relief_fatigue_woba = _fat_home_fut.result()
        except Exception:
            home_relief_fatigue_woba = 0.0
        try:
            wx = _wx_fut.result() or {}
        except Exception:
            wx = {}

        ump_data = None
        try:
            official_games = _off_fut.result()
            official_game = next((x for x in official_games if x.get('gamePk') == game_pk), None)
            ump = _get_hp_umpire(official_game or {})
            if ump and ump.get('id'):
                ump_data = _get_cached_ump(ump.get('id'), ump.get('fullName', ''))
        except Exception:
            ump_data = None

        ump_cache = {}
        if ump_data:
            ump_cache[game_pk] = {
                'date': datetime.now(ET).date(),
                'data': ump_data,
            }
        sim_env = get_sim_env_adjustments(
            game_pk,
            g,
            wx or {},
            home_team_id,
            ump_cache=ump_cache,
            DOME_VENUES=DOME_VENUES,
            PARK_FACTORS=PARK_FACTORS,
        )
        wx_mults = sim_env['wx_mults']
        ump_adj = sim_env['ump_adj']

        # ── Pre-compute BAT X multipliers per batter (once, not per sim) ─────
        # away batters face home_pitcher; home batters face away_pitcher.
        # Parallelized because each call performs BvP + platoon HTTP fetches
        # on cold cache; sequential it dominates cold-start sim time.
        _batx_jobs = [(i, b, home_pitcher) for i, b in enumerate(away_lineup)] \
                   + [(i, b, away_pitcher) for i, b in enumerate(home_lineup)]
        away_batx_map = {}
        home_batx_map = {}
        with ThreadPoolExecutor(max_workers=min(len(_batx_jobs) or 1, 18)) as _bx_ex:
            _bx_futs = {
                _bx_ex.submit(_batx_for_sim, b, opp, park, wx): (idx, b, opp)
                for idx, b, opp in _batx_jobs
            }
            for _fut in as_completed(_bx_futs):
                idx, b, opp = _bx_futs[_fut]
                try:
                    result = _fut.result()
                except Exception:
                    result = {'composite': 1.0, 'hit_mult': 1.0, 'hr_mult': 1.0,
                              'walk_mult': 1.0, 'k_mult': 1.0}
                if opp is home_pitcher:
                    away_batx_map[idx] = result
                else:
                    home_batx_map[idx] = result

        rng = AntitheticRandom(game_pk + int(datetime.now().strftime('%Y%m%d')) + 6)

        away_store = {i: [] for i in range(len(away_lineup))}
        home_store = {i: [] for i in range(len(home_lineup))}
        away_team_runs, home_team_runs, totals = [], [], []
        away_starter_lines, home_starter_lines = [], []
        away_bullpen_lines, home_bullpen_lines = [], []
        away_relief = {'Closer': [], 'Setup': [], 'Middle': []}
        home_relief = {'Closer': [], 'Setup': [], 'Middle': []}
        away_win = 0; home_win = 0; ties = 0
        sample = None

        for sim in range(sims):
            if sim % 2 == 1:
                rng.start_antithetic()
            away_off = _simulate_offense(
                away_lineup, home_pitcher, home_team_id, park, rng,
                batx_map=away_batx_map, wx_mults=wx_mults, ump_adj=ump_adj,
                relief_fatigue_woba=away_relief_fatigue_woba,
            )
            home_off = _simulate_offense(
                home_lineup, away_pitcher, away_team_id, park, rng,
                batx_map=home_batx_map, wx_mults=wx_mults, ump_adj=ump_adj,
                relief_fatigue_woba=home_relief_fatigue_woba,
            )
            if sim % 2 == 1:
                rng.stop_antithetic()
            if sample is None:
                sample = {
                    'away': away_off, 'home': home_off,
                    'away_abbr': away_abbr, 'home_abbr': home_abbr,
                    'away_pitcher': away_pitcher['name'], 'home_pitcher': home_pitcher['name']
                }
            for i, line in enumerate(away_off['batters']): away_store[i].append(line)
            for i, line in enumerate(home_off['batters']): home_store[i].append(line)
            home_starter_lines.append(away_off['starter'])
            away_starter_lines.append(home_off['starter'])
            home_bullpen_lines.append(away_off['bullpen'])
            away_bullpen_lines.append(home_off['bullpen'])
            for k in away_relief.keys():
                away_relief[k].append(home_off['relief_lines'][k])
                home_relief[k].append(away_off['relief_lines'][k])
            away_team_runs.append(away_off['runs']); home_team_runs.append(home_off['runs']); totals.append(away_off['runs'] + home_off['runs'])
            if away_off['runs'] > home_off['runs']: away_win += 1
            elif home_off['runs'] > away_off['runs']: home_win += 1
            else: ties += 1

        away_props = []
        for i, b in enumerate(away_lineup):
            s = _summarize_player(away_store[i])
            s.update({'id': b.get('id'), 'name': b.get('name'), 'slot': b.get('slot'), 'pos': b.get('pos'), 'bats': b.get('bats', 'S')})
            bx = away_batx_map.get(i, {})
            s['batx_composite'] = round(bx.get('composite', 1.0), 4)
            s['batx_hit_mult']  = round(bx.get('hit_mult',  1.0), 4)
            s['batx_hr_mult']   = round(bx.get('hr_mult',   1.0), 4)
            away_props.append(s)
        home_props = []
        for i, b in enumerate(home_lineup):
            s = _summarize_player(home_store[i])
            s.update({'id': b.get('id'), 'name': b.get('name'), 'slot': b.get('slot'), 'pos': b.get('pos'), 'bats': b.get('bats', 'S')})
            bx = home_batx_map.get(i, {})
            s['batx_composite'] = round(bx.get('composite', 1.0), 4)
            s['batx_hit_mult']  = round(bx.get('hit_mult',  1.0), 4)
            s['batx_hr_mult']   = round(bx.get('hr_mult',   1.0), 4)
            home_props.append(s)

        away_pitch_summary = _summarize_pitcher(away_starter_lines)
        away_pitch_summary.update({'name': away_pitcher['name'], 'pitchHand': away_pitcher['pitchHand']})
        home_pitch_summary = _summarize_pitcher(home_starter_lines)
        home_pitch_summary.update({'name': home_pitcher['name'], 'pitchHand': home_pitcher['pitchHand']})
        away_bullpen_summary = _summarize_pitcher(away_bullpen_lines)
        away_bullpen_summary.update({'name': away_abbr + ' Bullpen'})
        home_bullpen_summary = _summarize_pitcher(home_bullpen_lines)
        home_bullpen_summary.update({'name': home_abbr + ' Bullpen'})

        away_tiers = {k.lower(): _summarize_pitcher(v) for k, v in away_relief.items()}
        home_tiers = {k.lower(): _summarize_pitcher(v) for k, v in home_relief.items()}

        away_l = sum(1 for b in away_lineup if (b.get('bats') or 'S') == 'L')
        away_r = sum(1 for b in away_lineup if (b.get('bats') or 'S') == 'R')
        away_s = sum(1 for b in away_lineup if (b.get('bats') or 'S') == 'S')
        home_l = sum(1 for b in home_lineup if (b.get('bats') or 'S') == 'L')
        home_r = sum(1 for b in home_lineup if (b.get('bats') or 'S') == 'R')
        home_s = sum(1 for b in home_lineup if (b.get('bats') or 'S') == 'S')

        # Phase 2.6: expose Monte Carlo correlation matrix + top SGP combos.
        market_vectors = []

        def _event_meta(market):
            if market == 'batter_hits':
                return {'line': 0.5, 'side': 'Over', 'short': 'H'}
            if market == 'batter_home_runs':
                return {'line': 0.5, 'side': 'Over', 'short': 'HR'}
            if market == 'batter_total_bases':
                return {'line': 1.5, 'side': 'Over', 'short': 'TB'}
            if market == 'batter_rbis':
                return {'line': 0.5, 'side': 'Over', 'short': 'RBI'}
            if market == 'batter_runs':
                return {'line': 0.5, 'side': 'Over', 'short': 'R'}
            if market == 'batter_hits_runs_rbis':
                return {'line': 1.5, 'side': 'Over', 'short': 'H+R+RBI'}
            if market == 'pitcher_strikeouts':
                return {'line': 4.5, 'side': 'Over', 'short': 'K'}
            return {'line': 0.5, 'side': 'Over', 'short': 'PROP'}

        def _add_batter_market_vectors(lineup, store, team_abbr):
            batter_markets = {
                'batter_hits': ('h', 1),
                'batter_home_runs': ('hr', 1),
                'batter_total_bases': ('tb', 2),
                'batter_rbis': ('rbi', 1),
                'batter_runs': ('r', 1),
                'batter_hits_runs_rbis': (lambda x: (x.get('h', 0) + x.get('r', 0) + x.get('rbi', 0)), 2),
            }
            for idx, batter in enumerate(lineup):
                lines = store.get(idx, [])
                if not lines:
                    continue
                for market, (stat_source, event_floor) in batter_markets.items():
                    if callable(stat_source):
                        values = [stat_source(x) for x in lines]
                    else:
                        values = [x.get(stat_source, 0) for x in lines]
                    if not values:
                        continue
                    meta = _event_meta(market)
                    event_prob = sum(1 for x in values if x >= event_floor) / len(values)
                    market_vectors.append({
                        'player': batter.get('name', ''),
                        'team': team_abbr,
                        'market': market,
                        'values': values,
                        'event_floor': event_floor,
                        'event_prob': round(event_prob, 4),
                        'line': meta['line'],
                        'side': meta['side'],
                        'leg_label': f"{batter.get('name', '')} {meta['short']}",
                    })

        _add_batter_market_vectors(away_lineup, away_store, away_abbr)
        _add_batter_market_vectors(home_lineup, home_store, home_abbr)

        for p_name, p_team, p_lines in (
            (away_pitcher['name'], away_abbr, away_starter_lines),
            (home_pitcher['name'], home_abbr, home_starter_lines),
        ):
            values = [x.get('k', 0) for x in p_lines]
            if values:
                meta = _event_meta('pitcher_strikeouts')
                floor = 5
                market_vectors.append({
                    'player': p_name,
                    'team': p_team,
                    'market': 'pitcher_strikeouts',
                    'values': values,
                    'event_floor': floor,
                    'event_prob': round(sum(1 for x in values if x >= floor) / len(values), 4),
                    'line': meta['line'],
                    'side': meta['side'],
                    'leg_label': f"{p_name} {meta['short']}",
                })

        correlations = []
        combo_candidates = []
        for i in range(len(market_vectors)):
            row_a = market_vectors[i]
            for j in range(i + 1, len(market_vectors)):
                row_b = market_vectors[j]
                r = _pearson_corr(row_a['values'], row_b['values'])
                if abs(r) < 0.10:
                    continue
                strength = _corr_strength_label(r)
                warning = _corr_warning(row_a, row_b, r)
                corr_item = {
                    'playerA': row_a['player'],
                    'marketA': row_a['market'],
                    'teamA': row_a['team'],
                    'playerB': row_b['player'],
                    'marketB': row_b['market'],
                    'teamB': row_b['team'],
                    'r': round(r, 3),
                    'strength': strength,
                }
                if warning:
                    corr_item['warning'] = warning
                correlations.append(corr_item)

                if r > 0:
                    event_a = [1 if x >= row_a['event_floor'] else 0 for x in row_a['values']]
                    event_b = [1 if x >= row_b['event_floor'] else 0 for x in row_b['values']]
                    joint_hits = sum(1 for a, b in zip(event_a, event_b) if a and b)
                    combined_prob = joint_hits / sims
                    indep_prob = row_a['event_prob'] * row_b['event_prob']
                    combo_candidates.append({
                        'legs': [row_a['leg_label'], row_b['leg_label']],
                        'legs_meta': [
                            {
                                'player': row_a['player'],
                                'market': row_a['market'],
                                'line': row_a['line'],
                                'side': row_a['side'],
                                'team': row_a['team'],
                            },
                            {
                                'player': row_b['player'],
                                'market': row_b['market'],
                                'line': row_b['line'],
                                'side': row_b['side'],
                                'team': row_b['team'],
                            },
                        ],
                        'combined_prob': round(combined_prob, 3),
                        'r': round(r, 3),
                        'strength': strength,
                        'combined_ev_pct': round((combined_prob - indep_prob) * 100, 2),
                        'score': (combined_prob * 0.65) + (r * 0.35),
                    })

        correlations = sorted(correlations, key=lambda x: abs(x['r']), reverse=True)[:240]
        top_sgp_combos = sorted(combo_candidates, key=lambda x: x['score'], reverse=True)[:5]
        for c in top_sgp_combos:
            c.pop('score', None)

        # Build a projected (expected-value) box score from MC means.
        # The legacy `sampleBoxscore` is a single random draw from sim #0 — useful
        # for visualizing one possible game, but misleading as a prediction. This
        # struct exposes mean H/HR/RBI/etc per batter so consumers can show the
        # model's actual expectation alongside p(1+H) / p(2+H) variance bands.
        def _projected_team_box(props, lineup, team_runs):
            rows = []
            for i, b in enumerate(lineup):
                p = props[i] if i < len(props) else {}
                # Expected PAs — matches the slot decay used in _project_batter_batx
                exp_pa = round(max(3.4, 4.35 - i * 0.095), 2)
                rows.append({
                    'slot':       i + 1,
                    'name':       b.get('name'),
                    'pos':        b.get('pos'),
                    'bats':       b.get('bats', 'S'),
                    'pa':         exp_pa,
                    'mean_h':     p.get('mean_hits', 0.0),
                    'p50_h':      p.get('p50_hits', 0),
                    'p90_h':      p.get('p90_hits', 0),
                    'p_1plus_h':  p.get('p_1plus_hit', 0.0),
                    'p_2plus_h':  p.get('p_2plus_hit', 0.0),
                    'mean_hr':    p.get('mean_hr', 0.0),
                    'mean_rbi':   p.get('mean_rbi', 0.0),
                    'mean_r':     p.get('mean_runs', 0.0),
                    'mean_bb':    p.get('mean_bb', 0.0),
                    'mean_k':     p.get('mean_k', 0.0),
                    'mean_tb':    p.get('mean_tb', 0.0),
                    'p_1plus_hr': p.get('p_1plus_hr', 0.0),
                })
            return {
                'batters':   rows,
                'mean_runs': round(statistics.mean(team_runs), 2) if team_runs else 0.0,
                'mean_hits': round(sum(r['mean_h']  for r in rows), 1),
                'mean_bb':   round(sum(r['mean_bb'] for r in rows), 1),
                'mean_k':    round(sum(r['mean_k']  for r in rows), 1),
                'mean_tb':   round(sum(r['mean_tb'] for r in rows), 1),
            }

        projected_box = {
            'away':         _projected_team_box(away_props, away_lineup, away_team_runs),
            'home':         _projected_team_box(home_props, home_lineup, home_team_runs),
            'away_abbr':    away_abbr,
            'home_abbr':    home_abbr,
            'away_pitcher': away_pitcher['name'],
            'home_pitcher': home_pitcher['name'],
            'sims':         sims,
        }

        payload = {
            'success': True,
            'meta': {'sims': sims, 'awayAbbr': away_abbr, 'homeAbbr': home_abbr, 'parkFactor': park},
            'team': {
                'away_mean_runs': round(statistics.mean(away_team_runs), 2),
                'home_mean_runs': round(statistics.mean(home_team_runs), 2),
                'mean_total': round(statistics.mean(totals), 2),
                'median_total': statistics.median(totals),
                'std_total': round(statistics.pstdev(totals), 2) if len(totals) > 1 else 0.0,
                'p25_total': round(_pctl(totals, 25), 1),
                'p75_total': round(_pctl(totals, 75), 1),
                'p_8plus_total': round(sum(1 for x in totals if x >= 8)/len(totals), 3),
                'p_9plus_total': round(sum(1 for x in totals if x >= 9)/len(totals), 3),
                'p_10plus_total': round(sum(1 for x in totals if x >= 10)/len(totals), 3),
                # P(over) at each common book total — the O/U ladder.
                'ou_ladder': {str(L): round(sum(1 for x in totals if x > L)/len(totals), 3)
                              for L in (6.5, 7.5, 8.5, 9.5, 10.5, 11.5)},
                'away_win_pct': round(away_win / sims, 3),
                'home_win_pct': round(home_win / sims, 3),
                'tie_pct': round(ties / sims, 3),
            },
            'handedness': {
                'awayLineup': {'L': away_l, 'R': away_r, 'S': away_s},
                'homeLineup': {'L': home_l, 'R': home_r, 'S': home_s},
                'awayStarterHand': away_pitcher['pitchHand'],
                'homeStarterHand': home_pitcher['pitchHand'],
            },
            'playerProps': {'away': away_props, 'home': home_props},
            'pitcherProps': {
                'awayStarter': away_pitch_summary, 'homeStarter': home_pitch_summary,
                'awayBullpen': away_bullpen_summary, 'homeBullpen': home_bullpen_summary,
                'awayBullpenTiers': away_tiers, 'homeBullpenTiers': home_tiers,
            },
            'correlations': correlations,
            'top_sgp_combos': top_sgp_combos,
            'sampleBoxscore': sample,
            'projectedBoxscore': projected_box,
        }
        _correlation_cache[game_pk] = {
            'date': today,
            'signature': cache_signature,
            'payload': payload,
        }
        return payload
    except Exception as ex:
        print('[api_simulate]', traceback.format_exc())
        try:
            g = fetch_schedule_game(game_pk) or {}
            fallback = _simulation_fallback_payload(
                g,
                game_pk,
                sims=sims,
                warning=f'Fallback mode: {str(ex) or "simulation error"}'
            )
            return fallback
        except Exception as fallback_ex:
            print('[api_simulate:fallback]', traceback.format_exc())
            emergency = _simulation_fallback_payload(
                {},
                game_pk,
                sims=sims,
                warning=f'Emergency fallback: {str(ex) or "simulation error"}; {str(fallback_ex) or "fallback error"}'
            )
            return emergency


# ── Background simulation dispatcher ─────────────────────────────────────────
# Jobs keyed by (game_pk, sims) so that a 5k-sim request and a 2.5k-sim request
# don't race each other.  Entries: {'status': 'running'|'done', 'started': float,
# 'payload': dict|None}.
_sim_bg_jobs: dict = {}
_sim_bg_lock = threading.Lock()


@app.route('/api/simulate/<int:game_pk>')
def api_simulate(game_pk):
    try:
        sims = max(1500, min(5000, int(request.args.get('sims', 5000) or 5000)))
    except Exception:
        sims = 5000
    refresh = request.args.get('refresh') == '1'
    today = datetime.now(ET).strftime('%Y-%m-%d')
    job_key = (game_pk, sims)

    # 1. Fast cache hit
    cached = _correlation_cache.get(game_pk)
    if cached and not refresh and cached.get('date') == today:
        return jsonify(cached['payload'])

    # 2. Background job already running or done
    with _sim_bg_lock:
        job = _sim_bg_jobs.get(job_key)
    if job and not refresh:
        if job['status'] == 'done':
            return jsonify(job['payload'])
        elapsed = int(time.time() - job['started'])
        # Warm path finishes in ~90s; cold start (post-redeploy) can run 3-5min
        # while FG/Savant/pipeline workers compete for CPU. Grow the estimate
        # past the warm budget so the UI doesn't sit at "5s remaining" forever.
        if elapsed < 90:
            est = 90 - elapsed
        elif elapsed < 240:
            est = max(20, 240 - elapsed)
        else:
            est = max(15, 360 - elapsed)
        return jsonify({'computing': True, 'elapsed': elapsed,
                        'estimatedSeconds': est})

    # 3. Kick off background simulation
    started = time.time()
    with _sim_bg_lock:
        _sim_bg_jobs[job_key] = {'status': 'running', 'started': started, 'payload': None}

    def _run():
        try:
            payload = _do_simulate(game_pk, sims)
        except Exception as exc:
            g = {}
            try:
                g = fetch_schedule_game(game_pk) or {}
            except Exception:
                pass
            payload = _simulation_fallback_payload(g, game_pk, sims=0,
                                                   warning=str(exc)[:300])
        with _sim_bg_lock:
            _sim_bg_jobs[job_key]['status'] = 'done'
            _sim_bg_jobs[job_key]['payload'] = payload
        if payload and payload.get('success'):
            _correlation_cache[game_pk] = {
                'date': today, 'signature': payload.get('_sig', ''),
                'payload': payload,
            }

    threading.Thread(target=_run, daemon=True).start()
    return jsonify({'computing': True, 'elapsed': 0, 'estimatedSeconds': 90})


# ── Phase 7 Odds / Lineup / Edge Infrastructure ──────────────────────────────
ODDS_API_KEY = (os.getenv('ODDS_API_KEY') or '').strip()
ODDS_REGION = (os.getenv('ODDS_REGION') or 'us').strip()
ODDS_CACHE_STORE = os.path.join(DATA_DIR, 'odds_cache.json')


def _odds_ttl_seconds(env_key, default_seconds, min_seconds=30, max_seconds=24 * 60 * 60):
    """Read a TTL (seconds) from env with sane bounds and fallback."""
    raw = os.getenv(env_key)
    if raw is None or str(raw).strip() == '':
        return int(default_seconds)
    try:
        ttl = int(float(raw))
    except Exception:
        return int(default_seconds)
    return max(int(min_seconds), min(int(max_seconds), ttl))


def _odds_bool_env(env_key, default='1'):
    return str(os.getenv(env_key, default)).strip().lower() in ('1', 'true', 'yes')

# ── Odds API cache — prevents burning credits on every request ────────────────
# Events list: cache 6h (rarely changes intraday)
# Per-game odds snapshot: cache 24h by default (single fetch reused everywhere)
_ODDS_EVENTS_CACHE: dict = {}          # {'data': [...], 'ts': float}
_ODDS_GAME_CACHE:  dict = {}           # {event_id: {'all': [...], 'ts': float}}
_ODDS_EVENTS_TTL  = _odds_ttl_seconds('ODDS_EVENTS_TTL_SEC', 6 * 60 * 60)
_ODDS_GAME_TTL    = _odds_ttl_seconds('ODDS_GAME_TTL_SEC', 24 * 60 * 60)
_ODDS_NRFI_TTL    = _odds_ttl_seconds('ODDS_NRFI_TTL_SEC', 5 * 60)
_ODDS_DAILY_CACHE = _odds_bool_env('ODDS_DAILY_CACHE', '1')
_ODDS_SNAPSHOT_STRICT = _odds_bool_env('ODDS_SNAPSHOT_STRICT', '1')
_ODDS_SNAPSHOT_AUTOWARM = _odds_bool_env('ODDS_SNAPSHOT_AUTOWARM', '1')
_ODDS_SNAPSHOT_HEARTBEAT_SEC = _odds_ttl_seconds('ODDS_SNAPSHOT_HEARTBEAT_SEC', 5 * 60, min_seconds=60, max_seconds=60 * 60)
_ODDS_SNAPSHOT_RETRY_SEC = _odds_ttl_seconds('ODDS_SNAPSHOT_RETRY_SEC', 15 * 60, min_seconds=60, max_seconds=6 * 60 * 60)
_ODDS_CACHE_LOCK = threading.Lock()
_ODDS_SNAPSHOT_WORKER_LOCK = threading.Lock()
# Single-thread executor for non-blocking odds-cache file persistence.
_odds_io_executor = ThreadPoolExecutor(max_workers=1, thread_name_prefix="odds_io")
_ODDS_SNAPSHOT_WORKER_STARTED = False
_ODDS_SNAPSHOT_WORKER_LAST_ATTEMPT = 0.0
_ODDS_SNAPSHOT_META: dict = {
    'date': None,
    'complete': False,
    'running': False,
    'startedAt': None,
    'completedAt': None,
    'eventsCount': 0,
    'eventsFetched': 0,
    'errors': [],
    # The Odds API credit usage (from x-requests-* response headers), so we can
    # confirm caching is actually saving fetch usage.
    'creditsRemaining': None,
    'creditsUsed': None,
    'creditsLastCost': None,
    'creditsUsedToday': 0,
    'lastCreditAt': None,
}


def _record_odds_credits(resp):
    """Capture The Odds API credit headers after a live fetch. Cheap, best-effort."""
    try:
        h = resp.headers or {}
        rem = h.get('x-requests-remaining')
        used = h.get('x-requests-used')
        last = h.get('x-requests-last')
        with _ODDS_CACHE_LOCK:
            if rem is not None:
                _ODDS_SNAPSHOT_META['creditsRemaining'] = int(float(rem))
            if used is not None:
                _ODDS_SNAPSHOT_META['creditsUsed'] = int(float(used))
            if last is not None:
                cost = int(float(last))
                _ODDS_SNAPSHOT_META['creditsLastCost'] = cost
                if _ODDS_SNAPSHOT_META.get('date') == _odds_today_key():
                    _ODDS_SNAPSHOT_META['creditsUsedToday'] = int(_ODDS_SNAPSHOT_META.get('creditsUsedToday') or 0) + cost
            _ODDS_SNAPSHOT_META['lastCreditAt'] = datetime.now(timezone.utc).isoformat()
    except Exception:
        pass
_ODDS_ALL_MARKETS = (
    'h2h,spreads,totals,h2h_1st_1_innings,'
    'batter_hits,batter_total_bases,batter_home_runs,batter_rbis,'
    'batter_runs_scored,batter_stolen_bases,batter_hits_runs_rbis,pitcher_strikeouts'
)


def _odds_today_key():
    return datetime.now(ET).strftime('%Y-%m-%d')


def _odds_cache_entry_fresh(entry, data_key, ttl_sec):
    if not isinstance(entry, dict) or data_key not in entry:
        return False
    if _ODDS_DAILY_CACHE and entry.get('cache_date') == _odds_today_key():
        return True
    try:
        return (time.time() - float(entry.get('ts') or 0.0)) < float(ttl_sec)
    except Exception:
        return False


def _persist_odds_caches():
    payload = {
        'date': _odds_today_key(),
        'events': _ODDS_EVENTS_CACHE,
        'games': _ODDS_GAME_CACHE,
        'snapshot': _ODDS_SNAPSHOT_META,
        'savedAt': datetime.now(timezone.utc).isoformat(),
    }
    _save_json(ODDS_CACHE_STORE, payload)


def _restore_odds_caches():
    payload = _load_json(ODDS_CACHE_STORE, {})
    if not isinstance(payload, dict):
        return
    if payload.get('date') != _odds_today_key():
        return
    events = payload.get('events') or {}
    games = payload.get('games') or {}
    snapshot = payload.get('snapshot') or {}
    if isinstance(events, dict):
        _ODDS_EVENTS_CACHE.update(events)
    if isinstance(games, dict):
        _ODDS_GAME_CACHE.update(games)
    if isinstance(snapshot, dict):
        _ODDS_SNAPSHOT_META.update(snapshot)
        _ODDS_SNAPSHOT_META['running'] = False


def _ensure_daily_odds_snapshot():
    """Build one full odds snapshot for today, then serve cache-only for the rest of the day."""
    if not ODDS_API_KEY:
        return False

    with _ODDS_CACHE_LOCK:
        today = _odds_today_key()
        if _ODDS_SNAPSHOT_META.get('date') == today and _ODDS_SNAPSHOT_META.get('complete'):
            return True
        if _ODDS_SNAPSHOT_META.get('running'):
            return False
        _ODDS_SNAPSHOT_META.update({
            'date': today,
            'complete': False,
            'running': True,
            'startedAt': datetime.now(timezone.utc).isoformat(),
            'completedAt': None,
            'eventsCount': 0,
            'eventsFetched': 0,
            'errors': [],
            'creditsUsedToday': 0,
        })

    try:
        now = time.time()
        r = requests.get(
            'https://api.the-odds-api.com/v4/sports/baseball_mlb/events',
            params={'apiKey': ODDS_API_KEY, 'dateFormat': 'iso'},
            timeout=12,
        )
        r.raise_for_status()
        _record_odds_credits(r)
        events = r.json() or []

        with _ODDS_CACHE_LOCK:
            _ODDS_EVENTS_CACHE['data'] = events
            _ODDS_EVENTS_CACHE['ts'] = now
            _ODDS_EVENTS_CACHE['cache_date'] = _odds_today_key()
            _ODDS_SNAPSHOT_META['eventsCount'] = len(events)

        fetched = 0
        errors = []
        for ev in events:
            eid = ev.get('id')
            if not eid:
                continue
            try:
                now_ev = time.time()
                rr = requests.get(
                    f'https://api.the-odds-api.com/v4/sports/baseball_mlb/events/{eid}/odds',
                    params={
                        'apiKey': ODDS_API_KEY,
                        'regions': ODDS_REGION,
                        'markets': _ODDS_ALL_MARKETS,
                        'oddsFormat': 'american',
                        'dateFormat': 'iso',
                    },
                    timeout=15,
                )
                rr.raise_for_status()
                _record_odds_credits(rr)
                books = rr.json().get('bookmakers', []) or []
                with _ODDS_CACHE_LOCK:
                    _ODDS_GAME_CACHE[eid] = {
                        'all': books,
                        'ts': now_ev,
                        'cache_date': _odds_today_key(),
                    }
                fetched += 1
            except Exception as ex:
                errors.append(f'{eid}: {ex}')

        with _ODDS_CACHE_LOCK:
            _ODDS_SNAPSHOT_META['eventsFetched'] = fetched
            _ODDS_SNAPSHOT_META['errors'] = errors[:50]
            _ODDS_SNAPSHOT_META['completedAt'] = datetime.now(timezone.utc).isoformat()
            _ODDS_SNAPSHOT_META['complete'] = True
            _ODDS_SNAPSHOT_META['running'] = False
        # Persist to disk off the critical path so this thread isn't blocked by disk I/O.
        _odds_io_executor.submit(_persist_odds_caches)

        print(f'[Odds] Daily snapshot complete: events={len(events)} fetched={fetched} errors={len(errors)}')
        return True
    except Exception as ex:
        with _ODDS_CACHE_LOCK:
            _ODDS_SNAPSHOT_META['errors'] = [str(ex)]
            _ODDS_SNAPSHOT_META['completedAt'] = datetime.now(timezone.utc).isoformat()
            _ODDS_SNAPSHOT_META['complete'] = False
            _ODDS_SNAPSHOT_META['running'] = False
        _odds_io_executor.submit(_persist_odds_caches)
        print(f'[Odds] Daily snapshot failed: {ex}')
        return False


def _odds_snapshot_ready_today():
    with _ODDS_CACHE_LOCK:
        return (
            _ODDS_SNAPSHOT_META.get('date') == _odds_today_key()
            and bool(_ODDS_SNAPSHOT_META.get('complete'))
        )


def _start_odds_snapshot_worker():
    """Continuously ensure today's odds snapshot is built without manual priming."""
    global _ODDS_SNAPSHOT_WORKER_STARTED, _ODDS_SNAPSHOT_WORKER_LAST_ATTEMPT
    with _ODDS_SNAPSHOT_WORKER_LOCK:
        if _ODDS_SNAPSHOT_WORKER_STARTED:
            return
        _ODDS_SNAPSHOT_WORKER_STARTED = True

    def _runner():
        global _ODDS_SNAPSHOT_WORKER_LAST_ATTEMPT
        # Give startup loaders a short head start.
        time.sleep(8)
        while True:
            try:
                if not _ODDS_SNAPSHOT_AUTOWARM or not ODDS_API_KEY:
                    time.sleep(5 * 60)
                    continue

                if _odds_snapshot_ready_today():
                    time.sleep(_ODDS_SNAPSHOT_HEARTBEAT_SEC)
                    continue

                now = time.time()
                if (now - _ODDS_SNAPSHOT_WORKER_LAST_ATTEMPT) < _ODDS_SNAPSHOT_RETRY_SEC:
                    time.sleep(30)
                    continue

                _ODDS_SNAPSHOT_WORKER_LAST_ATTEMPT = now
                built = _ensure_daily_odds_snapshot()
                if built:
                    print('[ODDS_WORKER] Daily snapshot ready')
                else:
                    print('[ODDS_WORKER] Snapshot attempt incomplete; will retry')
            except Exception as ex:
                print(f'[ODDS_WORKER] Snapshot loop error: {ex}')
            time.sleep(30)

    threading.Thread(target=_runner, daemon=True).start()


_restore_odds_caches()


def _norm_name(s):
    return re.sub(r'[^a-z0-9]+', '', (s or '').lower())


def _american_to_implied(price):
    try:
        p = float(price)
        if p > 0:
            return round(100.0 / (p + 100.0), 4)
        if p < 0:
            return round((-p) / ((-p) + 100.0), 4)
        return None
    except Exception:
        return None


def _find_odds_event(away_name, home_name):
    if not ODDS_API_KEY:
        return None, []
    try:
        ok = _ensure_daily_odds_snapshot()
        if _ODDS_SNAPSHOT_STRICT and (not ok or not _odds_snapshot_ready_today()):
            return None, []
        with _ODDS_CACHE_LOCK:
            events = _ODDS_EVENTS_CACHE.get('data') or []
        na = _norm_name(away_name)
        nh = _norm_name(home_name)
        for ev in events:
            if _norm_name(ev.get('away_team')) == na and _norm_name(ev.get('home_team')) == nh:
                return ev, events
        return None, events
    except Exception as ex:
        print(f'[_find_odds_event] {ex}')
        return None, []


def _best_moneyline(bookmakers, away_name, home_name):
    best = {'away': None, 'home': None}
    for bk in bookmakers or []:
        for m in bk.get('markets', []) or []:
            if m.get('key') != 'h2h':
                continue
            for o in m.get('outcomes', []) or []:
                nm = o.get('name')
                item = {'bookmaker': bk.get('title'), 'price': o.get('price'), 'implied': _american_to_implied(o.get('price'))}
                if nm == away_name:
                    if best['away'] is None or float(o.get('price', -9999)) > float(best['away']['price']):
                        best['away'] = item
                elif nm == home_name:
                    if best['home'] is None or float(o.get('price', -9999)) > float(best['home']['price']):
                        best['home'] = item
    return best


def _best_total(bookmakers):
    best = None
    for bk in bookmakers or []:
        for m in bk.get('markets', []) or []:
            if m.get('key') != 'totals':
                continue
            outs = m.get('outcomes', []) or []
            over = next((x for x in outs if str(x.get('name')).lower() == 'over'), None)
            under = next((x for x in outs if str(x.get('name')).lower() == 'under'), None)
            if not over or not under:
                continue
            cand = {
                'bookmaker': bk.get('title'),
                'line': over.get('point'),
                'over_price': over.get('price'), 'under_price': under.get('price'),
                'over_implied': _american_to_implied(over.get('price')),
                'under_implied': _american_to_implied(under.get('price')),
            }
            if best is None:
                best = cand
            else:
                # prefer widely used standard line nearest consensus price
                if abs(float(cand['over_price'] or 0)) < abs(float(best['over_price'] or 0)):
                    best = cand
    return best


def _best_spread(bookmakers, away_name, home_name):
    """Return best run-line (spreads market) for each side."""
    best = {'away': None, 'home': None}
    for bk in bookmakers or []:
        for m in bk.get('markets', []) or []:
            if m.get('key') != 'spreads':
                continue
            for o in m.get('outcomes', []) or []:
                nm = o.get('name', '')
                point = o.get('point')  # e.g. -1.5 or +1.5
                price = o.get('price')
                item = {'bookmaker': bk.get('title'), 'price': price, 'point': point,
                        'implied': _american_to_implied(price)}
                if nm == away_name:
                    if best['away'] is None or abs(float(price or 0)) < abs(float(best['away']['price'] or 0)):
                        best['away'] = item
                elif nm == home_name:
                    if best['home'] is None or abs(float(price or 0)) < abs(float(best['home']['price'] or 0)):
                        best['home'] = item
    return best


def _load_event_odds(event_id, featured_only=False):
    if not ODDS_API_KEY or not event_id:
        return []
    try:
        ok = _ensure_daily_odds_snapshot()
        if _ODDS_SNAPSHOT_STRICT and (not ok or not _odds_snapshot_ready_today()):
            return []
        with _ODDS_CACHE_LOCK:
            cached = _ODDS_GAME_CACHE.get(event_id)
            return (cached or {}).get('all') or []
    except Exception as ex:
        print(f'[_load_event_odds] {ex}')
        with _ODDS_CACHE_LOCK:
            cached = _ODDS_GAME_CACHE.get(event_id)
        return (cached or {}).get('all', [])


def _load_event_market_odds(event_id, markets, cache_key, ttl_sec):
    # Keep signature for compatibility; serve subset from unified per-event cache.
    if not ODDS_API_KEY or not event_id or not markets:
        return []
    books = _load_event_odds(event_id)
    if not books:
        return []
    wanted = {m.strip() for m in str(markets).split(',') if m.strip()}
    if not wanted:
        return books
    filtered = []
    for bk in books:
        mkts = [m for m in (bk.get('markets') or []) if (m.get('key') or '') in wanted]
        if not mkts:
            continue
        b = dict(bk)
        b['markets'] = mkts
        filtered.append(b)
    return filtered


def _refresh_odds_events_cache():
    if not ODDS_API_KEY:
        return []
    ok = _ensure_daily_odds_snapshot()
    if _ODDS_SNAPSHOT_STRICT and (not ok or not _odds_snapshot_ready_today()):
        return []
    with _ODDS_CACHE_LOCK:
        return _ODDS_EVENTS_CACHE.get('data') or []


def _odds_cache_status_payload():
    now = time.time()
    with _ODDS_CACHE_LOCK:
        events_cached = int(len(_ODDS_EVENTS_CACHE.get('data') or []))
        events_ts = float(_ODDS_EVENTS_CACHE.get('ts') or 0.0)
        events_date = _ODDS_EVENTS_CACHE.get('cache_date')
        game_entries = _ODDS_GAME_CACHE
        game_cached = int(len(game_entries or {}))
        game_rows = []
        for eid, ent in (game_entries or {}).items():
            if not isinstance(ent, dict):
                continue
            game_rows.append({
                'eventId': eid,
                'bookmakers': len(ent.get('all') or []),
                'cacheDate': ent.get('cache_date'),
                'ageSec': round(max(0.0, now - float(ent.get('ts') or 0.0)), 1),
            })
        game_rows.sort(key=lambda x: x.get('ageSec', 0.0))

    file_exists = os.path.exists(ODDS_CACHE_STORE)
    file_meta = {
        'exists': file_exists,
        'path': ODDS_CACHE_STORE,
        'sizeBytes': os.path.getsize(ODDS_CACHE_STORE) if file_exists else 0,
        'modifiedAt': datetime.fromtimestamp(os.path.getmtime(ODDS_CACHE_STORE), tz=timezone.utc).isoformat() if file_exists else None,
    }
    return {
        'success': True,
        'keyConfigured': bool(ODDS_API_KEY),
        'dailyCacheEnabled': _ODDS_DAILY_CACHE,
        'snapshotStrict': _ODDS_SNAPSHOT_STRICT,
        'snapshotAutowarm': _ODDS_SNAPSHOT_AUTOWARM,
        'todayET': _odds_today_key(),
        'ttl': {
            'eventsSec': _ODDS_EVENTS_TTL,
            'gameSec': _ODDS_GAME_TTL,
            'nrfiSec': _ODDS_NRFI_TTL,
        },
        'eventsCache': {
            'count': events_cached,
            'cacheDate': events_date,
            'ageSec': round(max(0.0, now - events_ts), 1) if events_ts else None,
        },
        'gameCache': {
            'count': game_cached,
            'entries': game_rows[:30],
        },
        'snapshot': dict(_ODDS_SNAPSHOT_META),
        'snapshotWorker': {
            'started': _ODDS_SNAPSHOT_WORKER_STARTED,
            'retrySec': _ODDS_SNAPSHOT_RETRY_SEC,
            'heartbeatSec': _ODDS_SNAPSHOT_HEARTBEAT_SEC,
        },
        'file': file_meta,
    }


def _clear_odds_caches_locked():
    _ODDS_EVENTS_CACHE.clear()
    _ODDS_GAME_CACHE.clear()
    _ODDS_SNAPSHOT_META.update({
        'date': None,
        'complete': False,
        'running': False,
        'startedAt': None,
        'completedAt': None,
        'eventsCount': 0,
        'eventsFetched': 0,
        'errors': [],
    })
    _persist_odds_caches()


@app.route('/api/odds/cache/status')
def api_odds_cache_status():
    try:
        return jsonify(_odds_cache_status_payload())
    except Exception as ex:
        print(f'[api_odds_cache_status] {traceback.format_exc()}')
        return jsonify({'success': False, 'error': str(ex)}), 500


@app.route('/api/odds/cache/refresh', methods=['POST'])
def api_odds_cache_refresh():
    payload = request.get_json(silent=True) or {}
    mode = str(payload.get('mode') or request.args.get('mode') or 'snapshot').strip().lower()
    date_str = str(payload.get('date') or request.args.get('date') or datetime.now(ET).strftime('%Y-%m-%d')).strip()
    event_id = payload.get('eventId') or request.args.get('eventId')
    game_pk = payload.get('gamePk') or request.args.get('gamePk')
    clear_first = str(payload.get('clearFirst', request.args.get('clearFirst', '1'))).strip().lower() in ('1', 'true', 'yes')

    if not ODDS_API_KEY:
        return jsonify({'success': False, 'error': 'ODDS_API_KEY is not configured'}), 400

    try:
        with _ODDS_CACHE_LOCK:
            if clear_first:
                _clear_odds_caches_locked()

        events = _refresh_odds_events_cache()
        result = {
            'success': True,
            'mode': mode,
            'date': date_str,
            'eventsRefreshed': len(events),
            'prefetchedEventIds': [],
            'prefetchedCount': 0,
            'clearFirst': clear_first,
        }

        if mode in ('snapshot', 'build'):
            snapshot_ok = _odds_snapshot_ready_today()
            result['snapshotBuilt'] = snapshot_ok
            result['prefetchedEventIds'] = list((_ODDS_GAME_CACHE or {}).keys())[:50]
            result['prefetchedCount'] = len(_ODDS_GAME_CACHE or {})
        elif mode in ('today', 'all'):
            sched = fetch_schedule(date_str)
            event_map = {
                (_norm_name(ev.get('away_team')), _norm_name(ev.get('home_team'))): ev
                for ev in events
            }
            seen = set()
            for g in sched or []:
                away_name = (((g.get('teams') or {}).get('away') or {}).get('team') or {}).get('name')
                home_name = (((g.get('teams') or {}).get('home') or {}).get('team') or {}).get('name')
                ev = event_map.get((_norm_name(away_name), _norm_name(home_name)))
                if not ev:
                    continue
                eid = ev.get('id')
                if not eid or eid in seen:
                    continue
                seen.add(eid)
                _load_event_odds(eid)
                result['prefetchedEventIds'].append(eid)
            result['prefetchedCount'] = len(result['prefetchedEventIds'])
        elif mode in ('event', 'single'):
            target_event_id = event_id
            if not target_event_id and game_pk:
                try:
                    gpk = int(game_pk)
                except Exception:
                    return jsonify({'success': False, 'error': 'gamePk must be an integer'}), 400
                sched = fetch_schedule(date_str)
                g = next((x for x in (sched or []) if x.get('gamePk') == gpk), None)
                if not g:
                    return jsonify({'success': False, 'error': f'gamePk {gpk} not found for {date_str}'}), 404
                away_name = (((g.get('teams') or {}).get('away') or {}).get('team') or {}).get('name')
                home_name = (((g.get('teams') or {}).get('home') or {}).get('team') or {}).get('name')
                ev, _ = _find_odds_event(away_name, home_name)
                target_event_id = (ev or {}).get('id') if ev else None
            if not target_event_id:
                return jsonify({'success': False, 'error': 'event mode requires eventId or gamePk'}), 400
            _load_event_odds(target_event_id)
            result['prefetchedEventIds'] = [target_event_id]
            result['prefetchedCount'] = 1

        result['status'] = _odds_cache_status_payload()
        return jsonify(result)
    except Exception as ex:
        print(f'[api_odds_cache_refresh] {traceback.format_exc()}')
        return jsonify({'success': False, 'error': str(ex)}), 500


def _poisson_over_prob(mean, line):
    """P(X > line) = P(X >= floor(line)+1) via Poisson(mean). Works for any half-integer line."""
    k = int(line) + 1
    if mean <= 0 or k < 1:
        return 0.0
    lam = float(mean)
    log_p = -lam
    cdf = math.exp(log_p)
    for x in range(1, k):
        log_p += math.log(lam) - math.log(x)
        cdf += math.exp(log_p)
    return max(0.0, min(1.0, 1.0 - cdf))


# Binomial 1+ probability for low-count, low-trial outcomes (hit/PA).
# Removes the structural bias of Poisson(λ=expected_count) for 1+ hit, where
# events aren't rare and the trial count (PA) is small.
def _binomial_over_zero(mean_count, expected_n):
    try:
        m = float(mean_count or 0)
        n = float(expected_n or 0)
    except (TypeError, ValueError):
        return 0.0
    if m <= 0 or n <= 0:
        return 0.0
    p = max(0.0, min(0.95, m / n))
    return max(0.0, min(1.0, 1.0 - (1.0 - p) ** n))


def _logit(p):
    p = max(1e-4, min(1 - 1e-4, float(p)))
    return math.log(p / (1.0 - p))


def _logit_divergence(p_a, p_b):
    """Absolute divergence on the logit scale — variance-aware: a 22pt gap near
    p=0.5 yields ~0.9 nats, while the same gap near p=0.9 yields ~1.6 nats.
    """
    return abs(_logit(p_a) - _logit(p_b))


def _shrink_to_prior(p, prior, weight):
    """Linear blend p toward prior. weight=0 → no shrinkage, weight=1 → prior."""
    w = max(0.0, min(1.0, float(weight)))
    return (1.0 - w) * float(p) + w * float(prior)


# Per-projection coverage score for the XGB hit model. Returns 0..1 — 1 means
# all key Statcast + FanGraphs inputs are populated, 0 means inputs are too
# thin to trust the XGB output. Drives both blend weight and reliability flag.
_XGB_HIT_COVERAGE_KEYS = (
    # batter
    ("b", "sv_xba",     0.200, 0.310),   # wider band - catches more real values
    ("b", "sv_xwoba",   0.280, 0.380),
    ("b", "sv_brl_pct", 1.0,   15.0),
    ("b", "fg_pa",      10,    None),     # lower PA threshold
    ("b", "l7Hits",     0.0,   7.0),    # recent form counts too
    # pitcher
    ("p", "fg_kpct",    0.10,  0.40),
    ("p", "fg_era",     2.00,  7.00),   # use ERA if FIP missing
)


def _xgb_hit_coverage(batter_stats, pitcher_stats):
    """Score 0..1 for how well-populated the XGB hit-model inputs are.

    Each key contributes 1/N if present and inside a plausible band, 0.5/N if
    present but at a default fallback (i.e. signal-less), 0 if missing.
    """
    if not batter_stats and not pitcher_stats:
        return 0.0
    b = batter_stats or {}
    p = pitcher_stats or {}
    total = len(_XGB_HIT_COVERAGE_KEYS)
    score = 0.0
    for side, key, lo, hi in _XGB_HIT_COVERAGE_KEYS:
        src = b if side == "b" else p
        v = src.get(key)
        if v is None:
            continue
        try:
            f = float(v)
        except (TypeError, ValueError):
            continue
        if f == 0:
            continue
        if hi is None:
            # one-sided threshold (e.g. minimum PA)
            if f >= lo:
                score += 1.0
            else:
                score += 0.5 * (f / lo)
            continue
        mid = (lo + hi) / 2.0
        # Penalise values that look like the default fallback (mid of the band).
        if abs(f - mid) < (hi - lo) * 0.05:
            score += 0.5
        else:
            score += 1.0
    return max(0.0, min(1.0, score / total))


def _market_lines_for_player(market_props, player, mk):
    """Sorted list of distinct lines actually offered in the market for a player/market combo."""
    seen = set()
    for item in market_props:
        if item.get('player') == player and item.get('market_key') == mk:
            try:
                seen.add(round(float(item.get('line')), 2))
            except (TypeError, ValueError):
                pass
    return sorted(seen)


