def _parse_prop_markets(bookmakers, valid_names):
    grouped = {}
    for bk in bookmakers or []:
        bkt = bk.get('title')
        for m in bk.get('markets', []) or []:
            mk = m.get('key')
            outs = m.get('outcomes', []) or []
            for o in outs:
                player = o.get('description') or o.get('name')
                if mk.startswith('pitcher_'):
                    player = o.get('description') or o.get('name')
                if not player or player not in valid_names:
                    continue
                side = str(o.get('name', '')).lower()
                if side not in ('over', 'under'):
                    continue
                point = o.get('point')
                key = (player, mk, point, bkt)
                if key not in grouped:
                    grouped[key] = {'player': player, 'market_key': mk, 'line': point, 'bookmaker': bkt, 'over_price': None, 'under_price': None}
                grouped[key][f'{side}_price'] = o.get('price')
    out = []
    for item in grouped.values():
        item['over_implied'] = _american_to_implied(item.get('over_price'))
        item['under_implied'] = _american_to_implied(item.get('under_price'))
        out.append(item)
    return out


def _find_best_available_price(market_props, player, mk, line, side='over'):
    """
    Phase 3: Find best available price across all books for a given prop.
    Returns: (best_price, best_bookmaker) or (None, None) if no match found.
    """
    candidates = [
        (float(item.get(f'{side}_price', -999) or -999), item.get('bookmaker'))
        for item in market_props
        if item.get('player') == player and item.get('market_key') == mk and float(item.get('line', 0)) == float(line)
        and item.get(f'{side}_price') is not None
    ]
    
    if not candidates:
        return None, None
    
    if side == 'over':
        # For positive prices, higher is better; for negative, closer to 0 is better
        best_price, best_book = max(candidates, key=lambda x: x[0] if x[0] > 0 else (1000 + x[0]))
    else:
        best_price, best_book = max(candidates, key=lambda x: x[0] if x[0] > 0 else (1000 + x[0]))
    
    return best_price, best_book


def _market_price_summary(market_props, player, mk, line):
    """Return cross-book pricing summary for a player market at a target line."""
    all_items = [
        item for item in (market_props or [])
        if item.get('player') == player and item.get('market_key') == mk
    ]
    same_line = [
        item for item in all_items
        if float(item.get('line', 0) or 0) == float(line)
    ]

    if not all_items:
        return {
            'best_over_price': None,
            'best_over_book': None,
            'best_under_price': None,
            'best_under_book': None,
            'line_range': None,
            'book_count': 0,
            'market_implied': None,
            'market_bookmaker': None,
            'line_varies': False,
        }

    def _best_side(items, side_key):
        candidates = []
        for it in items:
            px = it.get(side_key)
            if px is None:
                continue
            candidates.append((px, it.get('bookmaker')))
        if not candidates:
            return None, None
        best_px, best_book = max(candidates, key=lambda x: _american_price_score(x[0]))
        return best_px, best_book

    best_over_price, best_over_book = _best_side(same_line, 'over_price')
    best_under_price, best_under_book = _best_side(same_line, 'under_price')

    line_vals = []
    for it in all_items:
        try:
            line_vals.append(float(it.get('line')))
        except Exception:
            continue
    line_range = None
    if line_vals:
        line_range = [round(min(line_vals), 2), round(max(line_vals), 2)]

    books = {it.get('bookmaker') for it in all_items if it.get('bookmaker')}

    return {
        'best_over_price': best_over_price,
        'best_over_book': best_over_book,
        'best_under_price': best_under_price,
        'best_under_book': best_under_book,
        'line_range': line_range,
        'book_count': len(books),
        'market_implied': _american_to_implied(best_over_price),
        'market_bookmaker': best_over_book,
        'line_varies': bool(line_range and line_range[0] != line_range[1]),
    }


def _group_line_shopping(market_props):
    """Group raw prop prices by player+market with all book lines preserved."""
    label_map = {
        'batter_hits': 'Hits',
        'batter_home_runs': 'Home Runs',
        'batter_total_bases': 'Total Bases',
        'batter_rbis': 'RBI',
        'batter_runs_scored': 'Runs',
        'batter_hits_runs_rbis': 'H+R+RBI',
        'batter_stolen_bases': 'Stolen Bases',
        'pitcher_strikeouts': 'Pitcher Strikeouts',
        'pitcher_walks': 'Pitcher Walks',
        'batter_strikeouts': 'Batter Strikeouts',
    }

    grouped = {}
    for item in market_props or []:
        player = item.get('player')
        mk = item.get('market_key')
        if not player or not mk:
            continue
        key = (player, mk)
        line_val = item.get('line')
        try:
            line_val = float(line_val)
        except Exception:
            line_val = None
        row = {
            'bookmaker': item.get('bookmaker'),
            'line': round(line_val, 2) if isinstance(line_val, float) else None,
            'over_price': item.get('over_price'),
            'under_price': item.get('under_price'),
            'over_implied': item.get('over_implied'),
            'under_implied': item.get('under_implied'),
        }
        grouped.setdefault(key, []).append(row)

    out = []
    for (player, mk), books in grouped.items():
        best_over = None
        best_under = None
        line_vals = []
        uniq_books = set()
        for b in books:
            if b.get('bookmaker'):
                uniq_books.add(b.get('bookmaker'))
            if b.get('line') is not None:
                line_vals.append(float(b.get('line')))
            op = b.get('over_price')
            up = b.get('under_price')
            if op is not None and (best_over is None or _american_price_score(op) > _american_price_score(best_over)):
                best_over = op
            if up is not None and (best_under is None or _american_price_score(up) > _american_price_score(best_under)):
                best_under = up

        line_range = None
        if line_vals:
            line_range = [round(min(line_vals), 2), round(max(line_vals), 2)]

        normalized_books = []
        for b in books:
            is_best_over = b.get('over_price') is not None and best_over is not None and b.get('over_price') == best_over
            is_best_under = b.get('under_price') is not None and best_under is not None and b.get('under_price') == best_under
            normalized_books.append({
                **b,
                'is_best_over': is_best_over,
                'is_best_under': is_best_under,
            })

        out.append({
            'player': player,
            'market_key': mk,
            'market_label': label_map.get(mk, mk),
            'best_over_price': best_over,
            'best_under_price': best_under,
            'line_range': line_range,
            'book_count': len(uniq_books),
            'line_varies': bool(line_range and line_range[0] != line_range[1]),
            'books': normalized_books,
        })

    out.sort(key=lambda x: (x.get('player', ''), x.get('market_key', '')))
    by_player = {}
    for g in out:
        by_player.setdefault(g['player'], []).append(g)

    return {'groups': out, 'by_player': by_player}


def _american_price_score(price):
    try:
        p = float(price)
        return p if p > 0 else (1000 + p)
    except Exception:
        return -999999


def _extract_first_inning_era(pitcher_id):
    if not pitcher_id:
        return 4.50
    try:
        year = datetime.now().year
        r = requests.get(
            f"{MLB_API}/people/{pitcher_id}/stats",
            params={"stats": "byInning", "group": "pitching", "season": year},
            timeout=8,
        )
        r.raise_for_status()
        splits = (r.json().get('stats') or [{}])[0].get('splits', []) or []
        for sp in splits:
            label = (sp.get('split', {}).get('description') or sp.get('split', {}).get('value') or '').lower()
            if '1st' not in label and 'first' not in label and label not in ('1', 'inning 1'):
                continue
            stat = sp.get('stat', {}) or {}
            era = _num(stat.get('era'), None)
            if era is not None and era > 0:
                return _clamp(era, 1.20, 12.00)
            ip = _num(stat.get('inningsPitched'), 0.0)
            er = _num(stat.get('earnedRuns'), 0.0)
            if ip > 0:
                return _clamp((er / ip) * 9.0, 1.20, 12.00)
    except Exception:
        pass
    season = pitcher_stats_mlb(pitcher_id) or {}
    return _clamp(_num(season.get('era'), 4.50), 1.20, 12.00)


def _leadoff_handedness_adj(leadoff, opp_pitch_hand):
    if not leadoff:
        return 1.0, {}
    split = hitter_split_profile(leadoff.get('id')) or {}
    code = 'vl' if str(opp_pitch_hand or 'R').upper() == 'L' else 'vr'
    prof = split.get(code) or split.get('vr') or split.get('vl') or {}
    obp = _clamp(_num(prof.get('obp'), 0.320), 0.240, 0.450)
    avg = _clamp(_num(prof.get('avg'), 0.250), 0.170, 0.360)
    pa = int(prof.get('pa') or 0)
    quality = (0.62 * obp) + (0.38 * avg)
    adj = _clamp(0.84 + ((quality - 0.300) * 2.30), 0.78, 1.28)
    if pa and pa < 40:
        adj = 1.0 + ((adj - 1.0) * 0.55)
    return adj, {'obp': round(obp, 3), 'avg': round(avg, 3), 'pa': pa}


def _nrfi_market_snapshot(away_name, home_name):
    if not ODDS_API_KEY:
        return {}
    event, _ = _find_odds_event(away_name, home_name)
    if not event:
        return {}
    event_id = event.get('id')
    if not event_id:
        return {}
    books = _load_event_market_odds(
        event_id,
        markets='h2h_1st_1_innings',
        cache_key='nrfi',
        ttl_sec=_ODDS_NRFI_TTL,
    )
    if not books:
        return {}

    nrfi_prices = []
    yrfi_prices = []
    for bk in books:
        title = bk.get('title')
        for m in bk.get('markets', []) or []:
            mkey = (m.get('key') or '').lower()
            if '1st' not in mkey and 'first' not in mkey:
                continue
            for o in m.get('outcomes', []) or []:
                name = (o.get('name') or '').strip().lower()
                price = o.get('price')
                implied = _american_to_implied(price)
                if implied is None:
                    continue
                rec = {'price': price, 'implied': implied, 'book': title}
                if name in ('nrfi', 'no', 'no run first inning', 'no runs first inning', 'no runs in first inning'):
                    nrfi_prices.append(rec)
                elif name in ('yrfi', 'yes', 'run first inning', 'run in first inning', 'yes run first inning'):
                    yrfi_prices.append(rec)

    out = {}
    if nrfi_prices:
        out['nrfi_implied'] = round(sum(x['implied'] for x in nrfi_prices) / len(nrfi_prices), 4)
        best_nrfi = max(nrfi_prices, key=lambda x: _american_price_score(x['price']))
        out['nrfi_price'] = best_nrfi['price']
        out['nrfi_book'] = best_nrfi['book']
    if yrfi_prices:
        out['yrfi_implied'] = round(sum(x['implied'] for x in yrfi_prices) / len(yrfi_prices), 4)
        best_yrfi = max(yrfi_prices, key=lambda x: _american_price_score(x['price']))
        out['yrfi_price'] = best_yrfi['price']
        out['yrfi_book'] = best_yrfi['book']
    return out


def _compute_nrfi(game_pk):
    g = fetch_schedule_game(game_pk)
    if not g:
        return {'success': False, 'error': 'Game not found'}

    away_team = g.get('teams', {}).get('away', {}).get('team', {})
    home_team = g.get('teams', {}).get('home', {}).get('team', {})
    away_name = away_team.get('name', 'Away')
    home_name = home_team.get('name', 'Home')
    away_abbr = away_team.get('abbreviation', 'AWY')
    home_abbr = home_team.get('abbreviation', 'HME')

    away_p = g.get('teams', {}).get('away', {}).get('probablePitcher', {}) or {}
    home_p = g.get('teams', {}).get('home', {}).get('probablePitcher', {}) or {}
    away_pid = away_p.get('id')
    home_pid = home_p.get('id')
    away_sp_name = away_p.get('fullName', 'Away SP')
    home_sp_name = home_p.get('fullName', 'Home SP')

    away_sp_hand = player_profile(away_pid).get('throws', 'R')
    home_sp_hand = player_profile(home_pid).get('throws', 'R')
    away_i1_era = _extract_first_inning_era(away_pid)
    home_i1_era = _extract_first_inning_era(home_pid)

    park = PARK_FACTORS.get(home_team.get('id'), 1.0)

    venue = g.get('venue', {}) or {}
    venue_id = venue.get('id')
    vloc = (venue.get('location') or {})
    coords = vloc.get('defaultCoordinates', {}) or {}
    lat = coords.get('latitude')
    lon = coords.get('longitude')
    try:
        dt_utc = datetime.fromisoformat(g.get('gameDate', '').replace('Z', '+00:00'))
        utc_off = VENUE_UTC_OFFSET.get(venue_id, -5)
        ghour = (dt_utc + timedelta(hours=utc_off)).hour
    except Exception:
        ghour = 13
    wx = get_weather(lat, lon, ghour, venue_id=venue_id)

    box = requests.get(f"{MLB_API}/game/{game_pk}/boxscore", timeout=10).json().get('teams', {})
    away_lineup = get_batters_from_boxscore(box.get('away', {}), 'away')
    home_lineup = get_batters_from_boxscore(box.get('home', {}), 'home')
    today = datetime.now(ET).strftime('%Y-%m-%d')
    lineup_signature = _game_lineup_signature(g, away_lineup, home_lineup)
    cached = _nrfi_cache.get(game_pk)
    if cached and cached.get('date') == today and cached.get('signature') == lineup_signature:
        return dict(cached.get('payload') or {'success': False, 'error': 'Cached NRFI payload missing'})
    away_leadoff = next((b for b in away_lineup if int(b.get('slot') or 0) == 1), (away_lineup[0] if away_lineup else {}))
    home_leadoff = next((b for b in home_lineup if int(b.get('slot') or 0) == 1), (home_lineup[0] if home_lineup else {}))

    away_hand_adj, away_split = _leadoff_handedness_adj(away_leadoff, home_sp_hand)
    home_hand_adj, home_split = _leadoff_handedness_adj(home_leadoff, away_sp_hand)

    temp = _num(wx.get('temp'), 72)
    weather_mult = 1.0
    weather_mult += _clamp((temp - 72.0) * 0.0025, -0.05, 0.08)
    # Directional wind: use the signed out-to-CF component, not raw speed. Wind
    # blowing OUT lifts first-inning run risk; blowing IN suppresses it. When the
    # park has no known orientation (wind_out is None) we add nothing rather than
    # assume every breeze boosts offense (the old, directionally-blind behavior).
    wind_out = wx.get('wind_out')
    wind_directional = wind_out is not None
    if wind_directional:
        weather_mult += _clamp(_num(wind_out, 0.0) * 0.0045, -0.05, 0.07)
    weather_mult = _clamp(weather_mult, 0.90, 1.14)

    away_score_rate_i1 = _clamp((home_i1_era / 9.0) * park * away_hand_adj * weather_mult, 0.03, 0.62)
    home_score_rate_i1 = _clamp((away_i1_era / 9.0) * park * home_hand_adj * weather_mult, 0.03, 0.62)

    nrfi_prob = _clamp((1.0 - away_score_rate_i1) * (1.0 - home_score_rate_i1), 0.03, 0.97)
    yrfi_prob = round(1.0 - nrfi_prob, 4)

    odds = _nrfi_market_snapshot(away_name, home_name)
    market_nrfi_implied = odds.get('nrfi_implied')
    market_yrfi_implied = odds.get('yrfi_implied')
    nrfi_edge = None if market_nrfi_implied is None else round(nrfi_prob - market_nrfi_implied, 4)
    yrfi_edge = None if market_yrfi_implied is None else round(yrfi_prob - market_yrfi_implied, 4)

    factors = []
    if home_i1_era <= 3.35 or away_i1_era <= 3.35:
        factors.append('Ace on mound suppresses early offense')
    if home_i1_era >= 5.10 or away_i1_era >= 5.10:
        factors.append('Volatile first-inning starter profile')
    if away_hand_adj <= 0.93:
        factors.append('Weak away leadoff split versus starter hand')
    if home_hand_adj <= 0.93:
        factors.append('Weak home leadoff split versus starter hand')
    if wind_directional and wind_out <= -6:
        factors.append('Wind blowing in suppresses early scoring')
    elif weather_mult <= 0.96:
        factors.append('Run environment dampened by weather')
    if wind_directional and wind_out >= 6:
        factors.append('Wind blowing out lifts first-inning run risk')
    elif weather_mult >= 1.06:
        factors.append('Weather boosts first-inning scoring risk')
    if park <= 0.97:
        factors.append('Pitcher-friendly park factor')
    elif park >= 1.03:
        factors.append('Hitter-friendly park factor')
    if not factors:
        factors.append('Balanced setup with neutral first-inning profile')

    payload = {
        'success': True,
        'gamePk': game_pk,
        'game': f"{away_abbr} @ {home_abbr}",
        'away': away_abbr,
        'home': home_abbr,
        'away_sp': away_sp_name,
        'home_sp': home_sp_name,
        'away_sp_i1_era': round(away_i1_era, 2),
        'home_sp_i1_era': round(home_i1_era, 2),
        'away_leadoff': away_leadoff.get('name', 'TBD'),
        'home_leadoff': home_leadoff.get('name', 'TBD'),
        'away_score_rate_i1': round(away_score_rate_i1, 4),
        'home_score_rate_i1': round(home_score_rate_i1, 4),
        'nrfi_prob': round(nrfi_prob, 4),
        'yrfi_prob': yrfi_prob,
        'market_nrfi_implied': market_nrfi_implied,
        'market_yrfi_implied': market_yrfi_implied,
        'nrfi_edge': nrfi_edge,
        'yrfi_edge': yrfi_edge,
        'book_price': odds.get('nrfi_price'),
        'bookmaker': odds.get('nrfi_book'),
        'yrfi_book_price': odds.get('yrfi_price'),
        'yrfi_bookmaker': odds.get('yrfi_book'),
        'park_factor': round(park, 3),
        'weather': wx,
        'leadoff_context': {
            'away': away_split,
            'home': home_split,
        },
        'key_factors': factors[:4],
    }
    _nrfi_cache[game_pk] = {
        'date': today,
        'signature': lineup_signature,
        'payload': payload,
    }
    return payload


@app.route('/api/nrfi/<int:game_pk>')
def api_nrfi(game_pk):
    try:
        out = _compute_nrfi(game_pk)
        if not out.get('success'):
            return jsonify(out), 404
        return jsonify(out)
    except Exception as ex:
        print('[api_nrfi]', traceback.format_exc())
        return jsonify({'success': False, 'error': str(ex)}), 500


def _compute_f5(game_pk):
    """Projects runs scored in the first 5 innings for each team."""
    try:
        _maybe_refresh_fg()
        _maybe_refresh_savant()

        gdata = None
        for delta in (0, -1, 1):
            ds    = (datetime.now(ET) + timedelta(days=delta)).strftime("%Y-%m-%d")
            raw   = fetch_schedule(ds)
            gdata = next((g for g in raw if g.get("gamePk") == game_pk), None)
            if gdata:
                break
        if not gdata:
            return {"success": False, "error": "Game not found"}

        away_t  = gdata["teams"]["away"]
        home_t  = gdata["teams"]["home"]
        home_id = home_t["team"]["id"]
        pf      = PARK_FACTORS.get(home_id, 1.0)

        ap_info = away_t.get("probablePitcher", {})
        hp_info = home_t.get("probablePitcher", {})
        ap_name = ap_info.get("fullName", "TBD")
        hp_name = hp_info.get("fullName", "TBD")
        ap_id   = ap_info.get("id");  hp_id = hp_info.get("id")

        ap_fg = fg_pitcher(ap_name); hp_fg = fg_pitcher(hp_name)
        ap_sv = sv_pitcher(ap_name); hp_sv = sv_pitcher(hp_name)
        ap_st = pitcher_stats_mlb(ap_id) if ap_id else {}
        hp_st = pitcher_stats_mlb(hp_id) if hp_id else {}

        def best_era(sv, fg, mlb):
            xera = sv.get("sv_xera")
            ip = fg.get("fg_ip", 0) or 0
            if xera and float(ip or 0) >= 15:
                try:
                    f = float(xera)
                    if 0 < f < 12: return f
                except Exception: pass
            for v in [fg.get("fg_era"), mlb.get("era")]:
                try:
                    f = float(v)
                    if 0 < f < 12: return f
                except Exception: pass
            return 4.50

        def best_fip(fg, fallback):
            try:
                f = float(fg.get("fg_fip", 0))
                if 0 < f < 12: return f
            except Exception:
                pass
            return fallback

        ap_era = best_era(ap_sv, ap_fg, ap_st)
        hp_era = best_era(hp_sv, hp_fg, hp_st)
        ap_fip = best_fip(ap_fg, ap_era)
        hp_fip = best_fip(hp_fg, hp_era)

        try:
            r = requests.get(f"{MLB_API}/game/{game_pk}/boxscore", timeout=8)
            r.raise_for_status()
            box       = r.json().get("teams", {})
            away_bats = get_batters_from_boxscore(box.get("away", {}), "away")
            home_bats = get_batters_from_boxscore(box.get("home", {}), "home")
        except Exception:
            away_bats = []; home_bats = []

        def lu_xwoba(bats):
            vals = []
            for b in bats:
                for k in ["sv_xwoba", "fg_woba"]:
                    try:
                        f = float(b.get(k, 0))
                        if 0.1 < f < 0.6:
                            vals.append(f); break
                    except Exception:
                        pass
                else:
                    vals.append(0.320)
            return round(sum(vals) / len(vals), 3) if vals else 0.320

        away_xwoba = lu_xwoba(away_bats)
        home_xwoba = lu_xwoba(home_bats)

        ven   = gdata.get("venue", {})
        vid   = ven.get("id")
        vloc  = (ven.get("location") or {})
        coord = (vloc.get("defaultCoordinates") or {})
        lat   = coord.get("latitude"); lon = coord.get("longitude")
        try:
            dt_utc = datetime.fromisoformat(gdata.get("gameDate", "").replace("Z", "+00:00"))
            ghour  = dt_utc.astimezone(ET).hour
        except Exception:
            ghour  = 13
        wx = get_weather(lat, lon, ghour, venue_id=vid)

        away_blend = 0.6 * hp_era + 0.4 * hp_fip
        home_blend = 0.6 * ap_era + 0.4 * ap_fip

        f5_scale  = 5.0 / 9.0
        pf_f5     = 1.0 + (pf - 1.0) * 0.65

        away_f5   = 4.50 * (away_blend / 4.50) * (away_xwoba / 0.320) * pf_f5 * f5_scale
        home_f5   = 4.50 * (home_blend / 4.50) * (home_xwoba / 0.320) * pf_f5 * f5_scale

        wx_adj = 0.0
        if not wx.get("dome"):
            try:
                t = float(wx.get("temp", 70))
                if t > 82:   wx_adj =  0.08
                elif t > 76: wx_adj =  0.04
                elif t < 48: wx_adj = -0.08
                elif t < 56: wx_adj = -0.04
            except Exception:
                pass

        wind_adj = _wind_run_adj(wx, scale=0.5)
        away_f5 = round(max(0.8, away_f5 + wx_adj + wind_adj), 2)
        home_f5 = round(max(0.8, home_f5 + wx_adj + wind_adj), 2)
        total_f5 = round(away_f5 + home_f5, 2)

        if total_f5 >= 5.0:
            signal = "LEAN OVER"; sig_col = "#00e676"
        elif total_f5 >= 4.5:
            signal = "SLIGHT OVER"; sig_col = "#76ff03"
        elif total_f5 <= 3.2:
            signal = "LEAN UNDER"; sig_col = "#f44336"
        elif total_f5 <= 3.7:
            signal = "SLIGHT UNDER"; sig_col = "#ff9800"
        else:
            signal = "NEUTRAL"; sig_col = "#6a8db0"

        diff = home_f5 - away_f5
        if abs(diff) > 0.25:
            fav     = home_t["team"].get("abbreviation","HOME") if diff > 0 else away_t["team"].get("abbreviation","AWAY")
            fav_col = "#00e5ff"
        else:
            fav = "EVEN"; fav_col = "#6a8db0"

        return {
            "success":      True,
            "gamePk":       game_pk,
            "awayAbbr":     away_t["team"].get("abbreviation","AWAY"),
            "homeAbbr":     home_t["team"].get("abbreviation","HOME"),
            "awayPitcher":  hp_name,
            "homePitcher":  ap_name,
            "awayF5":       away_f5,
            "homeF5":       home_f5,
            "totalF5":      total_f5,
            "signal":       signal,
            "signalColor":  sig_col,
            "f5Favorite":   fav,
            "favColor":     fav_col,
            "awayEra":      round(hp_era, 2),
            "homeEra":      round(ap_era, 2),
            "awayXwoba":    away_xwoba,
            "homeXwoba":    home_xwoba,
            "parkFactor":   pf,
            "wxAdj":        wx_adj,
            "windAdj":      wind_adj,
            "windField":    wx.get("wind_field"),
            "dome":         wx.get("dome", False),
        }

    except Exception as ex:
        print(f"[_compute_f5] {traceback.format_exc()}")
        return {"success": False, "error": str(ex)}


def _compute_game_projection_core(game_pk):
    """Numeric game projection: runs, total, favorite, win probabilities.
    Returns same numeric fields as /api/game-projection/ but without Claude AI insights."""
    try:
        _maybe_refresh_fg()
        _maybe_refresh_savant()
        gdata = fetch_schedule_game(game_pk)
        if not gdata:
            return {"success": False, "error": "Game not found"}
        away_t = gdata.get("teams",{}).get("away",{})
        home_t = gdata.get("teams",{}).get("home",{})
        ap = away_t.get("probablePitcher",{}); hp = home_t.get("probablePitcher",{})
        ap_n = ap.get("fullName","TBD"); hp_n = hp.get("fullName","TBD")
        hid = home_t.get("team",{}).get("id")
        pf = PARK_FACTORS.get(hid, 1.0)
        ap_mlb = pitcher_stats_mlb(ap.get("id")) if ap.get("id") else {}
        hp_mlb = pitcher_stats_mlb(hp.get("id")) if hp.get("id") else {}
        ap_fg = fg_pitcher(ap_n); hp_fg = fg_pitcher(hp_n)
        ap_sv = sv_pitcher(ap_n); hp_sv = sv_pitcher(hp_n)
        def best_era(sv, fg, mlb):
            xera = sv.get("sv_xera")
            ip = fg.get("fg_ip", 0) or 0
            if xera and float(ip or 0) >= 15:
                try:
                    f = float(xera)
                    if 0 < f < 12: return f
                except Exception: pass
            for v in [fg.get("fg_era"), mlb.get("era")]:
                try:
                    f = float(v)
                    if 0 < f < 12: return f
                except Exception: pass
            return 4.50
        def best_fip(fg, fallback):
            try:
                f = float(fg.get("fg_fip",0))
                if 0 < f < 12: return f
            except Exception: pass
            return fallback
        away_pit_era = best_era(hp_sv, hp_fg, hp_mlb)
        home_pit_era = best_era(ap_sv, ap_fg, ap_mlb)
        away_pit_fip = best_fip(hp_fg, away_pit_era)
        home_pit_fip = best_fip(ap_fg, home_pit_era)
        try:
            r = requests.get(f"{MLB_API}/game/{game_pk}/boxscore", timeout=10)
            r.raise_for_status()
            box = r.json().get("teams",{})
            away_bats = get_batters_from_boxscore(box.get("away",{}), "away")
            home_bats = get_batters_from_boxscore(box.get("home",{}), "home")
        except Exception:
            away_bats = []; home_bats = []
        def lineup_xwoba(bats):
            vals = []
            for b in bats:
                for k in ["sv_xwoba","fg_woba"]:
                    try:
                        f = float(b.get(k,0))
                        if 0.1 < f < 0.6: vals.append(f); break
                    except Exception: pass
                else:
                    vals.append(0.320)
            return round(sum(vals)/len(vals), 3) if vals else 0.320
        away_xwoba = lineup_xwoba(away_bats)
        home_xwoba = lineup_xwoba(home_bats)
        away_blend = 0.6*away_pit_era + 0.4*away_pit_fip
        home_blend = 0.6*home_pit_era + 0.4*home_pit_fip
        away_runs = 4.50 * (away_blend/4.50) * (away_xwoba/0.320) * pf
        home_runs = 4.50 * (home_blend/4.50) * (home_xwoba/0.320) * pf
        ven = gdata.get("venue", {})
        venue_id_wx = ven.get("id")
        vloc = ven.get("location", {}) or {}
        coords = vloc.get("defaultCoordinates", {}) or {}
        lat = coords.get("latitude")
        lon = coords.get("longitude")
        try:
            dt_utc_wx = datetime.fromisoformat(gdata.get("gameDate","").replace("Z","+00:00"))
            proj_hour = dt_utc_wx.astimezone(ET).hour
        except Exception:
            proj_hour = 13
        wx = get_weather(lat, lon, proj_hour, venue_id=venue_id_wx)
        wx_adj = 0.0
        if not wx.get("dome"):
            try:
                t = float(wx.get("temp","70"))
                if t > 82: wx_adj = 0.20
                elif t > 76: wx_adj = 0.10
                elif t < 48: wx_adj = -0.20
                elif t < 56: wx_adj = -0.10
            except Exception: pass
        wind_adj = _wind_run_adj(wx)
        # Bullpen fatigue boost vs the opposing tired pen (day-cached, non-blocking).
        aid = away_t.get("team", {}).get("id")
        away_bp = _bullpen_run_boost(_relief_fatigue_penalty_cached(hid))
        home_bp = _bullpen_run_boost(_relief_fatigue_penalty_cached(aid))
        away_runs = round(away_runs + wx_adj + wind_adj + away_bp, 1)
        home_runs = round(home_runs + wx_adj + wind_adj + home_bp, 1)
        total = round(away_runs + home_runs, 1)
        at_abbr = away_t.get("team",{}).get("abbreviation","AWAY")
        ht_abbr = home_t.get("team",{}).get("abbreviation","HOME")
        diff = home_runs - away_runs
        if abs(diff) > 0.7:
            fav = ht_abbr if diff > 0 else at_abbr
        else:
            fav = "EVEN"
        # Win probability from run differential (logistic mapping)
        try:
            home_win_prob = 1.0 / (1.0 + math.exp(-0.5 * diff))
        except Exception:
            home_win_prob = 0.5
        away_win_prob = round(1.0 - home_win_prob, 4)
        home_win_prob = round(home_win_prob, 4)
        return {
            "success": True,
            "gamePk": game_pk,
            "awayAbbr": at_abbr, "homeAbbr": ht_abbr,
            "awayRuns": away_runs, "homeRuns": home_runs,
            "total": total, "favorite": fav,
            "awayWinProb": away_win_prob, "homeWinProb": home_win_prob,
            "awayXwoba": away_xwoba, "homeXwoba": home_xwoba,
            "awayPitcherEra": round(away_pit_era,2),
            "homePitcherEra": round(home_pit_era,2),
            "awayPitcherFip": round(away_pit_fip,2),
            "homePitcherFip": round(home_pit_fip,2),
            "parkFactor": pf, "wxAdj": wx_adj,
        }
    except Exception as ex:
        print(f"[_compute_game_projection_core] {traceback.format_exc()}")
        return {"success": False, "error": str(ex)}


def _grade_game_bet(bet, away, home, ascore, hscore):
    """WON / LOST / PUSH for an ML or game-total bet vs a final box score."""
    try:
        a, h = int(ascore or 0), int(hscore or 0)
    except (TypeError, ValueError):
        return None
    if not bet:
        return None
    if bet.get("marketKey") == "game_moneyline":
        if a == h:
            return "PUSH"
        return "WON" if (away if a > h else home) == bet.get("side") else "LOST"
    if bet.get("marketKey") == "game_total" and bet.get("line") is not None:
        tot = a + h
        if tot == bet["line"]:
            return "PUSH"
        return "WON" if ((bet.get("side") == "Over") == (tot > bet["line"])) else "LOST"
    return None


_sharp_history_lock = threading.Lock()


def _record_sharp_verdict(game_pk, date_str, away, home, best, is_final, ascore, hscore):
    """Persist the pre-game Sharp Card verdict (locked once, before first pitch)
    and grade it against the final once available — building a rolling hit-rate
    record without re-grading a verdict that may have since shifted."""
    if not date_str:
        date_str = datetime.now(ET).strftime("%Y-%m-%d")
    try:
        with _sharp_history_lock:
            store = _load_json(SHARP_HISTORY_STORE, {})
            day = store.setdefault(date_str, {})
            rec = day.get(str(game_pk))
            changed = False
            if rec is None:
                # Lock the verdict only before the game is final, so we record a
                # genuine pre-result prediction.
                if best and not is_final:
                    day[str(game_pk)] = {
                        "recordedAt": datetime.now(ET).isoformat(),
                        "away": away, "home": home,
                        "bestBet": best, "grade": None, "gradedAt": None,
                    }
                    changed = True
            elif is_final and rec.get("grade") is None:
                rec["grade"] = _grade_game_bet(rec.get("bestBet"), away, home, ascore, hscore)
                rec["gradedAt"] = datetime.now(ET).isoformat()
                changed = True
            # Retention cap: this endpoint auto-writes on every dashboard/deep-dive
            # view, so keep only the most recent ~90 date keys to bound the file.
            if changed and len(store) > 90:
                for old in sorted(store.keys())[:-90]:
                    store.pop(old, None)
            if changed:
                _save_json(SHARP_HISTORY_STORE, store)
    except Exception as ex:
        print(f"[_record_sharp_verdict] {ex}")


def _mc_win_pct(game_pk):
    """Return (away_wp, home_wp) from the cached Monte Carlo sim for this game,
    tie-redistributed to a 2-way moneyline probability, or None if no fresh sim
    is cached. Lets the Sharp Card surface the simulation's variance-aware win%
    instead of the lightweight closed-form (which projects a wider run gap and
    therefore runs hotter), so its moneyline signal matches the simulation."""
    try:
        cc = _correlation_cache.get(game_pk)
        if not cc or cc.get('date') != datetime.now(ET).strftime('%Y-%m-%d'):
            return None
        team = ((cc.get('payload') or {}).get('team')) or {}
        aw, hw = team.get('away_win_pct'), team.get('home_win_pct')
        if aw is None or hw is None:
            return None
        decided = float(aw) + float(hw)
        if decided <= 0:
            return None
        return round(float(aw) / decided, 4), round(float(hw) / decided, 4)
    except Exception:
        return None


def _build_sharp_card(game_pk):
    """Server-side Sharp Card rollup — the game-level half of the deep-dive's
    in-page Sharp Card (side lean, total lean, scoring environment, drivers, a
    headline best bet, and a final-result grade). Player-prop selection stays
    client-side since it needs the Monte Carlo sim. Reuses parse_game (weather /
    park / score) and _compute_game_projection_core (total / favorite / win%)."""
    g = fetch_schedule_game(game_pk)
    if not g:
        return {"success": False, "error": "Game not found"}
    gd = parse_game(g) or {}
    proj = _compute_game_projection_core(game_pk) or {}
    away = gd.get("awayAbbr") or proj.get("awayAbbr") or "AWAY"
    home = gd.get("homeAbbr") or proj.get("homeAbbr") or "HOME"
    total = proj.get("total")
    fav = proj.get("favorite") or "EVEN"
    awp = proj.get("awayWinProb"); hwp = proj.get("homeWinProb")
    # Prefer the Monte Carlo win% when a fresh sim is cached — the closed-form
    # projection runs hotter (wider run gap) than the full lineup simulation.
    win_source = "model"
    _mc_wp = _mc_win_pct(game_pk)
    if _mc_wp is not None:
        awp, hwp = _mc_wp
        win_source = "monte_carlo"
    win_team, win_pct = (None, None)
    if awp is not None and hwp is not None:
        win_team, win_pct = (away, awp) if awp >= hwp else (home, hwp)
    lean_team = win_team if (win_source == "monte_carlo" and win_team) else fav
    run_env = "HIGH" if (total is not None and total > 9.5) else ("LOW" if (total is not None and total < 7.5) else "NEUTRAL")
    total_lean = "OVER" if run_env == "HIGH" else ("UNDER" if run_env == "LOW" else "NEUTRAL")

    imp = gd.get("weatherImpact") or {}
    drivers = []
    if gd.get("windField") and isinstance(gd.get("windOut"), (int, float)) and abs(gd["windOut"]) >= 4 and gd.get("temp") != "DOME":
        drivers.append(f"{abs(round(gd['windOut']))}mph {gd['windField']}")
    hl, hr = gd.get("hrParkFactorLHB"), gd.get("hrParkFactorRHB")
    if hl is not None and hr is not None and abs(hl - hr) >= 0.06:
        drivers.append("Park HR favors " + ("LHB" if hl > hr else "RHB"))

    # Headline best bet (ML / total only — props need the sim). The moneyline
    # signal must be backed by the Monte Carlo win% (not the hotter closed-form),
    # so a "STRONG BET" ML only fires when the simulation actually supports it.
    cands = []
    if (win_source == "monte_carlo" and win_pct is not None and win_pct >= 0.56
            and (fav == "EVEN" or fav == win_team)):
        cands.append({"conf": (win_pct - 0.5) * 2 + (0.12 if fav == win_team else 0.0),
                      "type": "ML", "marketKey": "game_moneyline", "side": win_team, "line": 0,
                      "text": f"{win_team} moneyline — {round(win_pct*100)}% to win"})
    if total is not None:
        if run_env == "HIGH" and total >= 9.2:
            cands.append({"conf": min(0.6, (total - 8.5) * 0.25), "type": "TOTAL",
                          "marketKey": "game_total", "side": "Over", "line": round(total * 2) / 2,
                          "text": f"Game total OVER — model {total:.1f} in a high-scoring environment"})
        elif run_env == "LOW" and total <= 7.8:
            cands.append({"conf": min(0.6, (8.5 - total) * 0.25), "type": "TOTAL",
                          "marketKey": "game_total", "side": "Under", "line": round(total * 2) / 2,
                          "text": f"Game total UNDER — model {total:.1f} in a suppressed environment"})
    best = None
    if cands:
        cands.sort(key=lambda c: -c["conf"])
        top = cands[0]
        tier = "STRONG BET" if top["conf"] >= 0.45 else ("LEAN" if top["conf"] >= 0.22 else "SLIGHT LEAN")
        best = {"type": top["type"], "marketKey": top["marketKey"], "side": top["side"],
                "line": top["line"], "tier": tier, "text": "Best bet: " + top["text"]}

    # Grade vs final when available.
    status = gd.get("status") or ""
    is_final = status in ("Final", "Game Over", "Completed Early")
    ascore, hscore = gd.get("awayScore"), gd.get("homeScore")
    grade = _grade_game_bet(best, away, home, ascore, hscore) if (is_final and best) else None

    # Persist the verdict (pre-game lock + post-game grade) for the hit-rate log.
    date_str = g.get("officialDate") or (g.get("gameDate") or "")[:10]
    _record_sharp_verdict(game_pk, date_str, away, home, best, is_final, ascore, hscore)

    return {
        "success": True, "gamePk": game_pk, "awayAbbr": away, "homeAbbr": home,
        "status": status, "final": is_final,
        "sideLean": {"team": lean_team, "winTeam": win_team, "winPct": win_pct, "source": win_source},
        "totalLean": {"lean": total_lean, "total": total, "runEnv": run_env},
        "environment": {"tier": imp.get("tier"), "runDelta": imp.get("runDelta"), "label": imp.get("label")},
        "drivers": drivers,
        "bestBet": best,
        "grade": grade,
    }


@app.route('/api/sharp-card/<int:game_pk>')
def api_sharp_card(game_pk):
    try:
        out = _build_sharp_card(game_pk)
        return jsonify(out), (200 if out.get("success") else 404)
    except Exception as ex:
        print(f"[api_sharp_card] {traceback.format_exc()}")
        return jsonify({"success": False, "error": str(ex)}), 500


@app.route('/api/sharp-card/accuracy')
def api_sharp_card_accuracy():
    """Rolling hit-rate of recorded Sharp Card best bets (graded verdicts)."""
    try:
        with _sharp_history_lock:
            store = _load_json(SHARP_HISTORY_STORE, {})
        overall = {"won": 0, "lost": 0, "push": 0}
        by_type = {}
        recent = []
        for date_str in sorted(store.keys(), reverse=True):
            for gpk, rec in store[date_str].items():
                grade = rec.get("grade")
                bet = rec.get("bestBet") or {}
                btype = bet.get("type") or "?"
                bucket = by_type.setdefault(btype, {"won": 0, "lost": 0, "push": 0})
                if grade == "WON":
                    overall["won"] += 1; bucket["won"] += 1
                elif grade == "LOST":
                    overall["lost"] += 1; bucket["lost"] += 1
                elif grade == "PUSH":
                    overall["push"] += 1; bucket["push"] += 1
                if grade and len(recent) < 30:
                    recent.append({"date": date_str, "gamePk": gpk,
                                   "matchup": f"{rec.get('away','')} @ {rec.get('home','')}",
                                   "bet": bet.get("text"), "grade": grade})
        decided = overall["won"] + overall["lost"]
        overall["hitRate"] = round(overall["won"] / decided, 3) if decided else None
        for b in by_type.values():
            d = b["won"] + b["lost"]
            b["hitRate"] = round(b["won"] / d, 3) if d else None
        return jsonify({"success": True, "overall": overall, "byType": by_type, "recent": recent})
    except Exception as ex:
        print(f"[api_sharp_card_accuracy] {traceback.format_exc()}")
        return jsonify({"success": False, "error": str(ex)}), 500


@app.route('/api/market/<int:game_pk>')
def api_market(game_pk):
    try:
        g = fetch_schedule_game(game_pk)
        if not g:
            return jsonify({'success': False, 'error': 'Game not found'}), 404

        away_team = g.get('teams', {}).get('away', {}).get('team', {})
        home_team = g.get('teams', {}).get('home', {}).get('team', {})
        away_name = away_team.get('name', '')
        home_name = home_team.get('name', '')
        away_abbr = away_team.get('abbreviation', 'AWAY')
        home_abbr = home_team.get('abbreviation', 'HOME')

        box = requests.get(f"{MLB_API}/game/{game_pk}/boxscore", timeout=10).json().get('teams', {})
        away_lineup = get_batters_from_boxscore(box.get('away', {}), 'away')
        home_lineup = get_batters_from_boxscore(box.get('home', {}), 'home')
        away_confirmed = len(away_lineup) >= 9
        home_confirmed = len(home_lineup) >= 9

        valid_names = set([x.get('name') for x in away_lineup + home_lineup if x.get('name')])
        away_p = g.get('teams', {}).get('away', {}).get('probablePitcher', {})
        home_p = g.get('teams', {}).get('home', {}).get('probablePitcher', {})
        if away_p.get('fullName'): valid_names.add(away_p.get('fullName'))
        if home_p.get('fullName'): valid_names.add(home_p.get('fullName'))

        event, events = _find_odds_event(away_name, home_name)
        featured = _load_event_odds(event.get('id') if event else None, featured_only=True) if event else []
        props_books = _load_event_odds(event.get('id') if event else None, featured_only=False) if event else []
        props = _parse_prop_markets(props_books, valid_names)

        market = {
            'moneyline': _best_moneyline(featured, away_name, home_name),
            'total': _best_total(featured),
        }

        return jsonify({
            'success': True,
            'meta': {
                'oddsApiConfigured': bool(ODDS_API_KEY),
                'oddsEventFound': bool(event),
                'eventId': event.get('id') if event else None,
                'bookmakersFeatured': len(featured),
                'bookmakersProps': len(props_books),
                'awayAbbr': away_abbr,
                'homeAbbr': home_abbr,
            },
            'lineup': {
                'awayConfirmed': away_confirmed,
                'homeConfirmed': home_confirmed,
                'awayCount': len(away_lineup),
                'homeCount': len(home_lineup),
                'status': g.get('status', {}).get('detailedState', 'Scheduled'),
            },
            'lines': market,
            'playerProps': props[:220],
        })
    except Exception as ex:
        print('[api_market]', traceback.format_exc())
        return jsonify({'success': False, 'error': str(ex)}), 500



def _append_calibration_history(event_type, adjustments, meta=None):
    meta = meta or {}
    hist = _load_json(CAL_HISTORY_STORE, [])
    hist.append({
        'timestamp': datetime.now().isoformat(),
        'eventType': event_type,
        'date': meta.get('date'),
        'window': meta.get('window'),
        'applied': meta.get('applied', []),
        'note': meta.get('note'),
        'adjustments': adjustments,
    })
    _save_json(CAL_HISTORY_STORE, hist[-800:])


def _history_in_window(end_date_str, window_days):
    dates = set(_dates_in_window(end_date_str, window_days))
    hist = _load_json(CAL_HISTORY_STORE, [])
    out = []
    for row in hist:
        if not isinstance(row, dict):
            continue
        ts = (row.get('timestamp') or '')[:10]
        if ts in dates:
            out.append(row)
    return out


def _daily_series(end_date_str, window_days, market_key=None):
    store = _tracker_store()
    dates = list(reversed(_dates_in_window(end_date_str, window_days)))
    series = []
    for ds in dates:
        day = _normalize_tracker_day(store.get(ds))
        rows = list(day.get('entries', []) or [])
        if market_key:
            rows = [r for r in rows if r.get('marketKey') == market_key]
        active = [r for r in rows if r.get('grade') in ('win', 'loss')]
        wins = sum(1 for r in active if r.get('grade') == 'win')
        losses = sum(1 for r in active if r.get('grade') == 'loss')
        hit_rate = round(wins / max(1, wins + losses), 4) if active else None
        avg_edge = round(sum(float(r.get('edge') or 0) for r in active) / max(1, len(active)), 4) if active else None
        series.append({
            'date': ds, 'graded': len(active), 'wins': wins, 'losses': losses,
            'hit_rate': hit_rate, 'avg_edge': avg_edge
        })
    return series


def _multiplier_history(end_date_str, window_days, market_key):
    hist = _history_in_window(end_date_str, window_days)
    points = []
    for row in hist:
        adj = row.get('adjustments', {}) or {}
        mult = ((adj.get('market_multipliers') or {}).get(market_key))
        if mult is None:
            continue
        points.append({
            'timestamp': row.get('timestamp'),
            'multiplier': float(mult),
            'eventType': row.get('eventType'),
            'note': row.get('note'),
            'applied': row.get('applied', []),
        })
    return points


