def _get_adjustments():
    obj = _load_json(ADJUST_STORE, _default_adjustments())
    d = _default_adjustments()
    d.update({k: v for k, v in obj.items() if k not in ('market_multipliers', 'blend_weights')})
    d['market_multipliers'].update(obj.get('market_multipliers', {}))
    d['blend_weights'].update(obj.get('blend_weights', {}))
    return d


def _market_mult(market_key, adjustments):
    return float((adjustments or {}).get('market_multipliers', {}).get(market_key, 1.0) or 1.0)


def _clamp01(v):
    return _clamp(v, 0.01, 0.99)


def _tracker_stat_from_boxscore(player_obj, market_key):
    if not player_obj:
        return None
    if market_key == 'pitcher_strikeouts':
        p = player_obj.get('stats', {}).get('pitching', {})
        return int(p.get('strikeOuts', 0) or 0)
    b = player_obj.get('stats', {}).get('batting', {})
    hits = int(b.get('hits', 0) or 0)
    doubles = int(b.get('doubles', 0) or 0)
    triples = int(b.get('triples', 0) or 0)
    hr = int(b.get('homeRuns', 0) or 0)
    singles = max(0, hits - doubles - triples - hr)
    mapping = {
        'batter_hits': hits,
        'batter_total_bases': singles + 2 * doubles + 3 * triples + 4 * hr,
        'batter_home_runs': hr,
        'batter_rbis': int(b.get('rbi', 0) or 0),
        'batter_runs_scored': int(b.get('runs', 0) or 0),
        'batter_hits_runs_rbis': hits + int(b.get('runs', 0) or 0) + int(b.get('rbi', 0) or 0),
        'batter_stolen_bases': int(b.get('stolenBases', 0) or 0),
    }
    return mapping.get(market_key)


def _grade_over(actual, line):
    if actual is None:
        return 'pending'
    if float(actual) > float(line):
        return 'win'
    if float(actual) < float(line):
        return 'loss'
    return 'push'


def _grade_side(actual, line, side='Over'):
    if actual is None:
        return 'pending'
    side_l = str(side or 'Over').lower()
    if side_l == 'under':
        if float(actual) < float(line):
            return 'win'
        if float(actual) > float(line):
            return 'loss'
        return 'push'
    return _grade_over(actual, line)


def _hub_rating(adj_prob, edge, l10_over_rate=0.5):
    trend_bonus = (l10_over_rate - 0.5) * 20
    edge_bonus  = min((edge or 0) * 100, 20)
    prob_base   = (adj_prob or 0) * 60
    raw = prob_base + edge_bonus + trend_bonus
    return max(0, min(100, round(raw)))


def _projection_reason_short(player, market_key, adj_prob, edge, opp_name=''):
    lbl = market_key.replace('batter_', '').replace('pitcher_', '').replace('_', ' ')
    if edge is not None:
        return f"{player} rates well for {lbl}; model {adj_prob:.1%} with edge {edge:.1%} versus market."
    if opp_name:
        return f"{player} rates well for {lbl}; model {adj_prob:.1%} against {opp_name}."
    return f"{player} rates well for {lbl}; model probability {adj_prob:.1%}."


def _build_team_market_rows(game_pk, capture_date, away_abbr, home_abbr,
                            away_name, home_name, adjustments):
    """Generates tracker rows for team-level / game-level markets:
    h2h (moneyline), totals (game O/U), f5_h2h, f5_totals, nrfi, yrfi.

    Each row matches the schema of the batter/pitcher rows in
    _build_tracker_rows_for_game so the tracker UI, grading, parlay builder,
    and bet slip all work unchanged.
    """
    rows = []
    label = f"{away_abbr}@{home_abbr}"
    proj = _compute_game_projection_core(game_pk)
    f5   = _compute_f5(game_pk)

    # Odds lookup
    ml = {'away': None, 'home': None}
    tot = None
    try:
        event, _ = _find_odds_event(away_name, home_name)
        if event and event.get('id'):
            books = _load_event_odds(event.get('id'), featured_only=False) or []
            ml = _best_moneyline(books, away_name, home_name) or ml
            tot = _best_total(books)
    except Exception as ex:
        print(f"[_build_team_market_rows] odds fetch failed for {game_pk}: {ex}")

    # NRFI/YRFI implied prices
    try:
        nrfi_snap = _nrfi_market_snapshot(away_name, home_name) or {}
    except Exception:
        nrfi_snap = {}

    def _finalize_row(row):
        """Apply common metadata + schema fields to every team-market row."""
        row['id'] = str(uuid4())
        row['savedAt'] = datetime.now(ET).isoformat()
        row['source'] = 'team_market'
        row['status'] = 'pending'
        row['actual'] = None
        row['grade'] = 'pending'
        row['parlayId'] = None
        row['parlayLeg'] = None
        row['closingPrice'] = None
        row['closingImplied'] = None
        row['closingBookmaker'] = None
        row['closingCapturedAt'] = None
        row['clvEdge'] = None
        row['profitUnits'] = None
        row['profitDollars'] = None
        row['bvpGrade'] = None
        row['date'] = capture_date
        row['gamePk'] = game_pk
        stake_profile = _stake_profile(row, adjustments)
        row['stakeDollars'] = stake_profile.get('stake_dollars')
        row['confidenceTier'] = _confidence_tier(row)
        return row

    def _emit(market_key, side, line, raw_prob, market_implied, market_price,
              bookmaker, opp_book_price, opp_book_name, team, reason):
        """Build a single row and append to rows."""
        raw_mult_prob = _clamp01(raw_prob * _market_mult(market_key, adjustments))
        adj_prob = raw_mult_prob
        edge = (adj_prob - market_implied) if market_implied is not None else None
        score = (edge * 100.0 if edge is not None else 0) + adj_prob
        hub = _hub_rating(adj_prob, edge or 0)
        ev_pct = round(adj_prob / market_implied - 1, 4) if market_implied and market_implied > 0 else None
        row = {
            'team': team,
            'player': label,
            'playerId': None,
            'marketKey': market_key,
            'line': line,
            'recommendedSide': side,
            'sideLabel': side,
            'rawProb': round(raw_prob, 4),
            'rawMultProb': round(raw_mult_prob, 4),
            'adjProb': round(adj_prob, 4),
            'modelMean': None,
            'edge': round(edge, 4) if edge is not None else None,
            'bookmaker': bookmaker,
            'marketPrice': market_price,
            'marketImplied': market_implied,
            'bestAvailablePrice': market_price,
            'bestAvailableBook': bookmaker,
            'bestOverPrice': market_price,
            'bestOverBook': bookmaker,
            'bestUnderPrice': opp_book_price,
            'bestUnderBook': opp_book_name,
            'best_over_price': market_price,
            'best_over_book': bookmaker,
            'best_under_price': opp_book_price,
            'best_under_book': opp_book_name,
            'lineRange': None,
            'bookCount': 1 if bookmaker else 0,
            'lineVaries': False,
            'line_range': None,
            'book_count': 1 if bookmaker else 0,
            'line_varies': False,
            'score': round(score, 4),
            'hubRating': hub,
            'evPct': ev_pct,
            'opp': home_abbr if team == away_abbr else away_abbr,
            'reason': reason,
            'openingPrice': market_price,
            'openingImplied': market_implied,
        }
        rows.append(_finalize_row(row))

    # ── Moneyline (h2h) ─────────────────────────────────────────────────────
    if proj.get('success'):
        away_wp = float(proj.get('awayWinProb') or 0.5)
        home_wp = float(proj.get('homeWinProb') or 0.5)
        if away_wp >= home_wp:
            side, side_wp, opp_wp = away_abbr, away_wp, home_wp
            side_ml, opp_ml = (ml or {}).get('away'), (ml or {}).get('home')
            team = away_abbr
        else:
            side, side_wp, opp_wp = home_abbr, home_wp, away_wp
            side_ml, opp_ml = (ml or {}).get('home'), (ml or {}).get('away')
            team = home_abbr
        mi = side_ml.get('implied') if side_ml else None
        mp = side_ml.get('price') if side_ml else None
        bk = side_ml.get('bookmaker') if side_ml else None
        opp_price = opp_ml.get('price') if opp_ml else None
        opp_book = opp_ml.get('bookmaker') if opp_ml else None
        _emit('h2h', side, 0, side_wp, mi, mp, bk, opp_price, opp_book, team,
              f"Model favors {side} ({side_wp:.1%} win prob) — {away_abbr} {proj.get('awayRuns')} / {home_abbr} {proj.get('homeRuns')}.")

    # ── Game Total Over/Under (totals) ──────────────────────────────────────
    if proj.get('success'):
        line = float(tot.get('line')) if tot and tot.get('line') is not None else 8.5
        model_total = float(proj.get('total') or 0)
        raw_prob = _poisson_over_prob(model_total, line)
        if raw_prob >= 0.5:
            side = 'Over'
            mi = tot.get('over_implied') if tot else None
            mp = tot.get('over_price') if tot else None
            opp_price = tot.get('under_price') if tot else None
        else:
            side = 'Under'
            raw_prob = 1.0 - raw_prob
            mi = tot.get('under_implied') if tot else None
            mp = tot.get('under_price') if tot else None
            opp_price = tot.get('over_price') if tot else None
        bk = tot.get('bookmaker') if tot else None
        _emit('totals', side, line, raw_prob, mi, mp, bk, opp_price, bk, home_abbr,
              f"Model total {model_total:.1f} vs line {line:.1f} — leans {side}.")

    # ── F5 Moneyline ────────────────────────────────────────────────────────
    if f5.get('success'):
        away_f5 = float(f5.get('awayF5') or 0)
        home_f5 = float(f5.get('homeF5') or 0)
        diff = home_f5 - away_f5
        try:
            home_wp_f5 = 1.0 / (1.0 + math.exp(-0.6 * diff))
        except Exception:
            home_wp_f5 = 0.5
        away_wp_f5 = 1.0 - home_wp_f5
        if away_wp_f5 >= home_wp_f5:
            side, side_wp, team = away_abbr, away_wp_f5, away_abbr
        else:
            side, side_wp, team = home_abbr, home_wp_f5, home_abbr
        _emit('f5_h2h', side, 0, side_wp, None, None, None, None, None, team,
              f"F5 model favors {side} ({side_wp:.1%}) — {away_abbr} {away_f5:.2f} / {home_abbr} {home_f5:.2f}.")

    # ── F5 Total ────────────────────────────────────────────────────────────
    if f5.get('success'):
        total_f5 = float(f5.get('totalF5') or 0)
        line = 4.5
        raw_prob = _poisson_over_prob(total_f5, line)
        if raw_prob >= 0.5:
            side = 'Over'
        else:
            side = 'Under'
            raw_prob = 1.0 - raw_prob
        _emit('f5_totals', side, line, raw_prob, None, None, None, None, None, home_abbr,
              f"F5 model total {total_f5:.2f} vs line {line:.1f} — leans {side}.")

    # ── NRFI / YRFI ─────────────────────────────────────────────────────────
    nrfi_imp = nrfi_snap.get('nrfi_implied')
    yrfi_imp = nrfi_snap.get('yrfi_implied')
    try:
        nrfi_model = _compute_nrfi(game_pk) if (nrfi_imp is not None or yrfi_imp is not None) else None
    except Exception:
        nrfi_model = None
    if nrfi_model and nrfi_model.get('success'):
        nrfi_prob = float(nrfi_model.get('nrfi_prob') or nrfi_model.get('nrfiProb') or 0)
        yrfi_prob = float(nrfi_model.get('yrfi_prob') or nrfi_model.get('yrfiProb') or (1.0 - nrfi_prob))
        nrfi_edge = (nrfi_prob - nrfi_imp) if nrfi_imp is not None else None
        yrfi_edge = (yrfi_prob - yrfi_imp) if yrfi_imp is not None else None
        # Emit only the side with positive edge (if any). Skip both if neither has edge.
        if nrfi_edge is not None and nrfi_edge > 0 and (yrfi_edge is None or nrfi_edge >= yrfi_edge):
            _emit('nrfi', 'NRFI', 0, nrfi_prob, nrfi_imp, nrfi_snap.get('nrfi_price'),
                  nrfi_snap.get('nrfi_book'), nrfi_snap.get('yrfi_price'), nrfi_snap.get('yrfi_book'),
                  home_abbr, f"NRFI model {nrfi_prob:.1%} vs market {nrfi_imp:.1%}.")
        elif yrfi_edge is not None and yrfi_edge > 0:
            _emit('yrfi', 'YRFI', 0, yrfi_prob, yrfi_imp, nrfi_snap.get('yrfi_price'),
                  nrfi_snap.get('yrfi_book'), nrfi_snap.get('nrfi_price'), nrfi_snap.get('nrfi_book'),
                  home_abbr, f"YRFI model {yrfi_prob:.1%} vs market {yrfi_imp:.1%}.")

    return rows


def _build_tracker_rows_for_game(game_pk, capture_date, adjustments=None, _sched=None, include_odds=False):
    adjustments = adjustments or _get_adjustments()
    raw = _sched if _sched is not None else fetch_schedule(capture_date)
    g = next((x for x in raw if x.get('gamePk') == game_pk), None)
    if not g:
        return []

    away_team = g.get('teams', {}).get('away', {}).get('team', {})
    home_team = g.get('teams', {}).get('home', {}).get('team', {})
    away_team_id = away_team.get('id')
    home_team_id = home_team.get('id')
    away_abbr = away_team.get('abbreviation', 'AWAY')
    home_abbr = home_team.get('abbreviation', 'HOME')

    # ── Try boxscore lineups first (works once game has started) ─────────────
    away_lineup, home_lineup = [], []
    try:
        box = requests.get(f"{MLB_API}/game/{game_pk}/boxscore", timeout=10).json().get('teams', {})
        away_lineup = get_batters_from_boxscore(box.get('away', {}), 'away')
        home_lineup = get_batters_from_boxscore(box.get('home', {}), 'home')
    except Exception as ex:
        print(f'[tracker_rows] boxscore fetch failed for {game_pk}: {ex}')

    # ── Pre-game fallback: scheduled lineups from already hydrated schedule ──
    if not away_lineup or not home_lineup:
        try:
            lineups = (g.get('lineups') or {})

            def _parse_scheduled_lineup(hitters):
                out = []
                for i, p in enumerate(hitters or [], start=1):
                    name = (p.get('fullName') or p.get('name') or '').strip()
                    pid  = p.get('id') or p.get('playerId')
                    pos  = (p.get('primaryPosition') or {}).get('abbreviation', '?')
                    if not name:
                        continue
                    fgb = fg_batter(name); svb = sv_batter(name)
                    out.append({'slot': i, 'id': pid, 'name': name, 'pos': pos, 'bats': 'S',
                                'fg_pa': fgb.get('fg_pa','N/A'), 'fg_r': fgb.get('fg_r','N/A'),
                                'fg_sb': fgb.get('fg_sb','N/A'), 'fg_woba': fgb.get('fg_woba','N/A'),
                                'fg_wrc': fgb.get('fg_wrc','N/A'), 'fg_war': fgb.get('fg_war','N/A'),
                                'sv_xba': svb.get('sv_xba','N/A'), 'sv_xslg': svb.get('sv_xslg','N/A'),
                                'sv_xwoba': svb.get('sv_xwoba','N/A'), 'sv_ev': svb.get('sv_ev','N/A'),
                                'sv_hh_pct': svb.get('sv_hh_pct','N/A'), 'sv_brl_pct': svb.get('sv_brl_pct','N/A'),
                                'sv_la': svb.get('sv_la','N/A'),
                                'avg': fgb.get('fg_avg','.---'), 'obp': fgb.get('fg_obp','.---'),
                                'slg': fgb.get('fg_slg','.---'), 'ops': fgb.get('fg_ops','.---'),
                                'ab': 0, 'hits': 0, 'hr': 0, 'rbi': 0})
                return out

            if not away_lineup:
                away_lineup = _parse_scheduled_lineup(lineups.get('awayBatters', []))
            if not home_lineup:
                home_lineup = _parse_scheduled_lineup(lineups.get('homeBatters', []))
        except Exception as ex:
            print(f'[tracker_rows] scheduled lineup parse failed for {game_pk}: {ex}')

    # ── Last resort: active roster (top 9 position players) ─────────────────
    def _roster_lineup(team_id):
        try:
            out = []
            for entry in _get_active_roster(team_id):
                pos = ((entry.get('position') or {}).get('abbreviation') or '?')
                if pos in ('P', 'SP', 'RP', 'CP'):
                    continue
                name = ((entry.get('person') or {}).get('fullName') or '').strip()
                pid  = ((entry.get('person') or {}).get('id'))
                if not name:
                    continue
                fgb = fg_batter(name); svb = sv_batter(name)
                out.append({'slot': len(out)+1, 'id': pid, 'name': name, 'pos': pos, 'bats': 'S',
                            'fg_pa': fgb.get('fg_pa','N/A'), 'fg_r': fgb.get('fg_r','N/A'),
                            'fg_sb': fgb.get('fg_sb','N/A'), 'fg_woba': fgb.get('fg_woba','N/A'),
                            'fg_wrc': fgb.get('fg_wrc','N/A'), 'fg_war': fgb.get('fg_war','N/A'),
                            'sv_xba': svb.get('sv_xba','N/A'), 'sv_xslg': svb.get('sv_xslg','N/A'),
                            'sv_xwoba': svb.get('sv_xwoba','N/A'), 'sv_ev': svb.get('sv_ev','N/A'),
                            'sv_hh_pct': svb.get('sv_hh_pct','N/A'), 'sv_brl_pct': svb.get('sv_brl_pct','N/A'),
                            'sv_la': svb.get('sv_la','N/A'),
                            'avg': fgb.get('fg_avg','.---'), 'obp': fgb.get('fg_obp','.---'),
                            'slg': fgb.get('fg_slg','.---'), 'ops': fgb.get('fg_ops','.---'),
                            'ab': 0, 'hits': 0, 'hr': 0, 'rbi': 0})
                if len(out) >= 9:
                    break
            return out
        except Exception:
            return []

    if not away_lineup:
        away_lineup = _roster_lineup(away_team_id)
    if not home_lineup:
        home_lineup = _roster_lineup(home_team_id)

    if not away_lineup or not home_lineup:
        return []

    park = PARK_FACTORS.get(home_team_id, 1.0)

    away_p = g.get('teams', {}).get('away', {}).get('probablePitcher', {})
    home_p = g.get('teams', {}).get('home', {}).get('probablePitcher', {})
    away_pitcher = _pitcher_model(away_p.get('fullName', 'Away SP'), away_p.get('id'), away_team_id)
    home_pitcher = _pitcher_model(home_p.get('fullName', 'Home SP'), home_p.get('id'), home_team_id)

    sims = int(os.getenv('TRACKER_SIMS', '700') or 700)
    sims = max(300, min(5000, sims))
    rng = random.Random(game_pk + int(capture_date.replace('-', '')) + 10)
    away_store = {i: [] for i in range(len(away_lineup))}
    home_store = {i: [] for i in range(len(home_lineup))}
    away_starter_lines, home_starter_lines = [], []

    for _ in range(sims):
        away_off = _simulate_offense(away_lineup, home_pitcher, home_team_id, park, rng)
        home_off = _simulate_offense(home_lineup, away_pitcher, away_team_id, park, rng)
        for i, line in enumerate(away_off['batters']): away_store[i].append(line)
        for i, line in enumerate(home_off['batters']): home_store[i].append(line)
        home_starter_lines.append(away_off['starter'])
        away_starter_lines.append(home_off['starter'])

    away_props, home_props = [], []
    for i, b in enumerate(away_lineup):
        s = _summarize_player(away_store[i]); s.update({'id': b.get('id'), 'name': b.get('name'), 'slot': b.get('slot'), 'pos': b.get('pos'), 'bats': b.get('bats', 'S')}); away_props.append(s)
    for i, b in enumerate(home_lineup):
        s = _summarize_player(home_store[i]); s.update({'id': b.get('id'), 'name': b.get('name'), 'slot': b.get('slot'), 'pos': b.get('pos'), 'bats': b.get('bats', 'S')}); home_props.append(s)

    away_sp = _summarize_pitcher(away_starter_lines); away_sp.update({'name': away_pitcher['name'], 'id': away_pitcher.get('id'), 'pitchHand': away_pitcher['pitchHand']})
    home_sp = _summarize_pitcher(home_starter_lines); home_sp.update({'name': home_pitcher['name'], 'id': home_pitcher.get('id'), 'pitchHand': home_pitcher['pitchHand']})

    market_props = []
    if include_odds:
        event, _ = _find_odds_event(away_team.get('name', ''), home_team.get('name', ''))
        props_books = _load_event_odds(event.get('id') if event else None, featured_only=False) if event else []
        valid_names = set([x.get('name') for x in away_lineup + home_lineup if x.get('name')])
        if away_pitcher.get('name'): valid_names.add(away_pitcher.get('name'))
        if home_pitcher.get('name'): valid_names.add(home_pitcher.get('name'))
        market_props = _parse_prop_markets(props_books, valid_names)

    def find_market(player, mk, line):
        for item in market_props:
            if item.get('player') == player and item.get('market_key') == mk and float(item.get('line')) == float(line):
                return item
        return None

    rows = []

    def process_hitters(arr, team_abbr, opp_name, opp_pitcher):
        for p in arr:
            player_name = p.get('name')
            for mk, mean_field in _BATTER_MEAN_FIELD_FOR_MK.items():
                # Use actual market lines from Odds API; fall back to single default
                mkt_lines = _market_lines_for_player(market_props, player_name, mk)
                lines_to_use = mkt_lines if mkt_lines else [_BATTER_FALLBACK_LINE[mk]]
                for line in lines_to_use:
                    prob_field = _BATTER_PROB_FIELD_FOR.get((mk, line))
                    if prob_field:
                        raw_prob = float(p.get(prob_field, 0) or 0)
                    else:
                        raw_prob = _poisson_over_prob(float(p.get(mean_field, 0) or 0), line)
                    if raw_prob < 0.10:
                        continue
                    raw_mult_prob = _clamp01(raw_prob * _market_mult(mk, adjustments))
                    market = find_market(player_name, mk, line)
                    msum = _market_price_summary(market_props, player_name, mk, line)
                    market_implied = msum.get('market_implied')
                    if market_implied and market_implied > 0:
                        over_imp = market_implied
                        under_imp = _american_to_implied(msum.get('best_under_price')) or (1 - over_imp)
                        adj_prob = logit_blend_prob(raw_mult_prob, over_imp, mk, over_imp, under_imp)
                    else:
                        adj_prob = raw_mult_prob
                    edge = (adj_prob - market_implied) if market_implied is not None else None
                    score = (edge * 100.0 if edge is not None else 0) + adj_prob
                    hub = _hub_rating(adj_prob, edge or 0)
                    mi = market_implied
                    ev_pct = round(adj_prob / mi - 1, 4) if mi and mi > 0 else None
                    temp_row = {
                        'date': capture_date, 'gamePk': game_pk, 'team': team_abbr, 'player': p.get('name'), 'playerId': p.get('id'), 'slot': p.get('slot'), 'marketKey': mk, 'line': line, 'recommendedSide': 'Over',
                        'rawProb': round(raw_prob, 4), 'rawMultProb': round(raw_mult_prob, 4), 'adjProb': round(adj_prob, 4), 'modelMean': round(float(p.get(mean_field, 0) or 0), 3), 'edge': round(edge, 4) if edge is not None else None,
                        'bookmaker': msum.get('market_bookmaker'), 'marketPrice': msum.get('best_over_price'), 'marketImplied': market_implied,
                        'bestAvailablePrice': msum.get('best_over_price'), 'bestAvailableBook': msum.get('best_over_book'),
                        'bestOverPrice': msum.get('best_over_price'), 'bestOverBook': msum.get('best_over_book'),
                        'bestUnderPrice': msum.get('best_under_price'), 'bestUnderBook': msum.get('best_under_book'),
                        'lineRange': msum.get('line_range'), 'bookCount': msum.get('book_count'), 'lineVaries': msum.get('line_varies'),
                        'best_over_price': msum.get('best_over_price'), 'best_over_book': msum.get('best_over_book'),
                        'best_under_price': msum.get('best_under_price'), 'best_under_book': msum.get('best_under_book'),
                        'line_range': msum.get('line_range'), 'book_count': msum.get('book_count'), 'line_varies': msum.get('line_varies'),
                        'score': round(score, 4), 'hubRating': hub, 'evPct': ev_pct, 'opp': opp_name, 'reason': _projection_reason_short(p.get('name'), mk, adj_prob, edge, opp_name), 'status': 'pending', 'actual': None, 'grade': 'pending', 'openingPrice': msum.get('best_over_price'), 'openingImplied': market_implied, 'closingPrice': None, 'closingImplied': None, 'closingBookmaker': None, 'closingCapturedAt': None, 'clvEdge': None, 'profitUnits': None, 'profitDollars': None,
                        'parlayId': None, 'parlayLeg': None
                    }
                    # ── MC fields (Step 4) ──────────────────────────────────────────────────
                    # xgb_ready() speaks the scorer's short market names
                    # (hits/tb/hr/rbi), not the book market keys (batter_*), so
                    # translate before gating — otherwise the guard is always
                    # False and the MC distribution fields stay null.
                    _mc_batter = None
                    _xgb_market, _full_fn = {
                        'batter_hits':        ('hits', xgb_hit_prob_full),
                        'batter_total_bases': ('tb',   xgb_tb_prob_full),
                        'batter_home_runs':   ('hr',   xgb_hr_prob_full),
                        'batter_rbis':        ('rbi',  xgb_rbi_prob_full),
                    }.get(mk, (None, None))
                    if _full_fn and xgb_ready(_xgb_market):
                        try:
                            _full = _full_fn(p, opp_pitcher) or {}
                        except Exception:
                            _full = {}
                        _mc_batter = _full.get('mc') or {}
                    temp_row['mc_prob_over']  = _mc_batter.get('mc_prob_over')  if _mc_batter else None
                    temp_row['mc_prob_under'] = _mc_batter.get('mc_prob_under') if _mc_batter else None
                    temp_row['mc_mean']       = _mc_batter.get('mc_mean')       if _mc_batter else None
                    temp_row['mc_p10']        = _mc_batter.get('mc_p10')        if _mc_batter else None
                    temp_row['mc_p25']        = _mc_batter.get('mc_p25')        if _mc_batter else None
                    temp_row['mc_p75']        = _mc_batter.get('mc_p75')        if _mc_batter else None
                    temp_row['mc_p90']        = _mc_batter.get('mc_p90')        if _mc_batter else None
                    temp_row['mc_std']        = _mc_batter.get('mc_std')        if _mc_batter else None
                    temp_row['mc_n_sims']     = _mc_batter.get('n_sims')        if _mc_batter else None
                    temp_row['mc_anchored']   = _mc_batter.get('anchored')      if _mc_batter else None
                    # ────────────────────────────────────────────────────────────────────────
                    # Phase 1: Add schema fields
                    temp_row['id'] = str(uuid4())
                    temp_row['savedAt'] = datetime.now(ET).isoformat()
                    temp_row['source'] = 'props_board'
                    stake_profile = _stake_profile(temp_row, adjustments)
                    temp_row['stakeDollars'] = stake_profile.get('stake_dollars')
                    # Phase 2: Add tier and BvP grade
                    temp_row['confidenceTier'] = _confidence_tier(temp_row)
                    if opp_pitcher and opp_pitcher.get('id'):
                        bvp_data = _fetch_bvp(p.get('id'), opp_pitcher.get('id'))
                        temp_row['bvpGrade'] = _compute_bvp_grade(bvp_data)
                    else:
                        temp_row['bvpGrade'] = None
                    rows.append(temp_row)

    # Away batters face the home pitcher; home batters face the away pitcher.
    process_hitters(away_props, away_abbr, home_pitcher.get('name'), home_pitcher)
    process_hitters(home_props, home_abbr, away_pitcher.get('name'), away_pitcher)

    k_xgb_ready = xgb_ready('k')
    for sp, team_abbr in [(away_sp, away_abbr), (home_sp, home_abbr)]:
        sp_mkt_lines = _market_lines_for_player(market_props, sp.get('name'), 'pitcher_strikeouts')
        k_lines = sp_mkt_lines if sp_mkt_lines else [3.5, 4.5, 5.5]
        mean_k = float(sp.get('mean_k', 0) or 0)
        # ── FanGraphs enrichment for pitcher K props (done once per starter) ──
        if k_xgb_ready:
            sp = {**sp, **enrich_pitcher(sp)}   # merges real FG stats into sp dict
            # Arsenal pitch-mix (usage-weighted whiff%/putaway%) for the K model.
            try:
                _ars = _arsenal_whiff_summary(sp.get('id'))
                if _ars:
                    sp['arsenalWhiff']   = _ars.get('whiff')
                    sp['arsenalPutaway'] = _ars.get('putaway')
            except Exception:
                pass
        # ─────────────────────────────────────────────────────────────────────
        for line in k_lines:
            prob_field = _K_PROB_FIELD_FOR.get(line)
            if prob_field:
                raw_prob = float(sp.get(prob_field, 0) or 0)
            else:
                raw_prob = _poisson_over_prob(mean_k, line)
            # XGBoost blend for K props — weight from model_adjustments blend_weights
            _xgb_k = xgb_k_prob(sp, line=line) if k_xgb_ready else None
            _mc_k_prob = raw_prob  # pure MC prob before any blend
            if _xgb_k is not None:
                _xgb_w = float((adjustments.get('blend_weights') or {}).get('xgb_k_weight', 0.60))
                _mc_w  = round(1.0 - _xgb_w, 4)
                raw_prob = max(0.0, min(1.0, _mc_w * raw_prob + _xgb_w * _xgb_k))
            if raw_prob < 0.12:
                continue
            raw_mult_prob = _clamp01(raw_prob * _market_mult('pitcher_strikeouts', adjustments))
            market = find_market(sp.get('name'), 'pitcher_strikeouts', line)
            msum = _market_price_summary(market_props, sp.get('name'), 'pitcher_strikeouts', line)
            market_implied = msum.get('market_implied')
            if market_implied and market_implied > 0:
                over_imp = market_implied
                under_imp = _american_to_implied(msum.get('best_under_price')) or (1 - over_imp)
                adj_prob = logit_blend_prob(raw_mult_prob, over_imp, 'pitcher_strikeouts', over_imp, under_imp)
            else:
                adj_prob = raw_mult_prob
            edge = (adj_prob - market_implied) if market_implied is not None else None
            score = (edge * 100.0 if edge is not None else 0) + adj_prob
            hub = _hub_rating(adj_prob, edge or 0)
            mi = market_implied
            ev_pct = round(adj_prob / mi - 1, 4) if mi and mi > 0 else None
            temp_row = {
                'date': capture_date, 'gamePk': game_pk, 'team': team_abbr, 'player': sp.get('name'), 'playerId': sp.get('id'), 'marketKey': 'pitcher_strikeouts', 'line': line, 'recommendedSide': 'Over',
                'rawProb': round(raw_prob, 4), 'rawMultProb': round(raw_mult_prob, 4), 'adjProb': round(adj_prob, 4), 'modelMean': round(float(sp.get('mean_k', 0) or 0), 3), 'edge': round(edge, 4) if edge is not None else None, 'xgbKProb': round(_xgb_k, 4) if _xgb_k is not None else None, 'mcKProb': round(_mc_k_prob, 4) if _xgb_k is not None else None,
                'bookmaker': msum.get('market_bookmaker'), 'marketPrice': msum.get('best_over_price'), 'marketImplied': market_implied,
                'bestAvailablePrice': msum.get('best_over_price'), 'bestAvailableBook': msum.get('best_over_book'),
                'bestOverPrice': msum.get('best_over_price'), 'bestOverBook': msum.get('best_over_book'),
                'bestUnderPrice': msum.get('best_under_price'), 'bestUnderBook': msum.get('best_under_book'),
                'lineRange': msum.get('line_range'), 'bookCount': msum.get('book_count'), 'lineVaries': msum.get('line_varies'),
                'best_over_price': msum.get('best_over_price'), 'best_over_book': msum.get('best_over_book'),
                'best_under_price': msum.get('best_under_price'), 'best_under_book': msum.get('best_under_book'),
                'line_range': msum.get('line_range'), 'book_count': msum.get('book_count'), 'line_varies': msum.get('line_varies'),
                'score': round(score, 4), 'hubRating': hub, 'evPct': ev_pct, 'opp': '', 'reason': _projection_reason_short(sp.get('name'), 'pitcher_strikeouts', adj_prob, edge), 'status': 'pending', 'actual': None, 'grade': 'pending', 'openingPrice': msum.get('best_over_price'), 'openingImplied': market_implied, 'closingPrice': None, 'closingImplied': None, 'closingBookmaker': None, 'closingCapturedAt': None, 'clvEdge': None, 'profitUnits': None, 'profitDollars': None,
                'parlayId': None, 'parlayLeg': None
            }
            # ── MC fields (Step 4) ──────────────────────────────────────────────────
            if k_xgb_ready:
                try:
                    _k_full = xgb_k_prob_full(sp, line=line) or {}
                except Exception:
                    _k_full = {}
                _mc_k   = (_k_full or {}).get('mc') or {}
            else:
                _mc_k = {}
            temp_row['mc_prob_over']  = _mc_k.get('mc_prob_over')
            temp_row['mc_prob_under'] = _mc_k.get('mc_prob_under')
            temp_row['mc_mean']       = _mc_k.get('mc_mean')
            temp_row['mc_p10']        = _mc_k.get('mc_p10')
            temp_row['mc_p25']        = _mc_k.get('mc_p25')
            temp_row['mc_p75']        = _mc_k.get('mc_p75')
            temp_row['mc_p90']        = _mc_k.get('mc_p90')
            temp_row['mc_std']        = _mc_k.get('mc_std')
            temp_row['mc_n_sims']     = _mc_k.get('n_sims')
            temp_row['mc_anchored']   = _mc_k.get('anchored')
            # ────────────────────────────────────────────────────────────────────────
            # Phase 1: Add schema fields
            temp_row['id'] = str(uuid4())
            temp_row['savedAt'] = datetime.now(ET).isoformat()
            temp_row['source'] = 'props_board'
            stake_profile = _stake_profile(temp_row, adjustments)
            temp_row['stakeDollars'] = stake_profile.get('stake_dollars')
            # Phase 2: Add tier and BvP grade
            temp_row['confidenceTier'] = _confidence_tier(temp_row)
            if away_pitcher and away_pitcher.get('id'):
                bvp_data = _fetch_bvp(sp.get('id'), away_pitcher.get('id'))
                temp_row['bvpGrade'] = _compute_bvp_grade(bvp_data)
            else:
                temp_row['bvpGrade'] = None
            rows.append(temp_row)

    # ── Team / game-level markets (h2h, totals, F5, NRFI/YRFI) ──────────────
    try:
        rows.extend(_build_team_market_rows(
            game_pk, capture_date, away_abbr, home_abbr,
            away_team.get('name', ''), home_team.get('name', ''), adjustments))
    except Exception as ex:
        print(f"[_build_tracker_rows_for_game] team_market build failed for {game_pk}: {ex}")

    rows.sort(key=lambda x: x.get('score', 0), reverse=True)
    keep = int((adjustments or {}).get('captured_per_game', 25) or 25)
    return rows[:keep]


def _build_tracker_rows_quick(game_obj, capture_date, adjustments=None):
    """Fast fallback when full simulation fails. Uses confirmed lineups only."""
    adjustments = adjustments or _get_adjustments()
    g = game_obj or {}
    away_team = g.get('teams', {}).get('away', {}).get('team', {})
    home_team = g.get('teams', {}).get('home', {}).get('team', {})
    away_abbr = away_team.get('abbreviation', 'AWAY')
    home_abbr = home_team.get('abbreviation', 'HOME')
    game_pk = g.get('gamePk')

    lineups = (g.get('lineups') or {})
    away_hitters = lineups.get('awayBatters') or []
    home_hitters = lineups.get('homeBatters') or []
    rows = []

    def _emit(hitters, team_abbr):
        for i, p in enumerate(hitters[:9], start=1):
            name = (p.get('fullName') or p.get('name') or '').strip()
            pid = p.get('id') or p.get('playerId')
            if not name:
                continue
            # Conservative heuristic probabilities by lineup slot.
            base_hit = max(0.45, min(0.63, 0.58 - (i - 1) * 0.015))
            base_tb2 = max(0.23, min(0.42, 0.36 - (i - 1) * 0.012))
            for mk, line, raw_prob in [
                ('batter_hits', 0.5, base_hit),
                ('batter_total_bases', 1.5, base_tb2),
            ]:
                adj_prob = _clamp01(raw_prob * _market_mult(mk, adjustments))
                row_data = {
                    'date': capture_date,
                    'gamePk': game_pk,
                    'team': team_abbr,
                    'player': name,
                    'playerId': pid,
                    'marketKey': mk,
                    'line': line,
                    'recommendedSide': 'Over',
                    'rawProb': round(raw_prob, 4),
                    'adjProb': round(adj_prob, 4),
                    'modelMean': None,
                    'edge': None,
                    'bookmaker': None,
                    'marketPrice': None,
                    'marketImplied': None,
                    'bestAvailablePrice': None,
                    'bestAvailableBook': None,
                    'bestOverPrice': None,
                    'bestOverBook': None,
                    'bestUnderPrice': None,
                    'bestUnderBook': None,
                    'lineRange': None,
                    'bookCount': 0,
                    'lineVaries': False,
                    'best_over_price': None,
                    'best_over_book': None,
                    'best_under_price': None,
                    'best_under_book': None,
                    'line_range': None,
                    'book_count': 0,
                    'line_varies': False,
                    'score': round(adj_prob, 4),
                    'hubRating': _hub_rating(adj_prob, 0),
                    'evPct': None,
                    'opp': '',
                    'reason': f'Fallback capture from confirmed lineup slot {i}.',
                    'status': 'pending',
                    'actual': None,
                    'grade': 'pending',
                    'openingPrice': None,
                    'openingImplied': None,
                    'closingPrice': None,
                    'closingImplied': None,
                    'closingBookmaker': None,
                    'closingCapturedAt': None,
                    'clvEdge': None,
                    'profitUnits': None,
                    'profitDollars': None,
                    'parlayId': None,
                    'parlayLeg': None,
                }
                # Phase 1: Add schema fields
                row_data['id'] = str(uuid4())
                row_data['savedAt'] = datetime.now(ET).isoformat()
                row_data['source'] = 'props_board'
                stake_profile = _stake_profile(row_data, adjustments)
                row_data['stakeDollars'] = stake_profile.get('stake_dollars')
                # Phase 2: Add tier and BvP grade (fallback capture)
                row_data['confidenceTier'] = _confidence_tier(row_data)
                row_data['bvpGrade'] = None  # No pitcher data in quick capture
                rows.append(row_data)

    _emit(away_hitters, away_abbr)
    _emit(home_hitters, home_abbr)
    rows.sort(key=lambda x: x.get('score', 0), reverse=True)
    keep = int((adjustments or {}).get('captured_per_game', 25) or 25)
    return rows[:keep]




_TRACKER_CAPTURE_LOCK = threading.Lock()
_TRACKER_CAPTURE_JOBS = {}
_TRACKER_AUTO_SYNC_LOCK = threading.Lock()
_TRACKER_AUTO_SYNC_STARTED = False


def _tracker_row_key(row):
    return (
        row.get('date'),
        row.get('gamePk'),
        row.get('player'),
        row.get('marketKey'),
        float(row.get('line') or 0),
    )


def _merge_tracker_entries(existing_rows, new_rows):
    out = {}
    for r in (existing_rows or []):
        if isinstance(r, dict):
            out[_tracker_row_key(r)] = r
    for r in (new_rows or []):
        if isinstance(r, dict):
            out[_tracker_row_key(r)] = r
    rows = list(out.values())
    rows.sort(key=lambda x: x.get('score', 0), reverse=True)
    return rows


def _tracker_capture_continue_bg(date_str, remaining_games, sched, adjustments, include_odds):
    try:
        bg_rows = []
        for g in remaining_games:
            gpk = g.get('gamePk')
            try:
                bg_rows.extend(_build_tracker_rows_for_game(gpk, date_str, adjustments, _sched=sched, include_odds=include_odds))
            except Exception:
                print(f'[tracker_capture_bg_game {gpk}]', traceback.format_exc())
        if not bg_rows:
            return
        with _TRACKER_STORE_LOCK:
            store = _load_json(TRACKER_STORE, {})
            day = _normalize_tracker_day(store.get(date_str))
            merged = _merge_tracker_entries(day.get('entries', []), _recalc_tracker_entries(bg_rows))
            day['entries'] = merged
            day['capturedAt'] = datetime.now().isoformat()
            store[date_str] = day
            _save_json(TRACKER_STORE, store)
    except Exception:
        print('[tracker_capture_bg]', traceback.format_exc())
    finally:
        with _TRACKER_CAPTURE_LOCK:
            _TRACKER_CAPTURE_JOBS.pop(date_str, None)


def _tracker_auto_sync_once():
    store = _tracker_store()
    if not store:
        return
    today = datetime.now(ET).strftime('%Y-%m-%d')
    for ds in sorted(store.keys(), reverse=True):
        if ds > today:
            continue
        day = _normalize_tracker_day(store.get(ds))
        pending = [r for r in day.get('entries', []) if r.get('grade') == 'pending']
        if not pending:
            continue
        # api_tracker_close / api_tracker_grade are admin-token-gated. When
        # ADMIN_TOKEN is set, calling them with an empty request context makes
        # _check_admin_auth() return a 401 that this worker would silently
        # discard — so nothing ever gets graded. Forward the token so the
        # internal call authenticates like a real admin request.
        _auth_headers = {'X-Admin-Token': _ADMIN_TOKEN} if _ADMIN_TOKEN else {}
        try:
            with app.test_request_context(f'/api/tracker/close/{ds}', method='POST', headers=_auth_headers):
                api_tracker_close(ds)
            with app.test_request_context(f'/api/tracker/grade/{ds}', method='POST', headers=_auth_headers):
                api_tracker_grade(ds)
        except Exception:
            print(f'[tracker_auto_sync_once {ds}] {traceback.format_exc()}')


def _start_tracker_auto_sync_worker():
    global _TRACKER_AUTO_SYNC_STARTED
    if str(os.getenv('TRACKER_AUTO_SYNC_ENABLED', '1')).strip().lower() not in ('1', 'true', 'yes'):
        return
    with _TRACKER_AUTO_SYNC_LOCK:
        if _TRACKER_AUTO_SYNC_STARTED:
            return
        _TRACKER_AUTO_SYNC_STARTED = True

    interval_min = max(5, int(os.getenv('TRACKER_AUTO_SYNC_MINUTES', '15') or 15))

    def _runner():
        while True:
            try:
                _tracker_auto_sync_once()
            except Exception:
                print(f'[tracker_auto_sync] {traceback.format_exc()}')
            time.sleep(interval_min * 60)

    threading.Thread(target=_runner, daemon=True).start()


_TRACKER_AUTO_CAPTURE_STARTED = False
_TRACKER_AUTO_CAPTURE_LOCK = threading.Lock()


def _tracker_auto_capture_once():
    """Capture today's slate into the tracker if it hasn't been captured yet.

    This is the missing half of the feedback loop: the auto-sync worker only
    *grades* picks that already exist, but picks only ever entered the tracker
    via the manual, admin-gated "Capture Slate" button. Without an automated
    capture, the tracker stays empty, the auto-grader has nothing to grade, and
    the per-market isotonic calibrators (which need graded outcomes) never
    train. This worker closes that gap.

    Reuses api_tracker_capture wholesale (parallel fetch, odds, background
    continuation) by calling it in-process with the admin token forwarded, so
    we don't duplicate the capture pipeline.
    """
    today = datetime.now(ET).strftime('%Y-%m-%d')

    # Only capture once lineups/odds have started to firm up. Capturing at
    # 3am ET would produce thin, projected-lineup picks. Configurable via
    # TRACKER_AUTO_CAPTURE_HOUR (ET, default 11:00).
    capture_hour = max(0, min(23, int(os.getenv('TRACKER_AUTO_CAPTURE_HOUR', '11') or 11)))
    if datetime.now(ET).hour < capture_hour:
        return

    store = _load_json(TRACKER_STORE, {})
    day = _normalize_tracker_day(store.get(today))
    # Already have picks for today — nothing to do. (Re-capture merges, but we
    # avoid re-hammering the MLB API once a day is populated.)
    if day.get('entries'):
        return

    _auth_headers = {'X-Admin-Token': _ADMIN_TOKEN} if _ADMIN_TOKEN else {}
    try:
        with app.test_request_context(f'/api/tracker/capture/{today}', method='POST', headers=_auth_headers):
            api_tracker_capture(today)
        print(f'[tracker_auto_capture] captured slate for {today}')
    except Exception:
        print(f'[tracker_auto_capture {today}] {traceback.format_exc()}')


def _start_tracker_auto_capture_worker():
    global _TRACKER_AUTO_CAPTURE_STARTED
    if str(os.getenv('TRACKER_AUTO_CAPTURE_ENABLED', '1')).strip().lower() not in ('1', 'true', 'yes'):
        return
    with _TRACKER_AUTO_CAPTURE_LOCK:
        if _TRACKER_AUTO_CAPTURE_STARTED:
            return
        _TRACKER_AUTO_CAPTURE_STARTED = True

    # Check a few times a day so the first run after capture_hour fires the
    # capture, and a failed capture gets retried on the next pass.
    interval_min = max(15, int(os.getenv('TRACKER_AUTO_CAPTURE_MINUTES', '120') or 120))

    def _runner():
        # Small startup delay so FG/Savant/schedule caches warm first.
        time.sleep(float(os.getenv('TRACKER_AUTO_CAPTURE_BOOT_DELAY_SEC', '90') or 90))
        while True:
            try:
                _tracker_auto_capture_once()
            except Exception:
                print(f'[tracker_auto_capture] {traceback.format_exc()}')
            time.sleep(interval_min * 60)

    threading.Thread(target=_runner, daemon=True).start()



@app.route('/api/best-bets/tier-thresholds', methods=['GET', 'POST'])
def api_best_bets_tier_thresholds():
    """Serve calibrated ELITE/STRONG/LEAN edge thresholds per market.

    GET  → returns the persisted thresholds (or defaults when calibrator
           hasn't run yet). Public-read.
    POST → re-runs the tier_calibrator against the current tracker history
           and writes data/tier_thresholds.json. Admin-token-gated.
    """
    if request.method == 'POST':
        denied = _check_admin_auth()
        if denied:
            return denied
        if not _TIER_CAL_AVAILABLE:
            return jsonify({'success': False, 'error': 'tier_calibrator unavailable'}), 503
        try:
            payload = _run_tier_calibration()
            return jsonify({'success': True, **payload})
        except Exception as e:
            return jsonify({'success': False, 'error': str(e)}), 500
    payload = _load_tier_thresholds() if _TIER_CAL_AVAILABLE else {
        'thresholds': {}, 'meta': {}, 'generated_at': None,
    }
    return jsonify({'success': True, **payload})


@app.route('/api/tracker/adjustments', methods=['GET', 'POST'])
def api_tracker_adjustments():
    if request.method == 'POST':
        denied = _check_admin_auth()
        if denied:
            return denied
        payload = request.get_json(silent=True) or {}
        base = _get_adjustments()
        for key in ['captured_per_game', 'best_edge_threshold', 'best_prob_threshold', 'bankroll', 'kelly_fraction', 'unit_size_pct', 'max_bet_pct', 'max_daily_risk_pct', 'max_team_exposure_pct', 'max_market_exposure_pct', 'max_game_exposure_pct']:
            if key in payload:
                base[key] = payload[key]
        if 'market_multipliers' in payload and isinstance(payload['market_multipliers'], dict):
            base['market_multipliers'].update(payload['market_multipliers'])
        _save_json(ADJUST_STORE, base)
        _append_calibration_history('manual_save', base, {'note': 'Manual adjustment save'})
        return jsonify({'success': True, 'adjustments': base})
    return jsonify({'success': True, 'adjustments': _get_adjustments()})


@app.route('/api/tracker/date/<date_str>')
def api_tracker_date(date_str):
    store = _load_json(TRACKER_STORE, {})
    day = _normalize_tracker_day(store.get(date_str))
    day['entries'] = _recalc_tracker_entries(day.get('entries', []))
    return jsonify({'success': True, 'date': date_str, 'adjustments': _get_adjustments(), 'capturedAt': day.get('capturedAt'), 'gradedAt': day.get('gradedAt'), 'closingCapturedAt': day.get('closingCapturedAt'), 'entries': day.get('entries', []), 'summary': _tracker_summary(day.get('entries', []))})


@app.route('/api/tracker/capture/<date_str>', methods=['POST'])
def api_tracker_capture(date_str):
    denied = _check_admin_auth()
    if denied:
        return denied
    # Backfill mode: picks captured for a past date are projected with the
    # CURRENT season caches, not point-in-time stats, so their model probs
    # carry mild look-ahead bias. Stamp them so calibration/eval can isolate
    # or down-weight them vs. genuinely live-captured picks.
    is_backfill = str(request.args.get('backfill', '')).strip().lower() in ('1', 'true', 'yes')
    try:
        adjustments = _get_adjustments()
        sched = fetch_schedule(date_str)
        if not sched:
            return jsonify({'success': False, 'error': f'No games found for {date_str}'}), 404

        # Keep request under Fly.io's ~60s proxy read timeout; remaining
        # games continue in a background thread (TRACKER_CAPTURE_BACKGROUND).
        budget_sec = float(os.getenv('TRACKER_CAPTURE_BUDGET_SEC', '45') or 45)
        deadline = time.time() + max(15.0, min(300.0, budget_sec))
        all_entries = []
        captured_games = 0
        recovered_games = 0
        failed_games = []
        # Default ON: without odds, captures produce empty PRICE SHOP / EV / edge
        # columns, which makes the tracker page look broken to the user. The
        # in-memory + on-disk odds cache (data/odds_cache.json) keeps API usage
        # low; set TRACKER_CAPTURE_INCLUDE_ODDS=0 to opt out.
        include_odds = str(os.getenv('TRACKER_CAPTURE_INCLUDE_ODDS', '1')).strip().lower() in ('1', 'true', 'yes')
        # The Odds API only serves live markets, so backfilling past dates can't
        # fetch historical odds and would just burn credits. Default odds OFF for
        # backfill unless the caller explicitly opts in via ?odds=1.
        _odds_q = request.args.get('odds')
        if _odds_q is not None:
            include_odds = str(_odds_q).strip().lower() in ('1', 'true', 'yes')
        elif is_backfill:
            include_odds = False

        # Parallelise I/O-bound boxscore/roster fetches across games.
        # cap workers at 4 to stay within the single-Gunicorn-worker memory budget.
        max_workers = min(4, len(sched))
        time_limit = max(1.0, deadline - time.time() - 1.0)

        def _capture_one(g):
            gpk = g.get('gamePk')
            try:
                rows = _build_tracker_rows_for_game(gpk, date_str, adjustments, _sched=sched, include_odds=include_odds)
                return gpk, rows, None, False
            except Exception as ex:
                print(f'[tracker_capture_game {gpk}]', traceback.format_exc())
                try:
                    rows = _build_tracker_rows_quick(g, date_str, adjustments)
                    return gpk, rows, None, True
                except Exception as ex2:
                    return gpk, [], str(ex)[:140], False

        # NOTE: Don't use `with ThreadPoolExecutor(...) as pool:` here — its
        # __exit__ blocks on shutdown(wait=True), which would force the response
        # to wait for every in-flight game to finish even after the time budget
        # has expired (defeating the whole point of the budget). Instead we
        # shutdown(wait=False) and let _tracker_capture_continue_bg re-run any
        # game that didn't complete in time.
        pool = ThreadPoolExecutor(max_workers=max_workers)
        try:
            futures = {pool.submit(_capture_one, g): g for g in sched}
            games_within_budget = []
            games_timed_out = []
            try:
                for fut in as_completed(futures, timeout=time_limit):
                    games_within_budget.append(fut)
            except TimeoutError:
                # Time budget exhausted before every game finished — the
                # remaining games are handed off to the background helper
                # below. Without this except, the bare TimeoutError bubbles
                # up to the outer handler and the user sees "Capture failed"
                # with zero entries persisted.
                pass
            timed_out_futures = [f for f in futures if f not in set(games_within_budget)]
            games_timed_out = [futures[f] for f in timed_out_futures]
        finally:
            pool.shutdown(wait=False, cancel_futures=True)

        for fut in games_within_budget:
            try:
                gpk, rows, err, recovered = fut.result()
                if err:
                    failed_games.append({'gamePk': gpk, 'error': err})
                else:
                    all_entries.extend(rows)
                    captured_games += 1
                    if recovered:
                        recovered_games += 1
            except Exception:
                pass

        with _TRACKER_STORE_LOCK:
            store = _load_json(TRACKER_STORE, {})
            day = _normalize_tracker_day(store.get(date_str))
            entries = _merge_tracker_entries(day.get('entries', []), _recalc_tracker_entries(all_entries))
            if is_backfill:
                for _e in entries:
                    _e['backfilled'] = True
            entries.sort(key=lambda x: x.get('score', 0), reverse=True)
            store[date_str] = {'capturedAt': datetime.now().isoformat(), 'gradedAt': None, 'closingCapturedAt': None, 'entries': entries, 'backfilled': is_backfill or day.get('backfilled', False)}
            saved_ok = _save_json(TRACKER_STORE, store)
        # Without this check, a failed disk write silently returns 210 picks to
        # the user — then "Capture Closing" 404s because the day isn't on disk.
        if not saved_ok:
            return jsonify({
                'success': False,
                'error': f'Captured {len(entries)} entries but failed to persist to disk. Check server logs and DATA_DIR permissions.',
                'capturedGames': captured_games,
                'totalGames': len(sched),
            }), 500
        timed_out = bool(games_timed_out)
        remaining_games = games_timed_out if timed_out else []
        background_started = False
        background_already_running = False
        if remaining_games and str(os.getenv('TRACKER_CAPTURE_BACKGROUND', '1')).strip().lower() in ('1', 'true', 'yes'):
            with _TRACKER_CAPTURE_LOCK:
                if date_str in _TRACKER_CAPTURE_JOBS:
                    background_already_running = True
                else:
                    t = threading.Thread(
                        target=_tracker_capture_continue_bg,
                        args=(date_str, remaining_games, sched, adjustments, include_odds),
                        daemon=True,
                    )
                    _TRACKER_CAPTURE_JOBS[date_str] = {'startedAt': datetime.now().isoformat(), 'remaining': len(remaining_games)}
                    t.start()
                    background_started = True
        msg = None
        if timed_out:
            if background_started:
                msg = f'Partial capture: {captured_games}/{len(sched)} games processed. Continuing {len(remaining_games)} game(s) in background — reload in ~30s.'
            elif background_already_running:
                msg = f'Partial capture: {captured_games}/{len(sched)} games processed. Background continuation already running — reload in ~30s.'
            else:
                msg = f'Partial capture: {captured_games}/{len(sched)} games processed in time budget.'
        elif not entries:
            msg = f'Capture completed for {captured_games}/{len(sched)} games but produced 0 entries.'
        if recovered_games:
            extra = f' Recovered {recovered_games} game(s) via fallback capture.'
            msg = (msg or 'Captured.') + extra
        return jsonify({
            'success': True,
            'date': date_str,
            'entries': entries,
            'summary': _tracker_summary(entries),
            'capturedAt': store[date_str]['capturedAt'],
            'capturedGames': captured_games,
            'totalGames': len(sched),
            'timedOut': timed_out,
            'backgroundStarted': background_started,
            'remainingGames': len(remaining_games),
            'recoveredGames': recovered_games,
            'failedGames': failed_games,
            'message': msg,
        })
    except Exception:
        tb = traceback.format_exc()
        print('[tracker_capture]', tb)
        return jsonify({'success': False, 'error': 'Capture failed', 'traceback': tb}), 500
        


@app.route('/api/tracker/grade/<date_str>', methods=['POST'])
def api_tracker_grade(date_str):
    denied = _check_admin_auth()
    if denied:
        return denied
    store = _load_json(TRACKER_STORE, {})
    raw_day = store.get(date_str)
    if raw_day is None:
        return jsonify({
            'success': False,
            'error': f'No saved picks for {date_str}. Click "Capture Slate" first to load picks for this date.',
            'needsCapture': True,
            'date': date_str,
        }), 409
    day = _normalize_tracker_day(raw_day)
    sched = fetch_schedule(date_str)
    games = {g.get('gamePk'): g for g in sched}
    for row in day.get('entries', []):
        gpk = row.get('gamePk')
        g = games.get(gpk)
        if not g:
            continue
        status = ((g.get('status') or {}).get('detailedState') or '').lower()
        if 'final' not in status:
            continue
        try:
            mk = row.get('marketKey')
            if mk in ('nrfi', 'yrfi'):
                inns = (g.get('linescore') or {}).get('innings') or []
                first = inns[0] if inns else {}
                a1 = int((((first.get('away') or {}).get('runs')) or 0))
                h1 = int((((first.get('home') or {}).get('runs')) or 0))
                actual = a1 + h1
                row['actual'] = actual
                row['grade'] = _grade_side(actual, row.get('line', 0.5), 'Under' if mk == 'nrfi' else 'Over')
                row['status'] = 'graded'
                continue
            if mk in ('h2h', 'totals', 'f5_h2h', 'f5_totals'):
                ls = (g.get('linescore') or {})
                teams_ls = ls.get('teams') or {}
                inns = ls.get('innings') or []
                away_abbr = (g.get('teams') or {}).get('away', {}).get('team', {}).get('abbreviation', 'AWAY')
                home_abbr = (g.get('teams') or {}).get('home', {}).get('team', {}).get('abbreviation', 'HOME')
                if mk == 'h2h':
                    a_runs = int((teams_ls.get('away') or {}).get('runs') or 0)
                    h_runs = int((teams_ls.get('home') or {}).get('runs') or 0)
                    winner = away_abbr if a_runs > h_runs else (home_abbr if h_runs > a_runs else None)
                    row['actual'] = winner
                    if winner is None:
                        row['grade'] = 'push'
                    else:
                        row['grade'] = 'win' if winner == row.get('recommendedSide') else 'loss'
                    row['status'] = 'graded'
                    continue
                if mk == 'totals':
                    a_runs = int((teams_ls.get('away') or {}).get('runs') or 0)
                    h_runs = int((teams_ls.get('home') or {}).get('runs') or 0)
                    actual = a_runs + h_runs
                    row['actual'] = actual
                    row['grade'] = _grade_side(actual, row.get('line'), row.get('recommendedSide') or 'Over')
                    row['status'] = 'graded'
                    continue
                # F5 markets: require at least 5 completed innings
                if len(inns) < 5:
                    continue
                a_f5 = sum(int((((inn.get('away') or {}).get('runs')) or 0)) for inn in inns[:5])
                h_f5 = sum(int((((inn.get('home') or {}).get('runs')) or 0)) for inn in inns[:5])
                if mk == 'f5_h2h':
                    winner = away_abbr if a_f5 > h_f5 else (home_abbr if h_f5 > a_f5 else None)
                    row['actual'] = winner
                    if winner is None:
                        row['grade'] = 'push'
                    else:
                        row['grade'] = 'win' if winner == row.get('recommendedSide') else 'loss'
                    row['status'] = 'graded'
                    continue
                if mk == 'f5_totals':
                    actual = a_f5 + h_f5
                    row['actual'] = actual
                    row['grade'] = _grade_side(actual, row.get('line'), row.get('recommendedSide') or 'Over')
                    row['status'] = 'graded'
                    continue
            box = requests.get(f"{MLB_API}/game/{gpk}/boxscore", timeout=10).json().get('teams', {})
            players = {}
            for side in ['away', 'home']:
                players.update((box.get(side) or {}).get('players', {}))
            pobj = None
            pid = row.get('playerId')
            if pid:
                pobj = players.get(f'ID{pid}')
            if not pobj:
                for v in players.values():
                    if (v.get('person', {}).get('fullName') or '').lower() == (row.get('player') or '').lower():
                        pobj = v; break
            actual = _tracker_stat_from_boxscore(pobj, row.get('marketKey'))
            row['actual'] = actual
            row['grade'] = _grade_side(actual, row.get('line'), row.get('recommendedSide') or 'Over')
            row['status'] = 'graded'
        except Exception:
            print('[tracker_grade_row]', traceback.format_exc())
    day['entries'] = _recalc_tracker_entries(day.get('entries', []))
    day['gradedAt'] = datetime.now().isoformat()
    _tracker_commit_day(date_str, day)
    return jsonify({'success': True, 'date': date_str, 'entries': day.get('entries', []), 'summary': _tracker_summary(day.get('entries', [])), 'gradedAt': day.get('gradedAt')})



# ── Phase 12 Auto-Calibration Layer ───────────────────────────────────────────
CALIBRATION_TARGETS = {
    'batter_hits': 0.56,
    'batter_total_bases': 0.55,
    'batter_home_runs': 0.52,
    'batter_rbis': 0.53,
    'batter_runs_scored': 0.53,
    'batter_hits_runs_rbis': 0.54,
    'batter_stolen_bases': 0.52,
    'pitcher_strikeouts': 0.55,
    'nrfi': 0.53,
    'yrfi': 0.50,
    'h2h': 0.52,
    'totals': 0.52,
    'f5_h2h': 0.52,
    'f5_totals': 0.52,
}


def _tracker_store():
    return _load_json(TRACKER_STORE, {})


def _coerce_tracker_entries(entries):
    if not isinstance(entries, list):
        return []
    return [row for row in entries if isinstance(row, dict)]


def _normalize_tracker_day(day_payload):
    if isinstance(day_payload, dict):
        return {
            'capturedAt': day_payload.get('capturedAt'),
            'gradedAt': day_payload.get('gradedAt'),
            'closingCapturedAt': day_payload.get('closingCapturedAt'),
            'entries': _coerce_tracker_entries(day_payload.get('entries', [])),
        }
    if isinstance(day_payload, list):
        return {
            'capturedAt': None,
            'gradedAt': None,
            'closingCapturedAt': None,
            'entries': _coerce_tracker_entries(day_payload),
        }
    return {
        'capturedAt': None,
        'gradedAt': None,
        'closingCapturedAt': None,
        'entries': [],
    }


def _dates_in_window(end_date_str, window_days):
    try:
        end_dt = datetime.strptime(end_date_str, '%Y-%m-%d').date()
    except Exception:
        end_dt = datetime.now().date()
    return [(end_dt - timedelta(days=i)).isoformat() for i in range(max(1, int(window_days)))]


def _collect_window_entries(end_date_str, window_days):
    store = _tracker_store()
    dates = set(_dates_in_window(end_date_str, window_days))
    rows = []
    for ds, payload in store.items():
        if ds in dates:
            rows.extend(_normalize_tracker_day(payload).get('entries', []))
    return rows


def _market_calibration(entries, current_adj):
    by_market = {}
    for row in entries:
        mk = row.get('marketKey')
        if not mk:
            continue
        by_market.setdefault(mk, [])
        if row.get('grade') in ('win', 'loss'):
            by_market[mk].append(row)

    out = []
    for mk, rows in by_market.items():
        graded = len(rows)
        wins = sum(1 for r in rows if r.get('grade') == 'win')
        losses = sum(1 for r in rows if r.get('grade') == 'loss')
        hit_rate = wins / max(1, graded)
        avg_edge = sum(float(r.get('edge') or 0) for r in rows) / max(1, graded)
        avg_prob = sum(float(r.get('adjProb') or r.get('rawProb') or 0) for r in rows) / max(1, graded)
        target = CALIBRATION_TARGETS.get(mk, 0.54)
        current_mult = float(current_adj.get('market_multipliers', {}).get(mk, 1.0) or 1.0)
        delta = hit_rate - target
        if graded < 8:
            confidence = 'LOW SAMPLE'
            suggested = current_mult
            action = 'hold'
        else:
            shift = _clamp(delta * 0.60, -0.08, 0.08)
            suggested = round(_clamp(current_mult + shift, 0.80, 1.20), 3)
            if suggested > current_mult + 0.004:
                action = 'increase'
            elif suggested < current_mult - 0.004:
                action = 'decrease'
            else:
                action = 'hold'
            confidence = 'HIGH' if graded >= 20 else 'MEDIUM'
        rationale = f"{mk}: {wins}-{losses} over last sample, hit rate {hit_rate:.1%} vs target {target:.1%}, avg edge {avg_edge:.1%}."
        out.append({
            'marketKey': mk,
            'graded': graded,
            'wins': wins,
            'losses': losses,
            'hit_rate': round(hit_rate, 4),
            'target_rate': round(target, 4),
            'avg_edge': round(avg_edge, 4),
            'avg_prob': round(avg_prob, 4),
            'current_multiplier': round(current_mult, 3),
            'suggested_multiplier': round(suggested, 3),
            'action': action,
            'confidence': confidence,
            'rationale': rationale,
        })
    out.sort(key=lambda x: (x['action'] == 'hold', -x['graded'], x['marketKey']))
    return out


# ── Brier Score Feedback Loop ─────────────────────────────────────────────────

def _compute_brier_stats(entries):
    """
    Compute per-market Brier scores from graded tracker entries.
    For pitcher_strikeouts entries that stored mcKProb + xgbKProb, also compute
    optimal XGB blend weight that minimises Brier over the sample.
    """
    by_market = {}
    for row in entries:
        if row.get('grade') not in ('win', 'loss'):
            continue
        mk = row.get('marketKey')
        if not mk:
            continue
        p = float(row.get('adjProb') or 0)
        if p <= 0:
            continue
        outcome = 1.0 if row.get('grade') == 'win' else 0.0
        rec = {'outcome': outcome, 'adjProb': p}
        if row.get('xgbKProb') is not None:
            rec['xgbKProb'] = float(row['xgbKProb'])
        if row.get('mcKProb') is not None:
            rec['mcKProb'] = float(row['mcKProb'])
        by_market.setdefault(mk, []).append(rec)

    results = {}
    for mk, rows in by_market.items():
        n = len(rows)
        if n == 0:
            continue
        brier = sum((r['adjProb'] - r['outcome']) ** 2 for r in rows) / n
        # Brier Skill Score vs coin-flip baseline (0.25)
        skill_score = round(1.0 - brier / 0.25, 4)
        entry = {
            'marketKey': mk,
            'graded': n,
            'brier_score': round(brier, 5),
            'skill_score': skill_score,
            'baseline_brier': 0.25,
            'confidence': 'HIGH' if n >= 30 else ('MEDIUM' if n >= 15 else 'LOW'),
        }

        # K-prop blend optimisation: find XGB weight that minimises Brier
        if mk == 'pitcher_strikeouts':
            blend_rows = [r for r in rows if 'xgbKProb' in r and 'mcKProb' in r]
            if blend_rows:
                nb = len(blend_rows)
                brier_xgb  = sum((r['xgbKProb'] - r['outcome']) ** 2 for r in blend_rows) / nb
                brier_mc   = sum((r['mcKProb']  - r['outcome']) ** 2 for r in blend_rows) / nb
                # Grid-search over XGB weight in [0, 1] step 0.05
                best_w, best_bs = 0.60, float('inf')
                for step in range(21):
                    w = round(step / 20, 2)
                    bs = sum((w * r['xgbKProb'] + (1 - w) * r['mcKProb'] - r['outcome']) ** 2
                             for r in blend_rows) / nb
                    if bs < best_bs:
                        best_bs, best_w = bs, w
                entry.update({
                    'xgb_brier': round(brier_xgb, 5),
                    'mc_brier':  round(brier_mc,  5),
                    'optimal_xgb_weight': best_w,
                    'optimal_brier': round(best_bs, 5),
                    'blend_sample_n': nb,
                })

        results[mk] = entry
    return results


def _brier_blend_calibration(entries, current_adj):
    """
    Suggest updated blend_weights based on Brier-score analysis.

    Logic:
    - pitcher_strikeouts  → optimise xgb_k_weight via grid search
    - All other markets   → no blend component to tune here (multiplier handles them)

    Returns a list of suggestion dicts (same shape as _market_calibration output)
    plus a top-level 'suggested_blend_weights' dict.
    """
    stats = _compute_brier_stats(entries)
    current_bw = (current_adj.get('blend_weights') or {})
    suggestions = []

    # ── XGB K-prop weight ──────────────────────────────────────────────────────
    k_stat = stats.get('pitcher_strikeouts')
    current_xgb_w = float(current_bw.get('xgb_k_weight', 0.60))
    if k_stat and k_stat.get('blend_sample_n', 0) >= 8:
        opt_w   = k_stat['optimal_xgb_weight']
        # Dampen the shift: move at most 0.10 toward optimal per calibration cycle
        shift   = _clamp(opt_w - current_xgb_w, -0.10, 0.10)
        new_w   = round(_clamp(current_xgb_w + shift, 0.20, 0.80), 2)
        action  = ('increase' if new_w > current_xgb_w + 0.01
                   else 'decrease' if new_w < current_xgb_w - 0.01
                   else 'hold')
        suggestions.append({
            'param': 'xgb_k_weight',
            'label': 'XGBoost K-prop weight',
            'current': current_xgb_w,
            'suggested': new_w,
            'optimal_from_data': opt_w,
            'action': action,
            'confidence': k_stat['confidence'],
            'brier_current': k_stat.get('blended_brier', k_stat['brier_score']),
            'brier_optimal': k_stat.get('optimal_brier'),
            'sample_n': k_stat['blend_sample_n'],
            'rationale': (
                f"XGB Brier {k_stat.get('xgb_brier','?'):.5f}, "
                f"MC Brier {k_stat.get('mc_brier','?'):.5f} over {k_stat['blend_sample_n']} graded K picks. "
                f"Optimal XGB weight from data: {opt_w:.2f} (current {current_xgb_w:.2f})."
            ),
        })
    else:
        suggestions.append({
            'param': 'xgb_k_weight',
            'label': 'XGBoost K-prop weight',
            'current': current_xgb_w,
            'suggested': current_xgb_w,
            'action': 'hold',
            'confidence': 'LOW SAMPLE',
            'sample_n': (k_stat or {}).get('blend_sample_n', 0),
            'rationale': 'Fewer than 8 graded K-prop picks with both MC and XGB probabilities stored.',
        })

    # Build suggested_blend_weights dict (apply only non-hold suggestions)
    suggested_bw = dict(current_bw)
    for s in suggestions:
        if s['action'] != 'hold':
            suggested_bw[s['param']] = s['suggested']

    return {
        'brier_stats': stats,
        'suggestions': suggestions,
        'current_blend_weights': current_bw,
        'suggested_blend_weights': suggested_bw,
    }


def _overall_window_summary(entries):
    graded = [x for x in entries if x.get('grade') in ('win', 'loss', 'push')]
    wins = sum(1 for x in graded if x.get('grade') == 'win')
    losses = sum(1 for x in graded if x.get('grade') == 'loss')
    pushes = sum(1 for x in graded if x.get('grade') == 'push')
    active = [x for x in graded if x.get('grade') in ('win', 'loss')]
    hit_rate = round(wins / max(1, wins + losses), 4) if active else 0.0
    avg_edge = round(sum(float(x.get('edge') or 0) for x in active) / max(1, len(active)), 4) if active else 0.0
    return {
        'tracked': len(entries), 'graded': len(graded), 'wins': wins, 'losses': losses,
        'pushes': pushes, 'hit_rate': hit_rate, 'avg_edge': avg_edge
    }


def _tracker_side_label(row):
    side = row.get('recommendedSide') or row.get('side')
    if side:
        return side
    market = str(row.get('marketKey') or '').lower()
    if market in ('nrfi', 'yrfi'):
        return market.upper()
    return 'Over'


def _tracker_live_summary(entries, adjustments=None):
    adjustments = adjustments or _get_adjustments()
    summary = _tracker_summary(entries)
    graded = [x for x in entries if x.get('grade') in ('win', 'loss', 'push')]
    active = [x for x in graded if x.get('grade') in ('win', 'loss')]
    pending = [x for x in entries if (x.get('grade') or 'pending') == 'pending']
    planned_stake = round(sum(float(x.get('stakeDollars') or 0) for x in entries), 2)
    pending_risk = round(sum(float(x.get('stakeDollars') or 0) for x in pending), 2)
    profit_dollars = round(sum(float(x.get('profitDollars') or 0) for x in graded), 2)
    profit_units = round(sum(float(x.get('profitUnits') or 0) for x in graded), 3)
    clv_rows = [x for x in graded if x.get('clvEdge') is not None]
    positive_clv = [x for x in clv_rows if float(x.get('clvEdge') or 0) > 0]
    avg_clv = round(sum(float(x.get('clvEdge') or 0) for x in clv_rows) / max(1, len(clv_rows)), 4) if clv_rows else None
    live_bankroll = round(float(adjustments.get('bankroll') or 0) + profit_dollars, 2)
    summary['pending'] = len(pending)
    summary['units'] = profit_units
    summary['at_risk'] = pending_risk
    summary['avg_clv'] = avg_clv
    summary['clv_positive_rate'] = round(len(positive_clv) / max(1, len(clv_rows)), 4) if clv_rows else None
    summary['bankroll'] = {
        'starting_bankroll': float(adjustments.get('bankroll') or 0),
        'live_bankroll': live_bankroll,
        'planned_stake': planned_stake,
        'pending_risk': pending_risk,
    }
    summary['value'] = {
        'dollars': profit_dollars,
        'units': profit_units,
        'avg_clv': avg_clv,
        'clv_positive_rate': summary['clv_positive_rate'],
        'graded_with_clv': len(clv_rows),
    }
    summary['snapshot'] = {
        'picks': summary.get('picks', 0),
        'graded': summary.get('graded', 0),
        'pending': len(pending),
        'hit_rate': summary.get('hit_rate', 0.0),
        'units': profit_units,
        'profit_dollars': profit_dollars,
        'at_risk': pending_risk,
        'bankroll': live_bankroll,
        'clv_rate': summary['clv_positive_rate'],
        'avg_clv': avg_clv,
    }
    if active:
        summary['avg_edge'] = round(sum(float(x.get('edge') or 0) for x in active) / len(active), 4)
    return summary


def _tracker_find_pick(store, pick_id, date_hint=None):
    dates = []
    if date_hint:
        dates.append(date_hint)
    dates.extend([ds for ds in store.keys() if ds not in dates])
    for ds in dates:
        payload = _normalize_tracker_day(store.get(ds))
        entries = payload.get('entries', [])
        for idx, row in enumerate(entries):
            if row.get('id') == pick_id:
                return ds, payload, entries, idx, row
    return None, None, None, None, None


def _tracker_pick_payload(row):
    out = dict(row)
    out['sideLabel'] = _tracker_side_label(row)
    return out


def _tracker_today_payload(date_str=None):
    date_str = date_str or datetime.now(ET).strftime('%Y-%m-%d')
    store = _tracker_store()
    day = _normalize_tracker_day(store.get(date_str))
    entries = [_tracker_pick_payload(x) for x in day.get('entries', [])]
    entries.sort(key=lambda x: ((x.get('grade') or 'pending') != 'pending', -(float(x.get('hubRating') or 0)), -(float(x.get('edge') or 0))))
    adjustments = _get_adjustments()
    return {
        'success': True,
        'date': date_str,
        'capturedAt': day.get('capturedAt'),
        'gradedAt': day.get('gradedAt'),
        'closingCapturedAt': day.get('closingCapturedAt'),
        'entries': entries,
        'summary': _tracker_live_summary(entries, adjustments),
        'settings': adjustments,
    }


def _tracker_performance_payload(date_str=None, window_days=30):
    date_str = date_str or datetime.now(ET).strftime('%Y-%m-%d')
    window_days = max(1, int(window_days or 30))
    entries = _collect_window_entries(date_str, window_days)
    adjustments = _get_adjustments()
    calibration = _market_calibration(entries, adjustments)
    overall_series = _daily_series(date_str, window_days, None)
    available_markets = sorted({row.get('marketKey') for row in entries if row.get('marketKey')})
    value_rows = [row for row in entries if row.get('grade') in ('win', 'loss', 'push')]
    clv_rows = [row for row in value_rows if row.get('clvEdge') is not None]
    top_clv = sorted(clv_rows, key=lambda x: float(x.get('clvEdge') or 0), reverse=True)[:10]
    daily = []
    for ds in reversed(_dates_in_window(date_str, window_days)):
        rows = _normalize_tracker_day(_tracker_store().get(ds)).get('entries', [])
        graded = [r for r in rows if r.get('grade') in ('win', 'loss', 'push')]
        active = [r for r in graded if r.get('grade') in ('win', 'loss')]
        wins = sum(1 for r in active if r.get('grade') == 'win')
        losses = sum(1 for r in active if r.get('grade') == 'loss')
        risk = round(sum(float(r.get('stakeDollars') or 0) for r in graded), 2)
        profit = round(sum(float(r.get('profitDollars') or 0) for r in graded), 2)
        units = round(sum(float(r.get('profitUnits') or 0) for r in graded), 3)
        clv_day = [r for r in graded if r.get('clvEdge') is not None]
        daily.append({
            'date': ds,
            'bets': len(rows),
            'graded': len(graded),
            'wins': wins,
            'losses': losses,
            'hit_rate': round(wins / max(1, wins + losses), 4) if active else None,
            'risk': risk,
            'profit': profit,
            'units': units,
            'roi': round(profit / risk, 4) if risk > 0 else None,
            'avg_clv': round(sum(float(r.get('clvEdge') or 0) for r in clv_day) / len(clv_day), 4) if clv_day else None,
        })
    return {
        'success': True,
        'date': date_str,
        'window': window_days,
        'summary': _tracker_live_summary(entries, adjustments),
        'overallSeries': overall_series,
        'availableMarkets': available_markets,
        'multiplierHistory': {mk: _multiplier_history(date_str, window_days, mk) for mk in available_markets},
        'calibration': calibration,
        'topCLV': top_clv,
        'daily': daily,
    }


def _tracker_backtest_payload(start_date, end_date, sims=2000):
    start_dt = datetime.strptime(start_date, '%Y-%m-%d').date()
    end_dt = datetime.strptime(end_date, '%Y-%m-%d').date()
    if end_dt < start_dt:
        start_dt, end_dt = end_dt, start_dt

    sims = max(250, min(10000, int(sims or 2000)))
    store = _tracker_store()
    daily = []
    cur = start_dt
    total_bets = 0.0
    total_wins = 0.0
    total_profit = 0.0
    total_risk = 0.0
    total_units = 0.0

    def _row_prob(row):
        try:
            p = float(row.get('adjProb') or row.get('rawProb') or 0)
            return _clamp(p, 0.01, 0.99)
        except Exception:
            return None

    def _row_stake(row):
        try:
            s = float(row.get('stakeDollars') or 0)
            return max(0.0, s)
        except Exception:
            return 0.0

    def _row_win_units(row):
        pu = _profit_units_from_american(row.get('openingPrice'))
        if pu is None:
            pu = _profit_units_from_american(row.get('marketPrice'))
        if pu is None:
            pu = _profit_units_from_american(row.get('bestAvailablePrice'))
        if pu is None:
            try:
                mi = float(row.get('marketImplied') or row.get('openingImplied') or 0)
                if mi > 0:
                    pu = max(0.0, (1.0 / mi) - 1.0)
            except Exception:
                pu = None
        return float(pu if pu is not None else 1.0)

    # Seed by selected window so repeated runs are stable.
    seed = int(start_dt.strftime('%Y%m%d')) * 100000000 + int(end_dt.strftime('%Y%m%d'))
    rng = random.Random(seed)

    while cur <= end_dt:
        ds = cur.strftime('%Y-%m-%d')
        rows = _normalize_tracker_day(store.get(ds)).get('entries', [])
        modeled = []
        for row in rows:
            if row.get('marketKey') == 'parlay':
                continue
            p = _row_prob(row)
            if p is None:
                continue
            stake = _row_stake(row)
            if stake <= 0:
                continue
            modeled.append({
                'p': p,
                'stake': stake,
                'win_units': _row_win_units(row),
            })

        if not modeled:
            daily.append({
                'date': ds,
                'bets': 0,
                'graded': 0,
                'wins': 0,
                'losses': 0,
                'hit_rate': None,
                'units': 0.0,
                'profit': 0.0,
                'risk': 0.0,
                'roi': None,
            })
            cur += timedelta(days=1)
            continue

        risk = sum(m['stake'] for m in modeled)
        sim_wins = 0.0
        sim_losses = 0.0
        sim_units = 0.0
        sim_profit = 0.0
        for _ in range(sims):
            wins_i = 0
            losses_i = 0
            units_i = 0.0
            profit_i = 0.0
            for m in modeled:
                if rng.random() <= m['p']:
                    wins_i += 1
                    units_i += m['win_units']
                    profit_i += m['stake'] * m['win_units']
                else:
                    losses_i += 1
                    units_i -= 1.0
                    profit_i -= m['stake']
            sim_wins += wins_i
            sim_losses += losses_i
            sim_units += units_i
            sim_profit += profit_i

        wins = sim_wins / sims
        losses = sim_losses / sims
        units = sim_units / sims
        profit = sim_profit / sims
        hit_rate = wins / max(1.0, (wins + losses))
        roi = (profit / risk) if risk > 0 else None

        total_bets += len(modeled)
        total_wins += wins
        total_profit += profit
        total_risk += risk
        total_units += units

        daily.append({
            'date': ds,
            'bets': len(modeled),
            'graded': len(modeled),
            'wins': round(wins, 2),
            'losses': round(losses, 2),
            'hit_rate': round(hit_rate, 4) if hit_rate is not None else None,
            'units': round(units, 3),
            'profit': round(profit, 2),
            'risk': round(risk, 2),
            'roi': round(roi, 4) if roi is not None else None,
        })
        cur += timedelta(days=1)

    summary = {
        'bets': int(round(total_bets)),
        'wins': round(total_wins, 2),
        'hit_rate': round(total_wins / max(1.0, total_bets), 4) if total_bets else None,
        'profit': round(total_profit, 2),
        'risk': round(total_risk, 2),
        'units': round(total_units, 3),
        'roi': round(total_profit / total_risk, 4) if total_risk > 0 else None,
    }
    return {
        'success': True,
        'start': start_dt.strftime('%Y-%m-%d'),
        'end': end_dt.strftime('%Y-%m-%d'),
        'days': (end_dt - start_dt).days + 1,
        'mode': 'historical_resimulation',
        'sims': sims,
        'summary': summary,
        'daily': daily,
    }


