@app.route('/api/eval/summary')
def api_eval_summary():
    from eval_models import (
        load_tracker, filter_picks, evaluate_market,
        rolling_trend, detect_drift, evaluate_mc_vs_xgb,
        ROLLING_WINDOWS
    )
    since   = request.args.get('since')
    market  = request.args.get('market')
    kelly   = float(request.args.get('kelly', 0.25))
    markets = [
        'batter_hits', 'batter_home_runs', 'batter_total_bases',
        'batter_rbi', 'pitcher_strikeouts'
    ]
    try:
        all_rows = load_tracker(TRACKER_STORE)
        target_markets = [market] if market else markets
        per_market = {}
        for mk in target_markets:
            picks = filter_picks(all_rows, since=since, until=None, market=mk)
            per_market[mk] = evaluate_market(mk, picks, kelly_frac=kelly)
        rolling = {}
        for mk in target_markets:
            rolling[mk] = rolling_trend(all_rows, mk, kelly_frac=kelly)
        drift = {}
        for mk in target_markets:
            drift[mk] = detect_drift(rolling.get(mk, {}), mk)
        mc = {}
        for mk in target_markets:
            picks = filter_picks(all_rows, since=since, until=None, market=mk)
            mc[mk] = evaluate_mc_vs_xgb(picks, mk)
        return jsonify({
            'success':    True,
            'per_market': per_market,
            'rolling':    rolling,
            'drift':      drift,
            'mc':         mc,
        })
    except FileNotFoundError:
        return jsonify({'success': False, 'error': 'No tracker data yet — capture and grade picks first'})
    except Exception as e:
        return jsonify({'success': False, 'error': str(e)})

