@app.route('/api/capture-daily-slate/<date_str>')
def api_capture_daily_slate(date_str):
    """Capture all AI projections for the day as a slate snapshot."""
    try:
        year = datetime.now().year
        # Get all games for this date
        raw = fetch_schedule(date_str)
        if not raw:
            return jsonify({'success': False, 'error': 'No games found for this date', 'slate': None})
        
        slate = {
            'date': date_str,
            'timestamp': datetime.now(timezone.utc).isoformat(),
            'games': [],
            'summary': {'total_games': len(raw), 'projections_captured': 0}
        }
        
        # Fetch AI projections for each game
        for game in raw:
            game_pk = game.get('gamePk')
            if not game_pk:
                continue
            
            try:
                ai_data = _get_ai_boxscore_data(game_pk)
                if ai_data.get('success'):
                    slate['games'].append({
                        'gamePk': game_pk,
                        'matchup': ai_data.get('matchup'),
                        'away_team': game.get('teams', {}).get('away', {}).get('team', {}).get('name'),
                        'home_team': game.get('teams', {}).get('home', {}).get('team', {}).get('name'),
                        'projections': ai_data.get('projections'),
                        'weather': ai_data.get('weather'),
                        'venue': ai_data.get('venue'),
                        'pitching': ai_data.get('pitching_matchup'),
                        'captured_at': datetime.now(timezone.utc).isoformat()
                    })
                    slate['summary']['projections_captured'] += 1
            except Exception as ex:
                print(f"[capture_slate] Failed to get AI projections for game {game_pk}: {traceback.format_exc()}")
                continue
        
        # Store slate in data directory
        slate_dir = os.path.join(DATA_DIR, 'slates')
        os.makedirs(slate_dir, exist_ok=True)
        slate_file = os.path.join(slate_dir, f"{date_str}_slate.json")
        with open(slate_file, 'w') as f:
            json.dump(slate, f, indent=2)
        
        return jsonify({
            'success': True,
            'slate': slate,
            'saved_to': slate_file
        })
    except Exception as ex:
        print(f"[capture_daily_slate] {traceback.format_exc()}")
        return jsonify({'success': False, 'error': str(ex), 'slate': None}), 500


@app.route('/api/parlay/build', methods=['POST'])
def api_build_parlay():
    """Build a parlay from selected game props."""
    try:
        req = request.get_json() or {}
        selections = req.get('selections', [])  # List of {game_pk, player, market, projection, side}
        
        if not selections:
            return jsonify({'success': False, 'error': 'No selections provided', 'parlay': None})
        
        parlay = {
            'id': datetime.now().isoformat().replace(':', '').replace('.', ''),
            'created_at': datetime.now(timezone.utc).isoformat(),
            'selections': [],
            'implied_odds': 1.0,
            'american_odds': 100,
            'summary': {'leg_count': 0, 'break_even_prob': 0.0}
        }
        
        # Build each leg
        prob_product = 1.0
        for sel in selections:
            game_pk = sel.get('game_pk')
            player = sel.get('player')
            market = sel.get('market')
            raw_proj = sel.get('projection', 0)
            try:
                # Handle 'N/A', None, or other non-numeric projections
                if raw_proj in (None, '', '-.--', '.---', 'N/A'):
                    projection = 0.0
                else:
                    projection = float(raw_proj)
            except Exception:
                projection = 0.0
            side = sel.get('side', 'Over')
            
            # Estimate win probability
            if market in ('batter_hits', 'batter_home_runs', 'batter_rbis'):
                # Simple heuristic: projection value → probability
                base_prob = 0.55 if projection >= 0.5 else 0.45
            elif market == 'pitcher_strikeouts':
                base_prob = 0.56 if projection >= 6.5 else 0.45
            else:
                base_prob = 0.52
            
            parlay['selections'].append({
                'game_pk': game_pk,
                'player': player,
                'market': market,
                'projection': projection,
                'side': side,
                'win_probability': base_prob,
                'american_odds': _prob_to_american(base_prob)
            })
            
            prob_product *= base_prob
        
        # Calculate parlay odds
        parlay['summary']['leg_count'] = len(parlay['selections'])
        parlay['summary']['break_even_prob'] = round(prob_product, 4)
        parlay['implied_odds'] = round(prob_product, 4)
        parlay['american_odds'] = _prob_to_american(prob_product)
        
        return jsonify({
            'success': True,
            'parlay': parlay
        })
    except Exception as ex:
        print(f"[build_parlay] {traceback.format_exc()}")
        return jsonify({'success': False, 'error': str(ex), 'parlay': None}), 500


# ── Auto parlay risk tiers ───────────────────────────────────────────────────
# Auto-generate Conservative / Moderate / Aggressive parlays from the model's
# own prop pool (Bobby's Bets "data-backed parlays across risk tiers"). Reuses
# the cached props-scan; each tier picks one leg per game so legs stay roughly
# independent and the combined-probability product is a fair estimate.
def _american_to_decimal(price):
    try:
        p = float(price)
    except (TypeError, ValueError):
        return None
    if p > 0:
        return 1.0 + p / 100.0
    if p < 0:
        return 1.0 + 100.0 / abs(p)
    return None


def _decimal_to_american(dec):
    try:
        d = float(dec)
    except (TypeError, ValueError):
        return None
    if d <= 1.0:
        return None
    return round((d - 1.0) * 100.0) if d >= 2.0 else round(-100.0 / (d - 1.0))


_PARLAY_PROP_MARKETS = {
    'batter_hits', 'batter_total_bases', 'batter_home_runs', 'batter_rbis',
    'batter_runs_scored', 'batter_hits_runs_rbis', 'pitcher_strikeouts',
}


def _parlay_leg_candidates(props):
    """Distinct candidate legs from the scan props: the best (highest model
    probability) leg per (player, market, line), restricted to player-prop
    markets that carry a model probability. Each leg uses a real book price when
    odds are available, else a model-implied price so payout/EV still compute."""
    best = {}
    for p in props or []:
        mk = p.get('marketKey')
        if mk not in _PARLAY_PROP_MARKETS:
            continue
        try:
            prob = float(p.get('adjProb'))
        except (TypeError, ValueError):
            continue
        if not (0.0 < prob < 1.0):
            continue
        key = (p.get('player'), mk, p.get('line'))
        cur = best.get(key)
        if cur is not None and prob <= cur['winProb']:
            continue
        price = p.get('bestOverPrice') or p.get('bestAvailablePrice') or p.get('marketPrice')
        price_source = 'market'
        if price is None:
            price = _prob_to_american(prob)
            price_source = 'model'
        best[key] = {
            'player': p.get('player'), 'playerId': p.get('playerId'),
            'team': p.get('team'), 'opp': p.get('opp'),
            'gamePk': p.get('gamePk'), 'matchup': p.get('matchup'),
            'marketKey': mk, 'marketLabel': _EDGE_MARKET_LABELS.get(mk, mk),
            'line': p.get('line'), 'side': p.get('recommendedSide') or 'Over',
            'winProb': round(prob, 4),
            'price': price, 'priceSource': price_source,
            'edge': p.get('edge'), 'evPct': p.get('evPct'),
            'hubRating': p.get('hubRating'), 'grade': _edge_letter_grade(p.get('edge')),
        }
    return list(best.values())


def _select_parlay_legs(cands, n, min_prob, max_prob, rank_key):
    pool = [c for c in cands if min_prob <= c['winProb'] <= max_prob]
    pool.sort(key=rank_key)
    chosen, used_games = [], set()
    for c in pool:
        gp = c.get('gamePk')
        if gp in used_games:          # one leg per game → legs stay ~independent
            continue
        chosen.append(c)
        used_games.add(gp)
        if len(chosen) >= n:
            break
    return chosen


def _build_parlay_from_legs(legs, name, risk):
    prob, dec, priced = 1.0, 1.0, True
    for l in legs:
        prob *= l['winProb']
        d = _american_to_decimal(l['price'])
        if d is None:
            priced = False
        else:
            dec *= d
    priced = priced and bool(legs)
    return {
        'name': name,
        'risk': risk,
        'legCount': len(legs),
        'legs': legs,
        'combinedWinProb': round(prob, 4) if legs else 0.0,
        'decimalOdds': round(dec, 3) if priced else None,
        'americanOdds': _decimal_to_american(dec) if priced else None,
        'payoutPer100': round((dec - 1.0) * 100.0, 2) if priced else None,
        # EV per unit staked = P(win) * decimal_payout - 1. Meaningfully positive
        # only when real book prices beat the model; ~0 on model-implied prices.
        'evPct': round(prob * dec - 1.0, 4) if priced else None,
    }


def _auto_parlays_payload(date_str):
    base = _props_scan_today_payload(date_str)
    cands = _parlay_leg_candidates(base.get('props', []))

    def _value(c):
        if c.get('edge') is not None:
            return float(c['edge'])
        if c.get('evPct') is not None:
            return float(c['evPct'])
        return (float(c.get('hubRating') or 0)) / 100.0

    conservative = _select_parlay_legs(cands, 3, 0.68, 0.999, lambda c: -c['winProb'])
    moderate     = _select_parlay_legs(cands, 3, 0.55, 0.85,  lambda c: (-_value(c), -c['winProb']))
    aggressive   = _select_parlay_legs(cands, 4, 0.42, 0.72,  lambda c: (-_value(c), -(float(c.get('hubRating') or 0))))

    return {
        'success': True,
        'date': date_str,
        'candidateCount': len(cands),
        'cached': base.get('cached', False),
        'computing': base.get('computing', False),
        'message': base.get('message'),
        'generatedAt': datetime.now(timezone.utc).isoformat(),
        'parlays': [
            _build_parlay_from_legs(conservative, 'Conservative', 'conservative'),
            _build_parlay_from_legs(moderate, 'Moderate', 'moderate'),
            _build_parlay_from_legs(aggressive, 'Aggressive', 'aggressive'),
        ],
    }


