@app.route('/api/parlay/send-to-tracker', methods=['POST'])
def api_parlay_to_tracker():
    """Send a parlay to the daily tracker."""
    try:
        req = request.get_json() or {}
        parlay = req.get('parlay')
        date_str = req.get('date', datetime.now().strftime('%Y-%m-%d'))
        notes = req.get('notes', '')
        
        if not parlay:
            return jsonify({'success': False, 'error': 'No parlay provided'})
        
        # Create tracker entries for this parlay
        parlay_entry = {
            'id': parlay.get('id'),
            'date': date_str,
            'type': 'parlay',
            'timestamp': datetime.now(timezone.utc).isoformat(),
            'selections': parlay.get('selections', []),
            'american_odds': parlay.get('american_odds'),
            'break_even_prob': parlay.get('summary', {}).get('break_even_prob'),
            'notes': notes,
            'status': 'pending',
            'grade': 'pending'
        }

        # Serialized + atomic + metadata-preserving (previously a raw, unlocked
        # open(...,'w') that clobbered the day's capturedAt/gradedAt/backfilled).
        with _TRACKER_STORE_LOCK:
            store = _tracker_store()
            day = _normalize_tracker_day(store.get(date_str))
            day['entries'] = (day.get('entries') or []) + [parlay_entry]
            store[date_str] = day
            _save_json(TRACKER_STORE, store)

        return jsonify({
            'success': True,
            'message': f'Parlay {parlay.get("id")} added to tracker for {date_str}',
            'entry_id': parlay.get('id')
        })
    except Exception as ex:
        print(f"[parlay_to_tracker] {traceback.format_exc()}")
        return jsonify({'success': False, 'error': str(ex)}), 500


@app.route('/api/model-upgrade/suggestions/<date_str>')
def api_model_upgrade_suggestions(date_str):
    """Get model upgrade suggestions based on daily performance grades."""
    try:
        store = _tracker_store()
        day = store.get(date_str, {})
        entries = day.get('entries', [])
        
        # Analyze performance
        graded = [e for e in entries if e.get('grade') in ('win', 'loss', 'push')]
        if not graded:
            return jsonify({
                'success': True,
                'date': date_str,
                'suggestions': [],
                'message': 'No graded entries yet for this date'
            })
        
        wins = sum(1 for e in graded if e.get('grade') == 'win')
        losses = sum(1 for e in graded if e.get('grade') == 'loss')
        hit_rate = round(wins / max(1, wins + losses), 3)
        
        suggestions = []
        
        # Rule 1: High hit rate (>60%) → increase model confidence
        if hit_rate >= 0.60:
            suggestions.append({
                'type': 'increase_confidence',
                'title': 'Boost Model Confidence',
                'description': f'Hit rate of {hit_rate*100:.1f}% suggests model is accurate. Increase confidence weighting.',
                'impact': 'Higher conviction on similar projections',
                'priority': 'high'
            })
        
        # Rule 2: Low hit rate (<40%) → decrease model confidence
        elif hit_rate < 0.40:
            suggestions.append({
                'type': 'decrease_confidence',
                'title': 'Reduce Model Confidence',
                'description': f'Hit rate of {hit_rate*100:.1f}% indicates model needs calibration. Reduce weight.',
                'impact': 'Lower conviction, increase filtering threshold',
                'priority': 'high'
            })
        
        # Rule 3: Specific market underperformance
        market_performance = {}
        for e in graded:
            if e.get('type') == 'parlay':
                for sel in e.get('selections', []):
                    mk = sel.get('market')
                    market_performance.setdefault(mk, {'wins': 0, 'losses': 0})
                    if e.get('grade') == 'win':
                        market_performance[mk]['wins'] += 1
                    else:
                        market_performance[mk]['losses'] += 1
        
        for market, perf in market_performance.items():
            total = perf['wins'] + perf['losses']
            mk_hit_rate = perf['wins'] / max(1, total)
            if mk_hit_rate < 0.35 and total >= 3:
                suggestions.append({
                    'type': 'market_adjustment',
                    'title': f'Adjust {market}',
                    'description': f'{market} has {mk_hit_rate*100:.1f}% hit rate across {total} bets.',
                    'impact': f'Consider skipping or reducing {market} projections',
                    'priority': 'medium'
                })
        
        return jsonify({
            'success': True,
            'date': date_str,
            'performance': {
                'graded': len(graded),
                'wins': wins,
                'losses': losses,
                'hit_rate': hit_rate
            },
            'suggestions': suggestions
        })
    except Exception as ex:
        print(f"[model_upgrade_suggestions] {traceback.format_exc()}")
        return jsonify({'success': False, 'error': str(ex)}), 500


def _prob_to_american(probability):
    """Convert decimal probability to American odds."""
    if probability <= 0 or probability >= 1:
        return 0
    if probability >= 0.5:
        return round(-100 * probability / (1 - probability))
    else:
        return round(100 * (1 - probability) / probability)


def _local_boxscore_projections(game_pk, context, away_bats, home_bats, ap_name, hp_name,
                                ap_fg, hp_fg, ap_sv, hp_sv, ap_stats, hp_stats, pf, wx,
                                away_t, home_t):
    def parse_float(value, fallback=0.0):
        try:
            return float(value)
        except Exception:
            return fallback

    def best_era(sv, fg, mlb):
        # FIX: Require min 15 IP before trusting xERA (avoids April small-sample noise)
        xera = sv.get('sv_xera')
        ip = fg.get('fg_ip', 0) or 0
        if xera and float(ip or 0) >= 15:
            try:
                f = float(xera)
                if 0 < f < 12:
                    return f
            except Exception:
                pass
        for v in (fg.get('fg_era'), mlb.get('era')):
            try:
                f = float(v)
                if 0 < f < 12:
                    return f
            except Exception:
                pass
        return 4.50

    def best_fip(fg, fallback):
        try:
            f = float(fg.get('fg_fip', 0))
            if 0 < f < 12:
                return f
        except Exception:
            pass
        return fallback

    def lineup_xwoba(bats):
        vals = []
        for b in bats:
            if not b:
                continue
            for key in ('sv_xwoba', 'fg_woba'):
                try:
                    f = parse_float(b.get(key, 0))
                except Exception:
                    f = 0.0
                if 0.1 < f < 0.6:
                    vals.append(f)
                    break
            else:
                vals.append(0.320)
        return round(sum(vals) / len(vals), 3) if vals else 0.320

    away_pit_era = best_era(hp_sv, hp_fg, hp_stats)
    home_pit_era = best_era(ap_sv, ap_fg, ap_stats)
    away_pit_fip = best_fip(hp_fg, away_pit_era)
    home_pit_fip = best_fip(ap_fg, home_pit_era)
    away_xwoba = lineup_xwoba(away_bats)
    home_xwoba = lineup_xwoba(home_bats)

    away_blend = 0.6 * away_pit_era + 0.4 * away_pit_fip
    home_blend = 0.6 * home_pit_era + 0.4 * home_pit_fip
    away_runs = 4.50 * (away_blend / 4.50) * (away_xwoba / 0.320) * pf  # FIX: corrected ERA direction
    home_runs = 4.50 * (home_blend / 4.50) * (home_xwoba / 0.320) * pf  # FIX: corrected ERA direction

    wx_adj = 0.0
    if not wx.get('dome'):
        try:
            temp = float(wx.get('temp', '70'))
            if temp > 82:
                wx_adj = 0.20
            elif temp > 76:
                wx_adj = 0.10
            elif temp < 48:
                wx_adj = -0.20
            elif temp < 56:
                wx_adj = -0.10
        except Exception:
            pass

    wind_adj = _wind_run_adj(wx)
    away_runs = round(max(2.0, min(8.0, away_runs + wx_adj + wind_adj)), 1)
    home_runs = round(max(2.0, min(8.0, home_runs + wx_adj + wind_adj)), 1)
    total_runs = round(away_runs + home_runs, 1)

    def build_reasoning(team_abbr, runs, xwoba, pitcher_name, opponent_name):
        return (
            f"{team_abbr} should score {runs} runs against {opponent_name} given the matchup, "
            f"their lineup xwOBA of {xwoba:.3f}, and the current weather/park profile."
        )

    away_reasoning = build_reasoning(context['away_abbr'], away_runs, away_xwoba,
                                     context['away_pitcher']['name'], context['home_pitcher']['name'])
    home_reasoning = build_reasoning(context['home_abbr'], home_runs, home_xwoba,
                                     context['home_pitcher']['name'], context['away_pitcher']['name'])

    confidence = 'HIGH' if total_runs > 10 or total_runs < 7 else 'MEDIUM'
    if not away_bats or not home_bats:
        confidence = 'LOW'

    def top_batter_props(bats, side):
        scored = []
        for b in bats:
            name = b.get('name')
            if not name:
                continue
            woba = parse_float(b.get('sv_xwoba') or b.get('fg_woba') or 0.320)
            hr = parse_float(b.get('hr') or b.get('fg_hr') or 0)
            avg = parse_float(b.get('avg') or b.get('fg_avg') or 0.240)
            scored.append((woba, name, avg, hr))
        return sorted(scored, key=lambda x: x[0], reverse=True)[:2]

    props = []
    for bats, side in ((away_bats, context['away_abbr']), (home_bats, context['home_abbr'])):
        best = top_batter_props(bats, side)
        if not best:
            continue
        name = best[0][1]
        woba = best[0][0]
        hr = best[0][3]
        if hr > 0:
            projection = round(min(0.42, 0.14 + woba * 0.25), 3)
            prop_type = 'hr'
            reasoning = f"{name} has strong contact and power metrics against this matchup."
        else:
            projection = round(min(0.76, max(0.32, woba * 2.0)), 3)
            prop_type = 'hits'
            reasoning = f"{name} profiles as a top contact bat with a good chance for multiple hits."
        props.append({
            'player': name,
            'prop': prop_type,
            'projection': projection,
            'reasoning': reasoning
        })

    for pitcher_name, pitcher_data in ((ap_name, ap_fg), (hp_name, hp_fg)):
        k9 = parse_float(pitcher_data.get('fg_k9') or pitcher_data.get('k9') or 6.0)
        k_prob = round(min(0.76, max(0.40, k9 / 9 * 0.72 + 0.18)), 3)
        props.append({
            'player': pitcher_name,
            'prop': 'k',
            'projection': k_prob,
            'reasoning': f"{pitcher_name} is likely to generate strikeouts based on his K/9 profile."
        })

    return {
        'away_runs': int(round(away_runs)),
        'home_runs': int(round(home_runs)),
        'away_hits': int(round(max(6, min(15, away_runs * 1.8)))),
        'home_hits': int(round(max(6, min(15, home_runs * 1.8)))),
        'total_runs': int(round(total_runs)),
        'away_reasoning': away_reasoning,
        'home_reasoning': home_reasoning,
        'key_factors': [
            f"Pitching matchup: {context['away_pitcher']['name']} vs {context['home_pitcher']['name']}",
            f"Lineup strength: {context['away_abbr']} xwOBA {away_xwoba}, {context['home_abbr']} xwOBA {home_xwoba}",
            f"Weather/Park: {wx.get('temp', 'N/A')}°F, {wx.get('condition', 'N/A')} at PF {pf}"
        ],
        'confidence': confidence,
        'notable_props': props[:3]
    }


def _get_ai_boxscore_data(game_pk):
    try:
        result = api_ai_boxscore(game_pk)
        if isinstance(result, tuple):
            result = result[0]
        if hasattr(result, 'get_json'):
            return result.get_json()
        return result
    except Exception as ex:
        print(f"[internal_ai_boxscore] {traceback.format_exc()}")
        return {'success': False, 'error': str(ex), 'projections': None}


@app.route('/api/ai-boxscore/<int:game_pk>')
def api_ai_boxscore(game_pk):
    """AI-powered box score projections using weather, player stats, and recent performance."""
    try:
        # Fetch game data
        gdata = fetch_schedule_game(game_pk)
        if not gdata:
            return jsonify({'success': False, 'error': 'Game not found', 'projections': None})
        
        # Team & weather info
        away_t = gdata.get("teams",{}).get("away",{})
        home_t = gdata.get("teams",{}).get("home",{})
        away_name = away_t.get("team",{}).get("name","Unknown")
        home_name = home_t.get("team",{}).get("name","Unknown")
        away_abbr = away_t.get("team",{}).get("abbreviation","AWAY")
        home_abbr = home_t.get("team",{}).get("abbreviation","HOME")
        
        # Weather
        ven = gdata.get("venue", {})
        venue_name = ven.get("name", "Unknown")
        venue_id = ven.get("id")
        vloc = ven.get("location", {}) or {}
        coords = vloc.get("defaultCoordinates", {}) or {}
        lat = coords.get("latitude")
        lon = coords.get("longitude")
        try:
            dt_utc_wx = datetime.fromisoformat(gdata.get("gameDate","").replace("Z","+00:00"))
            game_hour = dt_utc_wx.astimezone(ET).hour
        except Exception:
            game_hour = 13
        
        wx = get_weather(lat, lon, game_hour, venue_id=venue_id)
        if wx.get('temp') in (None, 'N/A'):
            raw_weather = gdata.get('weather', {}) or {}
            if raw_weather:
                wx = {
                    'temp': raw_weather.get('temp', 'N/A'),
                    'condition': raw_weather.get('condition', 'N/A'),
                    'wind': raw_weather.get('wind', 'N/A'),
                }
        
        # Pitchers
        ap = away_t.get("probablePitcher",{}); hp = home_t.get("probablePitcher",{})
        ap_name = ap.get("fullName","TBD"); hp_name = hp.get("fullName","TBD")
        ap_id = ap.get("id"); hp_id = hp.get("id")
        
        # Get pitcher stats
        ap_stats = pitcher_stats_mlb(ap_id) if ap_id else {}
        hp_stats = pitcher_stats_mlb(hp_id) if hp_id else {}
        ap_fg = fg_pitcher(ap_name); hp_fg = fg_pitcher(hp_name)
        ap_sv = sv_pitcher(ap_name); hp_sv = sv_pitcher(hp_name)
        
        # Get lineups
        try:
            r = requests.get(f"{MLB_API}/game/{game_pk}/boxscore", timeout=10)
            r.raise_for_status()
            box = r.json().get("teams",{})
            away_bats = get_batters_from_boxscore(box.get("away",{}), "away")
            home_bats = get_batters_from_boxscore(box.get("home",{}), "home")
        except Exception as ex:
            print(f'[ai_boxscore] boxscore fetch failed for {game_pk}: {ex}')
            away_bats = []; home_bats = []

        # Park factor
        hid = home_t.get("team",{}).get("id")
        pf = PARK_FACTORS.get(hid, 1.0)
        
        # Build context for AI
        context = {
            'away_team': away_name,
            'away_abbr': away_abbr,
            'home_team': home_name,
            'home_abbr': home_abbr,
            'weather': {
                'temp': wx.get('temp', 'N/A'),
                'condition': wx.get('condition', ''),
                'wind': wx.get('wind', 'N/A'),
            },
            'venue': {
                'name': venue_name,
                'park_factor': pf,
            },
            'away_pitcher': {
                'name': ap_name,
                'era': ap_fg.get('fg_era') or ap_stats.get('era', 'N/A'),
                'whip': ap_fg.get('fg_whip') or ap_stats.get('whip', 'N/A'),
                'k9': ap_fg.get('fg_k9') or ap_stats.get('k9', 'N/A'),
                'xera': ap_sv.get('sv_xera', 'N/A'),
            },
            'home_pitcher': {
                'name': hp_name,
                'era': hp_fg.get('fg_era') or hp_stats.get('era', 'N/A'),
                'whip': hp_fg.get('fg_whip') or hp_stats.get('whip', 'N/A'),
                'k9': hp_fg.get('fg_k9') or hp_stats.get('k9', 'N/A'),
                'xera': hp_sv.get('sv_xera', 'N/A'),
            },
            'away_lineup': [
                {
                    'slot': b.get('slot'),
                    'name': b.get('name'),
                    'pos': b.get('pos'),
                    'avg': b.get('avg'),
                    'obp': b.get('obp'),
                    'slg': b.get('slg'),
                    'woba': b.get('fg_woba'),
                    'xwoba': b.get('sv_xwoba'),
                    'ev': b.get('sv_ev'),
                    'hr': b.get('hr'),
                }
                for b in away_bats[:9]
            ],
            'home_lineup': [
                {
                    'slot': b.get('slot'),
                    'name': b.get('name'),
                    'pos': b.get('pos'),
                    'avg': b.get('avg'),
                    'obp': b.get('obp'),
                    'slg': b.get('slg'),
                    'woba': b.get('fg_woba'),
                    'xwoba': b.get('sv_xwoba'),
                    'ev': b.get('sv_ev'),
                    'hr': b.get('hr'),
                }
                for b in home_bats[:9]
            ],
        }

        ai_projections = None
        ai_error = None
        prompt = (
            f"Game: {context['away_team']} ({context['away_pitcher']['name']}, ERA {context['away_pitcher']['era']}) "
            f"at {context['home_team']} ({context['home_pitcher']['name']}, ERA {context['home_pitcher']['era']}).\n"
            f"Venue: {context['venue']['name']} (park factor {context['venue']['park_factor']}).\n"
            f"Weather: {context['weather']['temp']}°F, {context['weather']['condition']}, wind {context['weather']['wind']}.\n"
            f"Away lineup xwOBA top 3: " +
            ", ".join(f"{b['name']} {b.get('xwoba','N/A')}" for b in context['away_lineup'][:3]) + ".\n"
            f"Home lineup xwOBA top 3: " +
            ", ".join(f"{b['name']} {b.get('xwoba','N/A')}" for b in context['home_lineup'][:3]) + ".\n"
            "Return JSON with keys: away_runs (int), home_runs (int), away_hits (int), home_hits (int), "
            "total_runs (int), away_reasoning (str), home_reasoning (str), key_factors (list of str), "
            "confidence (HIGH|MEDIUM|LOW), notable_props (list of {player, prop, projection, reasoning})."
        )
        ai_projections, ai_error = _vertex_gemini_json(
            "narrative", prompt,
            system="You are an expert MLB analyst providing detailed game and player projections "
                   "based on comprehensive statistical analysis. Respond with raw JSON only.",
            max_tokens=2000, temperature=0.7,
        )

        if ai_projections is None:
            ai_projections = _local_boxscore_projections(
                game_pk, context, away_bats, home_bats, ap_name, hp_name,
                ap_fg, hp_fg, ap_sv, hp_sv, ap_stats, hp_stats, pf, wx,
                away_t, home_t
            )
            ai_projections['source'] = 'local_fallback'
            ai_projections['fallback_reason'] = ai_error or 'Gemini unavailable'
        
        return jsonify({
            'success': True,
            'gamePk': game_pk,
            'matchup': f"{away_abbr} vs {home_abbr}",
            'weather': context['weather'],
            'venue': context['venue'],
            'pitching_matchup': {
                'away_pitcher': context['away_pitcher'],
                'home_pitcher': context['home_pitcher']
            },
            'projections': ai_projections,
            'timestamp': datetime.now(timezone.utc).isoformat(),
        })
        
    except Exception as ex:
        print(f"[api_ai_boxscore] {game_pk}: {traceback.format_exc()}")
        return jsonify({
            'success': False,
            'error': str(ex),
            'projections': None
        }), 500

# ── Shared helper: fetch game + lineup ───────────────────────────────────────
def _props_fetch_game(game_pk, date_hint=None, gdata_override=None):
    """Fetch schedule entry + boxscore lineups, preferring the requested date.

    Pass gdata_override to skip the schedule fetch when the caller already has
    the raw schedule entry (e.g. cheatsheet bulk processing avoids N redundant
    fetch_schedule calls by passing the already-fetched entry directly).
    """
    if gdata_override and gdata_override.get("gamePk") == game_pk:
        gdata = gdata_override
    else:
        gdata = None
        candidate_dates = []
        if date_hint:
            date_hint = _normalize_date_str(date_hint, fallback='')
            if date_hint:
                candidate_dates.append(date_hint)
                try:
                    base_dt = datetime.strptime(date_hint, "%Y-%m-%d")
                    candidate_dates.extend([
                        (base_dt + timedelta(days=-1)).strftime("%Y-%m-%d"),
                        (base_dt + timedelta(days=1)).strftime("%Y-%m-%d"),
                    ])
                except Exception:
                    pass
        for delta in (0, -1, 1):
            candidate_dates.append((datetime.now(ET) + timedelta(days=delta)).strftime("%Y-%m-%d"))

        seen_dates = set()
        for date_str in candidate_dates:
            if not date_str or date_str in seen_dates:
                continue
            seen_dates.add(date_str)
            raw   = fetch_schedule(date_str)
            gdata = next((g for g in raw if g.get("gamePk") == game_pk), None)
            if gdata:
                break
    if not gdata:
        return None, [], [], {}, {}, {}

    away_t  = gdata.get("teams", {}).get("away", {})
    home_t  = gdata.get("teams", {}).get("home", {})
    ap_info = away_t.get("probablePitcher", {})
    hp_info = home_t.get("probablePitcher", {})

    # Skip boxscore fetch for postponed/cancelled games — there is no game to score.
    _gstatus = str((gdata.get("status") or {}).get("detailedState") or "").lower()
    _is_inactive = any(tok in _gstatus for tok in ("postponed", "cancelled", "canceled", "suspended"))

    away_bats, home_bats = [], []
    if not _is_inactive:
        try:
            r = requests.get(f"{MLB_API}/game/{game_pk}/boxscore", timeout=10)
            r.raise_for_status()
            box = r.json().get("teams", {})
            away_bats = get_batters_from_boxscore(box.get("away", {}), "away")
            home_bats = get_batters_from_boxscore(box.get("home", {}), "home")
        except Exception as ex:
            print(f"[props] boxscore error: {ex}")

    # Pre-game fallback: hydrate scheduled lineups from schedule payload.
    if not away_bats or not home_bats:
        lineups = (gdata.get("lineups") or {})

        def _parse_sched(hitters):
            out = []
            for i, p in enumerate(hitters or [], start=1):
                name = (p.get("fullName") or p.get("name") or "").strip()
                pid  = p.get("id") or p.get("playerId")
                pos  = (p.get("primaryPosition") or {}).get("abbreviation", "?")
                if not name:
                    continue
                fgb = fg_batter(name)
                svb = sv_batter(name)
                bio = _bio_cache.get(pid) or {}
                out.append({
                    "slot": i, "id": pid, "name": name, "pos": pos,
                    "bats": bio.get("bats", p.get("batSide", {}).get("code", "S")),
                    "lineup_status": "pending",
                    "avg": fgb.get("fg_avg", ".---"), "obp": fgb.get("fg_obp", ".---"),
                    "slg": fgb.get("fg_slg", ".---"), "ops": fgb.get("fg_ops", ".---"),
                    "ab": 0, "hits": 0, "hr": 0, "rbi": 0,
                    "fg_pa": fgb.get("fg_pa", "N/A"), "fg_r": fgb.get("fg_r", "N/A"),
                    "fg_sb": fgb.get("fg_sb", "N/A"), "fg_woba": fgb.get("fg_woba", "N/A"),
                    "fg_wrc": fgb.get("fg_wrc", "N/A"), "fg_war": fgb.get("fg_war", "N/A"),
                    "sv_xba": svb.get("sv_xba", "N/A"), "sv_xslg": svb.get("sv_xslg", "N/A"),
                    "sv_xwoba": svb.get("sv_xwoba", "N/A"), "sv_ev": svb.get("sv_ev", "N/A"),
                    "sv_hh_pct": svb.get("sv_hh_pct", "N/A"), "sv_brl_pct": svb.get("sv_brl_pct", "N/A"),
                    "sv_la": svb.get("sv_la", "N/A"),
                })
            return out

        if not away_bats:
            away_bats = _parse_sched(lineups.get("awayBatters") or [])
        if not home_bats:
            home_bats = _parse_sched(lineups.get("homeBatters") or [])

    # Last resort: build a provisional top-9 from active roster so projections
    # still render before official/projected lineups are published.
    if not away_bats or not home_bats:
        def _roster_fallback(team_id):
            out = []
            if not team_id:
                return out
            try:
                for p in _get_active_roster(team_id):
                    pos = ((p.get("position") or {}).get("abbreviation") or "?").upper()
                    if pos in ("P", "SP", "RP", "CP"):
                        continue
                    person = p.get("person") or {}
                    name = (person.get("fullName") or "").strip()
                    pid = person.get("id")
                    if not name:
                        continue
                    fgb = fg_batter(name)
                    svb = sv_batter(name)
                    bio = _bio_cache.get(pid) or {}
                    out.append({
                        "slot": len(out) + 1,
                        "id": pid,
                        "name": name,
                        "pos": pos,
                        "bats": bio.get("bats", "S"),
                        "lineup_status": "pending",
                        "avg": fgb.get("fg_avg", ".---"),
                        "obp": fgb.get("fg_obp", ".---"),
                        "slg": fgb.get("fg_slg", ".---"),
                        "ops": fgb.get("fg_ops", ".---"),
                        "ab": 0,
                        "hits": 0,
                        "hr": 0,
                        "rbi": 0,
                        "fg_pa": fgb.get("fg_pa", "N/A"),
                        "fg_r": fgb.get("fg_r", "N/A"),
                        "fg_sb": fgb.get("fg_sb", "N/A"),
                        "fg_woba": fgb.get("fg_woba", "N/A"),
                        "fg_wrc": fgb.get("fg_wrc", "N/A"),
                        "fg_war": fgb.get("fg_war", "N/A"),
                        "sv_xba": svb.get("sv_xba", "N/A"),
                        "sv_xslg": svb.get("sv_xslg", "N/A"),
                        "sv_xwoba": svb.get("sv_xwoba", "N/A"),
                        "sv_ev": svb.get("sv_ev", "N/A"),
                        "sv_hh_pct": svb.get("sv_hh_pct", "N/A"),
                        "sv_brl_pct": svb.get("sv_brl_pct", "N/A"),
                        "sv_la": svb.get("sv_la", "N/A"),
                    })
                    if len(out) >= 9:
                        break
            except Exception as ex:
                print(f"[props] roster fallback error team={team_id}: {ex}")
            return out

        away_team_id = (away_t.get("team") or {}).get("id")
        home_team_id = (home_t.get("team") or {}).get("id")
        if not away_bats:
            away_bats = _roster_fallback(away_team_id)
        if not home_bats:
            home_bats = _roster_fallback(home_team_id)

    # Pre-warm bio cache in parallel so every batter carries a real `bats` value
    # (lineup section needs this to render handedness correctly).
    _missing_pids = [b.get("id") for b in (away_bats + home_bats)
                     if b.get("id") and b.get("id") not in _bio_cache]
    if _missing_pids:
        try:
            with ThreadPoolExecutor(max_workers=min(len(_missing_pids), 9)) as _pool:
                list(_pool.map(player_profile, _missing_pids))
        except Exception:
            pass
    for b in away_bats + home_bats:
        pid = b.get("id")
        if pid and pid in _bio_cache:
            b["bats"] = _bio_cache[pid].get("bats", b.get("bats") or "S")
        elif not b.get("bats"):
            b["bats"] = "S"

    return gdata, away_bats, home_bats, away_t, home_t, {"ap": ap_info, "hp": hp_info}


# ── Platoon blend helper ──────────────────────────────────────────────────────
def _platoon_blend(batter, pitcher_hand, stat):
    """
    Returns a platoon-blended value for a given stat key ('avg', 'ops', 'slg', 'obp').
    Blends split stat with season stat weighted by PA sample size:
      >= 100 PA  → 80% split / 20% season
      >= 50  PA  → 65% split / 35% season
      >= 25  PA  → 45% split / 55% season
      <  25  PA  → season only
    Falls back gracefully when splits are missing.
    pitcher_hand: 'L' or 'R' (or 'S' treated as 'R')
    """
    hand = (pitcher_hand or 'R').upper()
    if hand not in ('L', 'R'):
        hand = 'R'

    split_key = f"vs_{'l' if hand == 'L' else 'r'}_{stat}"
    split_val = _safe_f(batter.get(split_key), 0.0)

    # Retrieve split PA — stored as vs_l_pa / vs_r_pa if present, else infer from ops
    pa_key    = f"vs_{'l' if hand == 'L' else 'r'}_pa"
    split_pa  = int(batter.get(pa_key, 0) or 0)

    # Season value
    season_map = {
        'avg': batter.get('avg') or batter.get('fg_avg'),
        'ops': batter.get('ops'),
        'slg': batter.get('slg') or batter.get('fg_slg'),
        'obp': batter.get('obp') or batter.get('fg_obp'),
    }
    season_val = _safe_f(season_map.get(stat), _STAT_DEFAULTS.get(stat, 0.0))

    # No split data — return season
    if split_val <= 0.0:
        return season_val

    # Blend weights by sample size
    if split_pa >= 100:
        w_split = 0.80
    elif split_pa >= 50:
        w_split = 0.65
    elif split_pa >= 25:
        w_split = 0.45
    else:
        w_split = 0.30   # small sample — lean season

    w_season  = 1.0 - w_split
    blended   = round(w_split * split_val + w_season * season_val, 4)
    return blended


# Stat defaults used as fallback when both split and season are missing
_STAT_DEFAULTS = {
    'avg': 0.245,
    'obp': 0.315,
    'slg': 0.390,
    'ops': 0.705,
}

# ── BAT X component weights (calibration hook) ────────────────────────────────
# Sum of weights defines relative contribution to composite multiplier.
# Increase/decrease individual weights to calibrate vs historical results.
BATX_WEIGHTS = BATX_WEIGHTS_V2


def _batter_hand_note(batter, pitcher_hand):
    """
    Returns a short string describing the platoon matchup, e.g. 'LHB vs RHP (+)'
    Used for UI display on the projection card.
    """
    bat  = (batter.get('bats') or 'S').upper()
    pit  = (pitcher_hand or 'R').upper()
    if bat == 'S':
        return f"SB vs {'RHP' if pit == 'R' else 'LHP'} (switch)"
    favorable = (bat == 'L' and pit == 'R') or (bat == 'R' and pit == 'L')
    direction = '+' if favorable else '−'
    return f"{'LHB' if bat == 'L' else 'RHB'} vs {'RHP' if pit == 'R' else 'LHP'} ({direction})"


# ── Batter projection engine (v2 — platoon-aware) ────────────────────────────
def _project_batter(batter, opp_pitcher_name, opp_pitcher_fg, opp_pitcher_sv,
                    park_factor, weather, pitcher_hand='R'):
    """
    Returns per-prop projections for one batter.
    Uses platoon-blended avg/obp/slg/ops as base rates when split PA is available.
    """
    name = batter.get("name", "")
    fg   = fg_batter(name)
    sv   = sv_batter(name)

    # ── Platoon-blended base rates ────────────────────────────────────────────
    avg  = platoon_blend_v2(batter, pitcher_hand, 'avg')
    obp  = platoon_blend_v2(batter, pitcher_hand, 'obp')
    slg  = platoon_blend_v2(batter, pitcher_hand, 'slg')
    ops  = platoon_blend_v2(batter, pitcher_hand, 'ops')

    # Fallback chain for fg-only stats (not in splits)
    fg_pa  = _safe_f(fg.get("fg_pa"),  200)
    fg_hr  = _safe_f(fg.get("fg_hr"),  3)
    fg_rbi = _safe_f(fg.get("fg_rbi"), 12)
    fg_r   = _safe_f(fg.get("fg_r"),   12)
    hr_r   = fg_hr  / max(fg_pa, 1)
    rbi_r  = fg_rbi / max(fg_pa, 1)
    r_r    = fg_r   / max(fg_pa, 1)

    # Scale HR rate by platoon OPS ratio (strong platoon advantage boosts power)
    season_ops  = _safe_f(batter.get('ops'), _STAT_DEFAULTS['ops'])
    ops_ratio   = ops / max(season_ops, 0.400)            # ≈1.0 neutral, >1 platoon advantage
    hr_r_adj    = hr_r * ops_ratio                        # HR scales with ops split

    xwoba = _safe_f(sv.get("sv_xwoba") or fg.get("fg_woba"), 0.310)
    brl   = _safe_f(sv.get("sv_brl_pct"), 6.0) / 100

    # ── Pitcher resistance multiplier ─────────────────────────────────────────
    opp_era  = _safe_f(opp_pitcher_fg.get("fg_era")  or opp_pitcher_sv.get("sv_era_p"), 4.20)
    opp_xera = _safe_f(opp_pitcher_sv.get("sv_xera"), opp_era)
    opp_xfip = _safe_f(opp_pitcher_fg.get("fg_xfip"), (opp_era + opp_xera) / 2)
    opp_kpct = _safe_f(opp_pitcher_fg.get("fg_kpct"), 0.22)
    bat_kpct = _safe_f(fg.get("fg_kpct") or sv.get("sv_k_pct"), 0.22)

    # xFIP as 3rd anchor: stabilizes low-IP pitchers; weighted avg of ERA/xERA/xFIP
    pit_mult = min(1.25, max(0.72, (opp_era * 0.35 + opp_xera * 0.35 + opp_xfip * 0.30) / 4.20))
    k_adj    = 1.0 - max(0.0, (opp_kpct - bat_kpct) * 0.5)

    # ── Platoon K-rate modifier ───────────────────────────────────────────────
    # Platoon disadvantage → more K exposure
    bat  = (batter.get('bats') or 'S').upper()
    pit  = (pitcher_hand or 'R').upper()
    if bat != 'S':
        platoon_k_mod = 0.96 if ((bat == 'L' and pit == 'R') or (bat == 'R' and pit == 'L')) else 1.04
    else:
        platoon_k_mod = 1.0   # switch hitter, neutral
    k_adj *= platoon_k_mod

    # ── Weather multiplier ────────────────────────────────────────────────────
    dome      = weather.get("dome", False)
    wx_mult   = 1.0
    if not dome:
        temp_f   = _safe_f(weather.get("temp"), 72)
        wind_spd = _safe_f(weather.get("wind_speed"), 0)
        wx_mult  = 1.0 + (temp_f - 72) * 0.003 + min(0.06, float(wind_spd) * 0.003)

    # ── Expected PA by slot ───────────────────────────────────────────────────
    slot   = int(batter.get("slot") or 5)
    exp_pa = round(4.35 - (slot - 1) * 0.095, 2)

    # ── Projections ───────────────────────────────────────────────────────────
    # Hits: platoon avg replaces season avg as base
    hits_proj = round(max(0.05, avg * exp_pa * pit_mult * k_adj * park_factor * wx_mult), 3)

    # Total Bases: built from platoon slg
    tb_proj   = round(max(0.08, slg * exp_pa * pit_mult * k_adj * park_factor * wx_mult), 3)

    # HR: platoon-adjusted hr rate + barrel bonus + park + weather
    hr_pf     = min(1.30, park_factor * 1.08)
    hr_proj   = round(max(0.005,
        hr_r_adj * exp_pa * hr_pf * (1.0 + (brl - 0.06) * 0.8) * wx_mult
    ), 4)

    # RBI: correlated to hits+HR, slot bonus
    slot_rbi_bonus = max(0.8, 1.0 + (4 - abs(slot - 4)) * 0.03)
    rbi_proj  = round(max(0.05, rbi_r * exp_pa * pit_mult * park_factor * slot_rbi_bonus), 3)

    # Runs: lead-off slots score more
    slot_r_bonus = max(0.8, 1.1 - abs(slot - 1.5) * 0.025)
    r_proj    = round(max(0.04, r_r * exp_pa * pit_mult * slot_r_bonus), 3)

    # H+R+RBI combo
    hrr_proj  = round(hits_proj + r_proj + rbi_proj, 3)

    return {
        "hits":        hits_proj,
        "hr":          hr_proj,
        "tb":          tb_proj,
        "rbi":         rbi_proj,
        "r":           r_proj,
        "hrr":         hrr_proj,
        "expected_pa": exp_pa,
        # expose the blended rates so the frontend can show them
        "split_avg":   round(avg, 3),
        "split_ops":   round(ops, 3),
        "platoon_note": _batter_hand_note(batter, pitcher_hand),
    }


# ── BAT X projection engine (v3) ──────────────────────────────────────────────
_LEAGUE_WOBA    = 0.320
_LEAGUE_BB_PCT  = 0.083
_LEAGUE_K_PCT   = 0.220
_LEAGUE_EV      = 88.5
_LEAGUE_BRL_PCT = 0.063   # 6.3 %

def _project_batter_batx(batter, opp_pitcher_name, opp_pitcher_fg, opp_pitcher_sv,
                          park_factor, weather, pitcher_hand='R',
                          opp_pitcher_id=None,
                          form=None, bvp=None, travel=None, def_factor=1.0):
    """
    BAT X-style projection engine with named component weights (BATX_WEIGHTS).
    Signature is backwards-compatible with _project_batter; adds optional
    form / bvp kwargs (Phase 1 dicts) and an 'adjustments' key in the return dict.

    All per-component raw contributions are stored in `adjustments` for calibration.
    """
    W = BATX_WEIGHTS  # shorthand

    name = batter.get("name", "")
    bid  = batter.get("id") or batter.get("mlb_id")
    fg   = fg_batter(name)
    sv   = sv_batter(name)

    # ── Bat tracking + swing/take (free Savant leaderboards) ──────────────────
    # Used below to boost power_contrib and shade disc_contrib. No-op if the
    # CSVs aren't available — fallback values keep behavior identical.
    bt  = sv_bat_tracking(name=name, player_id=bid) if _BAT_TRACKING_AVAILABLE else {}
    swt = sv_swing_take(name=name,   player_id=bid) if _BAT_TRACKING_AVAILABLE else {}
    bt_pwr_mult = bt_power_boost(bt) if _BAT_TRACKING_AVAILABLE else 1.0
    bt_disc_edge = bt_disc_boost(swt) if _BAT_TRACKING_AVAILABLE else 0.0

    # ── Slot / PA ─────────────────────────────────────────────────────────────
    slot   = int(batter.get("slot") or 5)
    exp_pa = round(4.35 - (slot - 1) * 0.095, 2)

    # ── Platoon-blended base rates ────────────────────────────────────────────
    avg  = platoon_blend_v2(batter, pitcher_hand, 'avg')
    obp  = platoon_blend_v2(batter, pitcher_hand, 'obp')
    slg  = platoon_blend_v2(batter, pitcher_hand, 'slg')
    ops  = platoon_blend_v2(batter, pitcher_hand, 'ops')

    season_avg = _safe_f(batter.get('avg') or fg.get('fg_avg'), _STAT_DEFAULTS['avg'])
    season_ops = _safe_f(batter.get('ops'), _STAT_DEFAULTS['ops'])

    # ── Raw stats ─────────────────────────────────────────────────────────────
    fg_pa   = _safe_f(fg.get("fg_pa"),  200)
    fg_hr   = _safe_f(fg.get("fg_hr"),  3)
    fg_rbi  = _safe_f(fg.get("fg_rbi"), 12)
    fg_r    = _safe_f(fg.get("fg_r"),   12)
    fg_iso  = _safe_f(fg.get("fg_iso"), 0.145)
    fg_bbp  = _safe_f(fg.get("fg_bbpct"), _LEAGUE_BB_PCT)
    fg_kp   = _safe_f(fg.get("fg_kpct"),  _LEAGUE_K_PCT)
    fg_woba = _safe_f(fg.get("fg_woba"), _LEAGUE_WOBA)
    fg_wrc  = _safe_f(fg.get("fg_wrc"),  100)

    sv_xba   = _safe_f(sv.get("sv_xba"),    season_avg)
    sv_xslg  = _safe_f(sv.get("sv_xslg"),   slg)
    sv_xwoba = _safe_f(sv.get("sv_xwoba") or fg.get("fg_woba"), _LEAGUE_WOBA)
    sv_ev    = _safe_f(sv.get("sv_ev"),      _LEAGUE_EV)
    sv_brl   = _safe_f(sv.get("sv_brl_pct"), _LEAGUE_BRL_PCT * 100) / 100   # → fraction
    sv_hh    = _safe_f(sv.get("sv_hh_pct"),  35.0) / 100                     # → fraction
    pull_air = _safe_f(sv.get("pull_pct_air"), 35.0) / 100

    hr_r  = fg_hr  / max(fg_pa, 1)
    rbi_r = fg_rbi / max(fg_pa, 1)
    r_r   = fg_r   / max(fg_pa, 1)

    # ── COMPONENT 1: Contact ──────────────────────────────────────────────────
    # Blend platoon AVG (80%) with xBA (20%); PA-confidence shrink vs league
    #   if <100 PA in platoon split, _platoon_blend already applies its own shrink.
    pa_conf    = min(1.0, fg_pa / 400)            # 0→1 as PA grows to 400
    avg_blend  = avg * 0.80 + sv_xba * 0.20
    contact_raw = avg_blend / _STAT_DEFAULTS['avg']   # ratio vs neutral baseline
    contact_raw = 1.0 + (contact_raw - 1.0) * (0.5 + 0.5 * pa_conf)  # shrink toward 1
    contact_contrib = (contact_raw - 1.0) * W["contact"]

    # ── COMPONENT 2: Power ────────────────────────────────────────────────────
    # ISO edge, barrel edge, EV edge, xSLG edge — combine with weights
    iso_edge  = (fg_iso - 0.145) / 0.145              # delta vs league-avg ISO
    brl_edge  = (sv_brl - _LEAGUE_BRL_PCT) / _LEAGUE_BRL_PCT
    ev_edge   = (sv_ev  - _LEAGUE_EV) / _LEAGUE_EV
    pull_edge = (pull_air - 0.35) / 0.35
    xslg_edge = (sv_xslg - _STAT_DEFAULTS['slg']) / _STAT_DEFAULTS['slg']
    power_raw = iso_edge * 0.30 + brl_edge * 0.30 + ev_edge * 0.15 + xslg_edge * 0.15 + pull_edge * 0.10
    # Apply bat-tracking power boost (1.0 when no data — backwards-compatible).
    power_raw = power_raw * bt_pwr_mult + (bt_pwr_mult - 1.0)
    power_contrib = power_raw * W["power"]

    # ── COMPONENT 3: Discipline ───────────────────────────────────────────────
    # Positive: high BB%, low K%, high xwOBA + swing/take run value
    bb_edge   = (fg_bbp - _LEAGUE_BB_PCT) / _LEAGUE_BB_PCT
    k_edge    = (_LEAGUE_K_PCT - fg_kp)   / _LEAGUE_K_PCT   # lower K → positive
    woba_edge = (sv_xwoba - _LEAGUE_WOBA) / _LEAGUE_WOBA
    disc_raw  = bb_edge * 0.30 + k_edge * 0.40 + woba_edge * 0.30 + bt_disc_edge
    disc_contrib = disc_raw * W["discipline"]

    # ── COMPONENT 4: Platoon ──────────────────────────────────────────────────
    bat = (batter.get('bats') or 'S').upper()
    pit = (pitcher_hand or 'R').upper()
    if bat == 'S':
        platoon_edge = 0.0
    elif (bat == 'L' and pit == 'R') or (bat == 'R' and pit == 'L'):
        platoon_edge = +0.05   # favorable platoon advantage
    else:
        platoon_edge = -0.05   # unfavorable
    platoon_contrib = platoon_edge * W["platoon"]

    # ── COMPONENT 5: Park ─────────────────────────────────────────────────────
    park_edge    = (park_factor - 1.0)
    park_contrib = park_edge * W["park"]

    # ── COMPONENT 6: Weather ──────────────────────────────────────────────────
    dome     = weather.get("dome", False)
    temp_f   = _safe_f(weather.get("temp"), 72) if not dome else 72
    wind_spd = _safe_f(weather.get("wind_speed"), 0) if not dome else 0
    wx_raw   = (temp_f - 72) * 0.003 + min(0.06, float(wind_spd) * 0.003)
    wx_mult  = 1.0 + wx_raw                   # hard multiplier used in final stats
    wx_edge  = wx_raw
    wx_contrib = wx_edge * W["weather"]

    # ── COMPONENT 7: Pitcher resistance ──────────────────────────────────────
    opp_era  = _safe_f(opp_pitcher_fg.get("fg_era")  or opp_pitcher_sv.get("sv_era_p"), 4.20)
    opp_xera = _safe_f(opp_pitcher_sv.get("sv_xera"), opp_era)
    bat_kpct = fg_kp

    recent_form = _pitcher_recent_form(opp_pitcher_id) if opp_pitcher_id else {}
    pit_mult, kpct_blended = pitcher_component_v2(opp_pitcher_fg, opp_pitcher_sv, recent_form)
    k_adj     = 1.0 - _clamp((kpct_blended - bat_kpct) * 0.5, -0.15, 0.15)
    # Platoon K modifier: disadvantage means more Ks
    if bat != 'S':
        plat_k = 0.97 if ((bat == 'L' and pit == 'R') or (bat == 'R' and pit == 'L')) else 1.03
    else:
        plat_k = 1.0
    k_adj *= plat_k

    pitcher_edge = (pit_mult * k_adj) - 1.0
    pitcher_contrib = pitcher_edge * W["pitcher"]

    # ── COMPONENT 8: Recent form (Phase 1) ───────────────────────────────────
    form_edge   = 0.0
    form_label  = "no data"
    if form and isinstance(form, dict):
        l7 = form.get("l7") or {}
        rw = l7.get("raw_woba") if l7 else None
        if rw is not None:
            form_edge  = _clamp((rw - _LEAGUE_WOBA) / _LEAGUE_WOBA, -0.25, 0.25)
            form_label = f"L7 wOBA {rw:.3f}"
    form_contrib = form_edge * W["form"]

    # ── COMPONENT 9: BvP (recency-weighted H2H) ──────────────────────────────
    bvp_edge    = 0.0
    bvp_label   = "no data"
    if bvp and isinstance(bvp, dict) and bvp.get("success"):
        reliability = _safe_f(bvp.get("reliability"), 0.0)
        we          = _safe_f(bvp.get("woba_edge"),    0.0)
        bvp_edge    = _clamp(we * reliability, -0.20, 0.20)
        recent_pa   = bvp.get("recent_pa", 0)
        bvp_label   = f"woba_edge {we:.3f} × rel {reliability:.2f} (recent_pa={recent_pa})"
    bvp_contrib  = bvp_edge * W.get("bvp", 0.01)

    # ── COMPONENT 10: Pitch-mix score (arsenal matchup) ──────────────────────
    # Blends two complementary signals:
    #   (a) FG per-pitch RV/100 — batter's run value against each pitch type, weighted
    #       by pitcher's current arsenal mix.  Uses recency-weighted 2021-2026 FG data.
    #   (b) Statcast SLG ratio — batter SLG vs each pitch ÷ league baseline.
    # If both signals are available, blend 60/40 (FG RV is more direct).
    pitch_mix_score  = 1.0
    pitch_mix_label  = "no data"
    bat_mlb_id = batter.get("id") or batter.get("mlb_id")
    if opp_pitcher_id and bat_mlb_id:
        try:
            fg_pm_score,  _ = _fg_pitch_matchup_score(bat_mlb_id, opp_pitcher_id)
            sv_pm_score,  _ = _compute_pitch_mix_score(str(opp_pitcher_id), str(bat_mlb_id))
            fg_has_data = (fg_pm_score != 1.0)
            sv_has_data = (sv_pm_score != 1.0)
            if fg_has_data and sv_has_data:
                pitch_mix_score = fg_pm_score * 0.60 + sv_pm_score * 0.40
                pitch_mix_label = f"fg_rv {fg_pm_score:.3f} + sv_slg {sv_pm_score:.3f} → {pitch_mix_score:.3f}"
            elif fg_has_data:
                pitch_mix_score = fg_pm_score
                pitch_mix_label = f"fg_rv {fg_pm_score:.3f}"
            elif sv_has_data:
                pitch_mix_score = sv_pm_score
                pitch_mix_label = f"sv_slg {sv_pm_score:.3f}"
        except Exception:
            pass
    pitch_mix_edge    = _clamp(pitch_mix_score - 1.0, -0.30, 0.30)
    pitch_mix_contrib = pitch_mix_edge * W.get("pitch_mix", 0.04)

    # ── COMPONENT 11: Travel / rest fatigue (schedule-derived) ───────────────
    # Schedule-derived multiplier in [0.96, 1.00]. Applied directly to the
    # composite — no W weight, since it's already a calibrated shade.
    travel_mult  = 1.0
    travel_note  = ""
    if travel and isinstance(travel, dict):
        try:
            travel_mult = float(travel.get("mult") or 1.0)
            travel_note = travel.get("note") or ""
        except (TypeError, ValueError):
            travel_mult = 1.0
    travel_edge    = travel_mult - 1.0
    travel_contrib = travel_edge   # weight=1.0 (literature-calibrated shade)

    # ── Composite multiplier ─────────────────────────────────────────────────
    # Sum contributions; each is a %-point delta weighted by its component weight.
    delta = (contact_contrib + power_contrib + disc_contrib + platoon_contrib
             + park_contrib + wx_contrib + pitcher_contrib
             + form_contrib + bvp_contrib + pitch_mix_contrib
             + travel_contrib)
    # Humility prior: when both per-batter matchup signals (recent form, BvP)
    # are unavailable, the season-level contributions can over-state confidence.
    # Pull the delta 30% toward zero so projections stay closer to neutral when
    # we genuinely have no matchup-specific info to distinguish this start from
    # the batter's seasonal baseline.
    has_form = bool(form and isinstance(form, dict) and (form.get("l7") or {}).get("raw_woba") is not None)
    has_bvp  = bool(bvp and isinstance(bvp, dict) and bvp.get("success") and _safe_f(bvp.get("reliability"), 0.0) > 0.0)
    if not has_form and not has_bvp:
        delta *= 0.70
    composite = _clamp(1.0 + delta, 0.55, 1.55)

    # ── Projections ──────────────────────────────────────────────────────────
    # Use wx_mult separately to preserve existing weather logic; pit_mult/k_adj 
    # are already baked into pitcher_contrib → composite.
    # Keep legacy structure: hits, tb, hr, rbi, r, hrr

    ops_ratio = ops / max(season_ops, 0.400)
    hr_r_adj  = hr_r * ops_ratio * _clamp(brl_edge + 1.0, 0.70, 1.40)

    # Opponent team-defense factor (OAA-based). Applies to BABIP-dependent
    # props only — better defense converts more balls in play into outs. HR is
    # excluded (fielding can't take back a ball over the fence).
    def_factor = _clamp(float(def_factor or 1.0), 0.90, 1.10)

    hits_proj = round(max(0.05, avg_blend * exp_pa * composite * wx_mult * def_factor), 3)
    tb_proj   = round(max(0.08, slg       * exp_pa * composite * wx_mult * def_factor), 3)

    hr_pf   = _clamp(park_factor * 1.08, 0.80, 1.35)
    pull_park_boost = 1.0 + (max(0.0, pull_edge) * max(0.0, park_factor - 1.0) * 1.25)
    pull_park_boost = _clamp(pull_park_boost, 0.95, 1.25)
    hr_proj = round(max(0.005,
        hr_r_adj * exp_pa * hr_pf * (1.0 + (sv_brl - _LEAGUE_BRL_PCT) * 0.8) * pull_park_boost * wx_mult
    ), 4)

    slot_rbi_bonus = max(0.8, 1.0 + (4 - abs(slot - 4)) * 0.03)
    rbi_proj = round(max(0.05, rbi_r * exp_pa * composite * slot_rbi_bonus * def_factor), 3)

    slot_r_bonus = max(0.8, 1.1 - abs(slot - 1.5) * 0.025)
    r_proj   = round(max(0.04, r_r * exp_pa * composite * slot_r_bonus * def_factor), 3)

    hrr_proj = round(hits_proj + r_proj + rbi_proj, 3)

    return {
        "hits":        hits_proj,
        "hr":          hr_proj,
        "tb":          tb_proj,
        "rbi":         rbi_proj,
        "r":           r_proj,
        "hrr":         hrr_proj,
        "expected_pa": exp_pa,
        "split_avg":   round(avg_blend, 3),
        "split_ops":   round(ops, 3),
        "platoon_note": _batter_hand_note(batter, pitcher_hand),
        "defFactor":   round(def_factor, 4),
        # BAT X diagnostics
        "composite":   round(composite, 4),
        "adjustments": {
            "contact":         round(contact_contrib,    4),
            "power":           round(power_contrib,      4),
            "pull_air":        round(pull_edge * 0.10 * W["power"], 4),
            "discipline":      round(disc_contrib,       4),
            "platoon":         round(platoon_contrib,    4),
            "park":            round(park_contrib,       4),
            "weather":         round(wx_contrib,         4),
            "pitcher":         round(pitcher_contrib,    4),
            "form":            round(form_contrib,       4),
            "bvp":             round(bvp_contrib,        4),
            "pitch_mix":       round(pitch_mix_contrib,  4),
            "travel":          round(travel_contrib,     4),
            "form_note":       form_label,
            "bvp_note":        bvp_label,
            "pitch_mix_note":  pitch_mix_label,
            "travel_note":     travel_note,
            "bat_speed":       round(float(bt.get("bat_speed") or 0.0), 2) if bt.get("bat_speed") is not None else None,
            "squared_up_pct":  round(float(bt.get("squared_up_pct") or 0.0), 4) if bt.get("squared_up_pct") is not None else None,
            "bt_power_mult":   round(bt_pwr_mult, 4),
            "bt_disc_edge":    round(bt_disc_edge, 4),
        },
    }


# ── Pitcher recent form cache ─────────────────────────────────────────────────
_pitcher_recent_cache = {}   # pid → {ts, era_recent, k9_recent, whip_recent, starts}

def _pitcher_recent_form(pitcher_id, n_starts=5):
    """
    Fetch last n_starts game logs for a pitcher and return blended weighted stats.
    Caches per pitcher per calendar day.
    Returns dict with era_recent, k9_recent, whip_recent, n_starts_found.
    """
    if not pitcher_id:
        return {}
    cache_key = f"{pitcher_id}_{datetime.now(ET).strftime('%Y-%m-%d')}"
    if cache_key in _pitcher_recent_cache:
        return _pitcher_recent_cache[cache_key]
    _evict_if_large(_pitcher_recent_cache, 500)
    try:
        yr = datetime.now().year
        r  = requests.get(
            f"{MLB_API}/people/{pitcher_id}/stats",
            params={"stats": "gameLog", "group": "pitching", "season": yr},
            timeout=8,
        )
        r.raise_for_status()
        _stats_list = r.json().get("stats") or []
        all_splits = _stats_list[0].get("splits", []) if _stats_list else []  # FIX: guard empty stats list
        # Only real starts (IP >= 3.0)
        starts = [
            sp for sp in all_splits
            if _safe_f(sp.get("stat", {}).get("inningsPitched", "0"), 0) >= 3.0
        ][-n_starts:]
        if not starts:
            _pitcher_recent_cache[cache_key] = {}
            return {}
        total_ip = total_er = total_k = total_bb = total_h = 0.0
        for sp in starts:
            st  = sp.get("stat", {})
            ip_s = str(st.get("inningsPitched", "0.0"))
            try:
                whole, thirds = ip_s.split(".")
                ip = int(whole) + int(thirds) / 3
            except Exception:
                ip = _safe_f(ip_s, 0)
            total_ip   += ip
            total_er   += _safe_f(st.get("earnedRuns"),   0)
            total_k    += _safe_f(st.get("strikeOuts"),   0)
            total_bb   += _safe_f(st.get("baseOnBalls"),  0)
            total_h    += _safe_f(st.get("hits"),         0)

        if total_ip < 1:
            _pitcher_recent_cache[cache_key] = {}
            return {}

        era_recent  = round((total_er  / total_ip) * 9, 2)
        k9_recent   = round((total_k   / total_ip) * 9, 2)
        bb9_recent  = round((total_bb  / total_ip) * 9, 2)
        whip_recent = round((total_h + total_bb) / total_ip, 3)

        out = {
            "era_recent":   _clamp(era_recent,  1.5, 12.0),
            "k9_recent":    _clamp(k9_recent,   2.0, 16.0),
            "bb9_recent":   _clamp(bb9_recent,  0.5,  9.0),
            "whip_recent":  _clamp(whip_recent, 0.6,  2.4),
            "n_starts":     len(starts),
            "total_ip":     round(total_ip, 1),
            "total_er":     int(total_er),
            "total_k":      int(total_k),
        }
        _pitcher_recent_cache[cache_key] = out
        return out
    except Exception as ex:
        print(f"[pitcher_recent_form] pid={pitcher_id}: {ex}")
        _pitcher_recent_cache[cache_key] = {}
        return {}


# ── Pitcher projection tuning constants ───────────────────────────────────────
# Expected PA by lineup slot over a full game (leadoff sees the most). Used to
# weight opponent-quality so the top of the order — which a starter faces ~3
# times — counts more than the 8-9 hitters when grading "lineup weakness".
_LINEUP_PA_WEIGHTS = [4.65, 4.55, 4.45, 4.36, 4.27, 4.17, 4.08, 3.99, 3.89]
# K% nudge for same-/opposite-handed matchups (pitcher platoon advantage). A
# same-handed hitter strikes out modestly more vs this pitcher; opposite less.
_K_PLATOON_MULT = 0.05
# League-average usage-weighted arsenal whiff% and the slope mapping a pitcher's
# deviation from it onto a K multiplier (≈ +8pp whiff → +6% projected Ks).
_LG_ARSENAL_WHIFF = 24.5
_ARSENAL_WHIFF_SLOPE = 0.0075


def _arsenal_whiff_summary(pitcher_id):
    """Usage-weighted whiff% / put-away% across a pitcher's arsenal.

    Reads the in-memory Savant pitch-arsenal cache (no external calls). Returns
    {'whiff', 'putaway', 'pitches'} or None when no arsenal is cached.
    """
    if not pitcher_id:
        return None
    with _sv_lock:
        ars = dict(_sv_pit_arsenal_stats.get(str(pitcher_id), {}))
    if not ars:
        return None
    w_whiff = w_putaway = use_sum = 0.0
    n = 0
    for st in ars.values():
        u = _safe_f(st.get("usage"), 0.0)
        wf = st.get("whiff_pct")
        if u <= 0 or wf is None:
            continue
        w_whiff   += _safe_f(wf, 0.0) * u
        w_putaway += _safe_f(st.get("k_pct"), 0.0) * u
        use_sum   += u
        n += 1
    if use_sum <= 0 or n == 0:
        return None
    return {
        "whiff":   round(w_whiff / use_sum, 2),
        "putaway": round(w_putaway / use_sum, 2),
        "pitches": n,
    }


# ── Pitcher projection engine (v2 — recent form weighted) ────────────────────
def _project_pitcher(pitcher_name, pitcher_id, pitcher_fg, pitcher_sv, pitcher_stats,
                     opp_batters, park_factor, weather, blend_weights=None,
                     game_pk=None, catcher_name=None, catcher_id=None,
                     pitcher_hand='R'):
    fg   = pitcher_fg
    sv   = pitcher_sv

    # ── Season stats ──────────────────────────────────────────────────────────
    k9_season   = _safe_f(fg.get("fg_k9"),   8.5)
    bb9_season  = _safe_f(fg.get("fg_bb9"),  3.0)
    era_season  = _safe_f(fg.get("fg_era") or pitcher_stats.get("era"), 4.20)
    whip_season = _safe_f(fg.get("fg_whip") or pitcher_stats.get("whip"), 1.28)
    kpct        = _safe_f(fg.get("fg_kpct") or sv.get("sv_k_pct"), 0.22)

    # ── Recent form (last 3-5 starts) — weight from blend_weights or default 0.40
    recent = _pitcher_recent_form(pitcher_id, n_starts=5)
    if recent:
        W_RECENT = float((blend_weights or {}).get('pitcher_w_recent', 0.40))
        W_SEASON = round(1.0 - W_RECENT, 4)
        era  = W_SEASON * era_season  + W_RECENT * recent["era_recent"]
        k9   = W_SEASON * k9_season   + W_RECENT * recent["k9_recent"]
        bb9  = W_SEASON * bb9_season  + W_RECENT * recent["bb9_recent"]
        whip = W_SEASON * whip_season + W_RECENT * recent["whip_recent"]
    else:
        era  = era_season
        k9   = k9_season
        bb9  = bb9_season
        whip = whip_season

    # ── Form trend flag (for UI) ──────────────────────────────────────────────
    # "struggling" = recent ERA 1.5+ runs worse than season
    # "dealing"    = recent ERA 1.5+ runs better than season
    form_flag = "neutral"
    if recent:
        delta = recent["era_recent"] - era_season
        if delta >= 1.5:
            form_flag = "struggling"
        elif delta <= -1.5:
            form_flag = "dealing"

    # ── Expected IP (quality-start model) ─────────────────────────────────────
    base_ip = 5.3
    ip_adj  = 1.0 + (4.20 - era) * 0.10
    exp_ip  = round(min(8.0, max(3.5, base_ip + ip_adj)), 1)

    # ── Opponent quality adjustment (platoon-aware, lineup-position weighted) ──
    # Each opposing hitter is graded vs THIS pitcher's handedness (platoon split
    # via Bayesian shrinkage in platoon_blend_v2), then aggregated with
    # lineup-slot PA weights so the top of the order counts more. This is what
    # turns a flat 9-man average into a real "lineup weakness vs handedness" read.
    phand = (pitcher_hand or 'R').upper()
    if phand not in ('L', 'R'):
        phand = 'R'
    opp_woba_acc = opp_kpct_acc = w_acc = 0.0
    for idx, b in enumerate(opp_batters[:9]):
        nm   = b.get("name", "")
        b_fg = fg_batter(nm)
        b_sv = sv_batter(nm)
        bats = (b.get("bats") or b_fg.get("fg_bats") or "R").upper()
        # Dict shaped for platoon_blend_v2 (handed splits, then season fallbacks).
        pb = {
            "bats":      bats,
            "fg_woba":   b_fg.get("fg_woba"),
            "sv_xwoba":  b_sv.get("sv_xwoba"),
            "vs_l_woba": b.get("vs_l_woba"), "vs_l_pa": b.get("vs_l_pa"),
            "vs_r_woba": b.get("vs_r_woba"), "vs_r_pa": b.get("vs_r_pa"),
        }
        woba_vs = platoon_blend_v2(pb, phand, 'woba')
        kpct_b  = _safe_f(b_fg.get("fg_kpct") or b_sv.get("sv_k_pct"), 0.22)
        # Same-handed matchup favors the pitcher (more whiffs); opposite fewer.
        if bats in ('L', 'R'):
            kpct_b *= (1.0 + _K_PLATOON_MULT) if bats == phand else (1.0 - _K_PLATOON_MULT)
        w = _LINEUP_PA_WEIGHTS[idx] if idx < len(_LINEUP_PA_WEIGHTS) else 3.9
        opp_woba_acc += woba_vs * w
        opp_kpct_acc += kpct_b  * w
        w_acc        += w

    avg_opp_woba = (opp_woba_acc / w_acc) if w_acc else 0.320
    avg_opp_kpct = (opp_kpct_acc / w_acc) if w_acc else 0.22
    opp_quality  = _clamp(avg_opp_woba / 0.320, 0.85, 1.15)
    k_opp_adj    = 1.0 + (avg_opp_kpct - 0.22) * 0.4

    k_proj  = round(max(0.5, (k9 / 9) * exp_ip * k_opp_adj / opp_quality), 2)
    bb_proj = round(max(0.1, (bb9 / 9) * exp_ip * opp_quality), 2)

    # ── Stuff+ / Location+ / Pitching+ K shade ────────────────────────────────
    # Tightens K projection when public pitch-quality grades disagree with
    # season FIP/xERA (the early-season leading indicator).
    stuff = fg_stuff(name=pitcher_name, player_id=pitcher_id) if _STUFF_AVAILABLE else None
    stuff_mult = 1.0
    if stuff:
        stuff_mult = fg_stuff_k_mult(stuff.get("pitching_plus", 100.0))
        if stuff_mult != 1.0:
            k_proj = round(k_proj * stuff_mult, 2)

    # ── Pitch-mix / arsenal swing-and-miss shade ──────────────────────────────
    # Usage-weighted whiff% across the pitcher's arsenal is an outcome-based
    # leading indicator of strikeout upside that season K/9 alone can lag (a
    # nasty slider-heavy mix vs a whiff-prone lineup). Centered at the league
    # average and tightly clamped so pitch mix refines rather than dominates.
    ars_summary = _arsenal_whiff_summary(pitcher_id)
    arsenal_k_mult = 1.0
    if ars_summary and ars_summary.get("whiff") is not None:
        arsenal_k_mult = _clamp(
            1.0 + (ars_summary["whiff"] - _LG_ARSENAL_WHIFF) * _ARSENAL_WHIFF_SLOPE,
            0.94, 1.07,
        )
        if arsenal_k_mult != 1.0:
            k_proj = round(k_proj * arsenal_k_mult, 2)

    # ── Catcher framing × HP umpire K shade ───────────────────────────────────
    # Combined multiplier captures the (framer × strike-zone bias) interaction.
    fu_mult, fu_meta = (1.0, None)
    if game_pk is not None:
        try:
            fu_mult, fu_meta = _framing_ump_k_mult(game_pk, catcher_name=catcher_name, catcher_id=catcher_id)
            if fu_mult != 1.0:
                k_proj = round(k_proj * fu_mult, 2)
        except Exception:
            fu_mult, fu_meta = 1.0, None

    if not weather.get("dome", False):
        temp_f = _safe_f(weather.get("temp"), 72)
        if temp_f > 88:
            k_proj = round(k_proj * 0.97, 2)

    return {
        "k":          k_proj,
        "bb":         bb_proj,
        "expected_ip": exp_ip,
        # Form metadata exposed to frontend
        "era_season":  round(era_season, 2),
        "era_recent":  round(recent.get("era_recent", era_season), 2) if recent else None,
        "era_blended": round(era, 2),
        "k9_recent":   round(recent.get("k9_recent",  k9_season),  2) if recent else None,
        "form_flag":   form_flag,
        "recent_starts": recent.get("n_starts", 0),
        "recent_ip":   recent.get("total_ip"),
        "recent_er":   recent.get("total_er"),
        "recent_k":    recent.get("total_k"),
        # Best Bets signal upgrades — exposed for UI surfacing
        "stuff_plus":     round(float(stuff["stuff_plus"]),    1) if stuff else None,
        "location_plus":  round(float(stuff["location_plus"]), 1) if stuff else None,
        "pitching_plus":  round(float(stuff["pitching_plus"]), 1) if stuff else None,
        "stuff_k_mult":   stuff_mult,
        "framing_ump":    fu_meta,
        "framing_ump_k_mult": fu_mult,
        # Pitch-mix (arsenal) swing-and-miss shade
        "arsenal_k_mult":  arsenal_k_mult,
        "arsenal_whiff":   ars_summary.get("whiff")   if ars_summary else None,
        "arsenal_putaway": ars_summary.get("putaway") if ars_summary else None,
        "arsenal_pitches": ars_summary.get("pitches") if ars_summary else None,
        # Platoon-aware, lineup-position-weighted opponent read
        "pitcher_hand":     phand,
        "opp_woba_platoon": round(avg_opp_woba, 3),
        "opp_kpct_platoon": round(avg_opp_kpct, 3),
        "opp_quality":      round(opp_quality, 3),
        "lineup_weighted":  True,
    }


def _safe_f(val, default=0.0):
    try:
        v = float(val)
        return v if v == v else default   # NaN guard
    except (TypeError, ValueError):
        return default


# ── Matchup scoring engine (v2 — platoon-aware) ───────────────────────────────
def _matchup_score(batter, pitcher_fg, pitcher_sv, pitcher_hand='R'):
    """
    Returns a 0–100 matchup score broken into 4 sub-scores.
    Uses platoon-blended contact/power metrics when split data is available.
    """
    name = batter.get("name", "")
    fg   = fg_batter(name)
    sv   = sv_batter(name)

    # ── Contact (25 pts): platoon-blended avg + xBA ───────────────────────────
    avg  = platoon_blend_v2(batter, pitcher_hand, 'avg')
    xba  = _safe_f(sv.get("sv_xba"), avg)
    con  = round(min(25, max(0, ((avg + xba) / 2 - 0.180) / (0.340 - 0.180) * 25)), 1)

    # ── Power (25 pts): platoon-blended slg + xSLG + iso + barrel% ───────────
    slg  = platoon_blend_v2(batter, pitcher_hand, 'slg')
    xslg = _safe_f(sv.get("sv_xslg"), slg)
    iso  = _safe_f(fg.get("fg_iso"), 0.145)
    brl  = _safe_f(sv.get("sv_brl_pct"), 6.0) / 100
    pwr  = round(min(25, max(0,
        ((slg + xslg) / 2 - 0.290) / (0.600 - 0.290) * 22 + brl * 15 + iso * 10
    )), 1)

    # ── OBP (25 pts): platoon-blended obp + BB% ───────────────────────────────
    obp   = platoon_blend_v2(batter, pitcher_hand, 'obp')
    bbpct = _safe_f(fg.get("fg_bbpct"), 0.08)
    obp_s = round(min(25, max(0, (obp - 0.270) / (0.420 - 0.270) * 22 + bbpct * 10)), 1)

    # ── Statcast (25 pts): EV / HH% / xwOBA — pitcher penalty ────────────────
    ev   = _safe_f(sv.get("sv_ev"), 87.0)
    hh   = _safe_f(sv.get("sv_hh_pct") or sv.get("sv_hhpct"), 33.0) / 100
    xwob = _safe_f(sv.get("sv_xwoba") or fg.get("fg_woba"), 0.310)
    opp_kpct = _safe_f(pitcher_fg.get("fg_kpct"), 0.22)
    opp_xera = _safe_f(pitcher_sv.get("sv_xera"), 4.20)
    pit_pen  = max(0.0, (0.22 - opp_kpct) * 10 + (opp_xera - 4.20) * 1.5)
    stc  = round(min(25, max(0,
        (ev - 82) / (98 - 82) * 8 +
        hh * 12 +
        (xwob - 0.270) / (0.420 - 0.270) * 8 +
        pit_pen
    )), 1)

    # ── Platoon bonus / penalty (up to ±4 pts) ────────────────────────────────
    bat  = (batter.get('bats') or 'S').upper()
    pit  = (pitcher_hand or 'R').upper()
    if bat != 'S':
        platoon_bonus = 3.0 if ((bat == 'L' and pit == 'R') or (bat == 'R' and pit == 'L')) else -3.0
    else:
        platoon_bonus = 1.5  # switch hitter slight edge

    total = round(min(100, max(0, con + pwr + obp_s + stc + platoon_bonus)), 1)
    tier  = "A" if total >= 70 else "B" if total >= 55 else "C" if total >= 40 else "D"

    return {
        "score":        total,
        "tier":         tier,
        "contact":      con,
        "power":        round(pwr, 1),
        "obp":          obp_s,
        "statcast":     stc,
        "platoon_bonus": platoon_bonus,
        "platoon_note": _batter_hand_note(batter, pitcher_hand),
    }


# ── Route: Prop projections ───────────────────────────────────────────────────
@app.route('/api/props/projections/<int:game_pk>')
def api_props_projections(game_pk):
    t0 = time.perf_counter()
    try:
        # Keep endpoint responsive during cold starts; refresh in background.
        _maybe_refresh_fg()
        _maybe_refresh_savant()
        _fetch_injury_status(force=False)

        date_hint = request.args.get('date')
        gdata, away_bats, home_bats, away_t, home_t, pitchers = _props_fetch_game(game_pk, date_hint=date_hint)
        if not gdata:
            return jsonify({"success": False, "error": "Game not found"}), 404

        away_abbr = away_t.get("team", {}).get("abbreviation", "AWAY")
        home_abbr = home_t.get("team", {}).get("abbreviation", "HOME")
        home_id   = home_t.get("team", {}).get("id")
        # Ballpark Pal microclimate factor when available; falls back to static.
        # Resolve both handedness splits so each batter's HR park factor reflects
        # the park's platoon skew (e.g. LHB short-porch boost at Yankee Stadium).
        pf        = _resolve_park_factor(home_abbr, home_id, hand="R", stat="HR")
        pf_lhb    = _resolve_park_factor(home_abbr, home_id, hand="L", stat="HR")
        pf_rhb    = pf
        pf_source = "bpp" if (_BPP_AVAILABLE and bp_park_factor(home_abbr, hand="R", stat="HR") is not None) else "static"

        away_full = away_t.get("team", {}).get("name", away_abbr)
        home_full = home_t.get("team", {}).get("name", home_abbr)

        event, _ = _find_odds_event(away_full, home_full)
        featured  = _load_event_odds(event.get("id") if event else None, featured_only=True) if event else []
        game_lines = {
            "awayFull":  away_full,
            "homeFull":  home_full,
            "moneyline": _best_moneyline(featured, away_full, home_full),
            "total":     _best_total(featured),
            "spread":    _best_spread(featured, away_full, home_full),
        }

        ap_info = pitchers["ap"]; hp_info = pitchers["hp"]
        ap_name = ap_info.get("fullName", "TBD")
        hp_name = hp_info.get("fullName", "TBD")
        ap_id   = ap_info.get("id");  hp_id  = hp_info.get("id")

        ap_fg = fg_pitcher(ap_name); hp_fg = fg_pitcher(hp_name)
        ap_sv = sv_pitcher(ap_name); hp_sv = sv_pitcher(hp_name)
        ap_st = pitcher_stats_mlb(ap_id) if ap_id else {}
        hp_st = pitcher_stats_mlb(hp_id) if hp_id else {}

        # ── Pitcher hands — the key new inputs ────────────────────────────────
        ap_hand = (ap_st.get("pitchHand") or "R").upper()
        hp_hand = (hp_st.get("pitchHand") or "R").upper()

        # Build league-wide Statcast distributions for percentile ranks.
        with _sv_lock:
            statcast_cache = dict(_sv_bat_statcast)
        ev_values = []
        hh_values = []
        brl_values = []
        pull_values = []
        for row in statcast_cache.values():
            try:
                ev_values.append(float(row.get('sv_ev')))
            except Exception:
                pass
            try:
                hh_values.append(float(row.get('sv_hh_pct')))
            except Exception:
                pass
            try:
                brl_values.append(float(row.get('sv_brl_pct')))
            except Exception:
                pass
            try:
                pull_values.append(float(row.get('pull_pct_air')))
            except Exception:
                pass

        # Weather
        ven   = gdata.get("venue", {})
        vid   = ven.get("id")
        vloc  = (ven.get("location") or {})
        coord = vloc.get("defaultCoordinates") or {}
        lat   = coord.get("latitude")
        lon   = coord.get("longitude")
        try:
            dt_utc = datetime.fromisoformat(gdata.get("gameDate", "").replace("Z", "+00:00"))
            ghour  = dt_utc.astimezone(ET).hour
        except Exception:
            ghour  = 13
        wx = get_weather(lat, lon, ghour, venue_id=vid)

        # ── Travel / rest features (per team) ─────────────────────────────────
        # Compute once per team so the shade is shared across all 9 batters.
        today_iso = gdata.get("gameDate") or ""
        try:
            today_dt = datetime.fromisoformat(today_iso.replace("Z", "+00:00")) if today_iso else None
            today_is_day = today_dt.astimezone(ET).hour < 17 if today_dt else False
        except Exception:
            today_dt, today_is_day = None, False
        today_venue = {"lat": lat, "lon": lon}
        away_team_id = (away_t.get("team") or {}).get("id")
        home_team_id = (home_t.get("team") or {}).get("id")

        def _team_travel(team_id, is_home_today):
            prev = _team_previous_venue(team_id, today_iso) if (_TRAVEL_AVAILABLE and team_id) else None
            if not prev:
                return {"mult": 1.0, "note": "", "km_traveled_24h": 0.0, "tz_shift": 0}
            try:
                y_dt = datetime.fromisoformat((prev.get("game_date") or "").replace("Z", "+00:00"))
            except Exception:
                y_dt = None
            return _compute_travel_features(
                today_venue=today_venue,
                yesterday_venue={"lat": prev["lat"], "lon": prev["lon"]},
                today_dt=today_dt, yesterday_dt=y_dt,
                yesterday_was_home=prev.get("was_home"), today_is_home=is_home_today,
                yesterday_was_night=prev.get("was_night"), today_is_day=today_is_day,
            )

        away_travel = _team_travel(away_team_id, is_home_today=False)
        home_travel = _team_travel(home_team_id, is_home_today=True)

        # ── Build batter projections (now passes pitcher_hand) ─────────────────
        away_confirmed = len(away_bats) >= 9 and all((b.get("lineup_status") or "confirmed") == "confirmed" for b in away_bats[:9])
        home_confirmed = len(home_bats) >= 9 and all((b.get("lineup_status") or "confirmed") == "confirmed" for b in home_bats[:9])

        def enrich_batters(batters, opp_pfg, opp_psv, opp_pst, opp_abbr, opp_pname, opp_pid, own_abbr='', lineup_confirmed=False, team_travel=None):
            opp_hand = (opp_pst.get("pitchHand") or "R").upper()
            batters_top = list((batters or [])[:9])
            # Opposing team's defense factor is constant for this side — resolve once.
            _side_def_factor = _def_factor_for_pitcher(opp_pid)

            def _enrich_one(b):
                name = b.get("name", "")
                bfg  = fg_batter(name)
                bsv  = sv_batter(name)
                brl  = bsv.get("sv_brl_pct")
                hh   = bsv.get("sv_hh_pct")
                ev   = bsv.get("sv_ev")
                pull = bsv.get("pull_pct_air")
                bid  = b.get("id")
                # Per-pitch outcome stats (keyed by full pitch name, e.g. "4-Seam Fastball").
                # Used by the PITCH MIX tab to render "BEST BATTER MATCHUPS VS PITCH".
                try:
                    with _sv_lock:
                        bat_arsenal_map = dict(_sv_bat_arsenal_stats.get(str(bid), {})) if bid else {}
                except Exception:
                    bat_arsenal_map = {}
                form = _fetch_rolling_form(bid, False) if bid else None
                bvp  = _fetch_bvp(bid, opp_pid)      if (bid and opp_pid) else None
                pitch_adv = _pitch_type_advantage(bid, opp_pid, batter_name=name, pitcher_name=opp_pname) if (bid and opp_pid) else {"status": "neutral", "note": "Neutral matchup"}
                bvp_grade = _compute_bvp_grade(bvp) if bvp else 'D'
                injury = _get_player_injury(bid) if bid else None
                # Handedness-aware HR park factor: a switch hitter bats opposite
                # the starter's throwing hand. Only the HR component meaningfully
                # depends on this; the split is neutral at parks without a skew.
                bhand = (bfg.get("fg_bats") or b.get("bats") or "R").upper()
                if bhand == "S":
                    bhand = "L" if opp_hand == "R" else "R"
                bpf = pf_lhb if bhand == "L" else pf_rhb
                proj = _project_batter_batx(
                    b, opp_pname, opp_pfg, opp_psv, bpf, wx,
                    pitcher_hand=opp_hand,
                    opp_pitcher_id=opp_pid,
                    form=form, bvp=bvp,
                    travel=team_travel,
                    def_factor=_side_def_factor,
                )
                slot = int(b.get("slot") or 9)
                xgb_hit_p = None
                if _XGB_AVAILABLE and xgb_ready('hits'):
                    xgb_hit_p = xgb_hit_prob(
                        {"name": name},
                        {"name": opp_pname, "pitchHand": opp_hand},
                    )
                wx_adj = _safe_f((proj.get("adjustments") or {}).get("weather"), 0.0)
                wind_bucket = "out" if wx_adj > 0.01 else ("in" if wx_adj < -0.01 else "calm")
                park_bucket = "hitter" if pf >= 1.04 else ("pitcher" if pf <= 0.96 else "neutral")
                slot_bucket = "1-3" if slot <= 3 else ("4-6" if slot <= 6 else "7-9")
                return {
                    "name":         name,
                    "team":         own_abbr or b.get("team", ""),
                    "pos":          b.get("pos", ""),
                    "slot":         slot,
                    "id":           b.get("id"),
                    "bats":         b.get("bats", ""),
                    "opp_pitcher":  opp_pname,
                    "opp_hand":     opp_hand,
                    "opp_era":      opp_pfg.get("fg_era") or opp_psv.get("sv_era_p"),
                    "opp_k9":       opp_pfg.get("fg_k9"),
                    "avg":          b.get("avg") or bfg.get("fg_avg"),
                    "obp":          b.get("obp") or bfg.get("fg_obp"),
                    "slg":          b.get("slg") or bfg.get("fg_slg"),
                    "fg_woba":      bfg.get("fg_woba"),
                    "sv_xwoba":     bsv.get("sv_xwoba"),
                    "bvpGrade":     bvp_grade,
                    "bvpTooltip":   (bvp or {}).get("tooltip") if isinstance(bvp, dict) else "",
                    "bvpPA":        (bvp or {}).get("pa") if isinstance(bvp, dict) else 0,
                    "bvpOPS":       (bvp or {}).get("ops") if isinstance(bvp, dict) else None,
                    "pitchTypeAdvantage": (pitch_adv or {}).get("status", "neutral"),
                    "pitchTypeAdvantageNote": (pitch_adv or {}).get("note", "Neutral matchup"),
                    "pitchTypePrimary": (pitch_adv or {}).get("primary_pitch"),
                    "pitchTypePrimaryLabel": (pitch_adv or {}).get("primary_pitch_label"),
                    "pitchTypeUsagePct": (pitch_adv or {}).get("usage_pct"),
                    "sv_ev":        ev,
                    "sv_hh_pct":    hh,
                    "sv_brl_pct":   brl,
                    "pull_pct_air": pull,
                    "sv_ev_pct_rank": _pct_rank(ev_values, ev),
                    "sv_hh_pct_rank": _pct_rank(hh_values, hh),
                    "sv_brl_pct_rank": _pct_rank(brl_values, brl),
                    "pull_pct_air_rank": _pct_rank(pull_values, pull),
                    "lineupConfirmed": bool(lineup_confirmed),
                    "lineupStatus": "confirmed" if lineup_confirmed else "pending",
                    "injuryStatus": (injury or {}).get("status"),
                    "injuryType": (injury or {}).get("type"),
                    "injuryDescription": (injury or {}).get("description"),
                    "filterTags": {
                        "vsHand": opp_hand,
                        "homeAway": "home" if (own_abbr == home_abbr) else "away",
                        "windBucket": wind_bucket,
                        "parkBucket": park_bucket,
                        "slotBucket": slot_bucket,
                        "lineup": "confirmed" if lineup_confirmed else "pending",
                    },
                    # Expose platoon splits for UI
                    "vs_l_avg":     b.get("vs_l_avg"),
                    "vs_r_avg":     b.get("vs_r_avg"),
                    "vs_l_ops":     b.get("vs_l_ops"),
                    "vs_r_ops":     b.get("vs_r_ops"),
                    "xgbHitProb":   round(xgb_hit_p, 4) if xgb_hit_p is not None else None,
                    "arsenal":      bat_arsenal_map,
                    "proj":         proj,
                }

            workers = min(9, max(1, len(batters_top)))
            with ThreadPoolExecutor(max_workers=workers) as ex:
                return list(ex.map(_enrich_one, batters_top))

        away_proj = enrich_batters(away_bats, hp_fg, hp_sv, hp_st, home_abbr, hp_name, hp_id, own_abbr=away_abbr, lineup_confirmed=away_confirmed, team_travel=away_travel)
        home_proj = enrich_batters(home_bats, ap_fg, ap_sv, ap_st, away_abbr, ap_name, ap_id, own_abbr=home_abbr, lineup_confirmed=home_confirmed, team_travel=home_travel)
        all_batters = away_proj + home_proj

        injury_summary_rows = []
        for bb in all_batters:
            st = (bb.get("injuryStatus") or "").upper()
            if not st:
                continue
            injury_summary_rows.append({
                "name": bb.get("name"),
                "team": bb.get("team"),
                "status": st,
                "description": bb.get("injuryDescription") or bb.get("injuryType") or st,
            })

        # ── Pitcher projections ────────────────────────────────────────────────
        pitchers_out = []
        for pid, pname, pfg, psv, pst, opp_bats, own_bats, pabbr, phand in [
            (ap_id, ap_name, ap_fg, ap_sv, ap_st, home_bats, away_bats, away_abbr, ap_hand),
            (hp_id, hp_name, hp_fg, hp_sv, hp_st, away_bats, home_bats, home_abbr, hp_hand),
        ]:
            if pname == "TBD":
                continue
            pinj = _get_player_injury(pid) if pid else None
            # The catcher receiving this pitcher's pitches is on his own team.
            cname, cid = _find_lineup_catcher(own_bats)
            proj = _project_pitcher(pname, pid, pfg, psv, pst, opp_bats, pf, wx,
                                    blend_weights=_get_adjustments().get('blend_weights'),
                                    game_pk=game_pk, catcher_name=cname, catcher_id=cid,
                                    pitcher_hand=phand)
            pitchers_out.append({
                "name":        pname,
                "team":        pabbr,
                "id":          pid,
                "role":        "SP",
                "pitchHand":   phand,
                "era":         pfg.get("fg_era") or psv.get("sv_era_p"),
                "whip":        pfg.get("fg_whip"),
                "fip":         pfg.get("fg_fip"),
                "xera":        psv.get("sv_xera"),
                "kpct":        pfg.get("fg_kpct") or psv.get("sv_k_pct"),
                "bbpct":       pfg.get("fg_bbpct") or psv.get("sv_bb_pct"),
                "whiffPct":    psv.get("sv_whiff"),
                "xwoba":       psv.get("sv_xwoba"),
                "arsenalPct":  psv.get("sv_arsenal_pct", {}),
                "arsenalVelo": psv.get("sv_arsenal_velo", {}),
                "pitchArsenal": _get_pitch_arsenal(pitcher_id=pid, pitcher_name=pname),
                "opp_k_pct":   sum(_safe_f(fg_batter(b.get("name","")).get("fg_kpct"), 0.22)
                                    for b in opp_bats[:9]) / max(len(opp_bats[:9]), 1),
                "opp_woba":    sum(_safe_f(fg_batter(b.get("name","")).get("fg_woba") or
                                           sv_batter(b.get("name","")).get("sv_xwoba"), 0.310)
                                    for b in opp_bats[:9]) / max(len(opp_bats[:9]), 1),
                "injuryStatus": (pinj or {}).get("status"),
                "injuryDescription": (pinj or {}).get("description"),
                "xgbKProbs": {
                    str(ln): xgb_k_prob(
                        {"fgera": pfg.get("fg_era"), "fgkpct": pfg.get("fg_kpct"),
                         "fgbbpct": pfg.get("fg_bbpct"), "svwhiffpct": psv.get("sv_whiff"),
                         "name": pname,
                         "arsenalWhiff": proj.get("arsenal_whiff"),
                         "arsenalPutaway": proj.get("arsenal_putaway")},
                        line=ln
                    ) if _XGB_AVAILABLE and xgb_ready('k') else None
                    for ln in [3.5, 4.5, 5.5]
                } if _XGB_AVAILABLE else {},
                "proj":        proj,
            })

        for pp in pitchers_out:
            st = (pp.get("injuryStatus") or "").upper()
            if not st:
                continue
            injury_summary_rows.append({
                "name": pp.get("name"),
                "team": pp.get("team"),
                "status": st,
                "description": pp.get("injuryDescription") or st,
            })


        # ── Attach real Odds API prop lines/prices to each pitcher and batter ──
        # Each entry is a real sportsbook line with the best over/under price &
        # book across all books, so the props board can render a "take" with the
        # actual market line (never a fabricated/default line).
        market_props = []
        if event:
            props_books = _load_event_odds(event.get('id'), featured_only=False) or []
            valid_names = set([x.get('name') for x in away_bats + home_bats if x.get('name')])
            ap = pitchers.get('ap', {}) if isinstance(pitchers, dict) else {}
            hp = pitchers.get('hp', {}) if isinstance(pitchers, dict) else {}
            if ap.get('fullName'): valid_names.add(ap.get('fullName'))
            if hp.get('fullName'): valid_names.add(hp.get('fullName'))
            market_props = _parse_prop_markets(props_books, valid_names)

        def _odds_markets_for(player_name, mk_list):
            out = []
            if not (market_props and player_name):
                return out
            for mk in mk_list:
                for ln in (_market_lines_for_player(market_props, player_name, mk) or []):
                    msum = _market_price_summary(market_props, player_name, mk, ln)
                    out.append({
                        'marketKey':     mk,
                        'line':          ln,
                        'overPrice':     msum.get('best_over_price'),
                        'overBook':      msum.get('best_over_book'),
                        'underPrice':    msum.get('best_under_price'),
                        'underBook':     msum.get('best_under_book'),
                        'marketImplied': msum.get('market_implied'),
                        'bookCount':     msum.get('book_count'),
                    })
            return out

        for b in all_batters:
            b['oddsMarkets'] = _odds_markets_for(
                b.get('name'),
                ['batter_hits', 'batter_total_bases', 'batter_home_runs', 'batter_rbis'])

        for p in pitchers_out:
            p['oddsMarkets'] = _odds_markets_for(
                p.get('name'),
                ['pitcher_strikeouts', 'pitcher_outs_recorded', 'pitcher_earned_runs'])

        return jsonify({
            "success":     True,
            "gamePk":      game_pk,
            "matchup":     f"{away_abbr} @ {home_abbr}",
            "awayAbbr":    away_abbr,
            "homeAbbr":    home_abbr,
            "awayFull":    away_full,
            "homeFull":    home_full,
            "batters":     all_batters,
            "pitchers":    pitchers_out,
            "weather":     wx,
            "park_factor": pf,
            "park_factor_source": pf_source,
            "travel": {
                "away": {**away_travel, "team": away_abbr},
                "home": {**home_travel, "team": home_abbr},
            },
            "lineup": {
                "awayConfirmed": away_confirmed,
                "homeConfirmed": home_confirmed,
                "overallConfirmed": bool(away_confirmed and home_confirmed),
            },
            "injury_summary": {
                "count": len(injury_summary_rows),
                "players": injury_summary_rows[:10],
            },
            "game_lines":  game_lines,
            "timestamp":   datetime.now(timezone.utc).isoformat(),
        })

    except Exception as ex:
        print(f"[api_props_projections] {traceback.format_exc()}")
        return jsonify({"success": False, "error": str(ex)}), 500
    finally:
        ms = int((time.perf_counter() - t0) * 1000)
        if ms >= 1000:
            print(f"[perf] /api/props/projections/{game_pk} {ms}ms")


@app.route('/api/props/scan/today')
def api_props_scan_today():
    date_str = request.args.get('date') or datetime.now(ET).strftime('%Y-%m-%d')
    refresh = str(request.args.get('refresh') or '').strip().lower() in ('1', 'true', 'yes')
    try:
        return jsonify(_props_scan_today_payload(date_str, refresh=refresh))
    except Exception as ex:
        print(f"[api_props_scan_today] {traceback.format_exc()}")
        return jsonify({'success': False, 'error': str(ex)}), 500


@app.route('/api/props/line-shopping/<int:game_pk>')
def api_props_line_shopping(game_pk):
    """Return line-shopping view grouped by player/market with all sportsbook lines."""
    try:
        _maybe_refresh_fg()
        _maybe_refresh_savant()

        gdata, away_bats, home_bats, away_t, home_t, pitchers = _props_fetch_game(game_pk, date_hint=request.args.get('date'))
        if not gdata:
            return jsonify({"success": False, "error": "Game not found"}), 404

        away_team_name = (away_t.get('team', {}) or {}).get('name', '')
        home_team_name = (home_t.get('team', {}) or {}).get('name', '')

        event, _ = _find_odds_event(away_team_name, home_team_name)
        if not event:
            return jsonify({
                "success": True,
                "gamePk": game_pk,
                "eventId": None,
                "groups": [],
                "players": {},
                "count": 0,
            })

        props_books = _load_event_odds(event.get('id'), featured_only=False) or []

        valid_names = set([x.get('name') for x in (away_bats + home_bats) if x.get('name')])
        ap = (pitchers or {}).get('ap', {}) or {}
        hp = (pitchers or {}).get('hp', {}) or {}
        if ap.get('fullName'):
            valid_names.add(ap.get('fullName'))
        if hp.get('fullName'):
            valid_names.add(hp.get('fullName'))

        market_props = _parse_prop_markets(props_books, valid_names)
        grouped = _group_line_shopping(market_props)

        return jsonify({
            "success": True,
            "gamePk": game_pk,
            "eventId": event.get('id'),
            "groups": grouped.get('groups', []),
            "players": grouped.get('by_player', {}),
            "count": len(grouped.get('groups', [])),
            "timestamp": datetime.now(timezone.utc).isoformat(),
        })
    except Exception as ex:
        print(f"[api_props_line_shopping] {traceback.format_exc()}")
        return jsonify({"success": False, "error": str(ex)}), 500


@app.route('/api/batting-order-matchups/<int:game_pk>')
def api_batting_order_matchups(game_pk):
    """Batting-order matchup rows for deep-dive tab, including pitch-type edge."""
    _maybe_refresh_fg()
    _maybe_refresh_savant()
    try:
        gdata, away_bats, home_bats, away_t, home_t, pitchers = _props_fetch_game(game_pk)
        if not gdata:
            return jsonify({"success": False, "error": "Game not found"}), 404

        ap_info = pitchers.get("ap", {})
        hp_info = pitchers.get("hp", {})
        ap_name = ap_info.get("fullName", "TBD")
        hp_name = hp_info.get("fullName", "TBD")
        ap_hand = (ap_info.get("pitchHand") or "R").upper()
        hp_hand = (hp_info.get("pitchHand") or "R").upper()
        ap_id = ap_info.get("id")
        hp_id = hp_info.get("id")

        away_abbr = away_t.get("team", {}).get("abbreviation", "AWAY")
        home_abbr = home_t.get("team", {}).get("abbreviation", "HOME")
        away_tid = away_t.get("team", {}).get("id")
        home_tid = home_t.get("team", {}).get("id")

        try:
            _, ranks_by_id = _get_team_pitching_rankings(force=False)
        except Exception:
            ranks_by_id = {}
        away_staff = ranks_by_id.get(away_tid) or {}
        home_staff = ranks_by_id.get(home_tid) or {}

        def _row(b, opp_pid, opp_name, opp_hand):
            nm = b.get("name", "")
            fgb = fg_batter(nm)
            svb = sv_batter(nm)
            split_avg = b.get("vs_l_avg") if opp_hand == "L" else b.get("vs_r_avg")
            pitch_adv = _pitch_type_advantage(b.get("id"), opp_pid, batter_name=nm, pitcher_name=opp_name) if (b.get("id") and opp_pid) else {"status": "neutral", "note": "Neutral matchup"}
            return {
                "slot": b.get("slot"),
                "name": nm,
                "pos": b.get("pos"),
                "avg": b.get("avg") or fgb.get("fg_avg") or "---",
                "slg": b.get("slg") or fgb.get("fg_slg") or "---",
                "iso": fgb.get("fg_iso") or "---",
                "ops": b.get("ops") or fgb.get("fg_ops") or "---",
                "xwoba": svb.get("sv_xwoba") or "---",
                "ev": svb.get("sv_ev") or "---",
                "brl_pct": svb.get("sv_brl_pct") or "---",
                "split_avg": split_avg if split_avg not in (None, "N/A", "") else 0,
                "pitch_type_advantage": (pitch_adv or {}).get("status", "neutral"),
                "pitch_type_note": (pitch_adv or {}).get("note", "Neutral matchup"),
            }

        away_rows = [_row(b, hp_id, hp_name, hp_hand) for b in away_bats[:9]]
        home_rows = [_row(b, ap_id, ap_name, ap_hand) for b in home_bats[:9]]

        return jsonify({
            "success": True,
            "gamePk": game_pk,
            "awayAbbr": away_abbr,
            "homeAbbr": home_abbr,
            "awayStaffBadge": _rank_staff_badge(away_staff.get('composite_rank')),
            "homeStaffBadge": _rank_staff_badge(home_staff.get('composite_rank')),
            "awayPitcherName": ap_name,  # FIX: away team's own pitcher shown on away side
            "awayPitcherHand": ap_hand,
            "homePitcherName": hp_name,  # FIX: home team's own pitcher shown on home side
            "homePitcherHand": hp_hand,
            "awayBatters": away_rows,
            "homeBatters": home_rows,
        })
    except Exception as ex:
        print(f"[api_batting_order_matchups] {traceback.format_exc()}")
        return jsonify({"success": False, "error": str(ex)}), 500


# ── Route: Matchup scores (v2 — platoon-aware) ────────────────────────────────
@app.route('/api/props/matchup-scores/<int:game_pk>')
def api_props_matchup_scores(game_pk):
    try:
        _maybe_refresh_fg()
        _maybe_refresh_savant()

        gdata, away_bats, home_bats, away_t, home_t, pitchers = _props_fetch_game(game_pk, date_hint=request.args.get('date'))
        if not gdata:
            return jsonify({"success": False, "error": "Game not found"}), 404

        away_abbr = away_t.get("team", {}).get("abbreviation", "AWAY")
        home_abbr = home_t.get("team", {}).get("abbreviation", "HOME")

        ap_info = pitchers["ap"]; hp_info = pitchers["hp"]
        ap_name = ap_info.get("fullName", "TBD")
        hp_name = hp_info.get("fullName", "TBD")
        ap_id   = ap_info.get("id");  hp_id  = hp_info.get("id")

        ap_fg = fg_pitcher(ap_name); ap_sv = sv_pitcher(ap_name)
        hp_fg = fg_pitcher(hp_name); hp_sv = sv_pitcher(hp_name)
        ap_st = pitcher_stats_mlb(ap_id) if ap_id else {}
        hp_st = pitcher_stats_mlb(hp_id) if hp_id else {}

        ap_hand = (ap_st.get("pitchHand") or "R").upper()
        hp_hand = (hp_st.get("pitchHand") or "R").upper()

        def score_lineup(batters, opp_pfg, opp_psv, opp_hand):
            out = []
            for b in batters[:9]:
                sc = _matchup_score(b, opp_pfg, opp_psv, pitcher_hand=opp_hand)
                out.append({
                    "name":  b.get("name", ""),
                    "pos":   b.get("pos", ""),
                    "slot":  b.get("slot", 0),
                    "bats":  b.get("bats", ""),
                    "score": sc,
                })
            return sorted(out, key=lambda x: x["slot"])

        # home batters face away pitcher (ap_hand), away batters face home pitcher (hp_hand)
        away_scores = score_lineup(away_bats, hp_fg, hp_sv, hp_hand)
        home_scores = score_lineup(home_bats, ap_fg, ap_sv, ap_hand)

        return jsonify({
            "success": True,
            "gamePk":  game_pk,
            "away": {
                "abbr":         away_abbr,
                "pitcher_name": hp_name,
                "pitcher_hand": hp_hand,
                "pitcher_era":  hp_fg.get("fg_era") or hp_sv.get("sv_era_p"),
                "batters":      home_scores,
            },
            "home": {
                "abbr":         home_abbr,
                "pitcher_name": ap_name,
                "pitcher_hand": ap_hand,
                "pitcher_era":  ap_fg.get("fg_era") or ap_sv.get("sv_era_p"),
                "batters":      away_scores,
            },
            "timestamp": datetime.now(timezone.utc).isoformat(),
        })

    except Exception as ex:
        print(f"[api_props_matchup_scores] {traceback.format_exc()}")
        return jsonify({"success": False, "error": str(ex)}), 500


