@app.route("/api/hr-analytics/scouting/<int:batter_id>/<int:pitcher_id>/<int:game_pk>")
def api_hr_scouting(batter_id, pitcher_id, game_pk):
    """Claude-powered HR scouting report. Cached per (batter, pitcher, date)."""
    try:
        date_str = datetime.now(ET).strftime("%Y-%m-%d")
        cache_key = (batter_id, pitcher_id, date_str)
        with _hr_scouting_lock:
            cached = _hr_scouting_cache.get(cache_key)
        if cached:
            return jsonify({"success": True, "report": cached, "cached": True})

        batter_name = ""
        try:
            r = requests.get(f"{MLB_API}/people/{batter_id}", timeout=6)
            batter_name = (r.json().get("people") or [{}])[0].get("fullName", "")
        except Exception:
            pass
        if not batter_name:
            return jsonify({"success": False, "error": "Could not resolve batter"}), 404

        home_team_id = 0
        if game_pk:
            try:
                gdata = fetch_schedule_game(game_pk)
                if gdata:
                    home_team_id = ((gdata.get("teams") or {}).get("home") or {}).get("team", {}).get("id", 0)
            except Exception:
                pass

        inputs  = _gather_batter_hr_inputs(batter_name, batter_id, pitcher_id, home_team_id)
        bvp     = _fetch_bvp(batter_id, pitcher_id) or {}
        p_per_ab = _p_hr_per_ab(
            inputs["iso"], inputs["barrel_pct"], inputs["hh_pct"],
            inputs["hr9_vs_hand"], inputs["park_hr_idx"], inputs["mix_score"],
        )
        prob_any, _ = _run_hr_monte_carlo(p_per_ab, n_sims=500)
        score = _daily_hr_score(
            inputs["iso"], inputs["barrel_pct"], inputs["hh_pct"],
            inputs["hr9_vs_hand"], inputs["park_hr_idx"], inputs["mix_score"],
        )

        payload = _build_scouting_payload(inputs, bvp, p_per_ab, prob_any, score)
        report  = _call_claude_scouting_report(payload)
        if not report:
            report = (
                f"Insufficient API access for AI scouting report. "
                f"Model score: {score}/100. HR probability: {round(prob_any*100,1)}%. "
                f"Key factors: ISO {inputs['iso']}, Barrel% {inputs['barrel_pct']}, "
                f"Park HR index {inputs['park_hr_idx']}."
            )

        with _hr_scouting_lock:
            _evict_if_large(_hr_scouting_cache, 500)
            _hr_scouting_cache[cache_key] = report

        return jsonify({
            "success": True,
            "report": report,
            "cached": False,
            "payload": payload,
        })
    except Exception as ex:
        print(f"[api_hr_scouting] {traceback.format_exc()}")
        return jsonify({"success": False, "error": str(ex)}), 500


@app.route("/api/hr-analytics/daily-scores")
def api_hr_daily_scores():
    """Ranked 0-100 HR scores for every starting batter in today's games."""
    try:
        date_str = datetime.now(ET).strftime("%Y-%m-%d")
        with _hr_daily_lock:
            cached = _hr_daily_cache.get("date")
            if cached == date_str and _hr_daily_cache.get("scores"):
                return jsonify({
                    "success": True,
                    "date": date_str,
                    "scores":      _hr_daily_cache["scores"],
                    "ai_blurbs":   _hr_daily_cache.get("ai_blurbs") or {},
                    "ai_enriched": bool(_hr_daily_cache.get("ai_blurbs")),
                    "ai_model":    _hr_daily_cache.get("ai_model"),
                    "cached":      True,
                })

        _maybe_refresh_fg()
        _maybe_refresh_savant()

        games_raw = fetch_schedule(date_str) or []
        scores = []

        for game in games_raw:
            game_pk = game.get("gamePk")
            if not game_pk:
                continue
            teams     = game.get("teams") or {}
            home_info = (teams.get("home") or {}).get("team") or {}
            away_info = (teams.get("away") or {}).get("team") or {}
            home_tid  = home_info.get("id", 0)
            away_tid  = away_info.get("id", 0)
            home_name = home_info.get("name", "")
            away_name = away_info.get("name", "")

            # Probable pitchers
            home_prob = (teams.get("home") or {}).get("probablePitcher") or {}
            away_prob = (teams.get("away") or {}).get("probablePitcher") or {}

            # ── Parse game time in ET ──────────────────────────────────────
            game_date_raw = game.get("gameDate") or ""
            game_date_iso = game_date_raw
            game_time_et  = ""
            try:
                dt_utc_g  = datetime.fromisoformat(game_date_raw.replace("Z", "+00:00"))
                dt_et_g   = dt_utc_g.astimezone(ET)
                game_time_et = dt_et_g.strftime("%-I:%M %p ET")
            except Exception:
                game_time_et = game_date_raw[-8:-3] if len(game_date_raw) >= 8 else ""
            game_time = game_time_et  # keep legacy field

            # ── Venue & dome check ─────────────────────────────────────────
            ven_obj  = game.get("venue") or {}
            venue_id = ven_obj.get("id")
            is_dome  = bool(venue_id and venue_id in DOME_VENUES)

            # ── Weather (skip for domes) ───────────────────────────────────
            wx = {"temp": None, "condition": None, "wind": None, "wind_dir": None, "rain_chance": None}
            if not is_dome:
                try:
                    vloc   = ven_obj.get("location") or {}
                    coords = vloc.get("defaultCoordinates") or {}
                    lat    = coords.get("latitude")
                    lon    = coords.get("longitude")
                    raw_wx = game.get("weather") or {}
                    if lat and lon:
                        try:
                            utc_offset    = VENUE_UTC_OFFSET.get(venue_id, -5)
                            from datetime import timedelta as _td
                            game_hour_loc = (datetime.fromisoformat(game_date_raw.replace("Z", "+00:00")) + _td(hours=utc_offset)).hour
                        except Exception:
                            game_hour_loc = 13
                        wx = get_weather(lat, lon, game_hour_loc, venue_id=venue_id)
                    elif raw_wx:
                        wx = {
                            "temp":        raw_wx.get("temp"),
                            "condition":   raw_wx.get("condition"),
                            "wind":        raw_wx.get("wind"),
                            "wind_dir":    "",
                            "rain_chance": raw_wx.get("precipitationChance"),
                        }
                except Exception:
                    pass

            # Fetch lineup for this game. Call the lineup builder in-process
            # rather than over a self-referential HTTP request to
            # localhost:$PORT — that round-trip silently failed whenever the
            # assumed port was wrong (default 10000 vs the prod bind 8080) or no
            # server was listening, leaving scores empty, and otherwise tied up
            # a second worker thread per game (up to 15× sequentially).
            lineup_data = {}
            try:
                _lu_resp = api_lineup(game_pk)
                lineup_data = (_lu_resp.get_json() if hasattr(_lu_resp, "get_json") else None) or {}
            except Exception:
                pass
            away_confirmed = bool(lineup_data.get("awayConfirmed") or len(lineup_data.get("away") or []) >= 9)
            home_confirmed = bool(lineup_data.get("homeConfirmed") or len(lineup_data.get("home") or []) >= 9)
            game_label = f"{away_name} @ {home_name} \u2022 {game_time_et}"
            
            for side in ("away", "home"):
                batters   = lineup_data.get(side, [])
                opp_prob  = home_prob if side == "away" else away_prob
                opp_pid   = opp_prob.get("id", 0)
                opp_name  = opp_prob.get("fullName", "TBD")
                team_tid  = away_tid if side == "away" else home_tid
                team_name = away_name if side == "away" else home_name
                opp_team  = home_name if side == "away" else away_name
                lineup_confirmed = away_confirmed if side == "away" else home_confirmed
                
                if not opp_pid:
                    continue

                for b in batters[:9]:
                    bid    = b.get("id") or b.get("playerId")
                    bname  = (b.get("name") or b.get("fullName") or "").strip()
                    bhand  = b.get("bats", "R")
                    slot   = b.get("slot", 0)
                    if not bid or not bname:
                        continue

                    try:
                        fgb = fg_batter(bname)
                        svb = sv_batter(bname)
                        iso        = _num(fgb.get("fg_iso"), 0.0) or max(0.0, _num(svb.get("sv_xslg"), 0.380) - _num(svb.get("sv_xba"), 0.250))
                        barrel_pct = _num(svb.get("sv_brl_pct"), 8.5)
                        hh_pct     = _num(svb.get("sv_hh_pct"), 40.0)
                        fgp_hr9    = _num(fg_pitcher(opp_name).get("fg_hr9"), 1.25) if opp_name else 1.25

                        hand_splits = _fetch_pitcher_hr9_by_hand(opp_pid)
                        hand_key    = "vl_hr9" if bhand == "L" else "vr_hr9"
                        hr9_vs_hand = hand_splits.get(hand_key, fgp_hr9)

                        park_hr_idx = HR_PARK_FACTORS.get(home_tid, 100)
                        bat_pid_str = str(svb.get("sv_pid", "") or bid).strip()
                        svp = sv_pitcher(opp_name) if opp_name else {}
                        pit_pid_str = str(svp.get("sv_pid", "") or opp_pid).strip()
                        mix_score, pitch_rows = _compute_pitch_mix_score(pit_pid_str, bat_pid_str)

                        # Top 4 pitches sorted by usage
                        pitch_table = sorted(
                            pitch_rows or [],
                            key=lambda r: r.get("usage", 0),
                            reverse=True
                        )[:4]

                        # Pitches where both pitcher allows ≥.500 SLG AND batter slugs ≥.550
                        lethal_pitches = [
                            r.get("pitch") for r in pitch_table
                            if r.get("pit_slg") is not None
                            and r.get("bat_slg") is not None
                            and r["pit_slg"] >= 0.500
                            and r["bat_slg"] >= 0.550
                        ]

                        pit_hand = "R"
                        try:
                            bio_p = player_profile(opp_pid)
                            pit_hand = bio_p.get("throws", "R")
                        except Exception:
                            pass
                        platoon_adv = 0.5 if bhand != pit_hand else -0.3

                        p_per_ab = _p_hr_per_ab(iso, barrel_pct, hh_pct, hr9_vs_hand, park_hr_idx, mix_score)
                        prob_any  = round(1 - (1 - p_per_ab) ** 4, 4)
                        score     = _daily_hr_score(iso, barrel_pct, hh_pct, hr9_vs_hand, park_hr_idx, mix_score, platoon_adv)

                        scores.append({
                            "batter_id":   bid,
                            "batter":      bname,
                            "batter_hand": bhand,
                            "slot":        slot,
                            "team":        team_name,
                            "opp_team":    opp_team,
                            "pitcher_id":  opp_pid,
                            "pitcher":     opp_name,
                            "game_pk":     game_pk,
                            "game_time":   game_time,
                            "home_team_id": home_tid,
                            "score":       score,
                            "prob_hr":     prob_any,
                            "p_per_ab":    p_per_ab,
                            "iso":         round(iso, 3),
                            "barrel_pct":  round(barrel_pct, 1),
                            "hh_pct":      round(hh_pct, 1),
                            "hr9_vs_hand": round(hr9_vs_hand, 3),
                            "park_hr_idx":      park_hr_idx,
                            "mix_score":        mix_score,
                            "game_time_et":     game_time_et,
                            "game_date_iso":    game_date_iso,
                            "game_label":       game_label,
                            "pitch_table":      pitch_table,
                            "lethal_pitches":   lethal_pitches,
                            "lineup_confirmed": lineup_confirmed,
                            "is_dome":          is_dome,
                            "weather_temp":     wx.get("temp"),
                            "weather_condition": wx.get("condition"),
                            "weather_wind":     wx.get("wind"),
                            "weather_wind_dir": wx.get("wind_dir"),
                            "weather_rain":     wx.get("rain_chance"),
                        })
                            
                        
                    except Exception:
                        continue

        scores.sort(key=lambda x: x["score"], reverse=True)

        ai_blurbs, ai_err = _vertex_hr_pick_blurbs(scores, top_n=20)

        with _hr_daily_lock:
            _hr_daily_cache["date"]      = date_str
            _hr_daily_cache["scores"]    = scores
            _hr_daily_cache["ai_blurbs"] = ai_blurbs
            _hr_daily_cache["ai_model"]  = VERTEX_MODELS.get("fast") if ai_blurbs else None
            _hr_daily_cache["ai_error"]  = ai_err

        return jsonify({
            "success": True,
            "date": date_str,
            "scores":      scores,
            "ai_blurbs":   ai_blurbs,
            "ai_enriched": bool(ai_blurbs),
            "ai_model":    VERTEX_MODELS.get("fast") if ai_blurbs else None,
            "ai_error":    ai_err,
            "cached":      False,
        })
    except Exception as ex:
        print(f"[api_hr_daily_scores] {traceback.format_exc()}")
        return jsonify({"success": False, "error": str(ex), "scores": []}), 500


# ── Preload caches at startup ───────────────────────────────────────────
# Load FG and Savant data before serving requests to ensure data is available
# on first access. This runs in background threads to avoid blocking startup.
def _preload_caches():
    """Preload FG, Savant, and roster caches at startup in background threads."""
    def load_fg():
        try:
            _load_fg_data()
            print("[STARTUP] FG cache preload complete")
        except Exception as ex:
            print(f"[STARTUP] FG cache preload failed: {ex}")

    def load_sv():
        try:
            _load_savant_data()
            print("[STARTUP] Savant cache preload complete")
        except Exception as ex:
            print(f"[STARTUP] Savant cache preload failed: {ex}")

    def load_rosters():
        # All 30 MLB team IDs (stable; new franchises would require updating this list).
        mlb_team_ids = [
            133, 134, 135, 136, 137, 138, 139, 140, 141, 142,
            143, 144, 145, 146, 147, 158, 108, 109, 110, 111,
            112, 113, 114, 115, 116, 117, 118, 119, 120, 121,
        ]
        loaded = 0
        for tid in mlb_team_ids:
            try:
                roster = _get_active_roster(tid)
                if roster:
                    loaded += 1
            except Exception:
                pass
        print(f"[STARTUP] Active roster cache preload complete: {loaded}/30 teams")

    def load_arsenal():
        global _local_arsenal_cache
        try:
            with _local_arsenal_lock:
                if _local_arsenal_cache is None:
                    _local_arsenal_cache = _load_local_pitcher_arsenal()
            print("[STARTUP] Local pitcher arsenal cache preload complete")
        except Exception as ex:
            print(f"[STARTUP] Local pitcher arsenal cache preload failed: {ex}")

    # Start cache loads in parallel background threads
    threading.Thread(target=load_fg, daemon=True).start()
    threading.Thread(target=load_sv, daemon=True).start()
    threading.Thread(target=load_rosters, daemon=True).start()
    threading.Thread(target=load_arsenal, daemon=True).start()

    def _prewarm_when_ready():
        # Wait for FG data to be available before prewarming dependent caches.
        deadline = time.time() + 90
        while time.time() < deadline:
            with _fg_lock:
                if _fg_loaded:
                    break
            time.sleep(3)
        prewarm_today_caches({
            "fetch_schedule": fetch_schedule,
            "_fetch_bvp": _fetch_bvp,
            "_pitcher_recent_form": _pitcher_recent_form,
            "_get_cached_ump": _get_cached_ump,
        })

    threading.Thread(target=_prewarm_when_ready, daemon=True).start()

    def _load_brain_overlays_when_ready():
        """Load brain overlays after FG cache is ready (brain merges into FG data)."""
        deadline = time.time() + 90
        while time.time() < deadline:
            with _fg_lock:
                if _fg_loaded:
                    break
            time.sleep(3)
        try:
            load_brain_overlays()
        except Exception as ex:
            print(f"[STARTUP] brain overlay load failed: {ex}")
    threading.Thread(target=_load_brain_overlays_when_ready, daemon=True).start()

    _start_odds_snapshot_worker()

# _preload_caches() is now triggered via the gunicorn post_fork hook in gunicorn_conf.py
# so that port 8080 is bound before any heavy network I/O begins.

# ── Vertex AI + BigQuery routes (multi-model orchestration) ──────────────────
# These routes coexist alongside the existing /api/cheatsheets/today,
# /api/game-projection/<pk>, /api/ai-boxscore/<pk>. Existing endpoints are
# unchanged so the UI keeps working; the new endpoints are the migration
# target as the BigQuery schema and Vertex throughput are validated.

# ── Arsenal-similarity BvP prior ──────────────────────────────────────────────
# Direct BvP samples are tiny (typically 3-15 PAs). We enrich them by pulling
# the batter's PA-by-PA Statcast log (last 2 seasons via pybaseball, cached on
# disk by PYBASEBALL_CACHE=1) and aggregating only the PAs against pitchers
# whose arsenal cosine-similarity to the target pitcher is >= 0.70. The direct
# BvP rates and the similar-pitcher prior rates are then Bayesian-blended by
# sample size — a 5-PA direct sample with a 300-PA prior leans heavily on the
# prior; a 100-PA direct sample dominates it.

ARSENAL_PRIOR_SEASONS    = int(os.environ.get("ARSENAL_PRIOR_SEASONS",   "2"))
ARSENAL_PRIOR_STRENGTH   = int(os.environ.get("ARSENAL_PRIOR_STRENGTH", "20"))
ARSENAL_PRIOR_SIM_FLOOR  = float(os.environ.get("ARSENAL_PRIOR_SIM_FLOOR", "0.70"))
ARSENAL_PRIOR_TOPN       = int(os.environ.get("ARSENAL_PRIOR_TOPN",     "10"))
ARSENAL_PRIOR_TIMEOUT_S  = float(os.environ.get("ARSENAL_PRIOR_TIMEOUT_S", "20.0"))

# In-memory cache for the batter Statcast DataFrame, keyed by
# (batter_id, today_date_str). Holds only the 4 columns we filter on
# (pitcher, events, game_date, pitch_type) to keep memory bounded.
_batter_statcast_cache: dict = {}
_batter_statcast_lock = threading.Lock()

# Separate cache for the richer per-PA Statcast pull used by the H2H tab —
# keeps the EV / launch_angle / hit_distance / bb_type columns that the
# arsenal-prior pulls drop. Keyed by (batter_id, today, vs_pitcher_id).
_batter_recent_statcast_cache: dict = {}
_batter_recent_statcast_lock = threading.Lock()


def _recent_statcast_for_batter(batter_id, pitcher_id=None, n=10, seasons=2):
    """Pull the batter's recent batted-ball events with Statcast metrics.

    Returns a list of dicts (most recent first) with keys:
        date, exit_velocity, launch_angle, hit_distance, trajectory, event
    Optionally filtered to events against a specific pitcher_id.

    Uses pybaseball.statcast_batter; caches the per-PA DataFrame per
    (batter_id, today, vs_pitcher) so repeat H2H lookups are free.
    Returns [] on any failure (FE renders em-dashes for missing values).
    """
    try:
        bid = int(batter_id)
    except Exception:
        return []
    today = datetime.now().strftime("%Y-%m-%d")
    cache_key = (bid, today, int(pitcher_id) if pitcher_id else None, int(n), int(seasons))
    with _batter_recent_statcast_lock:
        cached = _batter_recent_statcast_cache.get(cache_key)
        if cached is not None:
            return cached

    try:
        import pybaseball as pb
    except Exception as ex:
        logging.warning(f"[RecentStatcast] pybaseball import failed: {ex}")
        with _batter_recent_statcast_lock:
            _batter_recent_statcast_cache[cache_key] = []
        return []

    current_year = datetime.now().year
    season_years = list(range(current_year - max(1, seasons) + 1, current_year + 1))

    def _pull_one(yr):
        try:
            start = f"{yr}-03-01"
            end = today if yr == current_year else f"{yr}-11-30"
            df = pb.statcast_batter(start_dt=start, end_dt=end, player_id=bid)
            if df is None or df.empty:
                return None
            keep_cols = [c for c in ("game_date", "events", "launch_speed", "launch_angle",
                                     "hit_distance_sc", "bb_type", "pitcher", "description")
                         if c in df.columns]
            if "events" not in keep_cols:
                return None
            sub = df[keep_cols].dropna(subset=["events"])
            return sub
        except Exception as ex:
            logging.warning(f"[RecentStatcast] pull failed bid={bid} yr={yr}: {ex}")
            return None

    frames = []
    with ThreadPoolExecutor(max_workers=min(len(season_years), 4)) as ex:
        for fut in as_completed({ex.submit(_pull_one, yr): yr for yr in season_years}):
            df = fut.result()
            if df is not None and not df.empty:
                frames.append(df)

    if not frames:
        with _batter_recent_statcast_lock:
            _batter_recent_statcast_cache[cache_key] = []
        return []

    combined = pd.concat(frames, ignore_index=True)
    if pitcher_id and "pitcher" in combined.columns:
        try:
            pid = int(pitcher_id)
            combined["pitcher"] = pd.to_numeric(combined["pitcher"], errors="coerce")
            combined = combined[combined["pitcher"] == pid]
        except Exception:
            pass

    if combined.empty:
        with _batter_recent_statcast_lock:
            _batter_recent_statcast_cache[cache_key] = []
        return []

    try:
        combined = combined.sort_values("game_date", ascending=False).head(int(n))
    except Exception:
        combined = combined.head(int(n))

    out = []
    for _, row in combined.iterrows():
        def _num(v):
            try:
                if v is None or (isinstance(v, float) and pd.isna(v)):
                    return None
                return round(float(v), 1)
            except Exception:
                return None
        bb = row.get("bb_type")
        traj_map = {"ground_ball": "GB", "fly_ball": "FB", "line_drive": "LD",
                    "popup": "PU"}
        traj = traj_map.get(str(bb).lower(), None) if bb and not (isinstance(bb, float) and pd.isna(bb)) else None
        evt = row.get("events")
        event_str = str(evt).replace("_", " ").title() if evt and not (isinstance(evt, float) and pd.isna(evt)) else None
        out.append({
            "date":           str(row.get("game_date") or "")[:10],
            "exit_velocity":  _num(row.get("launch_speed")),
            "launch_angle":   _num(row.get("launch_angle")),
            "hit_distance":   _num(row.get("hit_distance_sc")),
            "trajectory":     traj,
            "event":          event_str,
        })

    with _batter_recent_statcast_lock:
        _batter_recent_statcast_cache[cache_key] = out
    return out

# Event classification for per-PA rate derivation.
_BVP_HIT_EVENTS    = {"single", "double", "triple", "home_run"}
_BVP_K_EVENTS      = {"strikeout", "strikeout_double_play"}
_BVP_BB_EVENTS     = {"walk"}
_BVP_HBP_EVENTS    = {"hit_by_pitch"}
_BVP_SAC_EVENTS    = {"sac_fly", "sac_fly_double_play", "sac_bunt", "sac_bunt_double_play"}


def _resolve_similar_pitcher_ids(names):
    """Map a list of pitcher names to MLBAM IDs via the boot-time cache.

    Returns {mlbam_id: name} dict so callers can audit which pitchers
    contributed to the aggregate. Names that don't resolve are dropped
    silently (logged at debug only — unmapped names are usually accent
    variants or minor leaguers not in the FG file).
    """
    if not names:
        return {}
    with _pitcher_name_to_mlbam_lock:
        idx = dict(_pitcher_name_to_mlbam)
    out = {}
    for nm in names:
        if not nm:
            continue
        mid = idx.get(_sv_key(nm)) or idx.get(_sv_key(_ascii_fold(nm)))
        if mid:
            out[mid] = nm
    return out


def _load_batter_statcast(batter_id, seasons=None):
    """Pull the batter's PA-by-PA Statcast log for the last N seasons.

    Returns a pandas DataFrame with columns (pitcher, events, game_date,
    pitch_type) restricted to rows where `events` is non-null (PA boundaries).
    Cached per (batter_id, today) so repeat lookups within the day are free.

    Returns None on any pybaseball failure or if PYBASEBALL_CACHE is off
    and we're rate-limited.
    """
    seasons = seasons or ARSENAL_PRIOR_SEASONS
    today = datetime.now().strftime("%Y-%m-%d")
    cache_key = (int(batter_id), today, seasons)
    with _batter_statcast_lock:
        cached = _batter_statcast_cache.get(cache_key)
        if cached is not None:
            return cached

    try:
        import pybaseball as pb
    except Exception as ex:
        logging.warning(f"[ArsenalPrior] pybaseball import failed: {ex}")
        return None

    current_year = datetime.now().year
    season_years = list(range(current_year - seasons + 1, current_year + 1))

    def _pull_one(yr):
        try:
            start = f"{yr}-03-01"
            end = today if yr == current_year else f"{yr}-11-30"
            df = pb.statcast_batter(start_dt=start, end_dt=end, player_id=int(batter_id))
            if df is None or df.empty:
                return None
            # Keep only PA boundaries and the columns we need.
            keep = [c for c in ("pitcher", "events", "game_date", "pitch_type") if c in df.columns]
            if "events" not in keep:
                return None
            sub = df[keep].dropna(subset=["events"])
            return sub
        except Exception as ex:
            logging.warning(f"[ArsenalPrior] statcast pull failed bid={batter_id} yr={yr}: {ex}")
            return None

    frames = []
    with ThreadPoolExecutor(max_workers=min(seasons, 4)) as ex:
        futures = {ex.submit(_pull_one, yr): yr for yr in season_years}
        for fut in as_completed(futures):
            df = fut.result()
            if df is not None and not df.empty:
                frames.append(df)

    if not frames:
        with _batter_statcast_lock:
            _batter_statcast_cache[cache_key] = None
        return None

    combined = pd.concat(frames, ignore_index=True)
    with _batter_statcast_lock:
        _batter_statcast_cache[cache_key] = combined
    return combined


def _aggregate_pa_outcomes(df):
    """Tally Statcast events into the canonical BvP counts schema.

    Returns {pa, ab, h, hr, bb, k, '1b', '2b', '3b', hbp} ints. Used by
    both the arsenal prior aggregation and (potentially) for direct BvP
    derivation once we have Statcast pulls for the pitcher too.
    """
    if df is None or df.empty:
        return None
    counts = {"pa": 0, "ab": 0, "h": 0, "hr": 0, "bb": 0, "k": 0,
              "1b": 0, "2b": 0, "3b": 0, "hbp": 0}
    for ev in df["events"].tolist():
        if ev is None or (isinstance(ev, float) and pd.isna(ev)):
            continue
        e = str(ev).lower().strip()
        counts["pa"] += 1
        if e in _BVP_HIT_EVENTS:
            counts["h"] += 1
            if e == "single":     counts["1b"] += 1
            elif e == "double":   counts["2b"] += 1
            elif e == "triple":   counts["3b"] += 1
            elif e == "home_run": counts["hr"] += 1
            counts["ab"] += 1
        elif e in _BVP_K_EVENTS:
            counts["k"] += 1
            counts["ab"] += 1
        elif e in _BVP_BB_EVENTS:
            counts["bb"] += 1
        elif e in _BVP_HBP_EVENTS:
            counts["hbp"] += 1
        elif e in _BVP_SAC_EVENTS:
            pass  # not an AB, not a BB/K/HBP
        else:
            # field_out, force_out, grounded_into_double_play, fielders_choice,
            # double_play, triple_play, etc.
            counts["ab"] += 1
    return counts if counts["pa"] else None


def _similar_pitchers_for(pitcher_name, top_n=None, sim_floor=None):
    """Return list of {name, similarity, primary_pitch} for similar arsenals.

    Mirrors the logic in /api/player/<bid>/arsenal-matchup/<pid> at app.py:455
    (primary-pitch gate + cosine >= threshold) so both surfaces stay aligned.
    """
    top_n = top_n or ARSENAL_PRIOR_TOPN
    sim_floor = sim_floor if sim_floor is not None else ARSENAL_PRIOR_SIM_FLOOR
    target = sv_pitcher(pitcher_name).get("sv_arsenal_pct", {})
    if not target:
        return [], None
    primary = max(target.items(), key=lambda x: x[1])[0]
    with _sv_lock:
        arsenal_idx = dict(_sv_arsenal_pct)
    out = []
    for name, arsenal in arsenal_idx.items():
        if not arsenal or name.lower() == pitcher_name.lower():
            continue
        other_primary = max(arsenal.items(), key=lambda x: x[1])[0]
        if other_primary != primary:
            continue
        sim = _arsenal_similarity(target, arsenal)
        if sim >= sim_floor:
            out.append({"name": name, "similarity": round(sim, 3),
                        "primary_pitch": other_primary})
    out.sort(key=lambda x: x["similarity"], reverse=True)
    return out[:top_n], primary


def _aggregate_vs_similar_pitchers(batter_id, similar_pitcher_names):
    """Pull batter Statcast, filter to PAs vs similar pitchers, tally counts.

    Returns (counts_dict, audit_dict) or (None, audit_dict_with_reason).
    audit_dict always includes the resolved similar-pitcher list and the
    PAs each contributed, so the response is fully traceable.
    """
    audit = {
        "similar_pitchers_in":  len(similar_pitcher_names),
        "similar_pitchers_resolved": 0,
        "per_pitcher_pa": {},
        "reason": None,
    }
    id_to_name = _resolve_similar_pitcher_ids(similar_pitcher_names)
    audit["similar_pitchers_resolved"] = len(id_to_name)
    if not id_to_name:
        audit["reason"] = "no_pitcher_ids_resolved"
        return None, audit

    df = _load_batter_statcast(batter_id)
    if df is None or df.empty:
        audit["reason"] = "no_batter_statcast"
        return None, audit
    if "pitcher" not in df.columns:
        audit["reason"] = "no_pitcher_column"
        return None, audit

    try:
        df["pitcher"] = pd.to_numeric(df["pitcher"], errors="coerce")
    except Exception:
        pass
    matched = df[df["pitcher"].isin(list(id_to_name.keys()))]
    if matched.empty:
        audit["reason"] = "no_pa_against_similar_pitchers"
        return None, audit

    # Per-pitcher PA breakdown for audit.
    try:
        per_pitcher = matched.groupby("pitcher").size().to_dict()
        audit["per_pitcher_pa"] = {
            id_to_name.get(int(pid), str(int(pid))): int(pa)
            for pid, pa in per_pitcher.items()
        }
    except Exception:
        pass

    counts = _aggregate_pa_outcomes(matched)
    if not counts:
        audit["reason"] = "events_unparseable"
        return None, audit
    return counts, audit


def _counts_to_pa_rates(counts):
    """Same shape as _bvp_row_to_pa_rates output, derived from real counts."""
    pa = max(1, int(counts.get("pa") or 0))
    one_b = int(counts.get("1b") or 0)
    two_b = int(counts.get("2b") or 0)
    three_b = int(counts.get("3b") or 0)
    hr = int(counts.get("hr") or 0)
    bb = int(counts.get("bb") or 0)
    k = int(counts.get("k") or 0)
    hbp = int(counts.get("hbp") or 0)
    return {
        "k":   k / pa,
        "bb":  bb / pa,
        "hbp": hbp / pa if hbp else 0.005,
        "1b":  one_b / pa,
        "2b":  two_b / pa,
        "3b":  three_b / pa,
        "hr":  hr / pa,
    }


def _blend_bvp_with_prior(direct_rates, direct_pa, prior_rates, prior_pa,
                          prior_strength=None):
    """Bayesian shrinkage: small direct samples lean on the prior.

    effective_prior_pa = min(prior_pa, prior_strength) caps the prior so a
    huge prior can't completely override a meaningful direct sample.
    Returns (blended_rates, weight_dict) where weight_dict.prior_weight
    is the share of the blended rate that came from the prior.
    """
    if not direct_rates and not prior_rates:
        return None, {"prior_weight": 0.0, "direct_pa": 0, "prior_pa": 0}
    if not prior_rates:
        return direct_rates, {"prior_weight": 0.0, "direct_pa": direct_pa, "prior_pa": 0}
    if not direct_rates or direct_pa <= 0:
        return prior_rates, {"prior_weight": 1.0, "direct_pa": 0, "prior_pa": prior_pa}

    strength = prior_strength if prior_strength is not None else ARSENAL_PRIOR_STRENGTH
    eff_prior_pa = min(int(prior_pa), int(strength))
    total = float(direct_pa + eff_prior_pa)
    if total <= 0:
        return direct_rates, {"prior_weight": 0.0, "direct_pa": direct_pa, "prior_pa": prior_pa}
    prior_w = eff_prior_pa / total
    direct_w = direct_pa / total
    keys = set(direct_rates.keys()) | set(prior_rates.keys())
    blended = {
        k: direct_w * float(direct_rates.get(k, 0.0))
           + prior_w * float(prior_rates.get(k, 0.0))
        for k in keys
    }
    return blended, {
        "prior_weight":  round(prior_w, 3),
        "direct_weight": round(direct_w, 3),
        "direct_pa":     int(direct_pa),
        "prior_pa":      int(prior_pa),
        "effective_prior_pa": int(eff_prior_pa),
        "prior_strength": int(strength),
    }


def _blend_multi(sources, total_strength_cap=None):
    """Blend N rate dicts by sample-size weights.

    `sources` is a list of (rates_dict, pa_count, per_source_strength_cap).
    Each source contributes its weight = min(pa_count, per_source_cap); the
    blended rate for each key is a weighted average. Empty sources skipped.

    `total_strength_cap` (optional) caps the *sum* of effective weights so
    no combined prior can completely override a real-sized direct sample.
    """
    cleaned = []
    for entry in sources:
        if not entry:
            continue
        rates, pa, cap = entry
        if not rates or pa is None or pa <= 0:
            continue
        eff = int(min(int(pa), int(cap))) if cap is not None else int(pa)
        if eff <= 0:
            continue
        cleaned.append((rates, eff, int(pa)))
    if not cleaned:
        return None, {"weights": [], "total_effective_pa": 0}
    total_w = sum(w for _, w, _ in cleaned)
    if total_strength_cap is not None and total_w > total_strength_cap:
        # Scale down proportionally so the cap is respected.
        scale = total_strength_cap / total_w
        cleaned = [(r, max(1, int(round(w * scale))), p) for r, w, p in cleaned]
        total_w = sum(w for _, w, _ in cleaned)
    keys = set()
    for r, _, _ in cleaned:
        keys.update(r.keys())
    blended = {
        k: sum(w * float(r.get(k, 0.0)) for r, w, _ in cleaned) / float(total_w)
        for k in keys
    }
    weights_audit = [
        {"effective_pa": w, "raw_pa": p, "weight": round(w / float(total_w), 3)}
        for _, w, p in cleaned
    ]
    return blended, {
        "weights": weights_audit,
        "total_effective_pa": int(total_w),
    }


# ── Pitcher-side prior: similar batters ────────────────────────────────────
# Mirror of the batter-arsenal prior, applied to the other side of the
# matchup. For a given (batter, pitcher) we ask: how has THIS PITCHER fared
# against batters with profile similar to THIS BATTER? "Similar batter" is
# defined as same handedness AND xwOBA within ARSENAL_PRIOR_XWOBA_WINDOW
# (sorted by xwOBA closeness, capped at ARSENAL_PRIOR_TOPN_BATTERS). The
# pitcher's PA-by-PA Statcast log is then filtered to those batter IDs and
# tallied into the same counts schema.

ARSENAL_PRIOR_XWOBA_WINDOW    = float(os.environ.get("ARSENAL_PRIOR_XWOBA_WINDOW",   "0.020"))
ARSENAL_PRIOR_TOPN_BATTERS    = int(os.environ.get("ARSENAL_PRIOR_TOPN_BATTERS",     "30"))
ARSENAL_PRIOR_PITCHER_STRENGTH = int(os.environ.get("ARSENAL_PRIOR_PITCHER_STRENGTH", "20"))

# In-memory cache for pitcher Statcast logs, mirror of _batter_statcast_cache.
_pitcher_statcast_cache: dict = {}
_pitcher_statcast_lock = threading.Lock()


def _similar_batters_for(batter_id, batter_name_hint=None):
    """Find batters with similar handedness + xwOBA to the target.

    Returns ([{batter_id, name, bats, xwoba, similarity}, ...], target_meta)
    where target_meta is the resolved {bats, xwoba} for the target so the
    caller can report it.

    Uses _batter_profiles (mlbam -> bats/name) and _sv_bat_xstats (name ->
    xwoba). Skips silently if either cache is empty or the target is
    unresolvable.
    """
    with _batter_profiles_lock:
        prof_idx = dict(_batter_profiles)
    target_prof = prof_idx.get(int(batter_id))
    if not target_prof:
        return [], {"reason": "target_not_in_profiles"}

    target_bats = target_prof.get("bats")
    target_name = batter_name_hint or target_prof.get("name") or ""
    if not target_bats:
        return [], {"reason": "target_handedness_unknown", "name": target_name}

    with _sv_lock:
        xs_idx = dict(_sv_bat_xstats)

    target_key = _sv_key(target_name)
    target_entry = xs_idx.get(target_key) or xs_idx.get(_sv_key(_ascii_fold(target_name)))
    target_xwoba = None
    if target_entry:
        # Prefer the 3dp value; the 2dp legacy field rounds .342 and .349 to
        # 0.34 and falsely matches Xavier Edwards with Bryan Reynolds.
        for fld in ("sv_xwoba_p3", "sv_xwoba"):
            v = target_entry.get(fld)
            if v in (None, "N/A", ""):
                continue
            try:
                target_xwoba = float(v); break
            except Exception:
                pass
    if target_xwoba is None:
        return [], {"reason": "target_xwoba_unknown", "name": target_name, "bats": target_bats}

    # Switch hitters: match both L and R candidates (they see both sides
    # depending on pitcher, so pooling is appropriate).
    accepted_bats = {target_bats}
    if target_bats == "S":
        accepted_bats = {"L", "R", "S"}

    # Build reverse lookup name -> mlbam from _batter_profiles.
    name_to_mlbam = {}
    for mid, prof in prof_idx.items():
        nm = (prof.get("name") or "").strip()
        if not nm:
            continue
        name_to_mlbam.setdefault(_sv_key(nm), mid)
        name_to_mlbam.setdefault(_sv_key(_ascii_fold(nm)), mid)

    candidates = []
    for name_key, entry in xs_idx.items():
        if name_key == target_key:
            continue
        mid = name_to_mlbam.get(name_key)
        if not mid:
            continue
        cand_prof = prof_idx.get(mid) or {}
        cand_bats = cand_prof.get("bats")
        if cand_bats not in accepted_bats:
            continue
        cand_xwoba = None
        for fld in ("sv_xwoba_p3", "sv_xwoba"):
            v = entry.get(fld)
            if v in (None, "N/A", ""):
                continue
            try:
                cand_xwoba = float(v); break
            except Exception:
                pass
        if cand_xwoba is None:
            continue
        delta = abs(cand_xwoba - target_xwoba)
        # Strict < (not <=) so candidates at the exact window edge — which
        # would compute to similarity 0.0 — get dropped instead of polluting
        # the top-N with zero-weight entries.
        if delta >= ARSENAL_PRIOR_XWOBA_WINDOW:
            continue
        sim = round(1.0 - (delta / ARSENAL_PRIOR_XWOBA_WINDOW), 3) if ARSENAL_PRIOR_XWOBA_WINDOW else 1.0
        if sim <= 0.05:   # extra floor for paranoia
            continue
        candidates.append({
            "batter_id": int(mid),
            "name":      cand_prof.get("name") or name_key,
            "bats":      cand_bats,
            "xwoba":     cand_xwoba,
            "similarity": sim,
        })
    candidates.sort(key=lambda c: c["similarity"], reverse=True)
    return candidates[:ARSENAL_PRIOR_TOPN_BATTERS], {
        "name":   target_name,
        "bats":   target_bats,
        "xwoba":  target_xwoba,
        "window": ARSENAL_PRIOR_XWOBA_WINDOW,
    }


def _load_pitcher_statcast(pitcher_id, seasons=None):
    """Pull the pitcher's PA-by-PA Statcast log via pybaseball.

    Mirror of _load_batter_statcast — same caching pattern, same column
    pruning. The DataFrame returned has the `batter` column populated with
    MLBAM IDs, which we filter against the similar-batter list.
    """
    seasons = seasons or ARSENAL_PRIOR_SEASONS
    today = datetime.now().strftime("%Y-%m-%d")
    cache_key = (int(pitcher_id), today, seasons)
    with _pitcher_statcast_lock:
        cached = _pitcher_statcast_cache.get(cache_key)
        if cached is not None:
            return cached

    try:
        import pybaseball as pb
    except Exception as ex:
        logging.warning(f"[ArsenalPriorPitcher] pybaseball import failed: {ex}")
        return None

    current_year = datetime.now().year
    season_years = list(range(current_year - seasons + 1, current_year + 1))

    def _pull_one(yr):
        try:
            start = f"{yr}-03-01"
            end = today if yr == current_year else f"{yr}-11-30"
            df = pb.statcast_pitcher(start_dt=start, end_dt=end, player_id=int(pitcher_id))
            if df is None or df.empty:
                return None
            keep = [c for c in ("batter", "events", "game_date", "pitch_type") if c in df.columns]
            if "events" not in keep:
                return None
            return df[keep].dropna(subset=["events"])
        except Exception as ex:
            logging.warning(f"[ArsenalPriorPitcher] statcast pull failed pid={pitcher_id} yr={yr}: {ex}")
            return None

    frames = []
    with ThreadPoolExecutor(max_workers=min(seasons, 4)) as ex:
        futures = {ex.submit(_pull_one, yr): yr for yr in season_years}
        for fut in as_completed(futures):
            df = fut.result()
            if df is not None and not df.empty:
                frames.append(df)

    if not frames:
        with _pitcher_statcast_lock:
            _pitcher_statcast_cache[cache_key] = None
        return None

    combined = pd.concat(frames, ignore_index=True)
    with _pitcher_statcast_lock:
        _pitcher_statcast_cache[cache_key] = combined
    return combined


def _aggregate_pitcher_vs_similar_batters(pitcher_id, similar_batter_ids):
    """Filter pitcher's PA log to similar-batter IDs and tally outcomes.

    Returns (counts_dict, audit_dict) or (None, audit_dict_with_reason).
    Symmetric to _aggregate_vs_similar_pitchers — same audit shape.
    """
    audit = {
        "similar_batters_in":       len(similar_batter_ids),
        "similar_batters_resolved": 0,
        "per_batter_pa":            {},
        "reason":                   None,
    }
    if not similar_batter_ids:
        audit["reason"] = "no_similar_batter_ids"
        return None, audit

    df = _load_pitcher_statcast(pitcher_id)
    if df is None or df.empty:
        audit["reason"] = "no_pitcher_statcast"
        return None, audit
    if "batter" not in df.columns:
        audit["reason"] = "no_batter_column"
        return None, audit

    try:
        df["batter"] = pd.to_numeric(df["batter"], errors="coerce")
    except Exception:
        pass
    id_set = set(int(x) for x in similar_batter_ids)
    matched = df[df["batter"].isin(list(id_set))]
    if matched.empty:
        audit["reason"] = "no_pa_against_similar_batters"
        return None, audit

    try:
        per_batter = matched.groupby("batter").size().to_dict()
        # Limit audit to top-5 contributors to keep response payload small.
        sorted_pb = sorted(per_batter.items(), key=lambda kv: kv[1], reverse=True)[:5]
        audit["per_batter_pa"] = {int(bid): int(pa) for bid, pa in sorted_pb}
        audit["similar_batters_resolved"] = len(per_batter)
    except Exception:
        pass

    counts = _aggregate_pa_outcomes(matched)
    if not counts:
        audit["reason"] = "events_unparseable"
        return None, audit
    return counts, audit


def _normalize_matchup_row(raw, source):
    """Map a CSV or BQ matchup row to the canonical BvP schema.

    BQ rows already use {pa, ab, h, hr, bb, k, avg, slg, woba, xwoba,
    batter_name, bats, pitcher_name, throws}. CSV rows from
    data/mlb_matchups_*.csv use bvp_* prefixed keys plus a much wider
    set of platoon-split and Statcast quality columns — without remapping,
    _bvp_row_to_pa_rates reads None for every count and the Monte Carlo
    silently runs on all-zero rates.

    For CSV rows we promote the bvp_* counts to canonical keys, derive PA
    from AB+BB (the CSV doesn't track HBP/SF), and preserve every other
    column under `context` so the Gemini prompt sees the richer signal.
    """
    if not raw:
        return raw
    if source != "csv_fallback":
        return dict(raw)
    r = dict(raw)
    ab = int(_num(r.get("bvp_ab")) or 0)
    bb = int(_num(r.get("bvp_bb")) or 0)
    canonical = {
        "pa":           ab + bb,
        "ab":           ab,
        "h":            int(_num(r.get("bvp_h"))  or 0),
        "hr":           int(_num(r.get("bvp_hr")) or 0),
        "bb":           bb,
        "k":            int(_num(r.get("bvp_k"))  or 0),
        "avg":          _num(r.get("bvp_avg")) or None,
        "ops":          _num(r.get("bvp_ops")) or None,
        "xwoba":        _num(r.get("batter_xwoba")) or None,
        "batter_name":  r.get("batter_name"),
        "bats":         r.get("batter_hand"),
        "pitcher_name": r.get("pitcher_name"),
    }
    extras = {k: v for k, v in r.items()
              if k not in canonical and v not in ("", None)}
    if extras:
        canonical["context"] = extras
    return canonical


def _bvp_row_to_pa_rates(row):
    """Convert a BvP situational stat row (BQ or CSV) into per-PA outcome rates.

    Expected row keys: pa, ab, h, hr, bb, k (the schema also has avg/slg/woba
    but we only need counts). Returns a rates dict matching the contract of
    _monte_carlo_vs_sp at app.py:7712.

    Singles/doubles/triples are split from (h - hr) using league-average splits
    because the BvP table doesn't carry per-hit-type counts.
    """
    pa = max(1, int(row.get("pa") or 0))
    h  = int(row.get("h")  or 0)
    hr = int(row.get("hr") or 0)
    bb = int(row.get("bb") or 0)
    k  = int(row.get("k")  or 0)
    non_hr_h = max(0, h - hr)
    return {
        "k":   k / pa,
        "bb":  bb / pa,
        "hbp": 0.005,
        "1b":  (non_hr_h * 0.755) / pa,
        "2b":  (non_hr_h * 0.205) / pa,
        "3b":  (non_hr_h * 0.040) / pa,
        "hr":  hr / pa,
    }


# ── /api/matchup analysis cache ──────────────────────────────────────────────
# Gemini quota is a finite daily resource. Without caching, every visit to a
# BvP page burns at least one Gemini call per matchup; with N batters in a
# lineup and dozens of users that can easily exhaust the daily quota by noon.
# Cache successful analyses for 24h keyed by (batter, pitcher, date) so each
# unique matchup costs at most one Gemini call per day. Failures are NOT cached.
_matchup_analysis_cache: dict = {}
_matchup_analysis_lock   = threading.Lock()
_MATCHUP_ANALYSIS_TTL    = int(os.environ.get("MATCHUP_ANALYSIS_TTL_SEC", "86400"))


def _matchup_cache_get(batter_id, pitcher_id):
    today = datetime.now(ET).strftime("%Y-%m-%d")
    key = (int(batter_id), int(pitcher_id), today)
    with _matchup_analysis_lock:
        entry = _matchup_analysis_cache.get(key)
        if not entry:
            return None
        expires_at, payload = entry
        if expires_at < time.time():
            _matchup_analysis_cache.pop(key, None)
            return None
        return payload


def _matchup_cache_put(batter_id, pitcher_id, payload):
    today = datetime.now(ET).strftime("%Y-%m-%d")
    key = (int(batter_id), int(pitcher_id), today)
    with _matchup_analysis_lock:
        _matchup_analysis_cache[key] = (time.time() + _MATCHUP_ANALYSIS_TTL, payload)


def _deterministic_verdict_from_mc(mc):
    """Derive a {verdict, confidence, key_factors, summary} block from MC output.

    Used as a fallback when the Gemini analysis fails (quota exhausted, network
    error, etc.) so the AI VERDICT panel still shows actionable content. The
    thresholds mirror the deterministic BEST PLAYS thresholds used elsewhere.
    """
    if not isinstance(mc, dict):
        return None
    hits = mc.get("hits") or {}
    tb   = mc.get("tb") or {}
    hr   = mc.get("hr") or {}
    p_hit = float(hits.get("p_ge_1") or 0)
    p_tb2 = float(tb.get("p_ge_2") or 0)
    p_hr  = float(hr.get("p_ge_1") or 0)

    def _v(p, over_thr, under_thr):
        if p >= over_thr:  return "OVER"
        if p <= under_thr: return "UNDER"
        return "PASS"

    verdict = {
        "hits": _v(p_hit, 0.65, 0.40),
        "tb":   _v(p_tb2, 0.55, 0.30),
        "hr":   _v(p_hr,  0.18, 0.04),
    }
    over_count = sum(1 for v in verdict.values() if v == "OVER")
    if over_count >= 2:
        summary = (
            f"Model gives {int(p_hit*100)}% on 1+ Hit and {int(p_tb2*100)}% on 2+ TB across "
            f"{mc.get('nPa', '~3')} projected PAs. Lean OVER on the BEST PLAYS markets."
        )
        confidence = 60 + min(20, over_count * 5)
    elif over_count == 0:
        summary = (
            f"Soft projection — {int(p_hit*100)}% on 1+ Hit, {int(p_tb2*100)}% on 2+ TB. "
            "Fade or pass; book lines likely better than the model."
        )
        confidence = 40
    else:
        summary = (
            f"Mixed signal — {int(p_hit*100)}% 1+ Hit, {int(p_tb2*100)}% 2+ TB, "
            f"{int(p_hr*100)}% HR. Shop the strongest market only."
        )
        confidence = 50

    factors = [
        f"1+ Hit prob {int(p_hit*100)}%",
        f"2+ TB prob {int(p_tb2*100)}%",
        f"HR prob {int(p_hr*100)}%",
    ]
    return {
        "verdict": verdict,
        "confidence": confidence,
        "key_factors": factors,
        "summary": summary,
        "risk": "Deterministic fallback — AI analyst temporarily unavailable.",
    }


# Full-game PA target used when verdicting standard prop markets (1+ Hit,
# 2+ TB, HR). These props settle over the whole game, so a 3-PA vs-SP MC
# under-projects probability and pushes the AI Verdict toward PASS even
# when the same page's game-total panel shows a clear BET.
_AI_VERDICT_FULL_GAME_PA = 4.35


def _season_context_for_prompt(batter_name, pitcher_name):
    """Pull season-level batter/pitcher context from in-memory FG/Savant caches.

    Without season context the Gemini prompt sees only the small-sample BvP H2H
    plus the vs-SP MC, which biases it toward PASS even on elite matchups. Adding
    season stats + Statcast quality lets the LLM override H2H noise.
    """
    batter = {}
    pitcher = {}
    if batter_name:
        try:
            fg = fg_batter(batter_name) or {}
            sv = sv_batter(batter_name) or {}
            obp = fg.get("fg_obp"); slg = fg.get("fg_slg")
            batter = {
                "avg":            fg.get("fg_avg"),
                "obp":            obp,
                "slg":            slg,
                "ops":            round(obp + slg, 3) if (obp is not None and slg is not None) else None,
                "hr":             fg.get("fg_hr"),
                "wrc_plus":       fg.get("fg_wrc"),
                "iso":            fg.get("fg_iso"),
                "k_pct":          fg.get("fg_kpct"),
                "xwoba":          sv.get("sv_xwoba"),
                "exit_velo":      sv.get("sv_ev"),
                "hard_hit_pct":   sv.get("sv_hh_pct"),
                "barrel_pct":     sv.get("sv_brl_pct"),
            }
        except Exception:
            pass
    if pitcher_name:
        try:
            fg = fg_pitcher(pitcher_name) or {}
            sv = sv_pitcher(pitcher_name) or {}
            pitcher = {
                "era":                  fg.get("fg_era"),
                "whip":                 fg.get("fg_whip"),
                "hr9":                  fg.get("fg_hr9"),
                "k_pct":                fg.get("fg_kpct"),
                "xwoba_against":        sv.get("sv_xwoba"),
                "barrel_pct_allowed":   sv.get("sv_brl_pct"),
                "hard_hit_pct_allowed": sv.get("sv_hh_pct"),
            }
        except Exception:
            pass
    return {
        "batter":  {k: v for k, v in batter.items()  if v is not None},
        "pitcher": {k: v for k, v in pitcher.items() if v is not None},
    }


@app.route("/api/matchup")
def api_matchup_vertex():
    """BigQuery + Monte Carlo + Gemini Pro batter-vs-pitcher matchup endpoint.

    Query: GET /api/matchup?batter_id=<int>&pitcher_id=<int>&pa=<float optional>

    Pipeline:
      1. BigQuery pull from BQ_BVP_TABLE joined with BQ_BATTERS / BQ_PITCHERS.
      2. Feed per-PA rates into existing _monte_carlo_vs_sp() (no reimpl).
      3. Send {bq_stats, mc_percentiles, park context} to gemini-2.5-pro for
         a finalized analytical block.

    Fallbacks: BQ unavailable -> _matchup_row() CSV cache; Gemini fails ->
    return stats + MC with analysis=null and source='stats_only'.
    """
    try:
        batter_id  = request.args.get("batter_id", type=int)
        pitcher_id = request.args.get("pitcher_id", type=int)
        pa_vs_sp   = request.args.get("pa", type=float) or 3.0
        if not batter_id or not pitcher_id:
            return jsonify({"success": False, "error": "batter_id and pitcher_id required"}), 400

        bq_stats = None
        source = "vertex"
        if _bigquery_available:
            from google.cloud import bigquery as _bq_mod
            sql = (
                f"SELECT bvp.batter_id, bvp.pitcher_id, bvp.pa, bvp.ab, bvp.h, bvp.hr, "
                f"bvp.bb, bvp.k, bvp.avg, bvp.slg, bvp.woba, bvp.xwoba, "
                f"b.name AS batter_name, b.bats, p.name AS pitcher_name, p.throws "
                f"FROM `{BQ_BVP_TABLE}` bvp "
                f"LEFT JOIN `{BQ_BATTERS}`  b ON b.player_id  = bvp.batter_id "
                f"LEFT JOIN `{BQ_PITCHERS}` p ON p.player_id  = bvp.pitcher_id "
                f"WHERE bvp.batter_id = @bid AND bvp.pitcher_id = @pid "
                f"ORDER BY bvp.updated_at DESC LIMIT 1"
            )
            rows = _bq_query_rows(sql, params=[
                _bq_mod.ScalarQueryParameter("bid", "INT64", batter_id),
                _bq_mod.ScalarQueryParameter("pid", "INT64", pitcher_id),
            ])
            if rows:
                bq_stats = rows[0]

        if bq_stats is None:
            csv_row = _matchup_row(batter_id, pitcher_id)
            if csv_row:
                bq_stats = csv_row
                source = "csv_fallback"

        # No direct BvP sample is the case the arsenal-similarity priors
        # were *built for*. Synthesize a zero-PA stats dict carrying just
        # the names + handedness needed by the prior helpers; the blender
        # filters pa<=0 sources, so direct contributes nothing and the
        # priors stand alone.
        if not bq_stats:
            batter_prof = {}
            with _batter_profiles_lock:
                batter_prof = dict(_batter_profiles.get(int(batter_id)) or {})
            batter_name = batter_prof.get("name") or ""
            bats        = batter_prof.get("bats")  or ""

            # Pitcher name: try the reverse of _pitcher_name_to_mlbam first
            # (in-memory, instant); fall back to MLB Stats API people lookup.
            pitcher_name = ""
            with _pitcher_name_to_mlbam_lock:
                for nm_key, mid in _pitcher_name_to_mlbam.items():
                    if int(mid) == int(pitcher_id):
                        pitcher_name = nm_key
                        break
            if not pitcher_name:
                try:
                    r = requests.get(f"{MLB_API}/people/{pitcher_id}", timeout=5)
                    r.raise_for_status()
                    people = r.json().get("people", [])
                    if people:
                        pitcher_name = people[0].get("fullName", "")
                except Exception:
                    pass

            bq_stats = {
                "pa": 0, "ab": 0, "h": 0, "hr": 0, "bb": 0, "k": 0,
                "batter_name":  batter_name,
                "bats":         bats,
                "pitcher_name": pitcher_name,
            }
            source = "no_direct_bvp"

        bq_stats = _normalize_matchup_row(bq_stats, source)
        direct_rates = _bvp_row_to_pa_rates(bq_stats)
        direct_pa = int(bq_stats.get("pa") or 0)

        # ──────────────────────────────────────────────────────────────────
        # Arsenal-similarity priors. We compute two of them in parallel and
        # then blend all three sources (direct BvP + batter-side + pitcher-
        # side) with _blend_multi:
        #
        #   batter-side prior  : batter's outcomes vs pitchers with arsenal
        #                        similar to the target pitcher
        #   pitcher-side prior : pitcher's outcomes vs batters with profile
        #                        (handedness + xwOBA) similar to the target
        #                        batter
        #
        # Both are hard-bounded by ARSENAL_PRIOR_TIMEOUT_S as a combined
        # budget so a cold cache never blocks /api/matchup past that limit.
        # ──────────────────────────────────────────────────────────────────
        prior_block         = {"status": "skipped", "reason": None}
        pitcher_prior_block = {"status": "skipped", "reason": None}
        per_pa = direct_rates
        try:
            pitcher_name = bq_stats.get("pitcher_name") or ""

            # ── Batter-side prior setup ──────────────────────────────────
            similar = []
            similar_names = []
            primary = None
            if not pitcher_name:
                prior_block.update(status="skipped", reason="no_pitcher_name")
            else:
                similar, primary = _similar_pitchers_for(pitcher_name)
                prior_block["target_pitcher"] = pitcher_name
                prior_block["primary_pitch"]  = primary
                prior_block["similar_count"]  = len(similar)
                prior_block["similar"] = [
                    {"name": s["name"], "similarity": s["similarity"]}
                    for s in similar
                ]
                if not similar:
                    prior_block.update(status="skipped", reason="no_similar_arsenals")
                else:
                    similar_names = [s["name"] for s in similar]

            # ── Pitcher-side prior setup ─────────────────────────────────
            similar_batters = []
            similar_batter_ids = []
            batter_name = bq_stats.get("batter_name") or ""
            similar_batters, target_meta = _similar_batters_for(batter_id, batter_name)
            pitcher_prior_block["target_batter"] = target_meta.get("name") or batter_name
            pitcher_prior_block["target_meta"]   = target_meta
            pitcher_prior_block["similar_count"] = len(similar_batters)
            pitcher_prior_block["similar"] = [
                {"name": s["name"], "bats": s["bats"], "xwoba": s["xwoba"],
                 "similarity": s["similarity"]}
                for s in similar_batters[:10]   # truncate audit payload
            ]
            if not similar_batters:
                pitcher_prior_block.update(status="skipped",
                                           reason=target_meta.get("reason") or "no_similar_batters")
            similar_batter_ids = [s["batter_id"] for s in similar_batters]

            # ── Run both pulls in parallel — each side gets its OWN budget so
            # a slow batter-side pull can't starve the pitcher-side one (this
            # was the root cause of the chronic "timeout_or_error: TimeoutError"
            # on the H2H "Pitcher vs similar-profile batters" panel).
            prior_counts = None
            prior_audit  = {}
            pitcher_prior_counts = None
            pitcher_prior_audit  = {}
            pulls_pool = ThreadPoolExecutor(max_workers=2)
            try:
                pending = {}
                if similar_names:
                    pending["batter_side"] = pulls_pool.submit(
                        _aggregate_vs_similar_pitchers, batter_id, similar_names
                    )
                if similar_batter_ids:
                    pending["pitcher_side"] = pulls_pool.submit(
                        _aggregate_pitcher_vs_similar_batters, pitcher_id, similar_batter_ids
                    )
                for label, fut in pending.items():
                    try:
                        counts, audit = fut.result(timeout=ARSENAL_PRIOR_TIMEOUT_S)
                    except Exception as tex:
                        counts, audit = None, {"reason": f"timeout_or_error: {tex.__class__.__name__}"}
                    if label == "batter_side":
                        prior_counts, prior_audit = counts, audit
                    else:
                        pitcher_prior_counts, pitcher_prior_audit = counts, audit
            finally:
                pulls_pool.shutdown(wait=False)

            # ── Resolve batter-side ──────────────────────────────────────
            if similar_names:
                prior_block["audit"] = prior_audit
                if prior_counts and prior_counts.get("pa", 0) > 0:
                    prior_block["status"]       = "ready"
                    prior_block["prior_counts"] = prior_counts
                    prior_block["confidence"]   = "low" if int(prior_counts["pa"]) < 15 else "ok"
                else:
                    prior_block["status"] = "no_prior_data"
                    prior_block["reason"] = (prior_audit or {}).get("reason")

            # ── Resolve pitcher-side ─────────────────────────────────────
            if similar_batter_ids:
                pitcher_prior_block["audit"] = pitcher_prior_audit
                if pitcher_prior_counts and pitcher_prior_counts.get("pa", 0) > 0:
                    pitcher_prior_block["status"]       = "ready"
                    pitcher_prior_block["prior_counts"] = pitcher_prior_counts
                    pitcher_prior_block["confidence"]   = "low" if int(pitcher_prior_counts["pa"]) < 30 else "ok"
                else:
                    pitcher_prior_block["status"] = "no_prior_data"
                    pitcher_prior_block["reason"] = (pitcher_prior_audit or {}).get("reason")

            # ── 3-way blend ──────────────────────────────────────────────
            sources = [(direct_rates, direct_pa, None)]  # direct has no cap
            if prior_counts and prior_counts.get("pa", 0) > 0:
                sources.append((
                    _counts_to_pa_rates(prior_counts),
                    int(prior_counts["pa"]),
                    ARSENAL_PRIOR_STRENGTH,
                ))
            if pitcher_prior_counts and pitcher_prior_counts.get("pa", 0) > 0:
                sources.append((
                    _counts_to_pa_rates(pitcher_prior_counts),
                    int(pitcher_prior_counts["pa"]),
                    ARSENAL_PRIOR_PITCHER_STRENGTH,
                ))
            if len(sources) > 1:
                blended, blend_audit = _blend_multi(sources)
                if blended:
                    per_pa = blended
                    if prior_block.get("status") == "ready":
                        prior_block["status"] = "blended"
                    if pitcher_prior_block.get("status") == "ready":
                        pitcher_prior_block["status"] = "blended"
                    prior_block["blend_audit"]         = blend_audit
                    pitcher_prior_block["blend_audit"] = blend_audit
        except Exception as ex:
            prior_block.update(status="error", reason=str(ex))
            app.logger.warning(f"[arsenal_prior] {ex}")

        # Genuinely no signal: direct empty AND both priors empty. Return
        # cleanly instead of running MC on all-zero rates.
        has_direct  = direct_pa > 0
        has_b_prior = bool(prior_counts and prior_counts.get("pa", 0) > 0)
        has_p_prior = bool(pitcher_prior_counts and pitcher_prior_counts.get("pa", 0) > 0)
        if not (has_direct or has_b_prior or has_p_prior):
            return jsonify({
                "success": True,
                "batter_id": batter_id,
                "pitcher_id": pitcher_id,
                "stats":                bq_stats,
                "monte_carlo":          None,
                "analysis":             None,
                "source":               "no_data",
                "arsenal_prior":        prior_block,
                "pitcher_batter_prior": pitcher_prior_block,
                "timestamp": datetime.now(timezone.utc).isoformat(),
            })

        mc = _monte_carlo_vs_sp(per_pa, pa_vs_sp, n_sims=4000,
                                rng_seed=batter_id * 1000 + pitcher_id)

        # Standard prop markets (1+ Hit, 2+ TB, HR) settle over the entire
        # game, not just the starter segment. The vs-SP MC alone was driving
        # the AI Verdict toward PASS even when the page's game-total panel
        # showed a clear BET — feed Gemini the full-game probability set so
        # its verdict matches the prop scope the user is actually betting on.
        mc_full_game = _monte_carlo_vs_sp(per_pa, _AI_VERDICT_FULL_GAME_PA,
                                          n_sims=4000,
                                          rng_seed=batter_id * 1000 + pitcher_id + 7)

        season_context = _season_context_for_prompt(
            bq_stats.get("batter_name") or "",
            bq_stats.get("pitcher_name") or "",
        )

                # ── XGB hit probability ────────────────────────────────────────────
        xgb_hit_p    = None
        xgb_hit_cov  = 0.0
        if xgb_ready("hits"):
            try:
                _batter_name  = bq_stats.get("batter_name") or ""
                _pitcher_name = bq_stats.get("pitcher_name") or ""
                _fg_b  = fg_batter(_batter_name)  or {}
                _sv_b  = sv_batter(_batter_name)  or {}
                _fg_p  = fg_pitcher(_pitcher_name) or {}
                _sv_p  = sv_pitcher(_pitcher_name) or {}
                _form  = _fetch_rolling_form(batter_id, False) or {}
                _xgb_bdict = {
                    **_fg_b, **_sv_b,
                    "name":      _batter_name,
                    "bats":      bq_stats.get("bats") or _fg_b.get("fg_bats") or "R",
                    "l7Hits":    _form.get("l7Hits"),
                    "l14Hits":   _form.get("l14Hits"),
                    "l7HitRate": _form.get("l7HitRate"),
                }
                _xgb_pdict = {
                    **_fg_p, **_sv_p,
                    "name":      _pitcher_name,
                    "pitchHand": bq_stats.get("throws") or _fg_p.get("fg_throws") or "R",
                }
                xgb_hit_p   = xgb_hit_prob(_xgb_bdict, _xgb_pdict)
                xgb_hit_cov = _xgb_hit_coverage(_xgb_bdict, _xgb_pdict) if xgb_hit_p is not None else 0.0
            except Exception:
                pass
        
        # Deterministic recommendation from the full-game MC. Used both as the
        # final fallback when Gemini fails and as a prior in the prompt so the
        # LLM has a model-aligned anchor instead of inventing PASS from a thin
        # H2H sample.
        model_rec = _deterministic_verdict_from_mc(mc_full_game or mc)

        analysis = None
        analysis_error = None
        analysis_source = None  # "gemini" | "cache" | "fallback"

        cached = _matchup_cache_get(batter_id, pitcher_id)
        if cached and cached.get("analysis"):
            analysis = cached["analysis"]
            analysis_source = "cache"

        if analysis is None and _gemini_available and (mc_full_game or mc):
            prompt = (
                "You are evaluating a batter-vs-pitcher MLB prop matchup. Standard "
                "prop markets (1+ Hit, 2+ Total Bases, Home Run) settle over the "
                "ENTIRE game (~4.35 PAs), not just the starting-pitcher segment — "
                "your verdict must reflect the FULL-GAME probability.\n\n"
                "Output strict JSON with keys: `verdict` (object with keys hits, tb, "
                "hr — each one of OVER|UNDER|PASS), `confidence` (0-100 int), "
                "`key_factors` (array of <=4 short strings), `risk` (string), "
                "`summary` (one paragraph, <=80 words).\n\n"
                "Anchor your verdict on the FULL-GAME Monte Carlo probabilities and "
                "season-level context. Only return PASS when the full-game probability "
                "is genuinely marginal (1+ Hit <60%, 2+ TB <50%, HR <16%) OR when the "
                "season + Statcast context clearly contradicts the per-PA rates. Do "
                "NOT downgrade a strong full-game projection to PASS just because the "
                "career head-to-head sample is small — H2H is one signal among many.\n\n"
                f"Batter season + Statcast context:\n"
                f"{json.dumps(season_context.get('batter') or {}, default=str, ensure_ascii=True)}\n\n"
                f"Pitcher season + Statcast context:\n"
                f"{json.dumps(season_context.get('pitcher') or {}, default=str, ensure_ascii=True)}\n\n"
                f"Career head-to-head (small-sample, use cautiously):\n"
                f"{json.dumps(bq_stats, default=str, ensure_ascii=True)}\n\n"
                f"Arsenal-similarity prior (batter vs similar-arsenal pitchers):\n"
                f"{json.dumps(prior_block, default=str, ensure_ascii=True)}\n\n"
                f"Similar-batter prior (pitcher vs similar-profile batters):\n"
                f"{json.dumps(pitcher_prior_block, default=str, ensure_ascii=True)}\n\n"
                f"XGBoost hit model — P(1+ hit, calibrated): "
                f"{round(xgb_hit_p, 3) if xgb_hit_p is not None else 'unavailable'} "
                f"(input coverage: {round(xgb_hit_cov, 2) if xgb_hit_p is not None else 'n/a'}). "
                f"When XGBoost is available and coverage >= 0.50, treat it as a strong signal "
                f"that should anchor the hits verdict — do NOT override a strong XGB probability "
                f"(>0.68 → OVER, <0.45 → UNDER) to PASS without explicit contradicting context.\n\n"
                f"FULL-GAME Monte Carlo — this is the prop scope "
                f"({(mc_full_game or {}).get('nSims')} sims, {(mc_full_game or {}).get('nPa')} PAs):\n"
                f"{json.dumps(mc_full_game, default=str, ensure_ascii=True)}\n\n"
                f"Starter-only Monte Carlo (vs-SP segment, narrower context):\n"
                f"{json.dumps(mc, default=str, ensure_ascii=True)}\n\n"
                f"Model recommendation (deterministic from full-game MC — treat as a prior):\n"
                f"{json.dumps(model_rec, default=str, ensure_ascii=True)}"
            )
            analysis, analysis_error = _vertex_gemini_json(
                "reasoning", prompt,
                system="You are an expert MLB betting analyst. Respond with raw JSON only.",
                max_tokens=600, temperature=0.3,
            )
            if analysis:
                analysis_source = "gemini"
                _matchup_cache_put(batter_id, pitcher_id, {"analysis": analysis})

        # Deterministic fallback: if Gemini failed (quota / network / parse) we
        # still want the AI VERDICT panel to show something useful. Use the
        # full-game MC since that's the prop scope.
        if analysis is None and (mc_full_game or mc):
            analysis = _deterministic_verdict_from_mc(mc_full_game or mc)
            if analysis:
                analysis_source = "fallback"

        # XGB override: if XGB is confident (cov >= 0.50) and Gemini said PASS on hits,
        # and XGB strongly disagrees, override hits verdict.
        if analysis and xgb_hit_p is not None and xgb_hit_cov >= 0.50 and analysis_source == "gemini":
            g_verdict = dict(analysis.get("verdict") or {})
            g_hits = str(g_verdict.get("hits") or "").upper()
            if g_hits == "PASS":
                if xgb_hit_p >= 0.68:
                    g_verdict["hits"] = "OVER"
                    analysis["verdict"] = g_verdict
                    analysis["risk"] = ((analysis.get("risk") or "") +
                        " XGB override: model P(hit)={:.3f} at coverage {:.2f}.".format(
                        xgb_hit_p, xgb_hit_cov)).strip()
                elif xgb_hit_p <= 0.45:
                    g_verdict["hits"] = "UNDER"
                    analysis["verdict"] = g_verdict
                    analysis["risk"] = ((analysis.get("risk") or "") +
                        " XGB override: model P(hit)={:.3f} at coverage {:.2f}.".format(
                        xgb_hit_p, xgb_hit_cov)).strip()
        
        # Safety net: when the model strongly recommends OVER but Gemini
        # downgrades to PASS, prefer the model call. This was the user-reported
        # failure mode — AI says PASS while every adjacent panel shows STRONG/BET
        # because the LLM anchored on a thin career H2H sample.
        if analysis and model_rec and analysis_source == "gemini":
            g_v = dict(analysis.get("verdict") or {})
            m_v = (model_rec.get("verdict") or {})
            overrode = []
            for mkt in ("hits", "tb", "hr"):
                g_mkt = str(g_v.get(mkt) or "").upper()
                m_mkt = str(m_v.get(mkt) or "").upper()
                if g_mkt == "PASS" and m_mkt == "OVER":
                    g_v[mkt] = "OVER"
                    overrode.append(mkt)
                elif g_mkt == "PASS" and m_mkt == "UNDER":
                    g_v[mkt] = "UNDER"
                    overrode.append(mkt)
            if overrode:
                analysis["verdict"] = g_v
                existing_risk = analysis.get("risk") or ""
                note = (f"Model override on {','.join(overrode)} — full-game "
                        "probability supports a side that the analyst initially "
                        "downgraded to PASS.")
                analysis["risk"] = (existing_risk + " " + note).strip() if existing_risk else note

        # Surface a friendlier reason when the Gemini error was a quota hit.
        if analysis_error and ("RESOURCE_EXHAUSTED" in str(analysis_error) or "429" in str(analysis_error)):
            analysis_error = "AI quota exhausted — showing deterministic model verdict."

        if analysis_source == "gemini":
            source = "vertex"
        elif analysis_source == "cache":
            source = "vertex_cached"
        elif analysis_source == "fallback":
            source = "model_fallback"
        elif source == "vertex":
            source = "stats_only"

        return jsonify({
            "success": True,
            "batter_id": batter_id,
            "pitcher_id": pitcher_id,
            "stats": bq_stats,
            "monte_carlo": mc,
            "monte_carlo_full_game":  mc_full_game,
            "model_recommendation":   model_rec,
            "arsenal_prior":         prior_block,
            "pitcher_batter_prior":  pitcher_prior_block,
            "analysis": analysis,
            "analysis_error": analysis_error,
            "analysis_source": analysis_source,
            "source": source,
            "model": (
                VERTEX_MODELS["reasoning"] if analysis_source in ("gemini", "cache")
                else "model-deterministic" if analysis_source == "fallback"
                else None
            ),
            "xgbHitProb":     round(xgb_hit_p, 4) if xgb_hit_p is not None else None,
            "xgbHitCoverage": round(xgb_hit_cov, 2) if xgb_hit_p is not None else None,
            "timestamp": datetime.now(timezone.utc).isoformat(),
        })
    except Exception as ex:
        app.logger.error(f"[api_matchup_vertex] {traceback.format_exc()}")
        return jsonify({"success": False, "error": str(ex)}), 500


def _vertex_cheatsheet_enrich(payload):
    """Add Gemini Flash-Lite ai_blurbs to a cheatsheet payload in place.

    Iterates the existing hitsBoard / pitcherWeakspots rows (capped) and asks
    Gemini for a one-sentence blurb per item. Non-invasive: the original
    fields remain untouched so the UI keeps rendering even if Gemini fails.
    """
    if not _gemini_available or not isinstance(payload, dict):
        payload["aiEnriched"] = False
        return payload

    try:
        hits_rows = (payload.get("hitsBoard") or {}).get("rows") or []
        weakspots = (payload.get("pitcherWeakspots") or {}).get("cards") or []
        # Cap inputs so a 15-game slate stays well under a couple seconds total.
        sample = {
            "top_hitters": [
                {"name": r.get("name"), "team": r.get("team"), "matchup": r.get("matchup"),
                 "l10HitPct": r.get("l10HitPct"), "score": r.get("score")}
                for r in hits_rows[:12]
            ],
            "weakspot_pitchers": [
                {"pitcher": c.get("pitcherName"), "form": c.get("formLabel"),
                 "vuln": c.get("pitchVulnerability"), "rec": c.get("recommendation")}
                for c in weakspots[:8]
            ],
        }
        if not sample["top_hitters"] and not sample["weakspot_pitchers"]:
            payload["aiEnriched"] = False
            return payload

        prompt = (
            "For each item below, write one concise (<=20 words) prop-betting blurb. "
            "Return JSON {top_hitter_blurbs: {name: blurb,...}, "
            "weakspot_blurbs: {pitcher: blurb,...}}.\n\n"
            f"{json.dumps(sample, ensure_ascii=True)}"
        )
        result, err = _vertex_gemini_json(
            "fast", prompt,
            system="You are a sharp MLB prop analyst. Be specific, no fluff. Raw JSON only.",
            max_tokens=1200, temperature=0.4,
        )
        if result:
            payload["aiBlurbs"] = result
            payload["aiEnriched"] = True
            payload["aiModel"] = VERTEX_MODELS["fast"]
        else:
            payload["aiEnriched"] = False
            payload["aiError"] = err
    except Exception as ex:
        app.logger.warning(f"[cheatsheet_vertex] enrich failed: {ex}")
        payload["aiEnriched"] = False
        payload["aiError"] = str(ex)
    return payload


def _vertex_hr_pick_blurbs(scores, top_n=20):
    """Generate one short Gemini Flash-Lite blurb per top HR pick.

    Returns a dict keyed by batter_id (string) -> blurb (string). The whole
    top-N batch is sent in a single Gemini call so a 20-pick slate costs
    one request and produces specific, factor-aware commentary on every
    card without the user having to drill into the AI Report tab.
    """
    if not _gemini_available or not scores:
        return {}, "gemini_unavailable"
    try:
        sample = [
            {
                "id":          s.get("batter_id"),
                "batter":      s.get("batter"),
                "pitcher":     s.get("pitcher"),
                "park_hr_idx": s.get("park_hr_idx"),
                "iso":         s.get("iso"),
                "barrel_pct":  s.get("barrel_pct"),
                "hh_pct":      s.get("hh_pct"),
                "hr9_vs_hand": s.get("hr9_vs_hand"),
                "score":       s.get("score"),
                "prob_hr":     s.get("prob_hr"),
            }
            for s in (scores or [])[:top_n]
        ]
        if not sample:
            return {}, None
        prompt = (
            "For each HR pick below, write ONE concise (<=22 words) blurb that "
            "names the single strongest factor (park, barrel rate, pitcher HR9, "
            "platoon, ISO, etc.). No fluff, no hype words. "
            "Return JSON {blurbs: {id: blurb, ...}} where id is the batter id as a string.\n\n"
            f"{json.dumps(sample, ensure_ascii=True)}"
        )
        result, err = _vertex_gemini_json(
            "fast", prompt,
            system="You are a sharp MLB HR-prop analyst. Be specific, evidence-first. Raw JSON only.",
            max_tokens=4000, temperature=0.4,
        )
        if not result:
            return {}, err
        raw = result.get("blurbs") or {}
        # Normalize keys to strings so the frontend lookup works regardless
        # of whether the model returned ints or strings as the JSON key.
        return {str(k): v for k, v in raw.items() if v}, None
    except Exception as ex:
        app.logger.warning(f"[hr_picks_vertex] enrich failed: {ex}")
        return {}, str(ex)


@app.route("/api/cheatsheet")
def api_cheatsheet_vertex():
    """Vertex-enriched cheatsheet alias for /api/cheatsheets/today.

    Reuses the existing _cheatsheet_cache + daemon-thread refresh machinery
    (no new async layer). When ai=1 (default) and Vertex is available, the
    cached payload is enriched with Gemini Flash-Lite blurbs before return.
    Existing /api/cheatsheets/today is unchanged.
    """
    try:
        force = request.args.get("refresh") == "1"
        want_ai = request.args.get("ai", "1") != "0"
        payload = _get_cheatsheets_today(force=force)
        if want_ai and not payload.get("computing"):
            payload = _vertex_cheatsheet_enrich(payload)
        return jsonify(payload)
    except Exception as ex:
        app.logger.error(f"[api_cheatsheet_vertex] {traceback.format_exc()}")
        return jsonify({"success": False, "error": str(ex)}), 500


def _build_insights_context(game_pk):
    """Build a compact storyline context dict from a game_pk for Vertex insights."""
    gdata = fetch_schedule_game(game_pk)
    if not gdata:
        return None
    away_t = gdata.get("teams", {}).get("away", {})
    home_t = gdata.get("teams", {}).get("home", {})
    ap = away_t.get("probablePitcher", {}); hp = home_t.get("probablePitcher", {})
    ap_name = ap.get("fullName", "TBD");    hp_name = hp.get("fullName", "TBD")
    ap_fg = fg_pitcher(ap_name) or {};      hp_fg = fg_pitcher(hp_name) or {}
    hid = home_t.get("team", {}).get("id")
    pf = PARK_FACTORS.get(hid, 1.0)
    ven = gdata.get("venue", {}) or {}
    return {
        "matchup": f"{away_t.get('team',{}).get('abbreviation','AWAY')} @ "
                   f"{home_t.get('team',{}).get('abbreviation','HOME')}",
        "venue": ven.get("name"),
        "park_factor": pf,
        "away_pitcher": {"name": ap_name, "era": ap_fg.get("fg_era"), "k9": ap_fg.get("fg_k9")},
        "home_pitcher": {"name": hp_name, "era": hp_fg.get("fg_era"), "k9": hp_fg.get("fg_k9")},
        "weather": gdata.get("weather") or {},
        "series": {"game": gdata.get("seriesGame"), "total": gdata.get("seriesTotal")},
    }


@app.route("/api/insights/<int:game_pk>")
def api_insights_vertex(game_pk):
    """Gemini Pro matchup insights for a game.

    Parallel to the existing /api/game-projection storyline. Routes through
    the narrative tier (Gemini Pro by default). Falls back to the existing
    deterministic _fallback_matchup_insights() output when Gemini is down.
    """
    try:
        _maybe_refresh_fg()
        ctx = _build_insights_context(game_pk)
        if not ctx:
            return jsonify({"success": False, "error": "Game not found"}), 404

        insights = None
        err = None
        if _gemini_available:
            prompt = (
                "Generate 3 to 5 concise MLB matchup storyline bullets for today's game. "
                "Use only the provided context. Prioritize actionable prop-betting context. "
                "Output JSON only with key `matchup_insights` as an array of strings.\n\n"
                f"Context JSON:\n{json.dumps(ctx, default=str, ensure_ascii=True)}"
            )
            parsed, err = _vertex_claude_json(
                "narrative", prompt,
                system="You are an expert MLB betting analyst. Respond with raw JSON only, no markdown.",
                max_tokens=600, temperature=0.4,
            )
            if isinstance(parsed, dict):
                items = parsed.get("matchup_insights")
                if isinstance(items, list):
                    insights = [str(x).strip() for x in items if str(x).strip()][:5]

        source = "vertex"
        if not insights:
            try:
                gdata = fetch_schedule_game(game_pk) or {}
                away_t = gdata.get("teams", {}).get("away", {})
                home_t = gdata.get("teams", {}).get("home", {})
                ap = away_t.get("probablePitcher", {}); hp = home_t.get("probablePitcher", {})
                insights = _fallback_matchup_insights(
                    gdata,
                    away_t.get("team", {}).get("abbreviation", "AWAY"),
                    home_t.get("team", {}).get("abbreviation", "HOME"),
                    8.5,
                    "MED",
                    "EVEN",
                    ap.get("fullName", "TBD"), hp.get("fullName", "TBD"),
                    float((fg_pitcher(ap.get("fullName", "")) or {}).get("fg_era") or 4.2),
                    float((fg_pitcher(hp.get("fullName", "")) or {}).get("fg_era") or 4.2),
                    ctx.get("weather") or {},
                )
                source = "fallback"
            except Exception as fex:
                err = f"vertex={err}; fallback={fex}"
                insights = []

        return jsonify({
            "success": True,
            "gamePk": game_pk,
            "matchup_insights": insights,
            "source": source,
            "model": VERTEX_MODELS["narrative"] if source == "vertex" else None,
            "fallback_reason": err if source == "fallback" else None,
            "context": ctx,
            "timestamp": datetime.now(timezone.utc).isoformat(),
        })
    except Exception as ex:
        app.logger.error(f"[api_insights_vertex] {game_pk}: {traceback.format_exc()}")
        return jsonify({"success": False, "error": str(ex)}), 500


@app.route("/api/projected-boxscore/<int:game_pk>")
def api_projected_boxscore_vertex(game_pk):
    """Gemini Pro full projected boxscore (premium tier).

    Mirror of /api/ai-boxscore that uses the premium model tier; falls back
    to the existing _local_boxscore_projections() helper on any failure.
    """
    try:
        _maybe_refresh_fg()
        _maybe_refresh_savant()
        gdata = fetch_schedule_game(game_pk)
        if not gdata:
            return jsonify({"success": False, "error": "Game not found"}), 404

        away_t = gdata.get("teams", {}).get("away", {})
        home_t = gdata.get("teams", {}).get("home", {})
        away_name = away_t.get("team", {}).get("name", "Unknown")
        home_name = home_t.get("team", {}).get("name", "Unknown")
        away_abbr = away_t.get("team", {}).get("abbreviation", "AWAY")
        home_abbr = home_t.get("team", {}).get("abbreviation", "HOME")
        ap = away_t.get("probablePitcher", {}); hp = home_t.get("probablePitcher", {})
        ap_name = ap.get("fullName", "TBD"); hp_name = hp.get("fullName", "TBD")
        ap_id = ap.get("id"); hp_id = hp.get("id")
        ap_stats = pitcher_stats_mlb(ap_id) if ap_id else {}
        hp_stats = pitcher_stats_mlb(hp_id) if hp_id else {}
        ap_fg = fg_pitcher(ap_name) or {}; hp_fg = fg_pitcher(hp_name) or {}
        ap_sv = sv_pitcher(ap_name) or {}; hp_sv = sv_pitcher(hp_name) or {}

        ven = gdata.get("venue", {}) or {}
        venue_name = ven.get("name", "Unknown")
        venue_id = ven.get("id")
        vloc = ven.get("location", {}) or {}
        coords = vloc.get("defaultCoordinates", {}) or {}
        lat = coords.get("latitude"); lon = coords.get("longitude")
        try:
            dt_utc_wx = datetime.fromisoformat(gdata.get("gameDate", "").replace("Z", "+00:00"))
            game_hour = dt_utc_wx.astimezone(ET).hour
        except Exception:
            game_hour = 13
        wx = get_weather(lat, lon, game_hour, venue_id=venue_id)
        if wx.get("temp") in (None, "N/A"):
            raw_wx = gdata.get("weather", {}) or {}
            if raw_wx:
                wx = {"temp": raw_wx.get("temp", "N/A"),
                      "condition": raw_wx.get("condition", "N/A"),
                      "wind": raw_wx.get("wind", "N/A")}

        try:
            r = requests.get(f"{MLB_API}/game/{game_pk}/boxscore", timeout=10)
            r.raise_for_status()
            box = r.json().get("teams", {})
            away_bats = get_batters_from_boxscore(box.get("away", {}), "away")
            home_bats = get_batters_from_boxscore(box.get("home", {}), "home")
        except Exception:
            away_bats = []; home_bats = []

        hid = home_t.get("team", {}).get("id")
        pf = PARK_FACTORS.get(hid, 1.0)

        context = {
            "away_team": away_name, "away_abbr": away_abbr,
            "home_team": home_name, "home_abbr": home_abbr,
            "weather": {"temp": wx.get("temp", "N/A"),
                         "condition": wx.get("condition", ""),
                         "wind": wx.get("wind", "N/A")},
            "venue": {"name": venue_name, "park_factor": pf},
            "away_pitcher": {"name": ap_name,
                              "era":  ap_fg.get("fg_era")  or ap_stats.get("era",  "N/A"),
                              "whip": ap_fg.get("fg_whip") or ap_stats.get("whip", "N/A"),
                              "k9":   ap_fg.get("fg_k9")   or ap_stats.get("k9",   "N/A"),
                              "xera": ap_sv.get("sv_xera", "N/A")},
            "home_pitcher": {"name": hp_name,
                              "era":  hp_fg.get("fg_era")  or hp_stats.get("era",  "N/A"),
                              "whip": hp_fg.get("fg_whip") or hp_stats.get("whip", "N/A"),
                              "k9":   hp_fg.get("fg_k9")   or hp_stats.get("k9",   "N/A"),
                              "xera": hp_sv.get("sv_xera", "N/A")},
            "away_lineup": [{"slot": b.get("slot"), "name": b.get("name"),
                              "avg": b.get("avg"), "xwoba": b.get("sv_xwoba"),
                              "hr": b.get("hr")} for b in away_bats[:9]],
            "home_lineup": [{"slot": b.get("slot"), "name": b.get("name"),
                              "avg": b.get("avg"), "xwoba": b.get("sv_xwoba"),
                              "hr": b.get("hr")} for b in home_bats[:9]],
        }

        ai_projections = None
        ai_error = None
        if _gemini_available:
            prompt = (
                f"Game: {context['away_team']} ({context['away_pitcher']['name']}, "
                f"ERA {context['away_pitcher']['era']}) at {context['home_team']} "
                f"({context['home_pitcher']['name']}, ERA {context['home_pitcher']['era']}).\n"
                f"Venue: {context['venue']['name']} (park factor {context['venue']['park_factor']}).\n"
                f"Weather: {context['weather']['temp']}°F, {context['weather']['condition']}, "
                f"wind {context['weather']['wind']}.\n"
                "Away lineup xwOBA top 3: " +
                ", ".join(f"{b['name']} {b.get('xwoba','N/A')}" for b in context["away_lineup"][:3]) + ".\n"
                "Home lineup xwOBA top 3: " +
                ", ".join(f"{b['name']} {b.get('xwoba','N/A')}" for b in context["home_lineup"][:3]) + ".\n"
                "Return JSON with keys: away_runs (int), home_runs (int), away_hits (int), "
                "home_hits (int), total_runs (int), away_reasoning (str), home_reasoning (str), "
                "key_factors (list of str), confidence (HIGH|MEDIUM|LOW), "
                "notable_props (list of {player, prop, projection, reasoning})."
            )
            ai_projections, ai_error = _vertex_claude_json(
                "premium", prompt,
                system="You are an expert MLB analyst providing detailed game and player "
                       "projections. Respond ONLY with valid JSON — no preamble, no markdown.",
                max_tokens=4000, temperature=0.7,
            )

        source = "vertex"
        if ai_projections is None:
            ai_projections = _local_boxscore_projections(
                game_pk, context, away_bats, home_bats, ap_name, hp_name,
                ap_fg, hp_fg, ap_sv, hp_sv, ap_stats, hp_stats, pf, wx,
                away_t, home_t,
            )
            source = "local_fallback"
            ai_projections["source"] = source
            ai_projections["fallback_reason"] = ai_error or "Gemini unavailable"
        else:
            ai_projections["source"] = source
            ai_projections["model"] = VERTEX_MODELS["premium"]

        return jsonify({
            "success": True,
            "gamePk": game_pk,
            "matchup": f"{away_abbr} vs {home_abbr}",
            "weather": context["weather"],
            "venue": context["venue"],
            "pitching_matchup": {"away_pitcher": context["away_pitcher"],
                                  "home_pitcher": context["home_pitcher"]},
            "projections": ai_projections,
            "timestamp": datetime.now(timezone.utc).isoformat(),
        })
    except Exception as ex:
        app.logger.error(f"[api_projected_boxscore_vertex] {game_pk}: {traceback.format_exc()}")
        return jsonify({"success": False, "error": str(ex)}), 500

# ── PrizePicks Integration ─────────────────────────────────────────────────────
_pp_cache = {"data": [], "ts": 0}
_PP_TTL   = 300  # 5-min cache

MLB_STAT_TYPES = {
    "Hits":                    "hits",
    "Total Bases":             "total_bases",
    "Home Runs":               "home_runs",
    "RBIs":                    "rbi",
    "Runs":                    "runs",
    "Stolen Bases":            "stolen_bases",
    "Pitcher Strikeouts":      "strikeouts",
    "Strikeouts":              "strikeouts",
    "Walks":                   "walks",
    "Earned Runs Allowed":     "earned_runs",
    "Hits Allowed":            "hits_allowed",
    "Pitching Outs":           "pitching_outs",
    "1st Inning Runs Allowed": "first_inning_runs",
}

def _fetch_prizepicks_mlb():
    """Fetch all PrizePicks props, filter MLB stat types, cross-ref FG projections."""
    try:
        url = "https://partner-api.prizepicks.com/projections?per_page=1000&include=new_player"
        headers = {
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
            "Accept": "application/json",
        }
        resp = requests.get(url, headers=headers, timeout=15)
        resp.raise_for_status()
        raw = resp.json()
    except Exception as e:
        app.logger.error(f"[PrizePicks] fetch error: {e}")
        return []

    # Build player lookup from included array
    player_map = {}
    for item in raw.get("included", []):
        if item.get("type") == "new_player":
            pid   = item["id"]
            attrs = item.get("attributes", {})
            player_map[pid] = {
                "name":     attrs.get("display_name") or attrs.get("name", "Unknown"),
                "team":     attrs.get("team", ""),
                "position": attrs.get("position", ""),
            }

    # Build quick batter/pitcher FG lookup for edge calc (name-keyed)
    with _fg_lock:
        fg_bat_snap = dict(_fg_bat)
        fg_pit_snap = dict(_fg_pit)

    props = []
    for proj in raw.get("data", []):
        if proj.get("type") != "projection":
            continue
        attrs = proj.get("attributes", {})
        rels  = proj.get("relationships", {})
        stat  = attrs.get("stat_type", "")

        if stat not in MLB_STAT_TYPES:
            continue

        pid    = (rels.get("new_player") or {}).get("data", {}).get("id", "")
        player = player_map.get(pid, {})
        line   = attrs.get("line_score")
        if line is None:
            continue

        stat_key  = MLB_STAT_TYPES[stat]
        our_proj  = None
        edge      = None
        edge_pct  = None
        direction = None

        # Cross-reference our FG projection for this player
        try:
            pname_lower = player.get("name", "").lower().strip()
            if pname_lower:
                # Batter stats
                fg_b = _fuzzy_lookup(pname_lower, fg_bat_snap)
                if fg_b:
                    stat_map = {
                        "hits":        fg_b.get("fg_avg", 0) * 4.2,
                        "total_bases": (fg_b.get("fg_slg", 0) * 4.2),
                        "home_runs":   fg_b.get("fg_hr", 0) / max(fg_b.get("fg_pa", 600), 1) * 4.2,
                        "rbi":         fg_b.get("fg_rbi", 0) / max(fg_b.get("fg_pa", 600), 1) * 4.2,
                        "runs":        fg_b.get("fg_r", 0) / max(fg_b.get("fg_pa", 600), 1) * 4.2,
                        "stolen_bases": fg_b.get("fg_sb", 0) / max(fg_b.get("fg_pa", 600), 1) * 4.2,
                        "walks":       fg_b.get("fg_bbpct", 0) * 4.2,
                    }
                    if stat_key in stat_map:
                        our_proj = round(float(stat_map[stat_key]), 2)
                # Pitcher stats
                if our_proj is None:
                    fg_p = _fuzzy_lookup(pname_lower, fg_pit_snap)
                    if fg_p:
                        stat_map_p = {
                            "strikeouts": fg_p.get("fg_k9", 0) / 9 * float(fg_p.get("fg_ip", 0) / max(fg_p.get("fg_gs", 1), 1)),
                            "walks":      fg_p.get("fg_bb9", 0) / 9 * float(fg_p.get("fg_ip", 0) / max(fg_p.get("fg_gs", 1), 1)),
                        }
                        if stat_key in stat_map_p:
                            our_proj = round(float(stat_map_p[stat_key]), 2)
                if our_proj is not None and our_proj > 0:
                    edge      = round(our_proj - float(line), 2)
                    edge_pct  = round((edge / float(line)) * 100, 1) if line else None
                    direction = "over" if edge > 0 else "under" if edge < 0 else "push"
        except Exception:
            pass

        props.append({
            "id":         proj["id"],
            "player":     player.get("name", "Unknown"),
            "team":       player.get("team", ""),
            "position":   player.get("position", ""),
            "stat":       stat,
            "stat_key":   stat_key,
            "line":       float(line),
            "our_proj":   our_proj,
            "edge":       edge,
            "edge_pct":   edge_pct,
            "direction":  direction,
            "status":     attrs.get("status", ""),
            "is_promo":   attrs.get("is_promo", False),
            "trending":   attrs.get("trending_count"),
            "start_time": attrs.get("start_time", ""),
            "game_id":    attrs.get("game_id", ""),
        })

    # Sort: props with edge first (abs desc), rest alphabetically
    props.sort(key=lambda x: (x["edge"] is None, -abs(x["edge"] or 0)))
    return props


@app.route("/api/prizepicks")
def api_prizepicks():
    global _pp_cache
    now = time.time()
    if now - _pp_cache["ts"] > _PP_TTL or not _pp_cache["data"]:
        _pp_cache["data"] = _fetch_prizepicks_mlb()
        _pp_cache["ts"]   = now
    stat_filter = request.args.get("stat", "").strip()
    data = _pp_cache["data"]
    if stat_filter:
        data = [p for p in data if p["stat_key"] == stat_filter]
    return jsonify({"status": "ok", "count": len(data), "props": data,
                    "cached_at": int(_pp_cache["ts"])})


@app.route("/api/prizepicks/player/<path:player_name>")
def api_prizepicks_player(player_name):
    global _pp_cache
    now = time.time()
    if now - _pp_cache["ts"] > _PP_TTL or not _pp_cache["data"]:
        _pp_cache["data"] = _fetch_prizepicks_mlb()
        _pp_cache["ts"]   = now
    name = player_name.lower().strip()
    data = [p for p in _pp_cache["data"]
            if name in p["player"].lower() or p["player"].lower() in name]
    return jsonify({"status": "ok", "count": len(data), "props": data,
                    "cached_at": int(_pp_cache["ts"])})


@app.route("/api/prizepicks/refresh", methods=["POST"])
def api_prizepicks_refresh():
    global _pp_cache
    _pp_cache["ts"] = 0
    return jsonify({"status": "ok", "message": "Cache cleared"})

